/* Тренажер «Підприємництво і фінансова грамотність», 8–9 класи.
   За модельною навчальною програмою (авт. Кузнєцова А. Я. та ін.), рекомендованою наказом МОН від 24.12.2024 № 1787.
   Кожна тема — наскрізна симуляція на ~30 хв: рішення змінюють стан (гроші, борг, довіра…), а стан змінює наступні кроки.
   Ставки податків і тарифи подано «за умовою». Зміст версіонований; результати учнів прив'язані до версії. */
const PFG_VERSION='pfg-2026.3';
const PN=n=>{const r=Math.round(n*100)/100;const [a,b]=String(Math.abs(r)).split('.');return (r<0?'−':'')+a.replace(/\B(?=(\d{3})+(?!\d))/g,' ')+(b?','+b:'');};
const PG=n=>PN(n)+' грн';
/* узгодження з числом: PL(3,'бал','бали','балів') → «3 бали» */
const PW=(n,a,b,c)=>{const x=Math.abs(Math.round(n))%100,y=x%10;return x>10&&x<20?c:y===1?a:y>=2&&y<=4?b:c;};
const PL=(n,a,b,c)=>PN(n)+' '+PW(n,a,b,c);
const PFG_SECTIONS={
 '8a':{grade:8,name:'Розділ І. Прикладні фінанси'},
 '8b':{grade:8,name:'Розділ ІІ. Родинні фінанси'},
 '9a':{grade:9,name:'Розділ І. Підприємливість і підприємництво'},
 '9b':{grade:9,name:'Розділ ІІ. Соціальна відповідальність бізнесу та відносини з державою'}
};
const PFG_TOPICS=[];
PFG_TOPICS.push({id:'8-1',sec:'8a',title:'Гроші у житті людини',minutes:30,
 intro:'Ти торгуєш посудом власної роботи і маєш машину часу. На тебе чекають чотири епохи: ярмарок без грошей, місто срібних монет, час паперових банкнот і сьогодення з картками. На зап’ясті в тебе лічильник «Статок»: він перераховує все твоє майно — горщики, срібло, банкноти — у сучасні гривні, щоб епохи можна було порівнювати. Що ти збережеш, кому довіришся й чи перевіриш гроші в одній епосі — з тим і ввійдеш у наступну.',
 init:()=>({w:6000,tr:50,w0:0,k3:0,need:0,f:{}}),
 meters:[{k:'w',label:'Статок',unit:'грн'},{k:'tr',label:'Довіра до тебе',unit:'балів'}],
 steps:[
  {id:'e1_rate',t:'calc',head:'Епоха 1 · Ярмарок без грошей',text:'Ярмарок над річкою, дуже давно. Грошей ще не існує — люди міняють річ на річ. Ти привозиш 12 горщиків власної роботи (лічильник рахує кожен як 500 грн). Тобі потрібні чоботи на зиму. Та швець горщиків не хоче: йому потрібне зерно. За чоботи він просить 4 мірки зерна. Селянин дає за 1 горщик 2 мірки зерна.',q:'Скільки горщиків коштують чоботи, якщо міняти через зерно?',ans:S=>2,unit:'горщики',hint:'Скільки разів по 2 мірки вміщується в 4 мірках?',sol:S=>'За 1 горщик дають 2 мірки зерна, а потрібно 4 мірки: 4 : 2 = 2 горщики. У бартері кожну ціну доводиться перераховувати через інший товар — єдиної міри вартості ще немає.'},
  {id:'e1_barter',t:'choice',head:'Епоха 1 · Як виміняти чоботи',text:'Селянин із зерном стоїть на іншому кінці ярмарку й уже запрягає воза. Швець квапить. Поруч соляр Сава міняє сіль і примовляє: «Сіль беруть усі — і швець, і селянин, і рибалка».',q:'Як ти дістанеш чоботи?',o:[
   {l:'Обміняти 2 горщики на сіль у Сави, а сіллю заплатити швецю',p:2,eff:S=>{S.w-=1000;S.f.salt=1;},fb:'Сіль тут беруть усі, тож вона працює як гроші — як засіб обміну. Чоботи коштували 2 горщики, і не довелося шукати людину, якій потрібні саме горщики.'},
   {l:'Бігти до селянина: горщики обміняти на зерно, зерно — на чоботи',p:1,eff:S=>{S.w-=1500;},fb:'Обмін вдався, але селянин поспішав, і ціна вийшла гіршою: 4 мірки зерна лише за 3 горщики. У бартері бажання двох людей мають збігтися — і це коштує часу й товару.'},
   {l:'Умовити швеця взяти горщики — запропонувати 5 замість 2',p:0,eff:S=>{S.w-=2500;},fb:'Швець узяв горщики тільки тому, що їх аж п’ять замість двох. Коли твій товар продавцеві не потрібен, бартер стає дуже дорогим: мінус 5 горщиків.'}]},
  {id:'e1_store',t:'choice',head:'Епоха 1 · У чому зберігати багатство',text:S=>'Ярмарок закінчується. У тебе лишилося '+PL(S.w/500,'горщик','горщики','горщиків')+' — лічильник показує '+PG(S.w)+'. Наступний ярмарок аж за рік, а горщики в дорозі б’ються. Багатство можна перевести в інший товар.',q:'У чому ти зберігатимеш статок до наступного року?',o:[
   {l:'У срібних зливках: мало місця, не псуються, цінуються в кожному місті',p:2,eff:S=>{S.f.store='silver';},fb:'Срібло не гниє, не б’ється, легко ділиться на частини, і його беруть усюди. Саме тому метали стали грошима: вони добре зберігають вартість.'},
   {l:'У зерні: воно потрібне всім і завжди',p:1,eff:S=>{S.w=Math.round(S.w*0.9/100)*100;S.f.store='grain';},fb:'Зерно справді беруть охоче, та за рік приблизно десяту частину з’їли миші й вогкість. Товарні гроші, які псуються, погано зберігають вартість.'},
   {l:'У в’яленій рибі: сьогодні за неї дають найбільше',p:0,eff:S=>{S.w=Math.round(S.w*0.7/100)*100;S.f.store='fish';},fb:'Сьогодні риба в ціні, але до наступного ярмарку майже третина її зіпсувалася. Те, що добре міняється зараз, не обов’язково доживе до часу, коли знадобиться.'},
   {l:'Нічого не міняти: горщики — мій товар, їх і повезу',p:0,eff:S=>{S.w-=1000;S.f.store='pots';},fb:'За рік переїздів два горщики розбилися. Товар, який займає багато місця й легко псується, — погана скарбничка.'}]},
  {id:'ev1',t:'event',head:'Епоха 2 · Місто срібних монет',text:S=>'Минають століття. Машина часу висаджує тебе в торговому місті, де князь карбує срібні монети. '+(S.f.store==='silver'?'Твої зливки міняйло охоче обмінює на монети — срібло не втратило нічого.':S.f.store==='grain'?'Більша частина зерна вціліла, решту з’їли миші. Зерно ти продаєш за монети.':S.f.store==='fish'?'Зіпсовану рибу довелося викинути, вцілілу ти продаєш за монети.':'Вцілілі горщики ти продаєш на ринку за монети.')+' Рахунок простий: 1 срібняк на кожні 100 грн лічильника. У тебе '+PL(S.w/100,'срібняк','срібняки','срібняків')+'.'},
  {id:'e2_left',t:'calc',head:'Епоха 2 · Ціни в монетах',text:S=>'На ринку кожен товар має ціну в срібняках: сувій сукна — 3, діжка меду — 4, кінь — 20. Тепер будь-що легко порівняти: монети стали мірою вартості. У тебе '+PL(S.w/100,'срібняк','срібняки','срібняків')+'. Ти купуєш 5 сувоїв сукна, щоб перепродати.',q:'Скільки срібняків залишиться в гаманці?',ans:S=>S.w/100-15,unit:'срібняків',hint:'Спершу знайди, скільки коштують 5 сувоїв по 3 срібняки.',sol:S=>'5 × 3 = 15 срібняків за сукно. '+PN(S.w/100)+' − 15 = '+PL(S.w/100-15,'срібняк','срібняки','срібняків')+'. Лічильник статку не змінився: частина багатства тепер лежить у сукні.'},
  {id:'e2_clip',t:'choice',head:'Епоха 2 · Підозрілі монети',text:'Купець Яким бере в тебе все сукно за 20 срібняків — це 5 срібняків заробітку. Він висипає монети на прилавок. Деякі здаються тоншими, а краї в них нерівні, ніби підрізані ножем.',q:'Як ти приймеш плату?',o:[
   {l:'Зважити монети на терезах міняйла: послуга коштує 1 срібняк',p:2,eff:S=>{S.w+=400;S.tr=Math.min(100,S.tr+5);S.f.weigh=1;},fb:'Терези показали: три монети обрізані. Яким без суперечки замінив їх на повні. Перевірка коштувала 1 срібняк, заробіток — 4. Пізніше ребро монет стали робити рифленим, щоб обрізану монету було видно одразу, — це один із давніх елементів захисту грошей.'},
   {l:'Перелічити монети: 20 штук — отже, 20 срібняків',p:0,eff:S=>{S.w-=300;S.f.clip=1;},fb:'Монет справді 20, але срібла в них менше: міняйло потім прийняв їх лише як 12 повних. Замість заробітку 5 срібняків — втрата 3.'},
   {l:'Відмовитися від угоди й шукати іншого покупця',p:1,eff:S=>{S.f.noSale=1;},fb:'Обрізані монети до тебе не потрапили, але інший покупець дав за сукно рівно стільки, скільки воно коштувало тобі. Гроші цілі, заробітку немає.'}]},
  {id:'e2_loan',t:'choice',head:'Епоха 2 · Сусід просить у борг',text:'Сусід по ринку, бондар Гнат, просить позичити 6 срібняків до наступного ярмарку: треба купити дошки на діжки. На ринку його знають як чесного майстра.',q:'Що ти зробиш?',o:[
   {l:'Позичити й скласти при свідках розписку: сума, строк, підписи',p:2,eff:S=>{S.w+=100;S.tr=Math.min(100,S.tr+10);S.f.loan=1;},fb:'Гнат повернув борг вчасно й додав срібняк на знак подяки. Позика, купівля, плата за роботу — усе це грошові відносини, і тримаються вони на чітких домовленостях. Гроші тут послужили засобом платежу.'},
   {l:'Позичити під слово честі: між своїми папери ні до чого',p:1,eff:S=>{S.w-=200;S.tr=Math.min(100,S.tr+5);},fb:'Гнат не обманював, але ви по-різному запам’ятали суму: він повернув 4 срібняки, а не 6. Без запису сперечаються навіть чесні люди.'},
   {l:'Відмовити: срібло потрібне для власної торгівлі',p:1,eff:S=>{S.tr=Math.max(0,S.tr-5);},fb:'Срібло лишилося при тобі, і це твоє право. Проте на ринку, де всі одне одного знають, допомога сусідові — це ще й довіра, яка згодом повертається.'},
   {l:'Позичити вдвічі більше, ніж він просить, але під великий відсоток',p:0,eff:S=>{S.w-=600;S.tr=Math.max(0,S.tr-15);},fb:'Гнат узяв 12 срібняків, але з такими відсотками розплатитися не зміг: повернув половину й поїхав з міста. Решта 6 срібняків пропала, а ринок запам’ятав твою жадібність.'}]},
  {id:'e2_carry',t:'choice',head:'Епоха 2 · Дорога до великого міста',text:S=>'Час їхати до великого міста. У тебе '+PL(S.w/100,'срібняк','срібняки','срібняків')+' — важкий гаманець, а на дорогах чатують розбійники. Купецький дім Лазаря пропонує: залиш срібло в його скрині тут, візьми розписку з печаткою, а в місті його контора видасть тобі монети. Плата — 2 срібняки.',q:'Як ти перевезеш статок?',o:[
   {l:'Залишити срібло в купецькому домі й їхати з розпискою',p:2,eff:S=>{S.w-=200;S.f.note=1;},fb:'Розбійники обшукали воза й не знайшли нічого цінного: папірець із печаткою їх не зацікавив. У місті контора Лазаря видала монети. З подібних розписок на срібло й золото згодом виросли паперові гроші.'},
   {l:'Найняти двох охоронців: кожен просить 2 срібняки',p:1,eff:S=>{S.w-=400;},fb:'Срібло доїхало, але охорона коштувала 4 срібняки — удвічі дорожче, ніж розписка купецького дому.'},
   {l:'Сховати монети в мішку з вовною й везти без охорони',p:0,eff:S=>{S.w=Math.round(S.w*2/3/100)*100;},fb:'Розбійники розпороли мішок і забрали приблизно третину срібла — усе, що встигли знайти. Метал надійно зберігає вартість, але возити його важко й небезпечно.'},
   {l:'Розділити ризик: половину везти при собі, половину довірити попутникові-купцеві',p:0,eff:S=>{S.w=Math.round(S.w/2/100)*100;},fb:'Попутник зник на першому ж роздоріжжі разом із половиною твого срібла. Ні печатки, ні свідків, ні навіть справжнього імені — шукати нікого.'}]},
  {id:'ev2',t:'event',head:'Епоха 3 · Час паперових грошей',text:S=>'Знову стрибок у часі. Місто початку XX століття: трамваї, вітрини, газети. У кишенях людей — паперові банкноти, які друкує державний банк. '+(S.f.note?'Ти всміхаєшся: вони схожі на далеких нащадків тієї розписки з печаткою.':'Ти згадуєш розписку купецького дому, яка тоді здалася зайвою: паперові гроші виросли з подібних розписок.')+' Машина часу міняє твоє срібло на банкноти: у тебе '+PN(S.w)+' карбованців (1 карбованець на 1 грн лічильника).',eff:S=>{S.k3=S.w;}},
  {id:'e3_hold',t:'choice',head:'Епоха 3 · Ціни ростуть',text:S=>'Ти відкриваєш крамницю посуду. Газети пишуть: держава друкує дедалі більше банкнот, щоб покрити свої витрати. Ціни на ринку вже повзуть угору. У тебе '+PN(S.w)+' карбованців.'+(S.tr>=60?' Постачальник Остап чув про тебе добре слово й пропонує частину товару з відстрочкою оплати.':''),q:'Як ти триматимеш статок цього року?',o:[
   {l:'Купити товар для крамниці: посуд, тканини, борошно',p:2,eff:S=>{S.f.hold='goods';},fb:'За рік ціни зросли на чверть — і твій товар подорожчав разом з ними. Карбованців за нього тепер дають більше, а купити на них можна стільки ж: лічильник статку не змінився.'},
   {l:'Купити товар, а ще на десяту частину взяти в Остапа з відстрочкою',when:S=>S.tr>=60,p:2,eff:S=>{S.w=Math.round(S.w*1.1/100)*100;S.f.hold='goods';S.f.credit=1;},fb:'Товар подорожчав разом із цінами. З Остапом розраховано вчасно, а додаткова партія дала заробіток — лічильник статку зріс. Відстрочку дають тим, кому довіряють.'},
   {l:'Половину вкласти в товар, половину тримати готівкою',when:S=>S.tr<60,p:1,eff:S=>{S.w=Math.round(S.w*0.9/100)*100;S.f.hold='half';},fb:'Ціни за рік зросли на чверть. Товарна половина зберегла вартість, готівкова — втратила п’яту частину купівельної спроможності. Разом лічильник статку «схуд» приблизно на десяту.'},
   {l:'Покласти все в банк під 10 % річних',p:1,eff:S=>{S.w=Math.round(S.w*0.88/100)*100;S.f.hold='bank';},fb:'Банк чесно нарахував 10 %, але ціни зросли на 25 %. Карбованців стало більше, а купити на них можна менше: відсоток був нижчий за інфляцію. Тому лічильник статку впав.'},
   {l:'Тримати банкноти в скрині: готівка надійніша за все',p:0,eff:S=>{S.w=Math.round(S.w*0.8/100)*100;S.f.hold='cash';},fb:'Жодна банкнота не зникла, але ціни зросли на чверть — і на ті самі гроші тепер можна купити на п’яту частину менше. Лічильник рахує не папірці, а те, що на них можна купити, тому він і впав.'}]},
  {id:'e3_power',t:'calc',head:'Епоха 3 · Що можуть гроші',text:S=>'Минув рік. Ціни зросли на 25 %. Торік мішок борошна коштував 80 карбованців. '+(S.f.hold==='cash'?'Твої '+PN(S.k3)+' карбованців увесь рік пролежали в скрині.':'Для порівняння: у сусіда-крамаря на початку року було стільки ж, скільки в тебе, — '+PN(S.k3)+' карбованців, і весь рік вони пролежали в скрині.'),q:S=>'Скільки мішків борошна можна купити на '+PN(S.k3)+' карбованців тепер?',ans:S=>S.k3/100,unit:'мішків',hint:'Спершу знайди нову ціну мішка: 80 і ще чверть від 80.',sol:S=>'Нова ціна: 80 + 80 × 0,25 = 100 карбованців. '+PN(S.k3)+' : 100 = '+PL(S.k3/100,'мішок','мішки','мішків')+'. Торік за кожні 400 карбованців давали 5 мішків, тепер — лише 4. Банкнот стільки ж, а купівельна спроможність упала на п’яту частину.'+(S.f.hold==='cash'?' Саме тому твій лічильник показує на п’яту частину менше.':S.f.hold==='bank'?' Твій вклад із 10 % втратив менше, ніж скриня сусіда, але теж не встиг за цінами.':S.f.hold==='half'?' Так само «схудла» і готівкова половина твого статку.':' Твій статок у товарі цього уникнув.')},
  {id:'e3_fake',t:'choice',head:'Епоха 3 · Велика банкнота',text:'У крамниці черга. Пан у капелюсі бере найдорожчий сервіз — лічильник оцінює його у 500 грн — і простягає одну велику банкноту. Папір якийсь гладенький, фарба блідіша, ніж зазвичай. Черга нетерпляче гуде.',q:'Що ти зробиш?',o:[
   {l:'Перевірити банкноту: глянути на просвіт, провести пальцем по малюнку, порівняти зі справжньою',p:2,eff:S=>{S.tr=Math.min(100,S.tr+5);S.f.check=1;},fb:'На просвіт не видно водяного знака, а малюнок на дотик зовсім гладкий. Ти повертаєш банкноту — пан квапливо зникає. Водяний знак, рельєфний друк, захисна стрічка — такі елементи захисту є й на сучасних гривнях.'},
   {l:'Узяти швидко, щоб не затримувати чергу',p:0,eff:S=>{S.w=Math.max(0,S.w-500);S.f.fake=1;},fb:'У банку банкноту визнали підробкою й вилучили без відшкодування. Сервіз поїхав із шахраєм: мінус 500 грн на лічильнику.'},
   {l:'Узяти, а ввечері розплатитися нею з постачальником — хай розбирається він',p:0,eff:S=>{S.w=Math.max(0,S.w-500);S.tr=Math.max(0,S.tr-20);S.f.fake=1;S.f.pass=1;},fb:'Постачальник помітив підробку одразу й банкноту не взяв. Свідомо збувати фальшиві гроші — злочин, навіть якщо перед тим обманули тебе. Мінус 500 грн на лічильнику й довіра ринку.'},
   {l:'Сказати, що великих банкнот не приймаєш, і відмовити панові',p:1,eff:S=>{S.f.noBig=1;},fb:'Підробка до тебе не потрапила, але так само доведеться відмовляти й чесним покупцям. Перевірити банкноту — надійніше, ніж не брати великих узагалі.'}]},
  {id:'ev3',t:'event',head:'Епоха 4 · Сьогодення',text:S=>'Останній стрибок — наш час. Лічильник показує '+PG(S.w)+', і тепер це звичайні гривні на твоєму рахунку. Ти ліпиш посуд і відкриваєш крамничку авторської кераміки: прилавок на ринку вихідного дня та сторінку в соцмережі. Гроші тепер бувають готівкові — банкноти й монети — і безготівкові: записи на банківських рахунках, якими керують карткою або телефоном.'+(S.f.fake?' Після історії з фальшивою банкнотою ти придивляєшся до кожної купюри.':'')},
  {id:'e4_pay',t:'choice',head:'Епоха 4 · Готівка чи картка',text:'Перші вихідні на ринку. Більшість покупців питає: «А карткою можна?» Банк пропонує термінал: комісія 2 % від кожної безготівкової оплати (за умовою задачі).',q:'Як ти прийматимеш оплату?',o:[
   {l:'І готівкою, і карткою',p:2,eff:S=>{S.tr=Math.min(100,S.tr+5);S.f.pay='both';},fb:'Кожен платить так, як йому зручно, і жоден покупець не йде через спосіб оплати. Комісія — плата за зручність і безпеку.'},
   {l:'Лише карткою: не треба здачі й не страшні підробки',p:1,eff:S=>{S.f.pay='card';},fb:'Зручно й безпечно, але бабуся, яка хотіла купити горнятко онуці, мала тільки готівку й пішла.'},
   {l:'Лише готівкою: навіщо віддавати банку 2 %',p:0,eff:S=>{S.f.pay='cash';},fb:'Комісію збережено, але ті, хто не носить із собою готівки, проходять повз твій прилавок.'}]},
  {id:'e4_fee',t:'calc',head:'Епоха 4 · Виторг вихідних',text:S=>'За вихідні до прилавка підійшло 30 покупців, готових купити. Середня покупка — 500 грн; із кожної покупки 100 грн — твій прибуток, решта йде на глину, випал і місце на ринку. '+(S.f.pay==='both'?'20 покупців платять карткою, 10 — готівкою. З карткових оплат банк утримує 2 %.':S.f.pay==='card'?'5 покупців мали лише готівку й пішли. Решта 25 платять карткою, і з цих оплат банк утримує 2 %.':'10 покупців не мали готівки й пішли. Решта 20 платять готівкою.'),q:S=>S.f.pay==='cash'?'Скільки гривень виторгу ти отримаєш за вихідні?':'Скільки гривень виторгу ти отримаєш за вихідні після комісії банку?',ans:S=>S.f.pay==='both'?14800:S.f.pay==='card'?12250:10000,unit:'грн',hint:S=>S.f.pay==='cash'?'Помнож кількість покупців, які справді купили, на середню покупку.':'Знайди суму карткових оплат, обчисли 2 % від неї й відніми від усього виторгу.',sol:S=>S.f.pay==='both'?'Усього: 30 × 500 = 15 000 грн. Карткою: 20 × 500 = 10 000 грн, комісія 2 % — 200 грн. 15 000 − 200 = 14 800 грн. Прибуток: 30 × 100 − 200 = 2 800 грн — на стільки зростає статок.':S.f.pay==='card'?'Купили 25 покупців: 25 × 500 = 12 500 грн. Комісія 2 % — 250 грн. 12 500 − 250 = 12 250 грн. Прибуток: 25 × 100 − 250 = 2 250 грн — на стільки зростає статок. Якби приймати ще й готівку, прибуток був би 2 800 грн.':'Купили 20 покупців: 20 × 500 = 10 000 грн. Комісії немає, але 10 покупців пішли: щоб не віддати банку 200 грн, втрачено 5 000 грн виторгу. Прибуток: 20 × 100 = 2 000 грн — на стільки зростає статок. З терміналом прибуток був би 2 800 грн.',eff:S=>{if(!S.f.sold){S.f.sold=1;S.w+=S.f.pay==='both'?2800:S.f.pay==='card'?2250:2000;}}},
  {id:'e4_scam',t:'choice',head:'Епоха 4 · Дзвінок «із банку»',text:'Увечері дзвонить телефон: «Служба безпеки банку. З вашої картки просто зараз намагаються зняти гроші! Щоб заблокувати операцію, назвіть код із SMS». Голос упевнений, на фоні шумить офіс, а SMS із кодом справді щойно прийшла.',q:'Що ти зробиш?',o:[
   {l:'Покласти слухавку й зателефонувати до банку за номером на звороті картки',p:2,eff:S=>{S.f.safe=1;},fb:'У банку підтвердили: жодних операцій не було. Справжній працівник банку ніколи не питає код із SMS, PIN чи три цифри зі звороту картки.'},
   {l:'Назвати код — гроші ж треба рятувати негайно',p:0,eff:S=>{S.w=Math.round(S.w*2/3/100)*100;S.f.scam=1;},fb:'Код був підтвердженням переказу. За хвилину з рахунку зникла приблизно третина твоїх грошей. Шахраї завжди квапять, щоб людина не встигла подумати.'},
   {l:'Коду не казати, але продиктувати номер картки й строк дії «для перевірки»',p:1,eff:S=>{S.w=Math.max(0,S.w-400);S.f.half=1;},fb:'Код лишився в таємниці, тож переказ не пройшов. Але з номером картки шахраї спробували оплатити покупку в інтернеті: картку довелося заблокувати й перевипустити. Поки тривала заміна, зірвалося замовлення зі сторінки в соцмережі: мінус 400 грн.'}]},
  {id:'e4_save',t:'choice',head:'Епоха 4 · Де тримати заощадження',text:S=>'Сезон завершено: у тебе '+PG(S.w)+'. За рік ти плануєш обладнати власну майстерню: піч, гончарне коло, глазурі. Приміщення звільниться лише за рік, тож гроші мають дочекатися. Прогноз інфляції на рік — 10 % (за умовою задачі).'+(S.f.hold==='cash'?' Ти добре пам’ятаєш, як скриня з банкнотами «схудла» на п’яту частину.':S.f.hold==='bank'?' Ти пам’ятаєш вклад під 10 %, коли ціни росли на 25 %: відсоток треба порівнювати з інфляцією.':S.f.hold==='half'?' Ти пам’ятаєш, як готівкова половина статку «схудла», а товарна — ні.':' У часи карбованців тебе виручив товар, але цього разу купити все наперед не вийде.'),q:'Де ти триматимеш гроші цей рік?',o:[
   {l:'На банківському вкладі під 12 % річних (за умовою задачі)',p:2,eff:S=>{S.f.save='dep';S.w0=S.w;},fb:'Вклади в банках гарантує держава, а відсоток вищий за прогноз інфляції — гроші мають устигнути за цінами.'},
   {l:'На картковому рахунку: завжди під рукою',p:1,eff:S=>{S.f.save='card';S.w0=S.w;},fb:'Від злодіїв гроші захищені, але відсотків на них немає — а ціни тим часом ростимуть.'},
   {l:'Зняти й сховати готівкою вдома',p:0,eff:S=>{S.f.save='cash';S.w0=S.w;},fb:'Відсотків на ці гроші немає, а ціни ростимуть — як колись у часи карбованців. До того ж готівку вдома можна втратити через крадіжку чи пожежу, і вона легко розходиться на дрібниці.'},
   {l:'Третину вкласти в «криптомонету» знайомого, яка «точно подвоїться за місяць»',p:0,eff:S=>{S.w=Math.round(S.w*2/3/100)*100;S.f.save='card';S.f.coin=1;S.w0=S.w;},fb:'Сайт «монети» зник за тиждень разом із третиною твоїх грошей. Обіцянка швидко подвоїти гроші без ризику — головна ознака шахрайства. Решта лишилася на картці без відсотків.'}]},
  {id:'e4_real',t:'calc',head:'Епоха 4 · Рік потому',text:S=>'Список покупок для майстерні — піч, гончарне коло, глазурі — складено ще торік, рівно на всі тодішні гроші: '+PG(S.w0)+'. Минув рік, і все зі списку подорожчало на 10 %. '+(S.f.save==='dep'?'Вклад за цей час зріс на 12 %.':S.f.save==='cash'?'Гроші лежали вдома готівкою, без відсотків, і 300 грн зі схованки розійшлося на дрібниці.':'Гроші лежали на картковому рахунку без відсотків.'),q:S=>S.f.save==='dep'?'Скільки гривень залишиться після купівлі всього зі списку?':'Скільки гривень бракує, щоб купити все зі списку?',ans:S=>Math.round(S.w0*(S.f.save==='dep'?0.02:0.1))+(S.f.save==='cash'?300:0),unit:'грн',hint:S=>S.f.save==='dep'?'Знайди суму на вкладі через рік (плюс 12 %) і нову ціну списку (плюс 10 %), потім порівняй.':S.f.save==='cash'?'Знайди нову ціну списку (плюс 10 %) і суму, яка лишилася в схованці, потім порівняй.':'Знайди, на скільки гривень подорожчав список: це 10 % від його ціни.',sol:S=>S.f.save==='dep'?'Вклад: '+PN(S.w0)+' × 1,12 = '+PG(Math.round(S.w0*1.12))+'. Список: '+PN(S.w0)+' × 1,1 = '+PG(Math.round(S.w0*1.1))+'. '+PN(Math.round(S.w0*1.12))+' − '+PN(Math.round(S.w0*1.1))+' = '+PG(Math.round(S.w0*0.02))+' залишиться: відсоток випередив інфляцію.':S.f.save==='cash'?'Список: '+PN(S.w0)+' × 1,1 = '+PG(Math.round(S.w0*1.1))+'. У схованці: '+PN(S.w0)+' − 300 = '+PG(S.w0-300)+'. Бракує '+PN(Math.round(S.w0*1.1))+' − '+PN(S.w0-300)+' = '+PG(Math.round(S.w0*0.1)+300)+'. Частину грошей «з’їла» інфляція, частину — дрібні витрати.':'Список подорожчав на 10 %: '+PN(S.w0)+' × 0,1 = '+PG(Math.round(S.w0*0.1))+'. На рахунку, як і було, '+PG(S.w0)+', тож саме стільки й бракує. Гривень не поменшало — поменшало того, що на них можна купити.',eff:S=>{if(!S.f.yr){S.f.yr=1;S.need=Math.round(S.w0*1.1);S.w=S.f.save==='dep'?Math.round(S.w0*1.12):S.f.save==='cash'?Math.max(0,S.w0-300):S.w0;}}}],
 finish:S=>{const ok=S.w>=S.need,lvl=ok&&S.w>=5000&&S.tr>=50&&!S.f.scam&&!S.f.coin?2:S.w>=3000&&S.tr>=35?1:0;
  const lost=[];if(S.f.clip)lost.push('купець з обрізаними монетами');if(S.f.fake)lost.push('покупець із фальшивою банкнотою');if(S.f.scam||S.f.half)lost.push('«служба безпеки банку»');if(S.f.coin)lost.push('«монета, що подвоїться»');
  return{level:lvl,title:['Статок розгубився дорогою крізь епохи','Статок уцілів, але з втратами','Статок пройшов з тобою крізь усі епохи'][lvl],text:'На початку в тебе було 12 горщиків — 6 000 грн за лічильником. Наприкінці подорожі: статок — '+PG(S.w)+', довіра до тебе — '+PL(S.tr,'бал','бали','балів')+'. Список для майстерні тепер коштує '+PG(S.need)+': '+(ok?'грошей вистачає'+(S.w>S.need?', ще й лишається '+PG(S.w-S.need):'')+'.':'бракує '+PG(S.need-S.w)+'.'),tips:[S.f.store==='silver'&&S.f.hold==='goods'?'Для заощаджень ти щоразу обираєш те, що добре зберігає вартість: срібло замість риби, товар замість банкнот під час інфляції.':'Частина статку зникла не через крадіїв, а через те, у чому він зберігався. Питай себе: що станеться з цією формою грошей за рік?',lost.length?'Гроші в тебе забирали ті, хто квапив або обіцяв легку вигоду: '+lost.join(', ')+'. Наступного разу спершу зупинись і перевір.':S.f.weigh&&S.f.check&&S.f.safe?'Перевірка грошей стала твоєю звичкою в кожній епосі: терези для монет, банкнота на просвіт, дзвінок до банку замість коду з SMS. Форма грошей змінюється, а звичка перевіряти — ні.':'Обману вдалося уникнути. Та перевірити гроші — зважити монети, глянути банкноту на просвіт — вигідніше, ніж просто відмовитися від угоди.',S.f.save==='dep'?'Відсоток за вкладом був вищий за інфляцію, тож гроші встигли за цінами: на майстерню вистачило.':S.f.coin?'Третина заощаджень зникла разом із «монетою», а решта лежала без відсотків, поки ціни росли на 10 %. Порівнюй відсоток за вкладом з інфляцією й не вір обіцянкам подвоїти гроші.':S.f.save==='cash'?'Готівка вдома не дала відсотків і потроху розійшлася, а ціни за рік зросли на 10 % — на майстерню вже не вистачає. Порівнюй відсоток за вкладом з інфляцією.':'Гривень на рахунку не поменшало, але ціни за рік зросли на 10 % — і на майстерню вже не вистачає. Порівнюй відсоток за вкладом з інфляцією.']};},
 terms:[['Бартер','прямий обмін товару на товар без використання грошей'],['Функції грошей','міра вартості, засіб обміну, засіб платежу та засіб нагромадження'],['Інфляція','тривале зростання цін, через яке на ту саму суму грошей можна купити менше'],['Купівельна спроможність','кількість товарів і послуг, яку можна придбати за певну суму грошей'],['Безготівкові розрахунки','оплата без банкнот і монет — переказом коштів між банківськими рахунками, зокрема карткою']]});

PFG_TOPICS.push({id:'8-2',sec:'8a',title:'Фінансова поведінка',minutes:30,
 intro:'Чотири тижні ти розпоряджаєшся власними кишеньковими грошима й збираєш на бездротові навушники. На тебе чекають знижки, друзі з різними характерами, пропозиція «подвоїти гроші», рахунок родини за світло й несподіванки воєнного часу. Звички, які ти обереш першого тижня, визначать, скільки грошей і які можливості матимеш в останньому.',
 init:()=>({save:1400,bill:1296,sc:40,debt:0,wk:0,fun:0,real:0,kwh:300,bonus:0,cutv:0,s4:0,pay4:0,end4:0,f:{}}),
 meters:[{k:'save',label:'Скарбничка',unit:'грн'},{k:'debt',label:'Борг',unit:'грн'},{k:'bill',label:'Рахунок родини за світло',unit:'грн'},{k:'sc',label:'Самоконтроль (зі 100)',unit:'балів'}],
 steps:[
  {id:'w1_need',t:'calc',head:'Тиждень 1 · Ціль',text:'Понеділок. Щотижня батьки дають тобі 800 грн. З них 150 грн іде на проїзд і 300 грн — на шкільні обіди (по 60 грн на день). Ти мрієш про бездротові навушники за 2 000 грн. У скарбничці вже є 1 400 грн, а до кінця місяця — 4 тижні.',q:'Скільки гривень треба відкладати щотижня, щоб устигнути?',ans:S=>150,unit:'грн',hint:'Спершу знайди, скільки бракує до 2 000 грн, потім поділи на кількість тижнів.',sol:S=>'Бракує: 2 000 − 1 400 = 600 грн. 600 : 4 = 150 грн на тиждень. Вільних грошей у тебе 800 − 150 − 300 = 350 грн на тиждень, тож ціль досяжна — якщо не збитися з плану.'},
  {id:'w1_plan',t:'plan',head:'Тиждень 1 · План на тиждень',text:'Після проїзду й обідів у тебе щотижня лишається 350 грн вільних грошей. Розподіли їх повністю. Цього плану ти триматимешся весь місяць.',q:'Скільки гривень на кожну статтю?',
   fields:[{k:'put',label:'Відкласти на навушники'},{k:'fun',label:'Розваги з друзями'},{k:'snack',label:'Смаколики й дрібниці'}],
   total:S=>350,
   best:S=>({put:150,fun:150,snack:50}),
   check:(S,v)=>v.put<50?'На ціль варто відкладати хоча б 50 грн на тиждень: інакше скарбничка не ростиме зовсім.':null,
   eff:(S,v)=>{S.wk=v.put;S.fun=v.fun;S.real=v.put;if(v.put<100)S.sc=Math.max(0,S.sc-5);},
   score:(S,v)=>v.put>=150&&v.fun+v.snack>=50?{p:2,fb:'Відкладеного вистачить, щоб зібрати на ціль за 4 тижні, і при цьому лишаються гроші на радість. Такий план реально виконати.'}:v.put>=150?{p:1,fb:'На ціль вистачить із запасом, але на розваги й дрібниці не лишилося майже нічого. План, у якому немає жодної радості, зазвичай зривається вже на другому тижні.'}:v.put>=100?{p:1,fb:'За такого темпу за 4 тижні збереться менше, ніж потрібні 600 грн. На навушники доведеться чекати довше або шукати додаткові гроші.'}:{p:0,fb:'Майже всі вільні гроші підуть на поточні бажання. Скарбничка за місяць майже не зросте.'}},
  {id:'w1_habit',t:'choice',head:'Тиждень 1 · Коли відкладати',text:S=>(S.wk>0?'План є: '+PG(S.wk)+' на тиждень — у скарбничку.':'У плані на скарбничку поки нічого.')+' Але в понеділок усі гроші ще в гаманці. Твій друг Марко каже: «Я відкладаю те, що лишається в п’ятницю». У нього зазвичай не лишається нічого. Подруга Соля, навпаки, рахує кожну гривню.',q:'Коли ти відкладатимеш гроші?',o:[
   {l:'У понеділок, одразу: спершу в скарбничку, а витрачати — решту',p:2,eff:S=>{S.f.first=1;S.real=S.wk;S.sc=Math.min(100,S.sc+10);},fb:'Гроші, які вже лежать у скарбничці, не спокушають. Тепер план виконується сам собою — щотижня повна сума.'},
   {l:'Половину — в понеділок, половину — в п’ятницю, якщо залишиться',p:1,eff:S=>{S.f.half=1;S.real=Math.max(0,S.wk-50);},fb:S=>S.wk<=0?'У плані на скарбничку нічого немає, тож і відкладати поки нічого.':'Перша половина в безпеці. А от «п’ятнична» частина до п’ятниці зазвичай тане: щотижня до скарбнички доходитиме '+PG(Math.max(0,S.wk-50))+' замість '+PG(S.wk)+'.'},
   {l:'У п’ятницю: що залишиться, те й відкладу',p:0,eff:S=>{S.f.last=1;S.real=Math.max(0,S.wk-100);S.sc=Math.max(0,S.sc-5);},fb:S=>S.wk<=0?'У плані на скарбничку нічого немає, а в п’ятницю в гаманці теж нічого не лишиться.':'Гроші в гаманці витрачаються легко й непомітно. Щотижня до скарбнички доходитиме '+PG(Math.max(0,S.wk-100))+' замість '+PG(S.wk)+' за планом.'}]},
  {id:'w1_track',t:'choice',head:'Тиждень 1 · Облік',text:'Соля показує нотатки в телефоні: вона записує кожну витрату, а в неділю дивиться підсумок за тиждень. «Спочатку нудно, — каже вона, — потім цікаво».',q:'Як ти стежитимеш за своїми витратами?',o:[
   {l:'Записувати витрати щодня й підбивати підсумок у неділю',p:2,eff:S=>{S.f.track=1;S.sc=Math.min(100,S.sc+10);},fb:'Хвилина на день — і ти бачитимеш, куди насправді йдуть гроші, а не куди тобі здається.'},
   {l:'Зберігати чеки й сповіщення, а рахувати — якщо знадобиться',p:1,eff:S=>{S.f.semi=1;},fb:'Дані є, але без підсумку вони нічого не підказують. Відновлювати тиждень заднім числом довго й неточно.'},
   {l:'Не записувати: суми малі, і так усе пам’ятаю',p:0,eff:S=>{S.sc=Math.max(0,S.sc-5);},fb:'Великі покупки пам’ять тримає, дрібні — губить. А саме з дрібних зазвичай і складається «не знаю, куди поділися гроші».'}]},
  {id:'w1_sale',t:'choice',head:'Тиждень 1 · Знижка «лише сьогодні»',text:'Четвер. У торговому центрі — табличка «−50 % лише сьогодні»: яскравий чохол для телефона коштує 200 грн замість 400. Твій старий чохол цілий. Марко підштовхує: «Бери, завтра такої ціни не буде!»',q:'Що ти зробиш?',o:[
   {l:'Записати чохол у список бажань і повернутися до нього за 24 години',p:2,eff:S=>{S.f.rule=1;S.sc=Math.min(100,S.sc+5);},fb:'Наступного дня чохол уже не здавався таким потрібним. Знижка на річ, без якої можна обійтися, — це не «заощаджено 200 грн», а «витрачено 200 грн».'},
   {l:'Купити, а на вихідних відмовитися від розваг',p:1,eff:S=>{S.save=Math.max(0,S.save-Math.max(0,200-S.fun));S.f.swap=1;},fb:S=>S.fun>=200?'Чохол куплено за гроші, призначені на розваги: скарбничка ціла, але вихідні минули без друзів. Імпульсивну покупку довелося оплатити чимось іншим.':S.fun>0?'На розваги в плані було лише '+PG(S.fun)+', тож решту — '+PG(200-S.fun)+' — довелося взяти зі скарбнички. Імпульсивна покупка завжди оплачується чимось іншим.':'На розваги в плані не було нічого, тож усі 200 грн довелося взяти зі скарбнички. Імпульсивна покупка завжди оплачується чимось іншим.'},
   {l:'Купити: така знижка буває рідко',p:0,eff:S=>{S.save=Math.max(0,S.save-200);S.sc=Math.max(0,S.sc-10);S.f.imp=1;},fb:'Цієї покупки в плані не було, тож 200 грн пішло зі скарбнички. Продавці добре знають, що слова «лише сьогодні» вимикають роздуми.'}]},
  {id:'ev_w1',t:'event',head:'Тиждень 1 · Підсумок',text:S=>'Неділя. '+(S.real>0?'За тиждень у скарбничку потрапляє '+PG(S.real)+'.':'За тиждень у скарбничку не потрапляє нічого.')+(S.wk<=0?'':S.f.first?' Їх відкладено ще в понеділок, тож до кінця тижня про них можна було не згадувати.':' У плані було '+PG(S.wk)+', але до п’ятниці частина розійшлася на дрібниці.')+(S.f.imp||S.f.swap?' А новий чохол уже лежить у шухляді: старий виявився зручнішим.':''),eff:S=>{S.save+=S.real;}},
  {id:'w2_leak',t:'calc',head:'Тиждень 2 · Куди зникають гроші',text:S=>'Другий тиждень. У скарбничці '+PG(S.save)+'. '+(S.f.track?'Недільний підсумок твоїх записів показує несподіване: з 60 грн на обід сам обід коштує 40 грн, а ще 20 грн щодня йде на солодкий напій з автомата.':'Куди розходяться гроші на обіди, ти точно не знаєш. Лише в четвер Соля допомагає відновити витрати '+(S.f.semi?'за твоїми чеками':'за сповіщеннями банку')+': з 60 грн на обід сам обід коштує 40 грн, а ще 20 грн щодня йде на солодкий напій з автомата.')+' У навчальному тижні 5 днів.',q:'Скільки гривень іде на напої за 4 тижні?',ans:S=>400,unit:'грн',hint:'Знайди витрати за один тиждень, потім помнож на кількість тижнів.',sol:S=>'За тиждень: 20 × 5 = 100 грн. За 4 тижні: 100 × 4 = 400 грн — це п’ята частина ціни навушників. Дрібна щоденна витрата за місяць перетворюється на велику.'},
  {id:'w2_cut',t:'choice',head:'Тиждень 2 · Що робити з «дрібницею»',text:S=>'400 грн на місяць — на напої, яких ти навіть не пам’ятаєш.'+(S.f.track?' Без записів це так і лишилося б непоміченим.':' Із записами це було б видно ще в неділю, а тепер тиждень майже минув.'),q:'Що ти зміниш?',o:[
   {l:'Носити воду з дому, а 100 грн щотижня додавати в скарбничку',p:2,eff:S=>{S.cutv=100;S.f.cut=2;S.sc=Math.min(100,S.sc+5);if(S.f.track)S.real+=100;},fb:S=>S.f.track?'Звичка змінилася — і вже з цього тижня в скарбничку йде на 100 грн більше. Нічого важливого при цьому не втрачено.':'Звичка змінилася, але цього тижня гроші на напої вже витрачено. На 100 грн більше в скарбничку піде з наступного тижня.'},
   {l:'Брати менший напій — за 10 грн',p:1,eff:S=>{S.cutv=50;S.f.cut=1;if(S.f.track)S.real+=50;},fb:S=>'Половину витрат прибрано: плюс 50 грн до скарбнички щотижня'+(S.f.track?'':' — щоправда, лише з наступного тижня')+'. Друга половина й далі спливає непомітно.'},
   {l:'Нічого: на таких дрібницях не розбагатієш',p:0,eff:S=>{S.sc=Math.max(0,S.sc-5);},fb:'20 грн справді дрібниця. Але 400 грн на місяць — це вже п’ята частина навушників.'}]},
  {id:'w2_friends',t:'choice',head:'Тиждень 2 · Друзі кличуть',text:S=>'П’ятниця. Друзі збираються в кіно, а потім на піцу — разом вийде 350 грн з кожного. Марко: «Та не будь занудою, один раз живемо!»'+(S.f.track?' За твоїми записами, на розваги цього тижня в плані '+PG(S.fun)+'.':' Скільки в тебе лишилося на розваги цього тижня, ти точно не знаєш.'),q:'Як ти вчиниш?',o:[
   {l:'Запропонувати інший план: кіновечір удома в Солі, кожен приносить щось до столу',p:2,eff:S=>{S.sc=Math.min(100,S.sc+5);S.f.alt=1;},fb:'Вечір вийшов не гіршим, а коштував пачку печива. Дружба не вимірюється сумою в чеку — і друзі це зрозуміли.'},
   {l:'Піти тільки в кіно на денний сеанс за 120 грн, без піци',p:S=>S.fun>=120?2:1,eff:S=>{S.save=Math.max(0,S.save-Math.max(0,120-S.fun));S.f.cinema=1;},fb:S=>S.fun>=120?'Квиток уклався в гроші, заплановані на розваги, і скарбничка не постраждала. Бути з друзями й триматися плану можна одночасно.':S.fun>0?'Розумний компроміс, але на розваги в плані було лише '+PG(S.fun)+': ще '+PG(120-S.fun)+' довелося взяти зі скарбнички.':'Розумний компроміс, але на розваги в плані не було нічого: усі 120 грн довелося взяти зі скарбнички.'},
   {l:'Піти з усіма, а чого не вистачить — узяти зі скарбнички',p:0,eff:S=>{S.save=Math.max(0,S.save-Math.max(0,350-S.fun));S.sc=Math.max(0,S.sc-10);S.f.party=1;},fb:S=>S.fun>=350?'Вечір був веселий і вклався в гроші на розваги. Та якщо на розваги йде все, що могло б іти на ціль, навушники ще довго лишатимуться мрією.':'Вечір був веселий, але зі скарбнички пішло '+PG(350-S.fun)+'. Рішення «як усі» ухвалюють швидко, а оплачують потім довго.'}]},
  {id:'w2_energy',t:'choice',head:'Тиждень 2 · Рахунок за світло',text:'Увечері тато розгортає рахунок за електроенергію: за місяць родина спожила 300 кВт·год і заплатила 1 296 грн. «Енергосистема країни пошкоджена через війну, електрики бракує, — каже він. — Заощаджувати зараз — це і про гроші, і про те, щоб світла вистачило всім. Пропоную угоду: зменшимо споживання — половину зекономленого віддаю тобі».',q:'Що ти запропонуєш?',o:[
   {l:'Скласти з родиною перелік звичок: прати з повним барабаном, гріти бойлер за таймером, вимикати прилади з розеток, замінити старі лампи',p:2,eff:S=>{S.f.en=2;S.kwh=250;S.sc=Math.min(100,S.sc+5);},fb:'Найбільше електрики беруть прилади, що гріють: бойлер, плита, пральна машина. Саме тому кілька спільних звичок помітно зменшують споживання — у вашій родині на 50 кВт·год за місяць.'},
   {l:'Вимикати у своїй кімнаті світло, комп’ютер і обігрівач, коли виходиш',p:1,eff:S=>{S.f.en=1;S.kwh=275;},fb:'Це теж економія — близько 25 кВт·год за місяць. Але головні споживачі в домі — бойлер, пральна машина й плита — працюють як і раніше.'},
   {l:'Нічого не міняти: один підліток на рахунок не впливає',p:0,eff:S=>{S.f.en=0;S.kwh=300;},fb:'Рахунок залишиться таким самим, а татова пропозиція — невикористаною. Споживання родини складається зі звичок кожного, і твоїх також.'}]},
  {id:'w2_bill',t:'calc',head:'Тиждень 2 · Скільки заплатить родина',text:S=>(S.f.en===2?'Тато прикидає: з новими звичками родина спожиє за місяць 250 кВт·год замість 300.':S.f.en===1?'Тато прикидає: якщо у твоїй кімнаті ніщо не працюватиме даремно, родина спожиє 275 кВт·год замість 300.':'Звички не змінилися, тож родина знову спожиє 300 кВт·год.')+' Тариф — 4,32 грн за 1 кВт·год (за умовою задачі).',q:'Скільки гривень родина заплатить за світло цього місяця?',ans:S=>Math.round(S.kwh*4.32),unit:'грн',hint:'Помнож кількість кіловат-годин на тариф.',sol:S=>PN(S.kwh)+' × 4,32 = '+PG(Math.round(S.kwh*4.32))+'.'+(S.kwh<300?' Минулого місяця було 1 296 грн, тож економія — 1 296 − '+PN(Math.round(S.kwh*4.32))+' = '+PG(1296-Math.round(S.kwh*4.32))+'. Твоя половина — '+PG((1296-Math.round(S.kwh*4.32))/2)+': тато віддасть її наприкінці місяця.':' Стільки ж, як і минулого місяця: економії немає, ділити нічого.'),eff:S=>{S.bill=Math.round(S.kwh*4.32);S.bonus=(1296-S.bill)/2;}},
  {id:'ev_w2',t:'event',head:'Тиждень 2 · Підсумок',text:S=>'Неділя. '+(S.real>0?'Цього тижня в скарбничку йде '+PG(S.real)+'.':'Цього тижня в скарбничку не йде нічого.')+(S.cutv>0?(S.f.track?' У цій сумі вже є гроші, які раніше йшли на напої.':' Гроші, які йшли на напої, додадуться з наступного тижня: цього разу звичку помічено запізно.'):'')+(S.f.party?' Про кіно з піцою нагадують лише фото в телефоні.':S.f.alt?' Друзі вже питають, коли наступний кіновечір у Солі.':''),eff:S=>{S.save+=S.real;if(!S.f.track&&S.cutv>0&&!S.f.late){S.f.late=1;S.real+=S.cutv;}}},
  {id:'w3_double',t:'choice',head:'Тиждень 3 · «Подвой свої гроші»',text:S=>'Третій тиждень, понеділок. У скарбничці '+PG(S.save)+'. У чаті класу дев’ятикласник Артем пише: «Є тема. Скидаєш 300 грн — за три дні отримуєш 600. Троє вже отримали, ось скріни». Марко вже переказав і радить тобі не баритися.',q:'Що ти зробиш?',o:[
   {l:'Спитати Артема, звідки береться прибуток, нічого не переказувати й розповісти про це батькам',p:2,eff:S=>{S.sc=Math.min(100,S.sc+5);S.f.told=1;},fb:'Пояснити, звідки прибуток, Артем не зміг. У таких схемах першим учасникам платять грошима наступних — доки не скінчаться новачки. Твої гроші цілі, а дорослі встигли попередити інших.'},
   {l:'Просто проігнорувати повідомлення',p:1,eff:S=>{S.f.ign=1;},fb:'Твої гроші цілі. Але ще кілька однокласників переказали свої — якби про це вчасно дізналися дорослі, втрат було б менше.'},
   {l:'Переказати 300 грн: скріни ж справжні',when:S=>S.save>=300,p:0,eff:S=>{S.save-=300;S.sc=Math.max(0,S.sc-15);S.f.pyr=1;},fb:'За три дні Артем видалив чат. Скріни були справжні: першим трьом справді заплатили — грошима тих, хто прийшов пізніше, зокрема твоїми й Марковими. Обіцянка подвоїти гроші без ризику — ознака шахрайства.'},
   {l:'Позичити в Солі 300 грн і вкласти їх — зі скарбнички брати шкода',p:0,eff:S=>{S.debt+=300;S.sc=Math.max(0,S.sc-15);S.f.pyr=1;S.f.owe=1;},fb:'За три дні Артем видалив чат, і грошей ніхто не побачив. А борг Солі залишився — його доведеться повертати зі скарбнички. Ризикувати позиченим — найдорожчий спосіб помилитися.'}]},
  {id:'w3_lend',t:'choice',head:'Тиждень 3 · Марко просить позичити',text:S=>'Четвер. Марко втратив в Артема 300 грн і тепер просить у тебе 200 грн «до понеділка». Соля тихо каже, що їй він винен 150 грн ще з минулого місяця.'+(S.f.owe?' Тобі зараз теж невесело: разом з Артемом зникли й 300 грн, позичені в Солі.':S.f.pyr?' Тобі зараз теж невесело: разом з Артемом зникли й твої 300 грн.':''),q:'Як ти відповіси?',o:[
   {l:'Не позичати, а запропонувати Маркові разом розписати його тиждень: що обов’язкове, а що зачекає',p:2,eff:S=>{S.sc=Math.min(100,S.sc+5);S.f.helpM=1;},fb:'Марко спершу образився, але план склав — і вперше дотягнув кишенькові до п’ятниці. Щедрість і легковажність — різні риси характеру.'},
   {l:'Позичити 100 грн і чітко домовитися: поверне в понеділок',p:1,eff:S=>{S.f.lent=1;},fb:'У понеділок Марко повернув 100 грн — невелика сума й чітка домовленість спрацювали. Та причина його вічного «не вистачає» нікуди не поділася.'},
   {l:'Позичити всі 200 грн без жодних умов: друзів у біді не кидають',p:0,eff:S=>{S.save=Math.max(0,S.save-200);S.f.lost=1;},fb:'У понеділок Марко розвів руками: «Наступного тижня, чесно». Хто вже має борги й не планує витрат, рідко повертає вчасно. Скарбничка поки що на 200 грн легша.'}]},
  {id:'w3_emerg',t:'choice',head:'Тиждень 3 · Відключення',text:S=>'П’ятниця. У місті аварійні відключення: світла немає по 8 годин поспіль. Старий павербанк родини не тримає заряд, а без зарядженого телефона не дізнаєшся ні про повітряну тривогу, ні про зміни в розкладі уроків. Новий павербанк коштує 400 грн. Мама питає: «Скинемося навпіл? Твоя частка — 200 грн». У скарбничці '+PG(S.save)+'.',q:'Що ти вирішиш?',o:[
   {l:'Дати 200 грн зі скарбнички: зв’язок і безпека важливіші за навушники',p:2,eff:S=>{S.save=Math.max(0,S.save-200);S.sc=Math.min(100,S.sc+5);S.f.pb=1;},fb:'У воєнний час резерв на непередбачене — така сама частина плану, як і ціль. Навушники трохи відсунулися, зате родина на зв’язку.'},
   {l:'Сказати, що скарбничка — лише на навушники, нехай купують батьки',p:1,eff:S=>{S.sc=Math.max(0,S.sc-5);S.f.nopb=1;},fb:'Батьки купили павербанк самі, і твоя скарбничка ціла. Але у воєнний час плани доводиться переглядати всім: безпека родини — спільна справа.'},
   {l:'Купити на ринку павербанк за 100 грн, без гарантії та чека',p:0,eff:S=>{S.save=Math.max(0,S.save-100);S.f.cheap=1;},fb:'Він перестав заряджати на третій день, а повернути його без чека не вдалося. Гроші витрачено, проблема лишилася: найдешевше не завжди найвигідніше.'}]},
  {id:'ev_w3',t:'event',head:'Тиждень 3 · Підсумок',text:S=>{const pay=Math.min(S.debt,S.save+S.real);return 'Неділя. '+(S.real>0?'Цього тижня в скарбничку йде '+PG(S.real)+'.':'Цього тижня в скарбничку не йде нічого.')+(S.f.pb?' Новий павербанк уже двічі виручив під час відключень.':S.f.cheap?' Дешевий павербанк лежить у шухляді мертвим вантажем.':'')+(S.debt>0?(pay>=S.debt?' Соля нагадала про '+PG(S.debt)+', позичені на «подвоєння»: борг повернуто зі скарбнички.':' Соля нагадала про '+PG(S.debt)+', позичені на «подвоєння». Стільки в скарбничці немає: ти віддаєш '+PG(pay)+', а решту — '+PG(S.debt-pay)+' — обіцяєш повернути за тиждень.'):'')+' Попереду останній тиждень.';},eff:S=>{if(S.f.w3)return;S.f.w3=1;S.save+=S.real;if(S.debt>0){const pay=Math.min(S.debt,S.save);S.save-=pay;S.debt-=pay;}S.s4=S.save;S.pay4=Math.min(S.debt,S.save+S.real+S.bonus);S.end4=S.save+S.real+S.bonus-S.pay4;}},
  {id:'w4_sum',t:'calc',head:'Тиждень 4 · Що буде в неділю',text:S=>'Початок четвертого тижня. У скарбничці '+PG(S.s4)+'.'+(S.real>0?' Цього тижня до неї додасться ще '+PG(S.real)+'.':' Цього тижня з кишенькових до неї не додасться нічого.')+(S.bonus>0?' А в п’ятницю тато віддасть твою половину економії на світлі — '+PG(S.bonus)+'.':' Економії на світлі немає, тож від тата нічого не додасться.')+(S.pay4>0?' Із цих грошей треба повернути Солі решту боргу — '+PG(S.pay4)+'.':''),q:'Скільки гривень буде в скарбничці наприкінці тижня?',ans:S=>S.end4,unit:'грн',hint:S=>(S.bonus>0?'До суми в скарбничці додай те, що відкладеш за тиждень, і свою половину економії.':'До суми в скарбничці додай те, що відкладеш за тиждень.')+(S.pay4>0?' Потім відніми борг.':''),sol:S=>S.end4===S.s4?'Цього тижня нічого не додається, тож у скарбничці так і лишиться '+PG(S.end4)+'. До 2 000 грн бракує '+PG(Math.max(0,2000-S.end4))+'.':PN(S.s4)+(S.real>0?' + '+PN(S.real):'')+(S.bonus>0?' + '+PN(S.bonus):'')+(S.pay4>0?' − '+PN(S.pay4):'')+' = '+PG(S.end4)+'. '+(S.end4>=2000?'На навушники за 2 000 грн вистачає.':'До 2 000 грн бракує '+PG(2000-S.end4)+'.'),eff:S=>{if(S.f.w4)return;S.f.w4=1;S.save=S.end4;S.debt=Math.max(0,S.debt-S.pay4);}},
  {id:'w4_donate',t:'choice',head:'Тиждень 4 · Збір',text:S=>'Клас збирає гроші на павербанки для військового госпіталю: класна керівниця дала реквізити офіційного рахунку благодійного фонду. А в соцмережах тобі трапляється зворушливе відео з «терміновим збором» — на картку невідомої людини, без жодних звітів.'+(S.f.pb?' Ти вже знаєш, чого вартий заряджений телефон, коли немає світла.':''),q:'Як ти вчиниш?',o:[
   {l:'Переказати 50 грн на збір класу — суму, яка не зламає твій план',p:2,eff:S=>{S.save=Math.max(0,S.save-50);S.sc=Math.min(100,S.sc+5);S.f.don=1;},fb:'Невеликий запланований внесок на перевірений збір — це теж фінансова поведінка воєнного часу. Клас зібрав на шість павербанків.'},
   {l:'Нічого не переказувати: кожна гривня зараз потрібна на ціль',p:1,eff:S=>{S.f.nodon=1;},fb:'Це твоє право, і скарбничка ціла. Проте допомога не обов’язково має бути великою: 50 грн на план майже не вплинули б.'},
   {l:'Переказати 200 грн на «терміновий збір» із відео — там усе так зворушливо',p:0,eff:S=>{S.save=Math.max(0,S.save-200);S.f.fakedon=1;},fb:'За два дні сторінку видалили: це були шахраї, які наживаються на чужому бажанні допомогти. Перш ніж переказувати, перевір, хто збирає і чи є звіти.'}]},
  {id:'w4_close',t:'choice',head:'Тиждень 4 · Навушники',text:S=>'Неділя, кінець місяця. У скарбничці '+PG(S.save)+'. Навушники коштують 2 000 грн. '+(S.save>=2000?'Грошей вистачає.':'Бракує '+PG(2000-S.save)+'.')+(S.debt>0?' І ще за тобою борг Солі — '+PG(S.debt)+'.':''),q:'Що ти зробиш?',o:[
   {l:'Купити навушники за 2 000 грн, а залишок залишити в скарбничці',when:S=>S.save>=2000,p:2,eff:S=>{S.save-=2000;S.f.got=1;},fb:S=>'Ціль досягнута власними грошима й без боргів.'+(S.save>2000?' А залишок — початок запасу на непередбачене.':'')},
   {l:'Купити навушники, а все, що лишиться, одразу витратити на частування для друзів',when:S=>S.save>=2000,p:1,eff:S=>{S.save=0;S.f.got=1;},fb:S=>S.save>2000?'Навушники твої. Але '+PG(S.save-2000)+' залишку розійшлося за один вечір: скарбничка порожня, і наступна несподіванка застане тебе без запасу.':'Навушники твої, але скарбничка порожня: наступна несподіванка застане тебе без запасу.'},
   {l:'Узяти дорожчу модель за 3 500 грн: різницю позичити у старшого брата',when:S=>S.save>=2000,p:0,eff:S=>{S.debt+=Math.max(0,3500-S.save);S.save=Math.max(0,S.save-3500);S.f.got=1;S.f.over=1;},fb:S=>'Місяць дисципліни закінчився боргом у '+PG(Math.max(0,3500-S.save))+'. Коли гроші нарешті є, найлегше переконати себе, що тепер можна й більше.'},
   {l:'Підзаробити: сусідка пані Ганна давно просить допомогти розібрати балкон і заплатить 300 грн',when:S=>S.save<2000,p:2,eff:S=>{S.save+=300;if(S.save>=2000&&S.debt===0){S.save-=2000;S.f.got=1;}else{S.f.wait=1;}},fb:S=>S.save+300>=2000&&S.debt===0?'Два дні роботи — і разом із заробленим грошей вистачило. Навушники куплено без жодного боргу.':'Заробіток скоротив розрив, але до 2 000 грн ще бракує '+PG(Math.max(0,2000-S.save-300))+'. Твоє рішення — дозбирати й не позичати: ціль відсунулася, але не зникла.'},
   {l:'Зачекати й збирати далі, нічого не змінюючи',when:S=>S.save<2000,p:1,eff:S=>{S.f.wait=1;},fb:'Нових боргів немає — це добре. Але якщо нічого не змінити, наступний місяць мине так само, як цей.'},
   {l:'Позичити решту в старшого брата й купити сьогодні',when:S=>S.save<2000,p:0,eff:S=>{S.debt+=2000-S.save;S.save=0;S.f.got=1;},fb:S=>'Навушники в тебе вже сьогодні, а разом з ними — борг у '+PG(2000-S.save)+'. Тепер кишенькові наступних тижнів уже не твої.'}]},
  {id:'w4_year',t:'calc',head:'Тиждень 4 · Світло за рік',text:S=>S.kwh<300?'Прийшов рахунок за світло: '+PG(S.bill)+' замість 1 296 грн минулого місяця. Тато задоволений і пропонує тримати ці звички надалі.':'Прийшов рахунок за світло: ті самі 1 296 грн. Сусіди з такою самою квартирою змінили кілька звичок і заплатили 1 080 грн.',q:S=>S.kwh<300?'Скільки гривень заощадить родина за рік, якщо так буде щомісяця?':'Скільки гривень за рік заощадила б твоя родина, якби платила як сусіди?',ans:S=>(S.kwh<300?1296-S.bill:216)*12,unit:'грн',hint:'Знайди економію за один місяць і помнож на 12.',sol:S=>S.kwh<300?'Економія за місяць: 1 296 − '+PN(S.bill)+' = '+PG(1296-S.bill)+'. За рік: '+PN(1296-S.bill)+' × 12 = '+PG((1296-S.bill)*12)+'. Звички не коштують нічого, а працюють щомісяця.':'Економія за місяць: 1 296 − 1 080 = 216 грн. За рік: 216 × 12 = 2 592 грн — більше, ніж коштують навушники.'}],
 finish:S=>{const lvl=S.f.got&&S.debt===0&&!S.f.pyr?2:S.debt===0&&(S.f.got||S.save>=1200)?1:0;
  const hasty=[];if(S.f.imp||S.f.swap)hasty.push('знижка «лише сьогодні»');if(S.f.party)hasty.push('вечір «як усі»');if(S.f.pyr)hasty.push('«подвоєння» грошей');if(S.f.lost)hasty.push('позика без домовленості');if(S.f.fakedon)hasty.push('зворушливий збір без звітів');
  return{level:lvl,title:['Місяць закінчився без цілі або з боргом','Ціль близько, але гроші ще вислизають','Ти керуєш грошима, а не вони тобою'][lvl],text:(S.f.got?'Навушники куплено. ':'Навушники поки не куплено. ')+'У скарбничці — '+PG(S.save)+', борг — '+PG(S.debt)+', рахунок родини за світло — '+PG(S.bill)+', самоконтроль — '+PL(S.sc,'бал','бали','балів')+' зі 100.',tips:[S.f.first?'Правило «спершу відклади, потім витрачай» спрацювало: скарбничка росла щотижня за планом.':S.f.half?'Половина суми чекала п’ятниці — і щотижня до скарбнички доходило менше, ніж у плані. Наступного разу клади всю суму в понеділок.':'У скарбничку йшло те, що залишалося в п’ятницю, — і щотижня залишалося менше, ніж у плані. Наступного разу клади гроші в скарбничку в понеділок.',hasty.length?'Гроші забирали рішення, ухвалені поспіхом: '+hasty.join(', ')+'. Пауза на 24 години перед незапланованою витратою захищає від них.':'Ні знижка, ні «легкі гроші», ні шахраї зі зборами тебе не зачепили: пауза перед рішенням — найдешевший захист.',S.kwh<300?'Нові звички зменшили рахунок родини за світло до '+PG(S.bill)+' — і половина зекономленого дісталася тобі.':'Рахунок за світло не змінився. Спробуй пройти місяць ще раз і пристати на татову пропозицію: ощадливе споживання енергії — це теж гроші.']};},
 terms:[['Фінансова поведінка','те, як людина заробляє, витрачає, заощаджує й позичає гроші та які рішення щодо них ухвалює'],['Імпульсивна покупка','незапланована покупка, зроблена під впливом емоцій, знижки чи тиску інших'],['Фінансова піраміда','схема, у якій учасникам платять не із заробленого прибутку, а з внесків нових учасників'],['Енергоощадність','звички й рішення, що зменшують споживання енергії без втрати потрібного результату'],['Резерв на непередбачене','запас грошей на раптові потреби, який не чіпають для звичайних покупок']]});

PFG_TOPICS.push({id:'8-3',sec:'8a',title:'Ролі людини: особистість, споживач, громадянин',minutes:30,
 intro:'За одну осінь ти побуваєш у трьох ролях. Спершу ти покупець: обираєш шкільний рюкзак і розбираєшся, що робити, коли покупка не підійшла. Потім продавець: два дні торгуєш печивом на шкільному ярмарку. Нарешті громадянин: отримуєш перше оплачуване замовлення й уперше бачиш, як із заробітку сплачують податки. Гроші й репутація переходять із ролі в роль: що вдасться зберегти спочатку, з тим і доведеться працювати далі.',
 init:()=>({cash:2600,rep:50,bp:0,q:0,price:0,s1:0,s2:0,left:0,loan:0,pay:0,owe:0,rp:0,ord:0,f:{}}),
 meters:[{k:'cash',label:'Гроші',unit:'грн'},{k:'rep',label:'Репутація',unit:'зі 100'}],
 steps:[
  {id:'a_disc',t:'calc',head:'Покупець · Знижка',text:'У тебе 2 600 грн: подарунок на день народження й накопичене. Потрібен новий шкільний рюкзак. У торговому центрі на вітрині — рюкзак «Хайп», який рекламує відомий блогер: 1 875 грн, сьогодні знижка 20 %.',q:'Скільки гривень коштує «Хайп» зі знижкою?',ans:S=>1500,unit:'грн',hint:'Знайди 20 % від 1 875 грн і відніми від початкової ціни.',sol:S=>'20 % від 1 875 грн — це 1 875 × 0,2 = 375 грн. 1 875 − 375 = 1 500 грн. Чи вигідна покупка, показує кінцева ціна, а не розмір знижки.'},
  {id:'a_factors',t:'choice',head:'Покупець · Який рюкзак обрати',text:'Є три варіанти. «Хайп» за 1 500 грн зі знижкою: такий у половини класу, але у відгуках пишуть, що блискавка слабка. «Мандрівник» за 900 грн: зручна спинка, рік гарантії, хороші відгуки. І рюкзак без назви на ринку за 600 грн: продавець запевняє, що він «такий самий, як фірмовий».',q:'Як ти вибиратимеш?',o:[
   {l:'Виписати, що мені справді потрібно — зручність, місткість, гарантія, — і порівняти всі три за цими ознаками',p:2,eff:S=>{S.f.bag='B';S.bp=900;S.cash-=900;},fb:'За твоїми ознаками переміг «Мандрівник» за 900 грн. Вибір визначили власні потреби, якість і ціна, а не реклама — і в гаманці лишилося 1 700 грн.'},
   {l:'Узяти «Хайп»: знижка лише сьогодні, і такий у всіх',p:1,eff:S=>{S.f.bag='A';S.bp=1500;S.cash-=1500;},fb:'Рюкзак непоганий, але рішення за тебе ухвалили реклама блогера, мода в класі та слова «лише сьогодні». Переплата — 600 грн порівняно з рюкзаком, у якого кращі відгуки.'},
   {l:'Узяти найдешевший на ринку: рюкзак є рюкзак',p:0,eff:S=>{S.f.bag='C';S.bp=600;S.cash-=600;},fb:'Сьогодні це мінус лише 600 грн. Але ціна — тільки один із чинників: про якість, гарантію й те, хто відповідатиме, якщо щось піде не так, не прозвучало жодного запитання.'}]},
  {id:'a_seller',t:'choice',head:'Покупець · Розмова з продавцем',text:S=>S.f.bag==='C'?'Продавець на ринку лічить твої гроші: «Чеків не даємо, у нас усе чесно. А за 150 грн дам ще „фірмовий“ брелок — без нього не той вигляд».':'На касі консультант наполягає: «Візьміть ще захисне просочення за 150 грн, без нього рюкзак швидко зноситься. А чек вам точно потрібен? Без чека зроблю знижку 50 грн».',q:'Як ти поведешся?',o:[
   {l:'Ввічливо відмовитися від зайвого й попросити чек',p:2,eff:S=>{S.f.chk=1;},fb:S=>S.f.bag==='C'?'Продавець побурчав, але виписав товарний чек із датою та підписом. Чек — твій доказ купівлі, а наполегливість продавця — не причина купувати зайве.':'Консультант знизав плечима й видав чек. Чек — твій доказ купівлі, а наполегливість продавця — не причина купувати зайве.'},
   {l:S=>S.f.bag==='C'?'Узяти брелок, але наполягти на чеку':'Узяти просочення — продавцеві видніше — і чек',p:1,eff:S=>{S.cash-=150;S.f.chk=1;S.f.extra=1;},fb:'Чек у тебе є, і це добре. Але 150 грн пішло на річ, якої п’ять хвилин тому не було у твоїх планах: продавець заробляє на додаткових продажах.'},
   {l:S=>S.f.bag==='C'?'Обійтися без чека: навіщо сваритися через папірець':'Погодитися без чека — 50 грн зайвими не будуть',p:0,eff:S=>{if(S.f.bag!=='C')S.cash+=50;S.f.chk=0;},fb:S=>S.f.bag==='C'?'Розмова минула мирно, але тепер у тебе немає жодного доказу, де й коли куплено рюкзак.':'Плюс 50 грн сьогодні. Але без чека в тебе немає доказу купівлі, а продаж, можливо, пройшов повз касу — тобто й повз податки.'}]},
  {id:'a_home',t:'event',head:'Покупець · Удома',text:S=>(S.f.bag==='B'?'У магазині рюкзак був порожній і сидів добре. Удома ти складаєш у нього всі підручники на понеділок — і з повним рюкзаком лямки врізаються в плечі, а коротшими їх не зробиш.':'Удома ти складаєш у рюкзак підручники. Папка формату А4 не влазить, а лямки не підганяються під твій зріст. Під час купівлі цього ніхто не перевіряв.')+' До школи ти з ним ще не ходиш, ярлики на місці.'+(S.f.chk?' Чек лежить у кишені рюкзака.':' Чека в тебе немає.')},
  {id:'a_days',t:'calc',head:'Покупець · Чотирнадцять днів',text:'Рюкзак куплено 3 жовтня. За умовою задачі: непродовольчий товар належної якості, який не підійшов, можна обміняти протягом 14 днів, не рахуючи дня купівлі. Товар має бути не вживаним, з ярликами.',q:'Якого числа жовтня — останній день, коли можна звернутися до продавця?',ans:S=>17,unit:'жовтня',hint:'День купівлі не рахується: перший день відліку — 4 жовтня.',sol:S=>'Перший день відліку — 4 жовтня, чотирнадцятий — 17 жовтня (3 + 14 = 17). Після цієї дати продавець має право відмовити.'},
  {id:'a_return',t:'choice',head:'Покупець · Що робити з рюкзаком',text:S=>'Сьогодні 8 жовтня. Рюкзак за '+PG(S.bp)+' стоїть у кутку.'+(S.f.chk?' У тебе є чек.':' Чека немає: довести, де й коли куплено рюкзак, нічим.'),q:'Що ти робитимеш?',o:[
   {l:'Піти до продавця з чеком, рюкзаком і ярликами та попросити обміняти на зручніший',when:S=>!!S.f.chk,p:2,eff:S=>{S.f.ret=1;},fb:'Продавець перевіряє чек і ярлики та обмінює рюкзак на модель, що тобі підходить, за ту саму ціну. Спрацювали три речі: чек, збережений вигляд товару й вчасне звернення.'},
   {l:'Піти до продавця з мамою, яка була з тобою в день купівлі, спокійно все пояснити й попросити обмін',when:S=>!S.f.chk,p:2,eff:S=>{S.cash-=100;S.f.ret=1;S.f.hard=1;},fb:'Без чека продавець міг просто відмовити. Після довгої розмови він пішов назустріч: запропонував іншу модель, але з доплатою 100 грн. Проблему розв’язано, проте з чеком це було б швидше й без доплати.'},
   {l:'Продати рюкзак на сайті оголошень і купити інший',p:1,eff:S=>{S.cash-=S.bp/3;S.f.resold=1;},fb:S=>'Новий, але «з рук» рюкзак купили лише за '+PG(S.bp*2/3)+' — на третину дешевше. Зручніший рюкзак'+(S.f.bag==='C'?' на тому самому ринку':'')+' коштує стільки само — '+PG(S.bp)+', тож твоя втрата — '+PG(S.bp/3)+'.'+(S.f.chk?' А з чеком обмін не коштував би нічого.':'')},
   {l:'Зайти до продавця якось потім, на осінніх канікулах',p:0,eff:S=>{S.f.late=1;},fb:'Наприкінці жовтня продавець лише розводить руками: 14 днів минуло. Право, яким не скористалися вчасно, зникає. Незручний рюкзак лишається в тебе.'},
   {l:'Залишити як є: ніяково турбувати людей через таке',p:0,eff:S=>{S.f.late=1;},fb:'Обмін товару — звичайна справа, а не сварка. Тепер незручний рюкзак із тобою щодня, а витрачених грошей шкода.'}]},
  {id:'b_intro',t:'event',head:'Продавець · Шкільний ярмарок',text:S=>(S.f.bag==='C'?'За місяць у рюкзака з ринку відірвалася лямка. Гарантії немає, тож ремонт у майстерні — 350 грн — оплачуєш ти. Дешевий рюкзак уже обійшовся в 950 грн. ':'')+(S.f.late?'Незручний рюкзак дається взнаки: щоб його розвантажити, довелося купити окрему сумку для папок і зошитів — 200 грн. ':'')+'На початку листопада у школі — дводенний ярмарок. Ви з однокласницею Олею вирішили продавати домашнє вівсяне печиво з арахісовою пастою, у пакуночках по 4 штуки. Оля пече — це її підготовка до кулінарного конкурсу. На тобі продукти, гроші, торгівля й оформлення стола: вивіску та цінники ти малюєш від руки. Твій стартовий капітал — те, що лишилося після історії з рюкзаком: '+PG(S.cash-(S.f.bintro?0:(S.f.bag==='C'?350:0)+(S.f.late?200:0)))+'.',eff:S=>{if(!S.f.bintro){S.f.bintro=1;if(S.f.bag==='C')S.cash-=350;if(S.f.late)S.cash-=200;}}},
  {id:'b_cost',t:'calc',head:'Продавець · Собівартість',text:'На 30 пакуночків потрібно: борошно й вівсяні пластівці — 70 грн, масло — 90 грн, цукор — 30 грн, арахісова паста — 60 грн, пакети та стрічки — 50 грн.',q:'У скільки гривень обходиться один пакуночок?',ans:S=>10,unit:'грн',hint:'Склади всі витрати на партію й поділи на кількість пакуночків.',sol:S=>'70 + 90 + 30 + 60 + 50 = 300 грн. 300 : 30 = 10 грн. Це собівартість: якщо продавати дешевше, кожен пакуночок приноситиме збиток.'},
  {id:'b_label',t:'choice',head:'Продавець · Наліпки зі складом',text:'Покупець має знати, що саме він купує, тому на пакуночках потрібні назва і склад. Є три способи це зробити.',q:'Який ти обереш?',o:[
   {l:'Замовити 100 наліпок у копіцентрі біля школи: 200 грн, квитанція, готово завтра',p:2,eff:S=>{S.cash-=200;S.rep=Math.min(100,S.rep+5);S.f.label=1;},fb:'Наліпки готові вчасно. А якби щось надрукували не так, квитанція дала б підставу вимагати передрук. Обираючи послугу, дивись не лише на ціну, а й на те, хто відповідає за результат.'},
   {l:'Написати склад від руки на картонці біля столу',p:1,eff:S=>{S.f.card=1;},fb:'Безплатно й чесно. Але на пакуночках, які покупці понесуть додому, складу не буде.'},
   {l:'Замовити в «дизайнера» з оголошення в месенджері: 120 грн, уся сума наперед на картку, без документів',p:0,eff:S=>{S.cash-=120;S.f.fakeD=1;},fb:'Після переказу «дизайнер» перестав відповідати. Ні квитанції, ні договору — довести замовлення нічим. Найдешевша послуга виявилася найдорожчою: 120 грн зникли, наліпок немає.'}]},
  {id:'b_stock',t:'choice',head:'Продавець · Скільки пекти',text:S=>'У тебе '+PG(S.cash)+'. Один пакуночок обходиться в 10 грн. Учителька, яка організовує ярмарок, каже: торік на схожому столі за два дні купили 50–60 пакуночків випічки.'+(S.cash<500?' На 50 пакуночків твоїх грошей уже не вистачає.':''),q:'Яку партію ви спечете?',o:[
   {l:'50 пакуночків за 500 грн',when:S=>S.cash>=500,p:2,eff:S=>{S.q=50;S.cash-=500;},fb:'Партія відповідає торішньому попиту: є що продавати обидва дні, і немає ризику залишитися з горою непроданого.'},
   {l:'50 пакуночків: 200 грн своїх і 300 грн позичити в сестри; після ярмарку повернути їй 330 грн',when:S=>S.cash<500,p:2,eff:S=>{S.q=50;S.cash-=200;S.loan=330;},fb:'Позика під зрозумілий попит — виправданий ризик: партія відповідає торішнім продажам. Але 30 грн із прибутку вже належать сестрі, а борг доведеться повернути за будь-якого виторгу. Так гроші, витрачені в ролі покупця, обмежують тебе в ролі продавця.'},
   {l:S=>S.cash<500?'20 пакуночків за 200 грн: лише на свої, без боргу':'20 пакуночків за 200 грн: менше ризику',p:1,eff:S=>{S.q=20;S.cash-=200;},fb:S=>S.cash<500?'Жодного боргу й жодного ризику. Але якщо попит буде як торік, товару вистачить менш ніж на половину покупців — і заробіток буде скромним.':'Ризику майже немає, але й товару замало: якщо попит буде як торік, більшість покупців піде від порожнього столу.'},
   {l:S=>S.cash>=1000?'100 пакуночків за 1 000 грн: більше товару — більше грошей':'100 пакуночків: вкласти все, а решту позичити в сестри й повернути на 10 % більше',p:0,eff:S=>{S.q=100;if(S.cash>=1000){S.cash-=1000;}else{S.loan=Math.round((1000-S.cash)*1.1);S.cash=0;}},fb:S=>'Це майже вдвічі більше, ніж купували торік. Продати все навряд чи вдасться, а печиво довго не лежить: кожен непроданий пакуночок — 10 грн збитку.'+(S.loan>0?' До того ж сестрі доведеться повернути '+PG(S.loan)+'.':'')}]},
  {id:'b_price',t:'choice',head:'Продавець · Ціна',text:S=>'Спечено '+S.q+' пакуночків, собівартість кожного — 10 грн. На сусідніх столах схожу випічку продають по 22–28 грн.',q:'Яку ціну ти поставиш?',o:[
   {l:'25 грн: як у сусідів, і заробіток є',p:2,eff:S=>{S.price=25;},fb:'Ціна покриває витрати, дає прибуток і не відлякує покупців. Продавець призначає ціну, але погоджуватися на неї чи ні — вирішує покупець.'},
   {l:'20 грн: трохи дешевше, ніж у всіх, щоб брали охочіше',p:S=>S.q===100?2:1,eff:S=>{S.price=20;S.rep=Math.min(100,S.rep+5);},fb:S=>S.q===100?'Товару в тебе більше, ніж зазвичай купують, тож нижча ціна допоможе продати більше пакуночків. З кожного ти заробляєш 10 грн замість 15, зате менше печива залишиться.':'Покупців буде більше, і вони це запам’ятають. Але з кожного пакуночка ти заробляєш 10 грн замість 15, а товару й так небагато.'},
   {l:'50 грн: ручна робота має коштувати дорого',p:0,eff:S=>{S.price=50;S.rep=Math.max(0,S.rep-10);},fb:'Покупець порівнює: поруч схожа випічка вдвічі дешевша. Більшість, почувши ціну, піде до сусідів і розповідатиме про «золоте печиво».'}]},
  {id:'b_open',t:'event',head:'Продавець · День перший',text:S=>'Перший день ярмарку. На столі '+S.q+' пакуночків по '+PG(S.price)+'.'+(S.f.label?' На кожному — акуратна наліпка з назвою і складом.':S.f.card?' Поруч стоїть картонка зі складом, написаним від руки.':' Складу ніде не написано: наліпок так і немає.')+(S.price===50?' Люди підходять, питають ціну — і більшість іде далі.':S.price===20?' Біля столу одразу збирається черга.':' Торгівля йде рівно.'),eff:S=>{S.s1=Math.min(S.q,S.price===20?32:S.price===25?24:4);S.left=S.q-S.s1;}},
  {id:'b_honest',t:'choice',head:'Продавець · Питання про склад',text:S=>'Жінка з хлопчиком бере пакуночок і питає: «Тут немає горіхів? У сина алергія на арахіс».'+(S.f.label?' Склад на наліпці надруковано дрібно, і вона не дочитала.':S.f.card?' Картонка зі складом стоїть на іншому краю столу.':' Складу ніде не написано.')+' Якщо скажеш правду — вона не купить.',q:'Що ти відповіси?',o:[
   {l:'Сказати чесно: є арахісова паста, це печиво вам не підходить',p:2,eff:S=>{S.rep=Math.min(100,S.rep+15);S.f.honest=1;},fb:'Жінка подякувала й пішла без покупки. А за пів години повернулася з подругою, яка взяла три пакуночки: «Тут кажуть правду». Один втрачений продаж приніс довіру.'},
   {l:'Знизати плечима: «Не знаю, пекла подруга»',p:1,eff:S=>{S.rep=Math.max(0,S.rep-5);S.f.shrug=1;},fb:'Жінка поклала пакуночок назад — і добре. Але продавець, який не знає, що продає, довіри не викликає: відповідати за товар має той, хто стоїть за столом.'},
   {l:'Заспокоїти: «Там зовсім трішки, нічого не станеться»',p:0,eff:S=>{S.rep=Math.max(0,S.rep-20);S.f.lie=1;},fb:S=>'Жінка купила. '+(S.f.label?'Удома вона таки дочитала наліпку':'Удома вона спитала про склад у чаті батьків, і Оля чесно відповіла')+' — печиво в сина встигли забрати. Уранці про це знала вся школа. Один продаж поставив під загрозу чуже здоров’я і твоє ім’я.'}]},
  {id:'b_fix',t:'choice',head:'Продавець · Невдоволений покупець',text:'Після обіду повертається шестикласник: у його пакуночку два печива з чотирьох розкришилися. «Я за таке платив?» Довкола стоять інші покупці й слухають.',q:'Як ти вчиниш?',o:[
   {l:'Вибачитися й запропонувати на вибір: новий пакуночок або гроші назад',p:2,eff:S=>{S.rep=Math.min(100,S.rep+10);if(S.left>0)S.left-=1;else S.s1-=1;S.f.fix=1;S.f.repl=1;},fb:'Хлопець узяв новий пакуночок і пішов задоволений. Ті, хто стояв поруч, побачили: тут за свій товар відповідають. Це коштувало один пакуночок і дало більше, ніж будь-яка реклама.'},
   {l:'Мовчки дати інший пакуночок, аби швидше пішов',p:1,eff:S=>{S.rep=Math.min(100,S.rep+5);if(S.left>0)S.left-=1;else S.s1-=1;S.f.repl=1;},fb:'Проблему розв’язано ціною одного пакуночка, але без жодного слова вибачення. Покупець отримав печиво, а не повагу — і це теж помітили.'},
   {l:'Відповісти: «Товар куплено — претензії не приймаються»',p:0,eff:S=>{S.rep=Math.max(0,S.rep-10);S.f.rude=1;},fb:'Один пакуночок збережено, а кількох покупців, які це чули, втрачено. Продавець відповідає за якість проданого, і покупець має право на заміну.'}]},
  {id:'b_rev1',t:'calc',head:'Продавець · Виторг першого дня',text:S=>'Вечір першого дня. Покупці заплатили за '+PL(S.s1,'пакуночок','пакуночки','пакуночків')+' по '+PG(S.price)+'.'+(S.f.repl?' Ще один пішов на заміну шестикласникові.':'')+(S.left===0?' Стіл порожній: кільком покупцям довелося відмовити.':' На столі ще '+PL(S.left,'пакуночок','пакуночки','пакуночків')+'.'),q:'Який виторг першого дня?',ans:S=>S.s1*S.price,unit:'грн',hint:'Помнож кількість оплачених пакуночків на ціну.',sol:S=>S.s1+' × '+S.price+' = '+PG(S.s1*S.price)+'. Це виторг, а не прибуток: із нього ще треба повернути гроші, вкладені в партію.',eff:S=>{if(!S.f.d1){S.f.d1=1;S.cash+=S.s1*S.price;}}},
  {id:'b_even',t:'calc',head:'Продавець · Чи повернулися гроші',text:S=>'У партію з '+S.q+' пакуночків вкладено '+PG(S.q*10)+'. Ціна пакуночка — '+PG(S.price)+'.',q:'Скільки пакуночків треба продати, щоб повернути всі гроші, вкладені в партію?',ans:S=>S.q*10/S.price,unit:'пакуночків',hint:'Поділи вкладену суму на ціну одного пакуночка.',sol:S=>PN(S.q*10)+' : '+S.price+' = '+(S.q*10/S.price)+'. '+(S.s1>=S.q*10/S.price?'Сьогодні оплачено '+S.s1+' — вкладене вже повернулося, далі кожен продаж дає прибуток.':'Сьогодні оплачено лише '+S.s1+' — до повернення вкладеного бракує ще '+(S.q*10/S.price-S.s1)+'.'),eff:S=>{if(!S.f.d2){S.f.d2=1;const d=S.rep>=65?(S.price===20?40:S.price===25?30:5):S.rep>=45?(S.price===20?32:S.price===25?24:4):(S.price===20?16:S.price===25?12:2);S.s2=Math.min(S.left,d);S.pay=Math.min(S.loan,S.cash+S.s2*S.price);S.owe=S.loan-S.pay;}}},
  {id:'b_day2',t:'event',head:'Продавець · День другий',text:S=>'Другий день ярмарку. '+(S.rep>=65?'Про твій стіл говорять добре'+(S.f.honest&&S.f.fix?': «там чесно кажуть про склад і не сперечаються через дрібниці»':S.f.honest?': «там чесно кажуть про склад»':S.f.fix?': «там за свій товар відповідають»':'')+'. Охочих купити більше, ніж учора.':S.rep>=45?'Охочих купити приблизно стільки ж, як учора.':'Чутки розійшлися швидко: повз твій стіл проходять, не зупиняючись.')+(S.left===0?' Та продавати нічого: усе розійшлося ще вчора. Товару було замало — і покупці йдуть до сусідів.':' Продано '+S.s2+' із '+S.left+' пакуночків, виторг — '+PG(S.s2*S.price)+'.'+(S.left-S.s2>0?' Непроданих — '+(S.left-S.s2)+': це '+PG((S.left-S.s2)*10)+' вкладених грошей, які не повернулися.':' Стіл порожній: продано все.'))+(S.loan>0?(S.owe>0?' Сестрі треба повернути '+PG(S.loan)+', але всіх твоїх грошей вистачає лише на '+PG(S.pay)+'. Ще '+PG(S.owe)+' лишаються боргом.':' Одразу після ярмарку ти повертаєш сестрі '+PG(S.loan)+'.'):''),eff:S=>{if(!S.f.d2done){S.f.d2done=1;S.cash+=S.s2*S.price-S.pay;}}},
  {id:'c_deal',t:'choice',head:'Громадянин · Перше замовлення',text:S=>'Після ярмарку до тебе підходить пані Ірина, власниця кав’ярні біля школи. '+(S.rep>=60?'«Про ваш стіл добре говорять, а вивіска й цінники в тебе гарні. Намалюй для кав’ярні святкову вивіску, меню на дошці й цінники. За місяць роботи нарахую 4 000 грн».':'«Про ваш стіл я чула різне. Але вивіска й цінники в тебе гарні — спробуймо з малого: меню на дошці й цінники. За місяць роботи нарахую 2 000 грн».')+' І додає: «Працюємо за договором. Тобі 14, тож мені потрібна згода когось із батьків. Із нарахованої суми я утримаю податки й перерахую їх до бюджету — на руки буде менше».'+(S.owe>0?' А сестрі ще треба віддати '+PG(S.owe)+'.':''),q:'Що ти вирішиш?',o:[
   {l:'Порадитися з батьками й погодитися працювати за договором',p:2,eff:S=>{S.ord=S.rep>=60?4000:2000;S.f.legal=1;},fb:'Мама прочитала договір і дала згоду. У тебе є замовлення й документ, де записано, що треба зробити і скільки за це заплатять. Так репутація продавця перетворилася на заробіток.'},
   {l:'Відмовитися: договір, податки — зарано, повернуся до цього в 16',p:1,eff:S=>{S.ord=S.rep>=60?4000:2000;S.f.declined=1;},fb:'Обережно й чесно. Але законний шлях був уже зараз — разом із батьками. Замовлення пані Ірина віддала студентці.'},
   {l:'Запропонувати без договору: гроші готівкою, без податків — зате на 10 % дешевше',p:0,eff:S=>{S.ord=S.rep>=60?4000:2000;S.rep=Math.max(0,S.rep-5);S.f.shadow=1;},fb:'Пані Ірина відмовилася: без договору вона не може записати оплату у витрати кав’ярні, а ти не маєш жодного захисту, якщо тобі не заплатять. Замовлення не відбулося, а враження про тебе зіпсувалося.'}]},
  {id:'c_goods',t:'choice',head:'Громадянин · Сухі маркери',text:S=>(S.f.legal?'Матеріали оплачує кав’ярня: пані Ірина дає тобі 300 грн і просить принести чек.':'Замовлення немає, але малювати ти не кидаєш: клас готує стінгазету до шкільного свята. Класна керівниця дає тобі 300 грн із класних грошей і просить принести чек.')+' У канцелярській крамниці ти купуєш набір із восьми маркерів і картон — рівно на 300 грн. Касирка кладе чек у пакет. Удома виявляється: чотири маркери з восьми сухі.',q:'Що ти зробиш?',o:[
   {l:'Повернутися до крамниці з маркерами й чеком і попросити замінити набір або повернути гроші',p:2,eff:S=>{S.f.claim=1;},fb:'Продавчиня перевірила маркери, вибачилася й замінила набір на справний. Покупець не мусить платити за товар із вадою. А чек тобі ще знадобиться — відзвітувати за чужі 300 грн.'},
   {l:'Не сперечатися через дрібницю: малювати чотирма маркерами, що пишуть',p:1,eff:S=>{S.rep=Math.max(0,S.rep-5);S.f.half=1;},fb:'Робота вийшла біднішою на кольори, і це помітили. За сухі маркери заплачено повну ціну, а крамниця так і не дізналася, що продає брак.'},
   {l:'Розвести сухі маркери водою: якось малюватимуть',p:0,eff:S=>{S.rep=Math.max(0,S.rep-15);S.f.bad=1;},fb:'Фарба пішла плямами й за день вицвіла. Той, хто знає про ваду й здає таку роботу, втрачає довіру набагато швидше, ніж здобував. А право на заміну так і лишилося невикористаним.'}]},
  {id:'c_tax',t:'calc',head:'Громадянин · Податки із заробітку',text:S=>(S.f.legal?'Місяць минув, роботу здано. Чек за матеріали ти віддаєш пані Ірині — так кав’ярня підтверджує свої витрати. За договором тобі нараховано '+PG(S.ord)+'.':'Удома мама пропонує порахувати, '+(S.f.shadow?'що втрачено разом із замовленням':'від чого ти відмовляєшся')+'. За договором пані Ірина нарахувала б тобі '+PG(S.ord)+'.')+' За умовою задачі із цієї суми утримують податок на доходи фізичних осіб — 18 % і військовий збір — 5 %.',q:S=>S.f.legal?'Скільки гривень ти отримаєш на руки?':'Скільки гривень було б у тебе на руках?',ans:S=>S.ord*0.77,unit:'грн',hint:'Знайди 18 % і 5 % від нарахованої суми та відніми обидві суми від неї.',sol:S=>'Податок на доходи: '+PN(S.ord)+' × 0,18 = '+PG(S.ord*0.18)+'. Військовий збір: '+PN(S.ord)+' × 0,05 = '+PG(S.ord*0.05)+'. '+PN(S.ord)+' − '+PN(S.ord*0.18)+' − '+PN(S.ord*0.05)+' = '+PG(S.ord*0.77)+'. Податки до бюджету перераховує той, хто платить за роботу, — тому нарахована сума й сума «на руки» різні.',eff:S=>{if(S.f.legal&&!S.f.paid){S.f.paid=1;S.cash+=S.ord*0.77;S.rp=Math.min(S.owe,S.cash);}}},
  {id:'c_end',t:'event',head:'Громадянин · Куди йдуть податки',text:S=>'На початку грудня у школі відкривають оновлене укриття й новий спортивний майданчик. Директорка пояснює: гроші виділено з бюджету громади, а він наповнюється насамперед податками з доходів людей, які тут живуть і працюють.'+(S.f.legal?' Із твого заробітку до бюджету пішло '+PG(S.ord*0.23)+' — тепер у спільних справах є і твоя частка.':' Твоєї частки там поки немає — вона з’явиться, коли ти почнеш заробляти офіційно.')+(S.f.chk?'':' Ти згадуєш рюкзак, куплений без чека: якщо продаж не записали в касі, податку з нього бюджет теж не отримав.')+(S.rp>0?' А першим ділом із заробітку ти віддаєш сестрі '+PG(S.rp)+' боргу, що лишався після ярмарку.':''),eff:S=>{if(S.rp>0&&!S.f.rpd){S.f.rpd=1;S.cash-=S.rp;S.owe-=S.rp;}}}],
 finish:S=>{const lvl=S.cash>=2600&&S.rep>=60&&S.owe===0?2:S.cash>=1000&&S.rep>=30&&S.owe===0?1:0;return{level:lvl,title:['Три ролі далися дорого','Досвід є, але гроші чи довіру втрачено','Розважливий покупець, чесний продавець, свідомий громадянин'][lvl],text:'На початку осені в тебе було 2 600 грн і репутація 50 зі 100. Наприкінці: гроші — '+PG(S.cash)+', репутація — '+S.rep+' зі 100'+(S.owe>0?', борг сестрі — '+PG(S.owe):'')+'.',tips:[S.f.bag==='B'&&S.f.ret&&!S.f.hard?'У ролі покупця твій вибір спирався на власні потреби, чек збережено, обмін зроблено вчасно — тому на ярмарок ти приходиш із найбільшою сумою.':'У ролі покупця гроші втрачено ще до ярмарку: '+(S.f.bag!=='B'?'вибір підказали реклама або сама лише ціна':S.f.late?'14 днів на обмін минули без звернення до продавця':S.f.resold?'замість обміну рюкзак продано з рук на третину дешевше':'без чека обмін обійшовся дорожче')+'. Наступного разу порівнюй товар за власними потребами, бери чек і звертайся до продавця вчасно.',S.f.honest&&S.f.fix?'У ролі продавця ти кажеш правду про склад і відповідаєш за свій товар — другого дня репутація привела до столу нових людей.':'У ролі продавця довіру втрачено там, де було шкода одного продажу чи одного пакуночка. Наступного разу порахуй, скільки коштує репутація на другий день.',S.f.legal?'У ролі громадянина ти працюєш за договором: із заробітку сплачено податки, і частина цих грошей повертається до громади.':'У ролі громадянина ти поки що осторонь: замовлення можна було взяти за договором зі згоди батьків і заробити законно.']};},
 terms:[['Споживач','людина, яка купує товари чи послуги для власних потреб'],['Чек','документ, що підтверджує купівлю: що, де, коли й за скільки придбано'],['Собівартість','сума всіх витрат на виготовлення одиниці товару'],['Репутація','думка людей про продавця, що складається з його попередніх учинків'],['Податок на доходи фізичних осіб','частина заробітку людини, яку перераховують до бюджету на спільні потреби']]});

PFG_TOPICS.push({id:'8-4',sec:'8b',title:'Потреби та інтереси родини',minutes:30,
 intro:'Два місяці ти допомагаєш родині Шевченків — мамі Оксані, татові Андрію, молодшому братові Тимкові й собі — вирішувати, на що піде спільна сума 30 000 грн і вісім вихідних. Бажань набагато більше, ніж грошей і часу. Кожен вибір щось закриває, а щось відкладає — і відкладене може нагадати про себе в найневдаліший момент.',
 init:()=>({cash:30000,wk:8,debt:0,mood:60,pb:0,f:{}}),
 meters:[{k:'cash',label:'Гроші родини',unit:'грн'},{k:'wk',label:'Вільні вихідні',unit:'з 8'},{k:'debt',label:'Борг',unit:'грн'},{k:'mood',label:'Злагода в родині',unit:'зі 100'}],
 steps:[
  {id:'start',t:'event',head:'Тиждень 1 · Родинна рада',text:'Перша субота жовтня. Шевченки зібралися на раду: на спільні справи до кінця листопада є 30 000 грн, відкладених із зарплат. На столі аркуш, куди кожен записав, чого хоче. Мама: «Пральна машина гуде так, що чути в сусідів». Тато: «У дитячій після того, як протік дах, у кутку пліснява, шпалери відстають». Тимко: «А в бабусі Ніни в листопаді ювілей — 70 років!»'},
  {id:'wish',t:'calc',head:'Тиждень 1 · Список бажань',text:'На аркуші: ремонт дитячої кімнати з майстрами — 15 000 грн; ювілей бабусі в кафе — 12 000 грн; нова пральна машина — 13 500 грн; трендові навушники тобі — 4 500 грн; самокат Тимкові — 3 500 грн; курси англійської мамі — 4 000 грн; спінінг татові — 2 500 грн.',q:'На скільки гривень усі бажання разом перевищують гроші родини?',ans:S=>25000,unit:'грн',hint:'Склади всі сім сум і відніми від результату 30 000 грн.',sol:S=>'15 000 + 12 000 + 13 500 + 4 500 + 3 500 + 4 000 + 2 500 = 55 000 грн. 55 000 − 30 000 = 25 000 грн. Гроші обмежені, а бажання не закінчуються — тож доведеться вибирати.'},
  {id:'time',t:'calc',head:'Тиждень 1 · Скільки є часу',text:'Час — теж ресурс, і його не докупиш. До кінця листопада буде 8 вихідних. Одні з них — сам ювілей бабусі, одні — Тимкові змагання з плавання в іншому місті, ще в одні вихідні тато чергує на роботі.',q:'Скільки вихідних лишається вільними для родинних справ?',ans:S=>5,unit:'вихідних',hint:'Відніми від 8 усі вихідні, які вже зайняті.',sol:S=>'8 − 1 − 1 − 1 = 5 вихідних. На них претендують і ремонт, і підготовка до свята, і відпочинок кожного. Показник «Вільні вихідні» тепер — 5.',eff:S=>{S.wk=5;}},
  {id:'sort',t:'choice',head:'Тиждень 1 · З чого почати',text:'Мама пропонує спершу домовитися, що важливіше. «Є те, без чого ми не обійдемося щодня: чистий одяг, здорове житло. Є те, що має дату. І є те, що просто дуже хочеться».',q:'З чого родина почне?',o:[
   {l:'Спершу нагальне — пральна машина й пліснява в дитячій; далі ювілей, бо дату не перенесеш; бажання кожного — із залишку',p:2,eff:S=>{S.f.prio=1;S.mood=Math.min(100,S.mood+2);},fb:'Родина вишикувала потреби в чергу: нагальні, з фіксованою датою, решта. Тепер у кожної гривні й кожного вихідного є своє місце.'},
   {l:'Спершу ювілей: 70 років буває раз, а побут зачекає',p:1,eff:S=>{S.f.pfirst=1;S.mood=Math.min(100,S.mood+1);},fb:'Свято справді важливе, і дата не зміниться. Але пральна машина й пліснява чекати не обіцяли — про них так нічого й не вирішили.'},
   {l:'Поділити 30 000 грн порівну на чотирьох — хай кожен витрачає на своє',p:0,eff:S=>{S.f.split=1;S.mood=Math.max(0,S.mood-4);},fb:'По 7 500 грн кожному — і жодної спільної потреби на такі гроші не закрити: ні машина, ні ремонт у цю суму не вкладаються. Рада закінчилася суперечкою, і до списку довелося повернутися.'},
   {l:'Почати з приємного: купити Тимкові самокат уже сьогодні, щоб хоч хтось був задоволений',p:0,eff:S=>{S.cash-=3500;S.f.scoot=1;S.mood=Math.min(100,S.mood+2);},fb:'Тимко щасливий. Але 3 500 грн пішли на бажання раніше, ніж родина розібралася з нагальним.'}]},
  {id:'wash',t:'choice',head:'Тиждень 1 · Пральна машина',text:S=>'Майстер оглянув пральну машину: зношений підшипник. Замінити зараз — 2 800 грн із гарантією на рік. «Будете тягнути — барабан заклинить. Тоді ремонт обійдеться в 6 500 грн, або купуватимете нову», — попереджає він. Сусід радить знайомого, який «зробить за 1 200 грн», але з уживаною деталлю й без гарантії.'+(S.f.prio?' Ви щойно домовилися: нагальне — насамперед.':'')+' У родини зараз '+PG(S.cash)+'.',q:'Що робити з машиною?',o:[
   {l:'Замінити підшипник у майстра за 2 800 грн',p:2,eff:S=>{S.cash-=2800;S.f.wfix=1;},fb:'Невеликі гроші сьогодні закрили потребу, яка за місяць коштувала б у кілька разів більше.'},
   {l:'Покликати знайомого сусіда за 1 200 грн',p:1,eff:S=>{S.cash-=1200;S.f.wcheap=1;},fb:'Дешевше на 1 600 грн, і машина знову пере. Але вживана деталь без гарантії — це низька ціна разом із низькою якістю: скільки вона протримається, не знає ніхто.'},
   {l:'Поки що не чіпати: машина ж пере, а гроші потрібні на інше',p:0,eff:S=>{S.f.wlater=1;},fb:'Гроші збережено для ремонту й свята. Але потреба нікуди не зникла — вона просто чекає свого моменту.'}]},
  {id:'room',t:'choice',head:'Тиждень 2 · Дитяча кімната',text:S=>'Дитяча, де живете ви з Тимком: у кутку пліснява, шпалери відстають. Можна зробити ремонт самим — 9 000 грн на матеріали й три вихідні всієї родини. Можна найняти майстрів — 15 000 грн (ті самі матеріали плюс 6 000 грн за роботу) і один вихідний, щоб винести й занести меблі. Можна лише обробити куток від плісняви й переклеїти одну стіну — 3 500 грн і один вихідний. Вільних вихідних — '+S.wk+', грошей — '+PG(S.cash)+'.',q:'Що вирішить родина?',o:[
   {l:'Зробити ремонт самим: 9 000 грн і три вихідні',p:2,eff:S=>{S.cash-=9000;S.wk-=3;S.mood=Math.min(100,S.mood+4);S.f.diy=1;},fb:'Три вихідні у фарбі та клеї, зате 6 000 грн лишилися в родині, а Тимко тепер уміє клеїти шпалери.'},
   {l:'Найняти майстрів: 15 000 грн і один вихідний',p:1,eff:S=>{S.cash-=15000;S.wk-=1;S.f.pro=1;},fb:'Швидко й акуратно, родина зберегла два вихідні. Але на все інше тепер на 6 000 грн менше.'},
   {l:'Лише прибрати плісняву й переклеїти одну стіну: 3 500 грн і один вихідний',p:1,eff:S=>{S.cash-=3500;S.wk-=1;S.f.rmin=1;},fb:'Найнагальніше зроблено за невеликі гроші: плісняви немає. Решта кімнати лишилася як була, і до ремонту ще доведеться повернутися.'},
   {l:'Відкласти ремонт до літа: узимку однаково вікна не відчиниш',p:0,eff:S=>{S.f.rlater=1;},fb:'Гроші й вихідні вільні. Але пліснява — не шпалери з нудним малюнком: вона росте, а ви з Тимком дихаєте нею щоночі.'}]},
  {id:'opp',t:'calc',head:'Тиждень 2 · Ціна вибору',text:S=>S.f.diy?'Ремонт власноруч зберіг родині гроші порівняно з майстрами (9 000 грн проти 15 000), але забрав три вихідні замість одного.':S.f.pro?'Майстри коштували дорожче, ніж ремонт власноруч (15 000 грн проти 9 000), зате родина віддала один вихідний замість трьох.':'Тато все ще порівнює два повні ремонти: самим — 9 000 грн і три вихідні, з майстрами — 15 000 грн і один вихідний.',q:S=>S.f.diy?'Скільки гривень зберіг родині кожен додатковий вихідний, відданий ремонту?':S.f.pro?'Скільки гривень родина заплатила за кожен збережений вихідний?':'Скільки гривень коштує кожен вихідний, який зберігають майстри?',ans:S=>3000,unit:'грн',hint:'Знайди різницю в грошах і різницю у вихідних, потім поділи одне на інше.',sol:S=>'15 000 − 9 000 = 6 000 грн; 3 − 1 = 2 вихідні; 6 000 : 2 = 3 000 грн за вихідний. Це альтернативна вартість: обираючи одне, родина відмовляється від іншого — або від грошей, або від часу.'},
  {id:'left',t:'calc',head:'Тиждень 2 · Що по кишені',text:S=>'Проміжний підсумок. Було 30 000 грн.'+(S.f.scoot?' Самокат Тимкові — 3 500 грн.':'')+(S.f.wfix?' Ремонт пральної машини — 2 800 грн.':S.f.wcheap?' Ремонт пральної машини у знайомого — 1 200 грн.':' На пральну машину не витрачено нічого.')+(S.f.diy?' Матеріали для дитячої — 9 000 грн.':S.f.pro?' Ремонт дитячої з майстрами — 15 000 грн.':S.f.rmin?' Куток і одна стіна в дитячій — 3 500 грн.':' На дитячу не витрачено нічого.')+' Попереду ювілей бабусі: навіть скромне свято вдома коштуватиме 6 000 грн. Тато пропонує прикинути: усе, що лишиться після такого свята, поділити порівну на чотирьох — на бажання кожного.',q:'Скільки гривень припало б на бажання кожного з чотирьох?',ans:S=>(S.cash-6000)/4,unit:'грн',hint:'Від 30 000 грн відніми все, що вже витрачено, і 6 000 грн на свято. Залишок поділи на 4.',sol:S=>{const w=S.f.scoot?11000:14500,r=S.cash-6000;return '30 000'+(S.f.scoot?' − 3 500':'')+(S.f.wfix?' − 2 800':S.f.wcheap?' − 1 200':'')+(S.f.diy?' − 9 000':S.f.pro?' − 15 000':S.f.rmin?' − 3 500':'')+' − 6 000 = '+PG(r)+'. '+PN(r)+' : 4 = '+PG(r/4)+'. '+(r/4>=4500?'Цього вистачило б на будь-яке бажання зі списку — якщо не станеться нічого несподіваного.':r/4>=2500?'На спінінг за 2 500 грн цього вистачає, а на навушники за 4 500 грн — ні. Усі бажання, що лишилися в списку, разом коштують '+PG(w)+' — бажання доводиться звіряти з можливостями.':'Цього не вистачає на жодне бажання зі списку: найдешевше, спінінг, коштує 2 500 грн. Бажання доводиться звіряти з можливостями.');}},
  {id:'news',t:'event',head:'Тиждень 4 · Дзвінок бабусі',text:S=>(S.f.diy?'Дитячу не впізнати: стіни сухі й світлі, хоч родина три тижні жила серед відер і драбин.':S.f.pro?'Майстри впоралися за тиждень: у дитячій сухо й світло.':S.f.rmin?'Куток у дитячій оброблено, плісняви немає. Решта шпалер тримається на чесному слові.':'У дитячій усе по-старому, лише темна пляма в кутку ніби побільшала.')+' Дзвонить бабуся Ніна: «Ювілей у другу суботу листопада. Буде дванадцятеро гостей. Тільки не витрачайтеся на мене, дітки!»'},
  {id:'fmt',t:'choice',head:'Тиждень 4 · Яким буде свято',text:S=>'Гостей — 12. Відсвяткувати можна по-різному: вдома, готуючи всією родиною (близько 6 000 грн на все і один вихідний на закупи й кухню); вдома, але страви замовити (близько 9 000 грн); у ресторані з ведучим (16 000 грн). У родини '+PG(S.cash)+', вільних вихідних — '+S.wk+'.'+(S.f.wfix?'':S.f.wcheap?' Пральна машина після дешевого ремонту знову почала гудіти.':' Пральна машина тим часом гуде дедалі гучніше.'),q:'Який формат обрати?',o:[
   {l:'Удома, готуємо всією родиною: 6 000 грн і один вихідний',p:2,eff:S=>{S.pb=6000;S.wk-=1;S.mood=Math.min(100,S.mood+4);S.f.home=1;},fb:'Свято вийде теплим і недорогим: родина платить не лише грошима, а й одним вільним вихідним на кухні.'},
   {l:S=>S.cash>=9000?'Удома, але страви замовити: 9 000 грн':'Удома, але страви замовити: 9 000 грн, а '+PG(9000-S.cash)+', яких бракує, позичити в родичів',p:S=>S.cash>=9000?1:0,eff:S=>{S.pb=9000;S.f.order=1;},fb:S=>S.cash>=9000?'Вихідний збережено, гості будуть нагодовані. За зекономлений час родина доплачує 3 000 грн.':'Вихідний збережено, але за нього родина платить позиченими грошима: на таке свято власних уже не вистачає.'},
   {l:S=>S.cash>=16000?'Ресторан із ведучим за 16 000 грн: ювілей буває раз':'Ресторан із ведучим за 16 000 грн, а '+PG(16000-S.cash)+', яких бракує, позичити в родичів',p:0,eff:S=>{S.pb=16000;S.mood=Math.min(100,S.mood+2);S.f.rest=1;},fb:S=>'Розкішно, і готувати не треба. Але один вечір забирає більше половини всіх грошей, які родина мала на два місяці.'+(S.cash<16000?' Частину суми доведеться позичати.':'')}]},
  {id:'party',t:'plan',head:'Тиждень 5 · Бюджет ювілею',text:S=>'Бюджет ювілею — '+PG(S.pb)+'. Розподіли його повністю. '+(S.f.home?'Продукти для домашнього столу — щонайменше 250 грн на гостя.':S.f.order?'Замовлені страви — щонайменше 450 грн на гостя.':'Меню в ресторані — щонайменше 900 грн на гостя.')+' Гостей — 12. Бабуся давно мріє про теплий плед і набір для в’язання — разом від 1 000 грн. Торт і квіти коштують від 800 грн. Решта — музика, фото й таксі для бабусиної сестри.',q:'Скільки гривень на кожну статтю?',
   fields:[{k:'food',label:'Частування на 12 гостей'},{k:'gift',label:'Подарунок бабусі'},{k:'decor',label:'Торт і квіти'},{k:'extra',label:'Музика, фото, таксі'}],
   total:S=>S.pb,
   best:S=>S.f.home?{food:3600,gift:1200,decor:800,extra:400}:S.f.order?{food:5400,gift:1500,decor:1200,extra:900}:{food:10800,gift:2500,decor:1500,extra:1200},
   check:(S,v)=>(v.food%100||v.gift%100||v.decor%100||v.extra%100)?'Вводь суми, кратні 100 грн.':null,
   eff:(S,v)=>{const m=S.f.home?3000:S.f.order?5400:10800;S.cash-=S.pb;if(v.food<m){S.cash-=m-v.food;S.mood=Math.max(0,S.mood-6);S.f.short=1;}else S.mood=Math.max(0,Math.min(100,S.mood+(v.gift>=1000?4:-4)+(v.decor>=800?2:-2)));if(S.cash<0){S.debt-=S.cash;S.cash=0;}},
   score:(S,v)=>{const m=S.f.home?3000:S.f.order?5400:10800;return v.food>=m&&v.gift>=1000&&v.decor>=800?{p:2,fb:'Гості ситі, бабуся отримала те, про що мріяла, торт і квіти на місці — і все в межах суми.'}:v.food>=m?{p:1,fb:'Частування вистачило, але на подарунок чи на торт із квітами лишилося замало. Свято запам’ятовують не лише за столом.'}:{p:0,fb:'На частування закладено менше, ніж потрібно на 12 гостей ('+PG(m)+'). Решту довелося терміново доплачувати — '+PG(m-v.food)+' понад бюджет.'};}},
  {id:'break',t:'event',head:'Тиждень 5 · Пральна машина',text:S=>(S.debt>0?'Бюджет свята складено, але власних грошей на нього не вистачило: '+PG(S.debt)+' позичено в родичів. ':'')+(S.f.wfix?'За тиждень до свята пральна машина після ремонту працює тихо. А в сусідів знизу така сама заклинила посеред прання — тепер вони шукають 6 500 грн на ремонт.':S.f.wcheap?'За тиждень до свята пральна машина знову гуде й б’ється об стіну: уживаний підшипник не протримався й місяця. Добре, що барабан ще цілий. Майстер терміново ставить нову деталь: 2 800 грн і ще 700 грн за терміновий виклик. Разом із першим ремонтом це 4 700 грн замість 2 800.'+(!S.f.wok&&S.cash<3500?' Власних грошей на це вже не вистачає — '+PG(3500-S.cash)+' доводиться позичити.':''):'За тиждень до свята пральна машина заклинила посеред прання й залила підлогу у ванній. Сталося те, про що попереджав майстер. Чекати тепер не можна: у родині четверо, а попереду гості.'),eff:S=>{if(S.f.wcheap&&!S.f.wok){S.f.wok=1;S.cash-=3500;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.mood=Math.max(0,S.mood-2);}else if(!S.f.wfix&&!S.f.wcheap&&!S.f.broken){S.f.broken=1;S.mood=Math.max(0,S.mood-4);}}},
  {id:'pq',t:'calc',when:S=>!!S.f.broken,head:'Тиждень 5 · Ціна чи якість',text:'У магазині дві моделі. Модель А: 9 000 грн, за відгуками служить близько 5 років. Модель Б: 13 500 грн, служить близько 9 років і до того ж витрачає менше води та електроенергії — ресурсів, які не безмежні.',q:'На скільки гривень дешевший один рік користування моделлю Б?',ans:S=>300,unit:'грн',hint:'Поділи ціну кожної моделі на кількість років служби й порівняй результати.',sol:S=>'А: 9 000 : 5 = 1 800 грн за рік. Б: 13 500 : 9 = 1 500 грн за рік. Різниця — 300 грн на рік на користь дорожчої моделі. Співвідношення «ціна/якість» показує не цінник, а те, скільки коштує рік користування.'},
  {id:'newwash',t:'choice',when:S=>!!S.f.broken,head:'Тиждень 5 · Термінова покупка',text:S=>'Модель А — 9 000 грн, модель Б — 13 500 грн. Майстер може відремонтувати стару машину, якій уже 11 років, за 6 500 грн із гарантією на 3 місяці. У родини зараз '+PG(S.cash)+(S.debt>0?', борг — '+PG(S.debt):'')+'. Якщо грошей не вистачить, решту доведеться позичати в родичів.',q:'Що вирішить родина?',o:[
   {l:'Купити модель Б за 13 500 грн',p:S=>S.cash>=16500?2:S.cash>=13500?1:0,eff:S=>{S.cash-=13500;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.f.wok=1;S.f.wb=1;},fb:S=>'Найдешевший рік користування й менші рахунки за воду та світло. '+(S.cash>=16500?'Грошей на неї вистачає, і запас у родини лишається.':S.cash>=13500?'Але на неї йде майже все, що є: запасу в родини не лишається.':'Але власних грошей на неї немає: '+PG(13500-S.cash)+' доводиться позичити. Вигідна покупка, яка не по кишені, обертається боргом.')},
   {l:'Купити модель А за 9 000 грн',p:S=>S.cash>=12000&&S.cash<16500?2:S.cash>=9000?1:0,eff:S=>{S.cash-=9000;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.f.wok=1;},fb:S=>'Нова машина з гарантією за меншу суму. Рік користування нею дорожчий, ніж моделлю Б, — така ціна нижчого цінника.'+(S.cash<9000?' Та й на неї власних грошей немає: '+PG(9000-S.cash)+' доводиться позичити.':S.cash<12000?' Після покупки запасу в родини майже не лишається.':'')},
   {l:'Відремонтувати стару за 6 500 грн',p:S=>S.cash<12000?2:1,eff:S=>{S.cash-=6500;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.f.wok=1;S.f.wrep=1;},fb:S=>'Найменша сума сьогодні'+(S.cash<6500?': позичити доведеться лише '+PG(6500-S.cash)+'.':', і позичати не доведеться.')+' Але машині 11 років, а гарантія на ремонт — лише три місяці.'},
   {l:'Нічого не купувати: до кінця листопада возити речі до пральні самообслуговування, 600 грн на тиждень',p:0,eff:S=>{S.cash-=1800;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.mood=Math.max(0,S.mood-6);S.f.nowash=1;},fb:'За три тижні пральня з’їла 1 800 грн, вихідні минали з пакетами білизни, а потреба так і лишилася незакритою.'}]},
  {id:'trend',t:'calc',head:'Тиждень 6 · Навушники',text:S=>'Ювілей позаду: бабуся розчулилася'+(S.f.short?', хоч за частування й довелося доплатити понад план':'')+'. Тепер ти згадуєш про своє бажання. Пів класу ходить у навушниках із підсвіткою за 4 500 грн. Ти чесно пригадуєш: модні речі ти носиш приблизно півтора року — потім виходить нова модель, і старі лягають у шухляду. Є й звичайні надійні навушники за 2 400 грн: такі служать близько чотирьох років.',q:'У скільки разів рік користування трендовими навушниками дорожчий?',ans:S=>5,unit:'разів',hint:'Знайди ціну одного року для кожної пари: поділи ціну на роки користування.',sol:S=>'4 500 : 1,5 = 3 000 грн за рік. 2 400 : 4 = 600 грн за рік. 3 000 : 600 = 5 разів. Трендова потреба швидко минає, а платити за неї доводиться найбільше.'},
  {id:'ears',t:'choice',head:'Тиждень 6 · Твоє бажання',text:S=>'Трендові навушники — 4 500 грн, надійні — 2 400 грн. У родини '+PG(S.cash)+(S.debt>0?' і борг '+PG(S.debt)+'.':'.')+(S.f.scoot?' Тимко вже має самокат, мама досі мріє про курси.':' Тимко досі мріє про самокат, мама — про курси.'),q:'Що ти запропонуєш родині?',o:[
   {l:'Купити трендові за 4 500 грн: у всіх же є',when:S=>S.cash>=4500,p:0,eff:S=>{S.cash-=4500;S.mood=Math.max(0,S.mood-3);S.f.trend=1;},fb:'Ти тепер як усі в класі. Але за рік ці навушники вийдуть із моди, а на бажання інших грошей поменшало — і це помітили.'},
   {l:'Попросити батьків позичити на трендові 4 500 грн: потім якось віддамо',when:S=>S.cash<4500,p:0,eff:S=>{S.debt+=4500;S.mood=Math.max(0,S.mood-5);S.f.trend=1;},fb:'Навушники є, і борг теж. Річ, яка за рік вийде з моди, родина оплачуватиме ще довго.'},
   {l:'Купити надійні за 2 400 грн',when:S=>S.cash>=2400,p:S=>S.debt>0||S.cash<5400?1:2,eff:S=>{S.cash-=2400;S.f.ears=1;},fb:S=>S.debt>0?'Вибір за ціною та якістю розумний. Але поки в родини борг, навіть 2 400 грн на бажання — зарано.':S.cash<5400?'Музика та сама, а рік користування вп’ятеро дешевший. Але після покупки в родини лишається менш ніж 3 000 грн запасу.':'Музика та сама, а рік користування вп’ятеро дешевший. І на бажання інших гроші лишилися.'},
   {l:'Нічого не просити: відкладати з кишенькових по 300 грн на тиждень і купити надійні за власні гроші',p:2,eff:S=>{S.mood=Math.min(100,S.mood+2);S.f.saveup=1;},fb:'2 400 : 300 = 8. Через вісім тижнів надійні навушники будуть твоїми — і жодної гривні зі спільних грошей.'},
   {l:'Попросити навушники в подарунок на день народження у квітні',p:1,eff:S=>{S.f.wait=1;},fb:'Гроші родини цілі, але бажання просто перекладено на інших і на кілька місяців уперед.'}]},
  {id:'weekend',t:'choice',head:'Тиждень 7 · Вихідні без справ',text:S=>'Попереду вихідні без жодних справ'+(S.wk>1?'.':' — останні вільні за ці два місяці.')+' Тато хоче на рибалку, мама — нарешті виспатися й розібрати шафи, Тимко — в аквапарк, ти — з друзями в кіно. Інтереси в кожного свої, а вихідні одні.',q:'Що запропонувати?',o:[
   {l:'Проголосувати за одну спільну справу: похід до лісу з багаттям і термосом, майже без витрат',p:2,eff:S=>{S.mood=Math.min(100,S.mood+7);S.wk-=1;S.f.together=1;},fb:'Кожен трохи поступився, зате вихідні стали спільними. Інтереси родини — це не сума чотирьох бажань, а те, що добре всім разом.'},
   {l:'Аквапарк усією родиною за 3 200 грн',when:S=>S.cash>=3200,p:S=>S.debt>0?0:1,eff:S=>{S.cash-=3200;S.mood=Math.min(100,S.mood+6);S.wk-=1;S.f.aqua=1;},fb:S=>S.debt>0?'Весело, але родина розважається на 3 200 грн, маючи борг.':'Усі разом, і всім весело. Щоправда, це 3 200 грн, а обирав, по суті, один Тимко.'},
   {l:'Хай кожен займеться своїм: рибалка, шафи, кіно',p:1,eff:S=>{S.mood=Math.max(0,S.mood-1);S.wk-=1;S.f.apart=1;},fb:'Кожен отримав своє, і ніхто не сварився. Але ще одні вихідні родина провела нарізно.'},
   {l:'Нікуди не йти: всі втомилися, посидимо вдома в телефонах',p:0,eff:S=>{S.mood=Math.max(0,S.mood-5);S.wk-=1;S.f.lazy=1;},fb:'Вихідні минули — і ніхто не згадає, чим вони відрізнялися від буднів. Час — ресурс, який не відкладеш на потім.'}]},
  {id:'end',t:'event',head:'Тиждень 8 · Останній тиждень',text:S=>'Кінець листопада. '+(S.f.rlater?'Пляма в дитячій розповзлася на пів стіни, у кімнаті пахне вогкістю. Мама терміново викликала майстрів: обробка стіни й нові шпалери — 7 000 грн. Це вдвічі дорожче, ніж коштувало прибрати плісняву на початку.':S.f.rmin?'Куток у дитячій сухий, але шпалери на сусідній стіні вже відходять — повний ремонт чекає на літо.':'У дитячій сухо й світло.')+(S.f.nowash?' Походи до пральні всіх виснажили, а машини досі немає.':' Пральна машина працює.')+(S.f.together?' Фото з лісового походу висить на холодильнику.':'')+(D=>D>2000?' Позичене треба віддавати: родичам обіцяно повертати борг — '+PG(D)+' — п’ятьма рівними частинами, по '+PG(D/5)+' щомісяця. До весни на бажання грошей не буде, і вдома через це напружено.':D>0?' Позичене треба віддавати: борг родичам — '+PG(D)+' — піде з грудневої зарплати, тож на бажання в грудні лишиться менше. Удома через це трохи напружено.':'')(S.f.endd?S.debt:S.debt+(S.f.rlater?Math.max(0,7000-S.cash):0)),eff:S=>{if(!S.f.endd){S.f.endd=1;if(S.f.rlater){S.cash-=7000;if(S.cash<0){S.debt-=S.cash;S.cash=0;}S.mood=Math.max(0,S.mood-5);S.f.rurgent=1;}if(S.f.rmin)S.mood=Math.max(0,S.mood-2);if(S.debt>0)S.mood=Math.max(0,S.mood-3);}}},
  {id:'total',t:'calc',head:'Тиждень 8 · Рахунок',text:S=>'Два місяці минули. На початку в родини було 30 000 грн. Зараз лишилося '+PG(S.cash)+(S.debt>0?', а борг перед родичами — '+PG(S.debt)+'.':', боргів немає.'),q:'Скільки гривень у середньому родина витрачала за місяць?',ans:S=>(30000-S.cash+S.debt)/2,unit:'грн',hint:S=>S.debt>0?'Спершу знайди всі витрати: власні гроші, яких уже немає, і ще позичені. Потім поділи на 2 місяці.':'Спершу знайди всі витрати: відніми залишок від початкової суми. Потім поділи на 2 місяці.',sol:S=>'Усього витрачено: 30 000 − '+PN(S.cash)+(S.debt>0?' + '+PN(S.debt):'')+' = '+PG(30000-S.cash+S.debt)+'. За місяць: '+PN(30000-S.cash+S.debt)+' : 2 = '+PG((30000-S.cash+S.debt)/2)+'. '+(S.debt>0?'Родина витратила більше, ніж мала: бажання перевищили можливості, і різницю доведеться повертати.':S.cash>=3000?'Родина вклалася у свої можливості: '+PG(S.cash)+' лишилося про запас і на те, що ще в списку.':'Боргів немає, але й запасу майже не лишилося: будь-яка несподіванка тепер означатиме позику.')}],
 finish:S=>{const wo=S.f.wfix||S.f.wok,ro=S.f.diy||S.f.pro||S.f.rmin;const lvl=S.debt===0&&wo&&ro&&S.mood>=62&&S.cash>=3000?2:S.debt<=5000&&wo?1:0;return{level:lvl,title:['Бажання перемогли можливості','Головне закрито, але з втратами','Родина вибирає впевнено'][lvl],text:'За два місяці: у родини лишилося '+PG(S.cash)+', борг — '+PG(S.debt)+', злагода — '+S.mood+' зі 100'+(S.wk>0?', нічим не зайнятих вихідних лишилося '+S.wk+'.':', усі вільні вихідні пішли на справи й спільний відпочинок.')+(S.f.rmin?' Повний ремонт дитячої — близько 9 000 грн — ще попереду.':''),tips:[S.f.wfix?'Пральну машину полагоджено, поки це коштувало 2 800 грн, — відкладена потреба не встигла стати терміновою.':S.f.wcheap?'Дешевий ремонт пральної машини довелося переробляти: 4 700 грн замість 2 800. Низька ціна без гарантії якості — не економія.':'Відкладений ремонт пральної машини повернувся більшим рахунком. Нагальну потребу дешевше закрити одразу.',S.debt>0?'Родина вийшла за межі своїх можливостей і тепер має борг. Наступного разу звір бажання із сумою до того, як обирати формат свята чи покупку.':'Витрати втримано в межах можливостей родини — без жодної позиченої гривні.',S.f.trend?'Трендові навушники коштували найдорожче в перерахунку на рік. Перед наступною модною покупкою порахуй ціну року користування.':S.f.together?'Спільний вихідний показав: інтереси родини — це не лише покупки, а й час разом.':'Спробуй ще раз і подбай про спільний час: злагода в родині залежить не тільки від грошей.']};},
 terms:[['Потреба','те, без чого людині чи родині складно або неможливо обійтися'],['Обмеженість ресурсів','грошей, часу й природних ресурсів завжди менше, ніж потрібно для всіх бажань'],['Альтернативна вартість','найкраще з того, від чого довелося відмовитися, обравши щось одне'],['Співвідношення «ціна/якість»','порівняння ціни речі з тим, як довго й наскільки добре вона служитиме'],['Трендова потреба','бажання мати річ, бо вона зараз у моді; таке бажання швидко минає']]});

PFG_TOPICS.push({id:'8-5',sec:'8b',title:'Плануємо родинний бюджет',minutes:30,
 intro:'Три місяці ти ведеш бюджет родини Коваленків: мама, тато, ти й молодша сестра. Ти рахуєш доходи, розподіляєш гроші, реагуєш на несподіванки. Кожне рішення змінює заощадження, борг і настрій родини — і з цим ти входиш у наступний місяць.',
 init:()=>({inc:53000,fixed:34000,save:3000,mood:60,debt:0,pay:0,cut:0,cl:0,fun:0,pocket:0,put:0,free2:0,spend2:0,f:{}}),
 meters:[{k:'save',label:'Заощадження',unit:'грн'},{k:'debt',label:'Борг',unit:'грн'},{k:'mood',label:'Настрій родини',unit:'/ 100'}],
 steps:[
  {id:'inc',t:'calc',head:'Місяць 1 · Доходи',text:'Початок місяця. Мама отримує 28 000 грн, тато — 22 000 грн, ще 3 000 грн тато заробляє підробітком у вихідні. У родини вже є 3 000 грн заощаджень.',q:'Скільки гривень становлять доходи родини за місяць?',ans:S=>S.inc,unit:'грн',hint:'Склади всі три надходження. Заощадження — це не дохід місяця.',sol:S=>'28 000 + 22 000 + 3 000 = 53 000 грн. Заощадження сюди не входять: це гроші, накопичені раніше.'},
  {id:'free',t:'calc',head:'Місяць 1 · Обов’язкові витрати',text:'Обов’язкові витрати родини на місяць: житло й комунальні послуги — 9 500 грн, їжа — 16 000, транспорт — 3 200, зв’язок та інтернет — 900, ліки й побутові товари — 2 400, гуртки дітей — 2 000 грн.',q:'Скільки гривень залишиться після обов’язкових витрат?',ans:S=>S.inc-S.fixed,unit:'грн',hint:'Спершу склади всі обов’язкові витрати, потім відніми їх від доходів 53 000 грн.',sol:S=>'Обов’язкові: 9 500 + 16 000 + 3 200 + 900 + 2 400 + 2 000 = 34 000 грн. Вільні гроші: 53 000 − 34 000 = 19 000 грн. Саме їх ти зараз розподілятимеш.'},
  {id:'plan',t:'plan',head:'Місяць 1 · План',text:'У тебе 19 000 грн вільних грошей. Розподіли їх повністю між чотирма статтями. Пам’ятай: родина хоче і радіти життю, і мати запас на несподіванки.',q:'Скільки гривень на кожну статтю?',
   fields:[{k:'cl',label:'Одяг і взуття'},{k:'fun',label:'Розваги, кафе, подарунки'},{k:'pocket',label:'Кишенькові гроші дітям'},{k:'put',label:'Відкласти в заощадження'}],
   total:S=>S.inc-S.fixed,
   best:S=>({cl:3000,fun:4500,pocket:1000,put:10500}),
   eff:(S,v)=>{Object.assign(S,v);S.save+=v.put;S.mood=Math.max(0,Math.min(100,S.mood+(v.fun>=4000?8:v.fun>=2000?0:-10)+(v.pocket>=800?3:-6)+(v.cl>=2000?2:-4)));},
   score:(S,v)=>v.put>=5300&&v.fun>=2000?{p:2,fb:'Відкладено не менше 10 % доходу, і на радість родині гроші лишилися. Це збалансований бюджет.'}:v.put>=5300?{p:1,fb:'Заощадження чудові, але на розваги майже нічого не лишилося. Бюджет без радості довго не витримують — настрій родини впав.'}:v.put>=2650?{p:1,fb:'Відкладено менше 10 % доходу. Орієнтир для заощаджень — щонайменше десята частина доходів, тобто 5 300 грн.'}:{p:0,fb:'Майже все пішло на поточні бажання, а запас лишився малим. Перша ж несподіванка це покаже.'}},
  {id:'fridge',t:'event',head:'Місяць 1 · Несподіванка',text:S=>'Наприкінці місяця ламається холодильник. Майстер із сервісного центру називає ціну ремонту: 5 500 грн. Чекати не можна — продукти псуються. У заощадженнях зараз '+PG(S.save)+'.'},
  {id:'fix',t:'choice',head:'Місяць 1 · Чим платити за ремонт',text:S=>S.save>=5500?'Заощаджень вистачає, щоб оплатити ремонт повністю.':'Заощаджень ('+PG(S.save)+') на ремонт не вистачає: бракує '+PG(5500-S.save)+'.',q:'Як оплатити ремонт?',o:[
   {l:'Оплатити із заощаджень',when:S=>S.save>=5500,p:2,eff:S=>{S.save-=5500;},fb:'Саме для цього й потрібна фінансова подушка: несподіванка не стала боргом.'},
   {l:S=>'Віддати всі заощадження, а про '+PG(5500-S.save)+' домовитися з майстром: він почекає до зарплати. Ці гроші підуть із розваг наступного місяця',when:S=>S.save<5500,p:2,eff:S=>{S.cut=5500-S.save;S.save=0;S.mood=Math.max(0,Math.min(100,S.mood-4));},fb:S=>'Неприємно, але без боргу під відсотки. Запас виявився замалим — так відгукнувся план першого місяця. Наступного місяця вільних грошей буде на '+PG(5500-S.save)+' менше.'},
   {l:'Оформити в сервісному центрі «розстрочку 0 %» на 4 місяці: за умовою задачі, комісія — 3 % від суми щомісяця',p:0,eff:S=>{S.debt+=6160;S.pay+=1540;S.f.had=1;},fb:'Комісія 3 % × 4 місяці = 12 %: за ремонт у 5 500 грн родина віддасть 6 160 грн. Чотири місяці поспіль із бюджету йтиме по 1 540 грн.'},
   {l:'Позичити 5 500 грн у бабусі й повертати частинами 4 місяці',p:1,eff:S=>{S.debt+=5500;S.pay+=1375;S.f.had=1;S.mood=Math.max(0,Math.min(100,S.mood-3));},fb:'Без відсотків, але борг є борг: чотири місяці по 1 375 грн уже не твої, і просити було ніяково.'}]},
  {id:'track',t:'choice',head:'Місяць 1 · Облік',text:'Місяць закінчився, і мама каже: «Я не розумію, куди діваються гроші між зарплатами».',q:'Як родина вестиме облік витрат?',o:[
   {l:'Записувати витрати щодня в застосунку й раз на тиждень переглядати',p:2,eff:S=>{S.f.track=1;},fb:'Хвилина на день — і наступного місяця буде видно те, чого зараз не видно.'},
   {l:'Складати чеки в коробку й порахувати колись потім',p:1,eff:S=>{},fb:'Дані є, а висновків немає. Наступного місяця вирішувати доведеться наосліп.'},
   {l:'Тримати все в голові',p:0,eff:S=>{},fb:'Великі покупки пам’ять зберігає, дрібні губить. А саме дрібні й «з’їдають» бюджет.'}]},
  {id:'m2',t:'event',head:'Місяць 2 · Зміни',text:S=>'Новий місяць приніс дві новини. Тато втратив підробіток — доходи родини тепер 50 000 грн. А продукти подорожчали на 5 %: на їжу потрібно вже 16 800 грн, тож обов’язкові витрати зросли до 34 800 грн.'+(S.pay?' До того ж відтепер щомісяця треба вносити платіж за боргом — '+PG(S.pay)+'.':'')+(S.cut?' І майстрові за холодильник треба доплатити '+PG(S.cut)+'.':''),eff:S=>{S.inc=50000;S.fixed=34800;}},
  {id:'free2',t:'calc',head:'Місяць 2 · Скільки вільних грошей',text:S=>'Доходи — 50 000 грн, обов’язкові витрати — 34 800 грн.'+(S.pay?' Платіж за боргом — '+PG(S.pay)+'.':S.cut?' Майстрові за ремонт холодильника треба доплатити '+PG(S.cut)+'.':' Боргів у родини немає.'),q:'Скільки гривень вільних грошей цього місяця?',ans:S=>S.inc-S.fixed-S.pay-S.cut,unit:'грн',hint:S=>'Від доходів відніми обов’язкові витрати'+(S.pay?' і платіж за боргом.':S.cut?' і доплату майстрові.':'.'),sol:S=>'50 000 − 34 800'+(S.pay?' − '+PN(S.pay):'')+(S.cut?' − '+PN(S.cut):'')+' = '+PG(S.inc-S.fixed-S.pay-S.cut)+'. Минулого місяця було 19 000 грн — план доведеться переглядати.',eff:S=>{S.free2=S.inc-S.fixed-S.pay-S.cut;S.debt=Math.max(0,S.debt-S.pay);}},
  {id:'cutplan',t:'choice',head:'Місяць 2 · Дефіцит плану',text:S=>'За планом першого місяця родина '+(S.put>=19000?'нічого не витрачала на одяг, розваги й кишенькові':'витрачала '+PG(S.cl+S.fun+S.pocket)+' на одяг, розваги й кишенькові')+' '+(S.put>0?'та відкладала '+PG(S.put):'і нічого не відкладала')+'. Разом це 19 000 грн, а вільних грошей тепер лише '+PG(S.free2)+'. Бракує '+PG(19000-S.free2)+'.'+(S.f.track?' Застосунок обліку показав: за місяць 1 900 грн пішло на снеки дорогою додому та три підписки, якими ніхто не користується.':' Куди саме розходяться дрібні гроші, ніхто в родині точно не знає.'),q:'Як збалансувати бюджет?',o:[
   {l:S=>'Прибрати непомітні витрати, знайдені в застосунку, решту скоротити з розваг'+(S.put>S.free2?'; відкладати все, що лишиться':S.put>=5000?'; відкладати, як і планувалося':' та відкладати 10 % доходу — 5 000 грн'),when:S=>!!S.f.track,p:2,eff:S=>{const put=S.put>=5000?Math.min(S.put,S.free2):5000;S.save+=put;S.spend2=S.free2-put;S.mood=Math.max(0,Math.min(100,S.mood-(S.put>=5000?1:3)));S.f.lean=1;},fb:S=>'Облік окупився: скорочено насамперед те, чого ніхто й не помітить. У заощадження цього місяця пішло '+PG(S.put>=5000?Math.min(S.put,S.free2):5000)+'.'},
   {l:S=>S.put>S.free2?'На одяг і розваги не витрачати нічого; відкладати все, що лишиться':S.put>=5000?'Скоротити одяг і розваги; відкладати, як і планувалося':'Скоротити одяг і розваги сильніше й відкладати 10 % доходу — 5 000 грн',p:2,eff:S=>{const put=S.put>=5000?Math.min(S.put,S.free2):5000;S.save+=put;S.spend2=S.free2-put;S.mood=Math.max(0,Math.min(100,S.mood-(S.put>=5000?6:8)));},fb:S=>'Дефіцит усунуто без боргу, у заощадження пішло '+PG(S.put>=5000?Math.min(S.put,S.free2):5000)+'. Родина сумує за кафе, але це чесна ціна.'},
   {l:S=>{const g=S.cl+S.fun+S.pocket-S.free2;return g<=0?'Звичні витрати не скорочувати, а відкласти те, що залишиться, — '+PG(-g):S.save>=g?'Звичні витрати не скорочувати: нічого не відкладати, а '+PG(g)+', яких бракує, узяти із заощаджень':'Звичні витрати не скорочувати й нічого не відкладати — якось воно буде';},p:S=>{const g=S.cl+S.fun+S.pocket-S.free2;return g>0?0:1;},eff:S=>{const sp=S.cl+S.fun+S.pocket,g=sp-S.free2;if(g<=0){S.save-=g;S.spend2=sp;}else{const tk=Math.min(g,S.save);S.save-=tk;S.spend2=S.free2+tk;if(g>tk)S.mood=Math.max(0,Math.min(100,S.mood-5));}},fb:S=>{const g=S.cl+S.fun+S.pocket-S.free2,tk=Math.min(Math.max(g,0),S.save);return g<=0?'Місяць закрито без боргу. У заощадження пішло '+PG(-g)+(-g>=5000?'. Це небагато менше, ніж могло б бути: скоротити бажання родина не захотіла.':' — менше десятої частини доходу. Запас росте повільніше, ніж міг би.'):'Цього місяця нічого не відкладено'+(tk?', а із запасу пішло '+PG(tk)+' на поточні бажання':'')+'.'+(g>tk?' Наприкінці місяця грошей усе одно забракло: від покупок на '+PG(g-tk)+' довелося відмовлятися поспіхом і зі сварками.':' Якщо так робити щомісяця, подушки не буде ніколи.');}},
   {l:S=>'Нічого не міняти, а '+PG(19000-S.free2)+', яких бракує, покрити кредитною карткою',p:0,eff:S=>{const pm=Math.round((19000-S.free2)*1.12/4);S.save+=S.put;S.spend2=S.cl+S.fun+S.pocket;S.debt+=4*pm;S.pay+=pm;S.f.had=1;S.f.card=1;S.mood=Math.max(0,Math.min(100,S.mood+2));},fb:S=>{const pm=Math.round((19000-S.free2)*1.12/4);return 'Сьогодні всі задоволені, але '+(S.put>0?'родина відкладає гроші й водночас позичає під відсотки.':'звичне життя тепер оплачується в борг.')+' За умовою задачі, банк бере 12 % від суми, а повертати треба чотири місяці. Борг зріс на '+PG(4*pm)+': з наступного місяця це ще '+PG(pm)+' щомісяця.';}}]},
  {id:'led',t:'choice',head:'Місяць 2 · Комунальні рахунки',text:S=>'Прийшли рахунки за комунальні послуги. Тато підрахував: якщо замінити всі лампи у квартирі на світлодіодні (1 800 грн), рахунок за світло зменшиться на 300 грн щомісяця. Є й дорожча ідея — утеплити вікна за 12 000 грн: це заощадить 400 грн на місяць на опаленні, але лише шість місяців опалювального сезону. У заощадженнях зараз '+PG(S.save)+'.',q:'Що вирішить родина?',o:[
   {l:'Купити світлодіодні лампи із заощаджень уже зараз',when:S=>S.save>=1800,p:2,eff:S=>{S.save-=1800;S.fixed-=300;S.f.led=1;},fb:'Невелике вкладення, яке з наступного місяця зменшує обов’язкові витрати на 300 грн.'},
   {l:'Купити лампи наступного місяця — з поточних грошей',when:S=>S.save<1800,p:2,eff:S=>{S.f.ledLater=1;},fb:'Запасу зараз замало, тож почекати місяць — розумно. Позичати заради економії було б дивно.'},
   {l:'Утеплити вікна в кредит на рік — економія ж більша',p:0,eff:S=>{S.debt+=13200;S.pay+=1100;S.f.had=1;S.f.win=1;},fb:'400 грн проти 300 виглядає краще, але вікна економлять лише пів року. А кредит, за умовою задачі, обійдеться в 13 200 грн: це 1 100 грн щомісяця цілий рік.'},
   {l:'Нічого не робити: рахунок не такий уже й великий',p:1,eff:S=>{},fb:'Грошей не витрачено, але й 300 грн щомісяця й далі йдуть у нікуди.'}]},
  {id:'payback',t:'calc',head:'Місяць 2 · Окупність',text:S=>S.f.win?'Перевір рішення про вікна: утеплення коштує 12 000 грн і заощаджує 400 грн на місяць протягом 6 місяців на рік.':'Порахуй окупність ламп: вони коштують 1 800 грн і заощаджують 300 грн щомісяця.',q:S=>S.f.win?'За скільки років окупиться утеплення (без урахування переплати за кредитом)?':'За скільки місяців окупляться лампи?',ans:S=>S.f.win?5:6,unit:S=>S.f.win?'років':'місяців',hint:S=>S.f.win?'Спершу знайди економію за рік: 400 × 6. Потім поділи вартість на річну економію.':'Поділи вартість ламп на щомісячну економію.',sol:S=>S.f.win?'Економія за рік: 400 × 6 = 2 400 грн. 12 000 : 2 400 = 5 років, а з переплатою за кредитом — ще довше. Лампи окупилися б за 6 місяців. Порівнювати треба не лише розмір економії, а й строк окупності.':'1 800 : 300 = 6 місяців. Далі лампи щомісяця зберігають родині 300 грн. Вікна за 12 000 грн окуповувалися б 5 років: 400 × 6 = 2 400 грн на рік.'},
  {id:'sis',t:'choice',head:'Місяць 2 · Кишенькові',text:S=>'Молодша сестра витратила всі кишенькові гроші за перший тиждень і просить у тебе ще 400 грн «до кінця місяця».'+(S.pocket<800?' Щоправда, і кишенькових у плані було небагато.':''),q:'Що ти зробиш?',o:[
   {l:'Не давати грошей, а сісти разом і скласти її план на місяць: обов’язкове, бажане, заощадження',p:2,eff:S=>{S.f.sis=1;S.mood=Math.max(0,Math.min(100,S.mood+2));},fb:'Найкорисніше, що можна дати, — не гроші, а вміння ними керувати.'},
   {l:'Дати 400 грн зі своїх у борг — поверне з наступних кишенькових',p:1,eff:S=>{S.mood=Math.max(0,Math.min(100,S.mood+1));},fb:'Сестра відчує ціну боргу, але чому гроші зникли за тиждень, так і не зрозуміє.'},
   {l:'Просто дати їй 400 грн із родинних грошей',p:0,eff:S=>{S.save=Math.max(0,S.save-400);S.mood=Math.max(0,Math.min(100,S.mood+3));},fb:S=>'Сьогодні всі задоволені. Але наступного місяця буде те саме'+(S.save>=400?', а запас родини зменшився на 400 грн.':', а 400 грн довелося забрати з грошей на продукти.')}]},
  {id:'m3',t:'event',head:'Місяць 3 · Підсумок і премія',text:S=>{const fx=S.fixed-(S.f.win?400:0),lamp=S.f.ledLater?1800:0,fr=S.inc-fx-S.pay-lamp,d=fr-S.spend2,tk=Math.min(Math.max(-d,0),S.save);return 'Третій місяць. Доходи ті самі — 50 000 грн.'+(S.f.led?' Рахунок за світло справді зменшився на 300 грн.':'')+(S.f.win?' Вікна утеплено: рахунок за опалення менший на 400 грн, зате додався платіж за кредитом — 1 100 грн.':'')+' Обов’язкові витрати — '+PG(fx)+(S.pay?', платежі за боргами — '+PG(S.pay):'')+(lamp?', лампи, як і планувалося, — 1 800 грн (рахунок за світло зменшиться з наступного місяця)':'')+'. Вільних грошей лишається '+PG(fr)+'.'+(S.spend2>0?' На одяг, розваги й кишенькові родина витрачає, як і минулого місяця, '+PG(S.spend2)+'.':' На одяг, розваги й кишенькові родина, як і минулого місяця, не витрачає нічого.')+(d>=0?' У заощадження пішло '+PG(d)+'.':' Цього не вистачає: '+(tk?PG(tk)+' довелося взяти із заощаджень'+(-d>tk?', а ще від покупок на '+PG(-d-tk)+' — відмовитися.':'.'):'від покупок на '+PG(-d)+' довелося відмовитися.'))+(S.f.sis?' Сестра вперше дотягнула кишенькові до кінця місяця й дуже цим пишається.':'')+' А ще мама отримала премію — 4 000 грн понад зарплату.';},eff:S=>{const fx=S.fixed-(S.f.win?400:0),lamp=S.f.ledLater?1800:0,d=S.inc-fx-S.pay-lamp-S.spend2;S.fixed=fx-(lamp?300:0);if(lamp)S.f.led=1;S.debt=Math.max(0,S.debt-S.pay);if(d>=0)S.save+=d;else{const tk=Math.min(-d,S.save);S.save-=tk;if(-d>tk)S.mood=Math.max(0,Math.min(100,S.mood-4));}}},
  {id:'bonus',t:'choice',head:'Місяць 3 · Що робити з премією',text:S=>'Премія 4 000 грн — це гроші поза планом.'+(S.debt>0?' У родини лишається борг '+PG(S.debt)+'.':' Боргів у родини немає.')+' Настрій родини зараз — '+PL(S.mood,'бал','бали','балів')+' зі 100.',q:'Як розпорядитися премією?',o:[
   {l:'Премію — на дострокове погашення боргу',when:S=>S.debt>0,p:2,eff:S=>{const p=Math.min(4000,S.debt);S.debt-=p;S.save+=4000-p;if(S.debt===0)S.pay=0;},fb:S=>S.debt<=4000?'Борг закрито повністю'+(S.debt<4000?', а решта премії — '+PG(4000-S.debt)+' — пішла в заощадження':'')+'. Щомісячних платежів більше немає: ці гроші знову вільні.':'Борг зменшився до '+PG(S.debt-4000)+'. Що швидше його закрити, то раніше платежі перестануть з’їдати вільні гроші.'},
   {l:'Половину відкласти, половину витратити на спільну радість',p:S=>S.debt>0?1:2,eff:S=>{S.save+=2000;S.mood=Math.max(0,Math.min(100,S.mood+6));},fb:S=>S.debt>0?'Розумний баланс, але поки є борг, він важливіший за нові заощадження.':'І запас зріс, і родина відчула, що економить не даремно.'},
   {l:'Усю премію відкласти',p:1,eff:S=>{S.save+=4000;S.mood=Math.max(0,Math.min(100,S.mood-3));},fb:S=>'Запас зріс на 4 000 грн. Але премія — рідкісна нагода потішити родину, і цього разу її пропущено.'+(S.debt>0?' Та й борг лишився.':'')},
   {l:'Усю премію — на вихідні в Карпатах',p:0,eff:S=>{S.mood=Math.max(0,Math.min(100,S.mood+12));},fb:S=>'Чудові вихідні. Але позапланові гроші зникли за два дні'+(S.debt>0?', а борг лишився.':', а запас не зріс.')}]},
  {id:'cushion',t:'calc',head:'Місяць 3 · Подушка безпеки',text:S=>'Підсумок трьох місяців. У заощадженнях родини '+PG(S.save)+'. Обов’язкові витрати на місяць — тепер '+PG(S.fixed)+'.',q:'На скільки місяців обов’язкових витрат вистачить заощаджень? Округли до десятих.',ans:S=>Math.round(S.save/S.fixed*10)/10,tol:0.1,unit:'міс.',hint:'Поділи заощадження на обов’язкові витрати за місяць.',sol:S=>{const a=Math.round(S.save/S.fixed*10)/10;return PN(S.save)+' : '+PN(S.fixed)+' ≈ '+PN(a)+' міс. Орієнтир для фінансової подушки — 3–6 місяців обов’язкових витрат. '+(a>=3?'Родина вже має такий запас.':a>=0.5?'Початок є. Подушку збирають не один місяць — головне не зупинятися.':'Поки що запасу не вистачить і на пів місяця.');}},
  {id:'goal',t:'calc',head:'Місяць 3 · Ціль на літо',text:S=>'Родина мріє про відпустку за 24 000 грн через 8 місяців. '+(S.debt>0?'А ще за ці 8 місяців вона хоче повністю повернути борг — '+PG(S.debt)+'.':'Боргів немає, тож усе відкладене піде на ціль.'),q:S=>'Скільки гривень щомісяця потрібно на відпустку'+(S.debt>0?' й борг разом? Округли до цілих гривень.':'?'),ans:S=>Math.round((24000+S.debt)/8),tol:1,unit:'грн',hint:S=>S.debt>0?'Додай до вартості відпустки суму боргу й поділи на 8 місяців.':'Поділи вартість відпустки на кількість місяців.',sol:S=>S.debt>0?'(24 000 + '+PN(S.debt)+') : 8 '+((24000+S.debt)%8?'≈ ':'= ')+PG(Math.round((24000+S.debt)/8))+' на місяць. Сама відпустка — це 3 000 грн на місяць; усе, що понад це, щомісяця забирає борг.':'24 000 : 8 = 3 000 грн на місяць. Це реально, якщо внесок у заощадження — така сама обов’язкова стаття, як комунальні послуги.'}],
 finish:S=>{const lvl=S.debt===0&&S.save>=12000&&S.mood>=55?2:S.save-S.debt>=5000?1:0;return{level:lvl,title:['Бюджет не втримався','Бюджет вистояв, але з втратами','Родина керує грошима впевнено'][lvl],text:'За три місяці: заощадження — '+PG(S.save)+', борг — '+PG(S.debt)+', настрій родини — '+PL(S.mood,'бал','бали','балів')+' зі 100.',tips:[S.debt>0?'Борг '+PG(S.debt)+' переходить у наступні місяці. Наступного разу, перш ніж позичати, перевір, чи не вистачить власних грошей і що можна скоротити.':S.f.had?'Борг закрито, але поки він був, платежі з’їдали вільні гроші. Перш ніж позичати, перевіряй, чи не вистачить власних грошей і що можна скоротити.':'Три місяці без жодного боргу — навіть коли впали доходи.',S.f.lean?'Облік витрат дав рішення, якого інакше не було б: скоротити непомітне.':S.f.track?'Облік вівся, але його підказкою — прибрати непомітні витрати — ніхто не скористався.':'Без обліку скорочувати довелося наосліп. Спробуй пройти ще раз і вести записи з першого місяця.',S.mood<55?'Настрій родини низький. Його псують і бюджет зовсім без радості, і сварки через гроші, яких забракло.':S.save<12000?'Родині було добре, але запас росте надто повільно. Відкладай щонайменше десяту частину доходу щомісяця.':'Вдалося втримати баланс між заощадженнями й радістю.']};},
 terms:[['Бюджет родини','план доходів і витрат родини на певний період'],['Дефіцит і профіцит','дефіцит — витрати більші за доходи; профіцит — доходи більші за витрати'],['Фінансова подушка','запас грошей на 3–6 місяців обов’язкових витрат'],['Окупність','час, за який вкладені гроші повертаються завдяки економії чи доходу']]});

PFG_TOPICS.push({id:'8-6',sec:'8b',title:'Запозичення, заощадження та інвестиції',minutes:30,
 intro:'Цілий рік — чотири квартали — ти разом із батьками керуєш грошима родини Мельників. На старті є 40 000 грн заощаджень і мета: ноутбук для твого навчання. Ти обираєш, де зберігати гроші, як діяти, коли вони знадобляться раніше, ніж планувалося, чи варто позичати й куди вкласти вільну суму. Вклад, борг і кредитна історія переходять із кварталу в квартал. А наприкінці ти зазирнеш на рік уперед і побачиш, що сталося з вкладеною премією.',
 init:()=>({free:40000,dep:0,debt:0,hist:70,q:0,m:0,r:15,r2:24,flex:0,home:0,L:0,T0:0,b1:0,b2:0,fx:0,ins:0,got:0,iv:0,lost:0,f:{}}),
 meters:[{k:'free',label:'Вільні гроші',unit:'грн'},{k:'dep',label:'На вкладі',unit:'грн'},{k:'debt',label:'Борг',unit:'грн'},{k:'hist',label:'Кредитна історія',unit:'/ 100'}],
 steps:[
  {id:'rate',t:'calc',head:'Січень · Звідки беруться заощадження',text:'Січень. У родини Мельників — мами Ірини, тата Олега, тебе й старшої сестри Соломії — 40 000 грн заощаджень. Вони лежать у шухляді. Твій ноутбук ледве працює, а для курсів програмування потрібен новий: він коштує 24 000 грн. Тато пропонує: «Цього року керуймо грошима разом і рахуймо все по-чесному». Доходи родини — 50 000 грн на місяць, усі витрати — 44 000 грн. Різницю можна відкладати.',q:'Скільки відсотків доходу родина може відкладати щомісяця?',ans:S=>12,unit:'% доходу',hint:'Спершу знайди, скільки гривень лишається, потім — яку частину від 50 000 грн це становить.',sol:S=>'50 000 − 44 000 = 6 000 грн. 6 000 : 50 000 = 0,12 = 12 %. Заощадження з’являються лише тоді, коли доходи більші за витрати, — це їхня перша передумова.'},
  {id:'habit',t:'choice',head:'Січень · Як відкладати',text:'Шість тисяч на місяць — це 18 000 грн за квартал. Але торік родина планувала так само, а відклала набагато менше: гроші «розходилися» ще до кінця місяця.',q:'Як родина відкладатиме цього року?',o:[
   {l:'У день зарплати одразу переказувати 6 000 грн на окремий рахунок, а жити на решту',p:2,eff:S=>{S.q=18000;S.m=6000;S.f.auto=1;},fb:'Спершу відкласти, потім витрачати: за квартал набирається 18 000 грн, і ніхто не помічає, як.'},
   {l:'Відкладати те, що лишиться наприкінці місяця',p:1,eff:S=>{S.q=9000;S.m=3000;},fb:'Лишається зазвичай менше, ніж планували: виходить близько 3 000 грн на місяць, тобто 9 000 грн за квартал.'},
   {l:'Не обмежувати себе щомісяця, а відкладати з премій і подарованих грошей',p:0,eff:S=>{S.q=3000;S.m=1000;},fb:'Такі гроші трапляються рідко: у середньому виходить лише 1 000 грн на місяць, тобто 3 000 грн за квартал. Без регулярності заощадження ростуть дуже повільно.'}]},
  {id:'bank',t:'choice',head:'Січень · Чия пропозиція краща',text:'Гроші в шухляді нічого не заробляють. Тато знайшов три пропозиції вкладу на 12 місяців (усі ставки й умови — за умовою задачі, податки з відсотків поки не рахуємо). Банк «А»: 15 % річних; якщо забрати гроші достроково, відсотків не виплатять. Банк «Б»: 13 % річних; гроші можна забрати будь-коли, і відсотки за фактичний строк збережуться. Обидва банки — учасники Фонду гарантування вкладів. Компанія «Швидкий капітал» (не банк): 28 % річних, у рекламі — «надійно, як у банку»; умови дострокового повернення надруковано дрібним шрифтом.',q:'Яку пропозицію обрати для вкладу?',o:[
   {l:'Банк «А»: 15 % річних, достроково — без відсотків',p:2,eff:S=>{S.r=15;S.f.banka=1;},fb:'Вищу з двох банківських ставок поєднано з державною гарантією вкладу. Ціна — ці гроші краще не чіпати цілий рік.'},
   {l:'Банк «Б»: 13 % річних, забрати можна будь-коли',p:1,eff:S=>{S.r=13;S.f.bankb=1;},fb:'Вклад захищений і гнучкий. Але гнучкість коштує 2 % річних: кожна тисяча принесе за рік на 20 грн менше. А для грошей «на всяк випадок» є картковий рахунок.'},
   {l:'«Швидкий капітал»: 28 % річних',p:0,eff:S=>{S.r=28;S.f.risky=1;},fb:'Майже вдвічі вища ставка — це плата за ризик. Вклади поза банками держава не гарантує: якщо компанія зникне, зникнуть і гроші.'}]},
  {id:'depcalc',t:'calc',head:'Січень · Як рахують відсотки',text:S=>'Ставку вказують за рік, навіть якщо гроші лежать менше. Перевір це на прикладі: 20 000 грн під '+S.r+' % річних на 6 місяців.',q:'Скільки гривень відсотків буде нараховано за ці 6 місяців?',ans:S=>100*S.r,unit:'грн',hint:'Знайди відсотки за цілий рік, а потім візьми ту частину року, яку лежали гроші.',sol:S=>'За рік: 20 000 × '+S.r+' % = '+PG(200*S.r)+'. Шість місяців — це половина року: '+PN(200*S.r)+' : 2 = '+PG(100*S.r)+'. Річна ставка не означає, що стільки нарахують за будь-який строк.'},
  {id:'alloc',t:'plan',head:'Січень · Розподіл заощаджень',text:S=>'За січень родина вже відклала '+PG(S.m)+', тож разом є '+PG(40000+S.m)+'. Розподіли ці гроші. Вклад на 12 місяців під '+S.r+' % річних'+(S.f.banka?': забереш достроково — відсотків не буде':S.f.bankb?': забрати можна будь-коли':': умови дострокового повернення заховано в договорі')+'. Картковий рахунок: гроші доступні щодня, але відсотків на залишок, за умовою задачі, не нараховують. Готівка вдома: завжди під рукою, але й спокуса велика. Мама просить, щоб щонайменше 12 000 грн можна було взяти будь-коли — на несподіванки.',q:'Скільки гривень куди?',
   fields:[{k:'term',label:'Вклад на 12 місяців'},{k:'flex',label:'Картковий рахунок'},{k:'home',label:'Готівка вдома'}],
   total:S=>40000+S.m,
   best:S=>({term:24000+S.m,flex:16000,home:0}),
   check:(S,v)=>(v.term%100||v.flex%100||v.home%100)?'Вводь суми, кратні 100 грн.':null,
   eff:(S,v)=>{S.dep=v.term;S.T0=v.term;S.flex=v.flex;S.home=v.home;S.free=v.flex+v.home;},
   score:(S,v)=>v.term>=20000&&v.flex+v.home>=12000&&v.home<=3000?{p:2,fb:'Запас під рукою, більша частина грошей працює на вкладі, удома — мінімум. Гроші розкладено за призначенням.'}:v.flex+v.home>=12000&&v.term>0?{p:1,fb:v.home>3000?'Запас є, і вклад є. Але вдома забагато готівки: вона нічого не заробляє й легко витрачається.':'Запас є, але на вклад пішло менше половини грошей — решта й далі нічого не заробляє.'}:v.term===0?{p:0,fb:'Усі гроші лишилися без відсотків. Те, що не працює, потроху втрачає вартість через зростання цін.'}:{p:0,fb:S.f.bankb?'Під рукою менше, ніж просила мама. Вклад у банку «Б» забрати можна, але тоді решту року ці гроші нічого не зароблять.':'Майже все замкнено на вкладі. Якщо гроші знадобляться раніше, доведеться або втрачати відсотки, або позичати.'}},
  {id:'q2',t:'event',head:'ІІ квартал · Несподіванка',text:S=>'Квітень. '+(S.home>=5000?'Готівка вдома потроху тане: 1 000 грн за три місяці пішла на «дрібні радощі», і ніхто не пам’ятає, на які саме. ':'')+'У татової машини зламалася коробка передач. Без авто він не дістанеться до роботи за містом. Ремонт коштує 22 000 грн.',eff:S=>{if(S.home>=5000){S.home-=1000;S.free-=1000;S.lost+=1000;}}},
  {id:'free2',t:'calc',head:'ІІ квартал · Що під рукою',text:S=>'Порахуй, скільки грошей родина може взяти одразу. На картковому рахунку — '+PG(S.flex)+', готівки вдома — '+PG(S.home)+'. За лютий і березень відкладено ще '+PG(S.q-S.m)+'. На вкладі — '+PG(S.T0)+(S.f.banka&&S.T0>0?', але якщо його чіпати, відсотки згорять.':'.'),q:'Скільки гривень під рукою, якщо не чіпати вклад?',ans:S=>S.flex+S.home+S.q-S.m,unit:'грн',hint:'Склади все, що лежить поза вкладом.',sol:S=>{const a=S.flex+S.home+S.q-S.m;return PN(S.flex)+' + '+PN(S.home)+' + '+PN(S.q-S.m)+' = '+PG(a)+'. '+(a>=22000?'Цього вистачає на ремонт за 22 000 грн.':'На ремонт за 22 000 грн бракує '+PG(22000-a)+'.');},eff:S=>{S.free=S.flex+S.home+S.q-S.m;}},
  {id:'car',t:'choice',head:'ІІ квартал · Чим платити за ремонт',text:S=>'Ремонт авто — 22 000 грн. Вільних грошей — '+PG(S.free)+', на вкладі — '+PG(S.dep)+'.'+(S.free<22000?' Бракує '+PG(22000-S.free)+'.':' Грошей вистачає.')+' Банк пропонує кредит: за умовою задачі, 24 % річних; повернути можна будь-коли, а відсотки беруть лише за фактичний строк.',q:'Як оплатити ремонт?',o:[
   {l:'Оплатити з вільних грошей',when:S=>S.free>=22000,p:2,eff:S=>{S.free-=22000;S.f.car=1;},fb:'Запас зробив свою справу: несподіванка не зачепила ні вклад, ні кредитну історію.'},
   {l:S=>'Віддати всі вільні гроші, а '+PG(22000-S.free)+' узяти в банку',when:S=>S.free<22000,p:2,eff:S=>{S.b1+=22000-S.free;S.debt=S.b1+S.b2+S.fx+S.ins;S.free=0;S.f.loan1=1;S.f.car=1;},fb:S=>'Позичено лише те, чого бракувало, на зрозумілих умовах, а вклад і далі заробляє. Квартал такого боргу коштує 6 % — '+PG(Math.round((22000-S.free)*.06))+'.'},
   {l:'Забрати вклад достроково й заплатити з нього',when:S=>S.dep>0,p:S=>S.free<22000?1:0,eff:S=>{S.got=S.f.bankb?Math.round(S.dep*.0325):0;if(S.f.risky)S.lost+=S.dep*.1;S.free+=(S.f.risky?S.dep*.9:S.dep+S.got)-22000;S.dep=0;S.f.broke=1;S.f.car=1;},fb:S=>S.f.risky?'«Швидкий капітал» повернув гроші, але утримав «комісію за дострокове розірвання» — 10 % вкладу, тобто '+PG(S.dep*.1)+'. Про неї йшлося в тому самому дрібному шрифті.':S.f.bankb?'Банк «Б» повернув вклад і відсотки за три місяці — '+PG(Math.round(S.dep*.0325))+'. Але решту року ці гроші вже нічого не зароблять.':'Банк «А» повернув вклад без відсотків: усе, що він мав заробити за рік, втрачено. Строковий вклад — не місце для грошей на несподіванки.'},
   {l:'Узяти в банку кредит на всі 22 000 грн, щоб не чіпати запас',when:S=>S.free>=22000,p:0,eff:S=>{S.b1+=22000;S.debt=S.b1+S.b2+S.fx+S.ins;S.f.loan1=1;S.f.car=1;},fb:'Запас цілий, але на 22 000 грн боргу щокварталу набігає 6 % — 1 320 грн. Це плата за гроші, які в родини й так були.'},
   {l:'Суму, якої бракує, взяти онлайн мікропозикою «за 5 хвилин без довідок»: за умовою задачі, 1 % на день',when:S=>S.free<22000,p:0,eff:S=>{S.fx+=Math.round((22000-S.free)*1.6);S.lost+=Math.round((22000-S.free)*.6);S.debt=S.b1+S.b2+S.fx+S.ins;S.free=0;S.f.micro=1;S.f.car=1;},fb:S=>'1 % на день здається дрібницею. Але швидко повернути таку суму родині нічим, і за 60 днів набігає 60 % понад позичене (більше, за умовою задачі, нарахувати не можуть). Замість '+PG(22000-S.free)+' доведеться віддати '+PG(Math.round((22000-S.free)*1.6))+'. У банку та сама сума за квартал коштувала б 6 %.'},
   {l:'Відкласти ремонт: тато поки добиратиметься автобусами',p:S=>S.free<22000?1:0,eff:S=>{S.f.nocar=1;},fb:'Гроші цілі, але тато втрачає три години на день і мусив відмовитися від підробітку: за квартал родина відкладе на 3 000 грн менше. А ремонтувати машину все одно доведеться.'}]},
  {id:'pay',t:'choice',head:'ІІ квартал · Платіж',text:S=>'У родини є ще стара розстрочка за холодильник: платіж 1 500 грн треба внести до 20 червня. Цього місяця через машину все пішло шкереберть, і мама згадала про платіж 19-го ввечері. Відомості про позики й прострочки потрапляють до бюро кредитних історій. Умовний рейтинг кредитної історії родини зараз — '+PL(S.hist,'бал','бали','балів')+' зі 100.',q:'Що зробити?',o:[
   {l:'Заплатити сьогодні ж і налаштувати автоплатіж на наступні місяці',p:2,eff:S=>{S.hist=Math.min(100,S.hist+10);S.f.autopay=1;},fb:'Платіж пройшов вчасно, а автоплатіж подбає про наступні. Вчасні внески поліпшують кредитну історію.'},
   {l:'Подзвонити в банк і попросити перенести дату на тиждень',p:1,eff:S=>{S.f.resched=1;},fb:'Цього разу банк пішов назустріч, прострочки немає. Але це разова послуга, а не система: наступного місяця дата знову може загубитися.'},
   {l:'Заплатити через два тижні, після зарплати: це ж лише 1 500 грн',p:0,eff:S=>{S.hist=Math.max(0,S.hist-25);S.f.late=1;S.lost+=200;if(S.free>=200)S.free-=200;else{S.fx+=200;S.debt=S.b1+S.b2+S.fx+S.ins;}},fb:'Банк нарахував 200 грн пені, а прострочка потрапила до кредитної історії. Сума мала, а запис лишиться надовго.'},
   {l:'Пропустити цей платіж, а в липні внести одразу два',p:0,eff:S=>{S.hist=Math.max(0,S.hist-35);S.f.late=1;},fb:'Місяць прострочки — це вже серйозний запис у кредитній історії. Наступний кредитор побачить його першим.'}]},
  {id:'q3',t:'event',head:'ІІІ квартал · Липень',text:S=>{const add=Math.max(0,S.q-(S.f.nocar?3000:0)),i1=Math.round(S.b1*.06),owe=S.b1+i1+S.fx,p=Math.min(add,owe),fr=S.free+add-p,sh=Math.max(0,24000-fr),r=S.hist>=70?24:36;return 'Липень. За другий квартал відкладено '+(add>0?PG(add):'0 грн')+(S.f.nocar?' — на 3 000 грн менше, ніж могло б бути, бо тато без машини втратив підробіток.':'.')+(owe>0?(i1>0?' За три місяці на борг у банку набігло '+PG(i1)+' відсотків.':'')+' У родині домовилися: відкладене насамперед іде на борги. '+(p>0?'Сплачено '+PG(p)+(owe>p?', лишилося '+PG(owe-p)+'.':' — борг закрито.'):'Але цього разу платити нічим: борг — '+PG(owe)+'.'):'')+(S.f.nocar?' Відкладати ремонт далі не можна: без машини тато може втратити роботу. А поломка за три місяці погіршилася — тепер ремонт коштує 24 000 грн. '+(sh>0?'Вільних грошей вистачило лише на '+PG(fr)+', решту — '+PG(sh)+' — довелося взяти в банку під '+r+' % річних.':'Його оплачено з вільних грошей.'):'')+' Тим часом твій ноутбук зависає дедалі частіше. А курс програмування, якого ти так чекаєш, починається у вересні.';},eff:S=>{const add=Math.max(0,S.q-(S.f.nocar?3000:0)),i1=Math.round(S.b1*.06);let a=Math.min(add,S.b1+i1+S.fx);S.free+=add-a;S.b1+=i1;S.lost+=i1;const x=Math.min(a,S.fx);S.fx-=x;a-=x;S.b1-=a;S.r2=S.hist>=70?24:36;if(S.f.nocar){const sh=Math.max(0,24000-S.free);S.free=Math.max(0,S.free-24000);S.b2+=sh;S.f.car=1;S.lost+=2000;}S.debt=S.b1+S.b2+S.fx+S.ins;}},
  {id:'inst',t:'calc',head:'ІІІ квартал · «Розстрочка 0 %»',text:'Новий ноутбук коштує 24 000 грн. У магазині консультант каже: «Навіщо платити одразу? Оформимо розстрочку під 0 % на 12 місяців!» У договорі дрібним шрифтом: щомісячна комісія за обслуговування — 2 % від ціни товару.',q:'Скільки гривень загалом покупець віддасть за ноутбук ціною 24 000 грн?',ans:S=>29760,unit:'грн',hint:'Знайди комісію за один місяць, помнож на 12 і додай до ціни.',sol:S=>'2 % від 24 000 = 480 грн на місяць. За 12 місяців: 480 × 12 = 5 760 грн — це переплата. Загальна сума до сплати: 24 000 + 5 760 = 29 760 грн. «0 %» у рекламі не означає «безкоштовно»: дивитися треба на загальну суму й комісії.'},
  {id:'lapbuy',t:'choice',head:'ІІІ квартал · Купити зараз чи почекати',text:S=>'Ноутбук — 24 000 грн. Вільних грошей — '+PG(S.free)+'.'+(S.debt>0?' На родині вже є борг — '+PG(S.debt)+'.':'')+(S.free<24000?' На ноутбук бракує '+PG(24000-S.free)+'. Банк, глянувши на кредитну історію родини ('+S.hist+' зі 100), пропонує кредит під '+(S.r2===24?'24 % річних (за умовою задачі).':'36 % річних — позичальникам без прострочок, за умовою задачі, дають під 24 %.'):'')+' У магазині є ще відновлений ноутбук із гарантією на рік за 16 000 грн: трохи слабший, але для навчання його достатньо. А можна почекати до грудня й накопичити: старий ноутбук поки що вмикається.',q:'Що вирішить родина?',o:[
   {l:'Заплатити за новий власними грошима',when:S=>S.free>=24000,p:2,eff:S=>{S.free-=24000;S.f.own=1;},fb:'Жодної переплати: ноутбук коштував рівно 24 000 грн. Саме для цього родина й відкладала.'},
   {l:S=>S.free>0?'Купити новий зараз: віддати всі вільні гроші, а '+PG(24000-S.free)+' узяти в банку':'Купити новий зараз: усі 24 000 грн узяти в банку',when:S=>S.free<24000,p:1,eff:S=>{S.L=24000-S.free;S.b2+=S.L;S.debt=S.b1+S.b2+S.fx+S.ins;S.free=0;S.f.loan2=1;},fb:S=>'Ноутбук є вже зараз'+(S.free>0?', і позичено лише різницю':'')+'. Але за пів року на '+PG(24000-S.free)+' боргу набіжить '+PG(Math.round((24000-S.free)*S.r2/200))+' відсотків, а запасу під рукою не лишилося зовсім.'},
   {l:'Купити відновлений за 16 000 грн власними грошима',when:S=>S.free>=16000,p:S=>S.free<24000?2:1,eff:S=>{S.free-=16000;S.f.refurb=1;},fb:S=>S.free<24000?'Для навчання вистачить, гарантія є, і жодного боргу. Потребу закрито тими грошима, які були.':'Для навчання вистачить, а 8 000 грн різниці лишилися в родині. Хоча на новий грошей теж вистачало.'},
   {l:'Почекати до грудня й накопичити, а поки що вчитися на старому',p:S=>S.free<24000?2:1,eff:S=>{S.f.wait=1;},fb:S=>S.free<24000?(S.debt>0?'Нового боргу немає, переплати теж.':'Жодного боргу й жодної переплати.')+' Ціна очікування — пів року на старому ноутбуці, який зависає посеред занять.':'Гроші на ноутбук уже є, і потреба справжня. Пів року на старому, який зависає посеред занять, нічого не заощадять.'},
   {l:'Оформити «розстрочку 0 %» на всі 24 000 грн, а свої гроші не чіпати',p:0,eff:S=>{S.ins+=29760;S.lost+=5760;S.debt=S.b1+S.b2+S.fx+S.ins;S.f.inst=1;},fb:'Власні гроші цілі, але за ноутбук родина віддасть 29 760 грн. Комісія 2 % на місяць — це 5 760 грн понад ціну.'},
   {l:'Суму, якої бракує, взяти мікропозикою онлайн: за умовою задачі, 1 % на день, без довідок і черг',when:S=>S.free<16000,p:0,eff:S=>{S.fx+=Math.round((24000-S.free)*1.6);S.lost+=Math.round((24000-S.free)*.6);S.debt=S.b1+S.b2+S.fx+S.ins;S.free=0;S.f.micro=1;},fb:S=>'Гроші прийшли за п’ять хвилин. Але швидко повернути їх родині нічим, і за 60 днів набігає 60 % понад позичене (більше, за умовою задачі, нарахувати не можуть): замість '+PG(24000-S.free)+' доведеться віддати '+PG(Math.round((24000-S.free)*1.6))+'.'}]},
  {id:'loan',t:'calc',head:'ІІІ квартал · Ціна кредитної історії',text:S=>S.f.loan2?'Родина взяла в банку '+PG(S.L)+' під '+(S.r2===24?'24 % річних. Якби в кредитній історії були прострочки, ставка, за умовою задачі, була б 36 %.':'36 % річних. Якби прострочки не було, ставка, за умовою задачі, була б 24 %.'):'Тато про всяк випадок дізнався умови банку (за умовою задачі): кредит 20 000 грн позичальникам без прострочок дають під 24 % річних, а з прострочками — під 36 %. У кредитній історії родини'+(S.f.late?' прострочка є.':' прострочок немає.'),q:S=>(S.f.loan2?(S.r2===24?'Скільки гривень відсотків за рік зберігає родині чиста кредитна історія?':'Скільки гривень зайвих відсотків за рік коштує родині зіпсована кредитна історія?'):'На скільки гривень більше відсотків за рік заплатить позичальник із прострочками?')+' Округли до цілих гривень.',ans:S=>Math.round((S.f.loan2?S.L:20000)*12/100),tol:1,unit:'грн',hint:'Порахуй відсотки за рік за кожною ставкою й знайди різницю. Або одразу знайди 12 % від суми: 36 − 24 = 12.',sol:S=>{const a=S.f.loan2?S.L:20000;return PN(a)+' × 36 % = '+PG(Math.round(a*36)/100)+'; '+PN(a)+' × 24 % = '+PG(Math.round(a*24)/100)+'. Різниця: '+PG(Math.round(a*12/100))+'. Та сама сума в тому самому банку коштує по-різному — залежно від того, як позичальник платив раніше.';}},
  {id:'q4',t:'event',head:'IV квартал · Грудень',text:S=>{const add=2*S.q,i=Math.round(S.b1*.12)+Math.round(S.b2*S.r2/200),owe=S.b1+S.b2+S.fx+i,due=Math.min(S.ins,14880),ip=Math.min(due,add+S.free),p=Math.min(Math.max(0,add-ip),owe);return 'Грудень. За друге півріччя відкладено ще '+PG(add)+'.'+(S.ins>0?' За розстрочкою за ноутбук за пів року внесено '+PG(ip)+(ip<due?' — на більше грошей не вистачило':'')+'; на наступний рік лишається '+PG(S.ins-ip)+'.':'')+(owe>0?(i>0?' За пів року на борг у банку набігло '+PG(i)+' відсотків.':'')+(p>0?' Відкладене насамперед іде на борги: сплачено '+PG(p)+(owe>p?', лишилося '+PG(owe-p)+'.':S.ins>0?' — цей борг закрито.':' — боргів більше немає.'):' Платити за рештою боргів нічим: вони становлять '+PG(owe)+'.'):'')+(S.dep>0?(S.f.risky?' А від «Швидкого капіталу» тривожні новини: сайт не відкривається, телефони мовчать.':' Строк вкладу в банку добіг кінця.'):S.f.broke?' Вкладу в родини вже немає: його забрали навесні.':' Вкладу родина не відкривала.')+(S.f.wait?' Ти досі вчишся на старому ноутбуці: за осінь він тричі зависав посеред заняття.':'');},eff:S=>{const add=2*S.q;S.lost+=Math.round(S.b1*.12)+Math.round(S.b2*S.r2/200);S.b1+=Math.round(S.b1*.12);S.b2+=Math.round(S.b2*S.r2/200);const ip=Math.min(S.ins,14880,add+S.free);S.ins-=ip;let rest=add-ip;if(rest<0){S.free+=rest;rest=0;}let a=Math.min(rest,S.b1+S.b2+S.fx);S.free+=rest-a;for(const k of ['fx','b1','b2']){const x=Math.min(a,S[k]);S[k]-=x;a-=x;}S.debt=S.b1+S.b2+S.fx+S.ins;}},
  {id:'yield',t:'calc',head:'IV квартал · Що приніс вклад',text:S=>S.T0===0?'Вкладу родина не відкривала. Тато підрахував, що було б, якби 20 000 грн пролежали рік у банку «А» під 15 % річних.':S.f.broke?(S.f.risky?'Навесні родина забрала зі «Швидкого капіталу» вклад '+PG(S.T0)+' і втратила на цьому комісію — 10 % суми. А тепер компанія збанкрутувала: тим, хто тримав гроші до кінця, повернули лише половину вкладу.':S.f.bankb?'Навесні родина забрала з банку «Б» вклад '+PG(S.T0)+' під 13 % річних і отримала відсотки лише за три місяці — '+PG(S.got)+'.':'Навесні родина достроково забрала з банку «А» вклад '+PG(S.T0)+' під 15 % річних і не отримала відсотків.'):S.f.risky?'«Швидкий капітал» збанкрутував. Вкладникам повернули лише половину вкладених грошей і жодних відсотків. У родини там було '+PG(S.T0)+'.':'На вкладі рік пролежали '+PG(S.T0)+' під '+S.r+' % річних.',q:S=>S.T0===0?'Скільки гривень відсотків принесли б ці 20 000 грн за рік?':S.f.broke?(S.f.risky?'Скільки гривень комісії втратила родина навесні?':'Скільки гривень відсотків нарахував би банк, якби вклад пролежав увесь рік?'):S.f.risky?'Скільки гривень родина втратила?':'Скільки гривень відсотків нарахував банк?',ans:S=>S.T0===0?3000:S.f.risky?(S.f.broke?S.T0/10:S.T0/2):S.T0*S.r/100,unit:'грн',hint:S=>S.T0>0&&S.f.risky?(S.f.broke?'10 % — це десята частина суми.':'Половина вкладу — це його сума, поділена на 2.'):'Гроші лежали б рівно рік, тож треба знайти річний відсоток від суми вкладу.',sol:S=>S.T0===0?'20 000 × 15 % = 3 000 грн. Стільки коштував родині рік, коли всі гроші були «під рукою».':S.f.risky?(S.f.broke?PN(S.T0)+' × 10 % = '+PG(S.T0/10)+'. Якби гроші лишилися в компанії, пропала б половина вкладу — '+PG(S.T0/2)+'. Родину врятував випадок, а не розрахунок, і навіть цей порятунок обійшовся в '+PG(S.T0/10)+'.':PN(S.T0)+' : 2 = '+PG(S.T0/2)+'. Обіцяні 28 % так і лишилися в рекламі. Висока ставка без державної гарантії — це ризик втратити сам вклад.'):PN(S.T0)+' × '+S.r+' % = '+PG(S.T0*S.r/100)+'. '+(S.f.broke?(S.f.bankb?'Родина отримала лише '+PG(S.got)+': дострокове зняття коштувало їй '+PG(S.T0*S.r/100-S.got)+'.':'Така ціна грошей, покладених не за призначенням.'):'Разом із вкладом родина отримує '+PG(S.T0+S.T0*S.r/100)+'. У житті з відсотків ще утримали б податки, тож на руки вийшло б трохи менше.'),eff:S=>{if(S.dep>0){S.free+=S.f.risky?S.dep/2:S.dep+S.dep*S.r/100;if(S.f.risky){S.f.burned=1;S.lost+=S.dep/2;}else S.f.earned=1;S.dep=0;}}},
  {id:'lapdec',t:'event',when:S=>!!S.f.wait,head:'IV квартал · Ноутбук',text:S=>S.free>=24000?'Пів року очікування позаду. Вільних грошей — '+PG(S.free)+': новий ноутбук куплено за 24 000 грн — за власні гроші, без жодної гривні переплати.':S.free>=16000?'Пів року очікування позаду, але на новий ноутбук грошей так і не назбиралося: вільних лише '+PG(S.free)+'. Родина купує відновлений за 16 000 грн.':'Пів року очікування позаду, але вільних грошей лише '+PG(S.free)+'. Цього не вистачає навіть на відновлений ноутбук, тож покупку знову відкладено.',eff:S=>{if(S.free>=24000){S.free-=24000;S.f.own=1;}else if(S.free>=16000){S.free-=16000;S.f.refurb=1;}else S.f.nolap=1;}},
  {id:'inv',t:'choice',head:'IV квартал · Премія',text:S=>'Мама отримала річну премію — 10 000 грн. Це гроші понад план. '+(S.debt>0?'У родини ще лишається борг '+PG(S.debt)+', вільних грошей — '+PG(S.free)+'. ':'Боргів у родини немає. ')+'Соломія пропонує премію вкласти: «Державні облігації дають, за умовою задачі, 16 % річних і вважаються одним із найнадійніших вкладень. Фонд акцій може дати більше, а може й піти в мінус. А ще мій одногрупник збирає гроші в „криптопроєкт“: обіцяє 5 % на тиждень».',q:'Як розпорядитися премією?',o:[
   {l:'Спершу закрити борг — премією, а якщо її не вистачить, то й вільними грошима; решту додати до запасу',when:S=>S.debt>0,p:2,eff:S=>{let a=Math.min(S.free+10000,S.debt);S.free+=10000-a;for(const k of ['fx','b1','b2','ins']){const x=Math.min(a,S[k]);S[k]-=x;a-=x;}S.debt=S.b1+S.b2+S.fx+S.ins;S.hist=Math.min(100,S.hist+5);S.f.repaid=1;},fb:S=>(S.debt<=S.free+10000?'Борг закрито повністю.':'Борг зменшився до '+PG(S.debt-S.free-10000)+'.')+' Відсотки за боргом вищі, ніж дохід від надійних вкладень, тож погасити його — найвигідніше, що можна зробити з вільними грошима.'},
   {l:'Розділити: 5 000 грн — в облігації, 3 000 грн — на вклад у банку, 2 000 грн — у фонд акцій',p:S=>S.debt>0?1:2,eff:S=>{S.f.div=1;},fb:S=>S.debt>0?'Розподіл розумний, але поки є борг, відсотки за ним перекривають дохід від вкладень.':'Гроші розкладено по різних кошиках: якщо один підведе, інші втримають результат. Це й є диверсифікація.'},
   {l:'Усе — у фонд акцій: торік він зріс на 40 %',p:S=>S.debt>0?0:1,eff:S=>{S.f.one=1;},fb:'Торішнє зростання нічого не обіцяє на завтра. Тепер уся премія залежить від одного ринку.'},
   {l:'Усе — у «криптопроєкт»: 5 % на тиждень — такого не дасть жоден банк',p:0,eff:S=>{S.f.scam=1;},fb:'Дохідність, якої не дає ніхто інший, і «гарантія» на словах — дві головні ознаки шахрайства. Що вища обіцянка, то вищий ризик.'}]},
  {id:'mkt',t:'event',head:'Епілог · Рік потому',text:S=>'Зазирнімо на рік уперед. Облігації принесли обіцяні 16 %, вклад у банку — 15 %, а фонд акцій за цей рік упав на 20 %. «Криптопроєкт» зник разом із сайтом і грошима всіх учасників. '+(S.f.repaid?'Твоя родина премію не вкладала: вона пішла на борг, і відсотки за ним більше не набігали.':S.f.div?'Премію родини було розділено на три частини.':S.f.one?'Уся премія родини була у фонді акцій.':'Уся премія родини була в «криптопроєкті» — і зникла разом із ним.'),eff:S=>{S.iv=S.f.div?10850:S.f.one?8000:0;S.lost+=S.f.one?2000:S.f.scam?10000:0;}},
  {id:'res',t:'calc',head:'Епілог · Ризик і дохідність',text:S=>S.f.one?'У фонд акцій було вкладено 10 000 грн, і за рік він упав на 20 %.':(S.f.div?'Порахуй результат розділеного портфеля':S.f.scam?'Премії вже не повернути. Порахуй, яким був би результат розділеного портфеля':'Порахуй, яким був би за цей рік результат розділеного портфеля')+': 5 000 грн в облігаціях (+16 %), 3 000 грн на вкладі (+15 %), 2 000 грн у фонді акцій (−20 %).',q:S=>S.f.one?'Скільки гривень лишилося від премії?':'Скільки гривень стало б із 10 000 грн за рік?',ans:S=>S.f.one?8000:10850,unit:'грн',hint:S=>S.f.one?'Падіння на 20 % означає, що лишилося 80 % суми.':'Порахуй кожну частину окремо: зростання на 16 % — це множення на 1,16; падіння на 20 % — на 0,8.',sol:S=>S.f.one?'10 000 × 0,8 = 8 000 грн. Фонд міг і зрости — наперед цього не знає ніхто. Саме тому гроші ділять: портфель із трьох частин дав би 10 850 грн, бо втрату на акціях перекрили б облігації та вклад.':'5 000 × 1,16 = 5 800; 3 000 × 1,15 = 3 450; 2 000 × 0,8 = 1 600. Разом: 10 850 грн. Одна частина втратила п’яту частину вартості, а портфель загалом усе одно зріс — так працює диверсифікація. Самі облігації дали б більше, але наперед ніхто не знав, що зросте, а що впаде.'}],
 finish:S=>{const w=S.free-S.debt+S.iv,lvl=S.debt===0&&S.hist>=70&&w>=35000&&S.lost<=4000&&!S.f.nolap&&S.f.earned?2:w>=15000&&!S.f.nolap?1:0;return{level:lvl,title:['Гроші керували родиною','Рік пройдено, але дорогою ціною','Гроші працюють на родину'][lvl],text:'На кінець року: вільних грошей — '+PG(S.free)+', борг — '+PG(S.debt)+', кредитна історія — '+PL(S.hist,'бал','бали','балів')+' зі 100. '+(S.f.nolap?'Ноутбука досі немає.':S.f.refurb?'Для навчання куплено відновлений ноутбук.':'Ноутбук для навчання куплено.')+(S.f.div?' Вкладена премія за рік перетворилася на 10 850 грн.':S.f.one?' Від вкладеної премії за рік лишилося 8 000 грн.':S.f.scam?' Премію втрачено в «криптопроєкті».':'')+(S.lost>0?' Усі втрати року (відсотки за позиками, комісії, пеня, розтрачена готівка, невдалі вкладення) — '+PG(S.lost)+'.':' На відсотки за позиками, пеню й невдалі вкладення не втрачено ні гривні.'),tips:[S.f.auto?'Автоматичний переказ у день зарплати давав 18 000 грн щокварталу — на цьому трималися всі подальші рішення.':'Родина відкладала нерегулярно, тому запас ріс повільно. Спробуй принцип «спершу відклади, потім витрачай».',S.f.late?'Одна прострочка на 1 500 грн зіпсувала кредитну історію: за умовою задачі, кредит для такої родини дорожчає з 24 до 36 % річних. Автоплатіж не коштує нічого.':'Вчасні платежі зберегли кредитну історію — а з нею й дешевші позики на майбутнє.',S.f.burned?'Ставка 28 % поза банком виявилася платою за ризик: половина вкладу пропала. Перед вкладом перевіряй, чи гарантує його держава.':S.f.risky&&S.f.broke?'«Швидкий капітал» збанкрутував. Гроші родини вціліли випадково, та й то без 10 % комісії. Перед вкладом перевіряй, чи гарантує його держава.':S.f.scam?'Обіцянка 5 % на тиждень закінчилася втратою всієї премії. Надвисока «гарантована» дохідність — ознака шахрайства.':S.f.micro?'Мікропозика під 1 % на день обійшлася в 60 % понад позичене. Швидкі гроші — найдорожчі.':S.f.div?'Премію розділено між різними інструментами, тож одна невдача не з’їла результат.':S.f.repaid?'Премія пішла на борг, і відсотки за ним перестали набігати. Борг варто гасити раніше, ніж щось вкладати.':S.debt>0?'Борг '+PG(S.debt)+' переходить у наступний рік, і відсотки на нього набігають далі. Гаси його раніше, ніж вкладати.':'Вільні гроші варто розкладати по різних кошиках: наступного разу спробуй диверсифікацію.']};},
 terms:[['Депозит (вклад)','гроші, передані банку на зберігання за винагороду — відсотки'],['Кредит','гроші, позичені на певний строк, які треба повернути з відсотками'],['Переплата','різниця між усією сумою, сплаченою за кредитом, і позиченою сумою'],['Кредитна історія','відомості про те, як людина брала й повертала позики'],['Диверсифікація','розподіл грошей між різними вкладеннями, щоб зменшити ризик']]});

PFG_TOPICS.push((()=>{
 /* допоміжні функції (стан: card — основна картка, virt — віртуальна, jar — накопичувальний рахунок) */
 const sec=(S,d)=>{S.sec=Math.max(0,Math.min(100,S.sec+d));};
 const sync=S=>{S.side=S.virt+S.jar;};
 const day=S=>S.lim>0?Math.min(S.card,S.lim):S.card;                 /* скільки можна списати з основної картки за добу */
 const drain=S=>S.f.notif?day(S):Math.min(S.card,2*day(S));          /* без сповіщень пропажу видно лише наступного дня */
 const take=(S,x)=>{x=Math.max(0,Math.min(S.card,x));S.card-=x;S.lost+=x;return x;};
 const pay=(S,x)=>{const a=Math.min(S.card,x),b=Math.min(S.jar,x-a);S.card-=a;S.jar-=b;sync(S);return a+b;};
 const jn=(S,x)=>S.card<x?' На основній картці грошей бракувало, тож '+PG(Math.min(S.jar,x-S.card))+' довелося переказати з накопичувального рахунку.':'';
 const hitWhy=S=>{const x=drain(S);
  if(!S.card)return 'На основній картці не було ні гривні, тож цього разу списувати нічого. Але дані картки тепер у чужих руках.';
  if(!S.lim)return 'З картки списали все — '+PG(x)+': добового ліміту немає.';
  if(S.f.notif)return 'З картки списали '+PG(x)+'. '+(x<S.lim?'Це все, що на ній було.':'Більше за добу не дозволив ліміт.')+' Сповіщення показало списання одразу.';
  return 'З картки списали '+PG(x)+'. Сповіщень про кожну операцію немає, тож пропажу видно аж наступного дня: '+(x<2*S.lim?'за цей час забрали все, що було на картці.':'ліміт '+PG(S.lim)+' спрацював двічі.');};
 const norm=v=>{const r=x=>Math.round((x||0)/100)*100;let jar=Math.min(5500,Math.max(3000,r(v.jar))),main=Math.max(500,r(v.main));if(main+jar>6000)main=6000-jar;return{main:main,jar:jar,virt:6000-jar-main};};
 const shop=S=>{const top=Math.max(0,540-S.card),c=S.card+top,d=S.lim>0?Math.min(c,S.lim):c,dr=S.f.notif?d:Math.min(c,2*d);return{top:top,x:Math.min(c,Math.max(540,dr))};};
 const own=S=>S.f.hit||S.f.vhit;
 const left=S=>S.card+S.virt+S.jar;
 const W=n=>PL(n,'тиждень','тижні','тижнів');
 return {id:'8-7',sec:'8b',title:'Фінансова безпека та шахрайство',minutes:30,
 intro:'Тобі 14, і в тебе перша банківська картка. На ній 6 000 грн — подарунки на день народження й те, що вже відкладено на велосипед за 9 000 грн. Перші дні ти налаштовуєш захист. Потім два тижні до тебе приходять ті, хто хоче ці гроші забрати: «покупчиня», «служба безпеки банку», «інвестклуб», «магазин» і «друг». Від налаштувань у перші дні залежить, скільки можна втратити потім.',
 init:()=>({card:6000,side:0,sec:20,lost:0,virt:0,jar:0,lim:0,pyr:0,pyr0:0,gran:0,f:{}}),
 meters:[{k:'card',label:'На основній картці',unit:'грн'},{k:'side',label:'Накопичувальний рахунок і віртуальна картка',unit:'грн'},{k:'sec',label:'Рівень захисту',unit:'зі 100'},{k:'lost',label:'Втрачено',unit:'грн'}],
 steps:[
  {id:'start',t:'event',head:'День 1 · Перша картка',text:'Понеділок. Мама віддає тобі картку й запечатаний конверт із PIN-кодом: «Картка твоя. Як її захистити, вирішуй без мене — у застосунку банку все є». На картці 6 000 грн. До велосипеда бракує ще 3 000 грн.'},
  {id:'pin',t:'choice',head:'День 1 · PIN-код',text:'У конверті — чотири цифри. PIN потрібен у банкоматі й для великих покупок у магазині. Його можна змінити в застосунку.',q:'Що зробити з PIN-кодом?',o:[
   {l:'Запам’ятати, конверт порвати й викинути, нікому не казати',p:2,eff:S=>{sec(S,15);S.f.pin=1;},fb:'PIN тепер існує лише у твоїй голові. Навіть якщо картка загубиться, готівку з неї не знімуть.'},
   {l:'Змінити на свій рік народження — так точно не забудеться',p:0,eff:S=>{S.f.pinyear=1;},fb:'Запам’ятати легко — і вгадати теж: рік народження є в учнівському квитку та в соцмережах.'},
   {l:'Записати на папірці й носити в одному чохлі з карткою',p:0,eff:S=>{S.f.pinpaper=1;},fb:'Тепер картка й ключ до неї лежать разом. Хто знайде чохол, знайде все одразу.'},
   {l:'Зберегти в нотатках телефона під назвою «код від домофона»',p:1,eff:S=>{sec(S,10);S.f.pinnote=1;},fb:'Краще, ніж папірець біля картки. Але телефон теж може потрапити в чужі руки. Найнадійніше місце для PIN — пам’ять.'}]},
  {id:'limit',t:'choice',head:'День 1 · Ліміти',text:'У застосунку є розділ «Ліміти»: скільки грошей на добу можна зняти готівкою чи витратити карткою. Зараз обмежень немає. Твої звичайні витрати — обід, проїзд, дрібниці: до 200 грн на день.',q:'Який добовий ліміт поставити?',o:[
   {l:'500 грн на добу; для великої покупки тимчасово підніму',p:2,eff:S=>{S.lim=500;sec(S,20);},fb:'Щоденним витратам ліміт не заважає, а чужим рукам не дасть забрати за добу більше ніж 500 грн.'},
   {l:'1 500 грн на добу — із запасом, щоб не міняти щоразу',p:1,eff:S=>{S.lim=1500;sec(S,10);},fb:'Якийсь захист є. Але 1 500 грн — це більше, ніж ти витрачаєш за тиждень: стільки за добу зможе забрати й чужа людина.'},
   {l:'Без лімітів: це мої гроші, навіщо собі щось забороняти',p:0,eff:S=>{S.lim=0;},fb:'Зручно. Але без ліміту з картки можна списати все до копійки — і не лише тобі.'}]},
  {id:'notif',t:'choice',head:'День 2 · Сповіщення',text:'Застосунок питає, чи надсилати сповіщення про операції з карткою.',q:'Що обрати?',o:[
   {l:'Про кожну операцію, навіть на 5 грн',p:2,eff:S=>{S.f.notif=1;sec(S,20);},fb:'Будь-яке списання видно за секунди — і можна заблокувати картку, поки не зникло більше.'},
   {l:'Лише про операції понад 1 000 грн',p:1,eff:S=>{S.f.notifbig=1;sec(S,10);},fb:'Великі списання ти помітиш. Але шахраї часто знімають потроху — сумами, які не привертають уваги.'},
   {l:'Вимкнути: вони дратують і відволікають на уроках',p:0,eff:S=>{S.f.nonotif=1;},fb:'У телефоні тиша — і така сама тиша про те, що відбувається з грошима. Про списання ти дізнаєшся, лише коли відкриєш застосунок.'}]},
  {id:'split',t:'plan',head:'День 2 · Де лежать гроші',text:'У застосунку можна безплатно відкрити віртуальну картку для покупок в інтернеті та накопичувальний рахунок: ним не можна платити, і дані картки доступу до нього не дають. Мама просить про одне: щонайменше половину, 3 000 грн, одразу покласти на накопичувальний рахунок. Решту розподіляєш ти. На обіди, проїзд і дрібниці тобі досить 1 000–1 500 грн на два тижні. На покупки в інтернеті ти зазвичай витрачаєш 300–600 грн на місяць.',q:'Скільки гривень куди? Розподіли всі 6 000 грн.',
   fields:[{k:'main',label:'Основна картка'},{k:'virt',label:'Віртуальна картка для інтернету'},{k:'jar',label:'Накопичувальний рахунок'}],
   total:S=>6000,
   best:S=>({main:1400,virt:600,jar:4000}),
   check:(S,v)=>(v.main%100||v.virt%100||v.jar%100)?'Вводь суми, кратні 100 грн.':v.jar<3000?'Мама просила покласти на накопичувальний рахунок щонайменше 3 000 грн.':v.main<500?'На основній картці лиши щонайменше 500 грн — на обіди й проїзд.':null,
   eff:(S,v)=>{const n=norm(v);S.card=n.main;S.virt=n.virt;S.jar=n.jar;sync(S);sec(S,n.main<=1500&&n.virt>=300&&n.virt<=1000?15:n.main<=2000?10:0);},
   score:(S,v)=>{const n=norm(v);return n.main<=1500&&n.virt>=300&&n.virt<=1000?{p:2,fb:'На основній картці — лише гроші на щодень, в інтернеті «світиться» невелика сума, решта недосяжна для карток. Навіть якщо дані якоїсь картки вкрадуть, втратити можна небагато.'}:n.main<=2000?{p:1,fb:n.main>1500?'Більшість грошей сховано. Але на основній картці '+PG(n.main)+' — більше, ніж потрібно на два тижні.':n.virt<300?'На основній картці зайвого немає. Але на віртуальній майже порожньо: за покупки в інтернеті доведеться платити основною, показуючи її дані сайтам.':'На основній картці зайвого немає. Але на віртуальній '+PG(n.virt)+' — значно більше, ніж ти витрачаєш в інтернеті. Картка, дані якої бачать сайти, має бути майже порожня.'}:{p:0,fb:'На накопичувальному рахунку лише те, про що просила мама. На основній картці, якою платять щодня, лежить '+PG(n.main)+'. Якщо її дані потраплять до шахраїв, під ударом опиниться все це.'};}},
  {id:'risk',t:'calc',head:'День 3 · Найгірший випадок',text:S=>'Припустімо найгірше: дані твоєї основної картки потрапили до шахраїв. На ній зараз '+PG(S.card)+'. '+(S.lim>0?'Добовий ліміт — '+PG(S.lim)+'.':'Добового ліміту немає.')+' За умовою задачі перевищити ліміт неможливо, а до накопичувального рахунку й віртуальної картки ці дані доступу не дають.',q:'Яку найбільшу суму можуть списати з цієї картки за одну добу?',ans:S=>day(S),unit:'грн',hint:'Списати можна не більше, ніж є на картці, і не більше, ніж дозволяє ліміт. Потрібне менше з двох чисел.',sol:S=>(S.lim>0?(S.card<=S.lim?'На картці '+PG(S.card)+' — це не більше за ліміт '+PG(S.lim)+', тож списати можуть усе, що на ній є: '+PG(S.card)+'. Ліміт, більший за залишок, не захищає.':'На картці '+PG(S.card)+', але ліміт не дасть списати за добу більше ніж '+PG(S.lim)+'.'):'Ліміту немає, тож під загрозою все, що лежить на картці: '+PG(S.card)+'.')+' Решта — '+PG(S.side)+' — від цієї картки не залежить.'},
  {id:'tfa',t:'choice',head:'День 3 · Акаунти',text:'До твоєї пошти прив’язані месенджер та ігри. Пароль усюди один — кличка кота й рік народження. Месенджер пропонує ввімкнути двоетапну перевірку: при вході з нового пристрою він питатиме додатковий код.',q:'Що зробиш?',o:[
   {l:'Увімкнути двоетапну перевірку й поставити різні довгі паролі',p:2,eff:S=>{S.f.tfa=1;sec(S,15);},fb:'Тепер навіть украдений пароль не відчинить акаунт: потрібен ще код, який є лише в тебе.'},
   {l:'Придумати один новий складний пароль для всього',p:1,eff:S=>{sec(S,10);S.f.onepass=1;},fb:'Підібрати його важче. Але якщо він «витече» з одного сайту, відчиняться всі двері одразу.'},
   {l:'Нічого не міняти: кому потрібен акаунт школяра',p:0,eff:S=>{S.f.oldpass=1;},fb:'Акаунт школяра потрібен тим, хто хоче написати від його імені друзям і родичам: «Позич до завтра».'},
   {l:'Увімкнути двоетапну перевірку, а пароль лишити старий: код же однаково захистить',p:1,eff:S=>{S.f.tfa=1;S.f.tfa2=1;sec(S,10);},fb:'Код справді зупинить чужий вхід у месенджер. Але той самий слабкий пароль лишився в пошті та іграх — там його ніщо не підстраховує.'}]},
  {id:'sale',t:'choice',head:'День 5 · Покупчиня',text:S=>'Ти продаєш старі ролики: оголошення на сайті, ціна — 1 200 грн. За годину в месенджер пише «Олена»: «Беру! Я вже оплатила через безпечну доставку. Перейдіть за посиланням і введіть дані картки, щоб отримати гроші». Адреса в посиланні схожа на сайт оголошень, але із зайвою літерою.',q:'Що робити?',o:[
   {l:'Нічого не вводити: щоб отримати переказ, досить номера картки. Запропонувати оплату при отриманні на пошті',p:2,eff:S=>{S.f.sale=1;},fb:'«Олена» зникла одразу після твоєї відмови. Тому, хто справді хоче переказати гроші, вистачає номера картки. Термін дії та CVV потрібні лише для того, щоб платити твоєю карткою.'},
   {l:'Перейти й увести номер, термін дії та CVV основної картки',p:0,eff:S=>{take(S,drain(S));S.f.hit=1;sec(S,-5);},fb:S=>'Сторінка була копією справжньої, а «оплати» ніколи не існувало. '+hitWhy(S)},
   {l:S=>'Увести дані віртуальної картки: на ній лише '+PG(S.virt),when:S=>S.virt>0,p:0,eff:S=>{S.lost+=S.virt;S.virt=0;sync(S);S.f.vhit=1;sec(S,-5);},fb:S=>'З віртуальної картки зникло все — '+PG(S.virt)+'. Основна картка й накопичувальний рахунок уціліли. Та щоб отримати гроші, дані картки не потрібні ніколи — жодної.'},
   {l:'Перейти за посиланням лише подивитися, нічого не вводячи',p:1,eff:S=>{sec(S,-3);},fb:'Гроші цілі. Але підроблена сторінка може підсунути шкідливий файл, а «покупчиня» бачить, що ти вагаєшся, і тиснутиме далі.'}]},
  {id:'stolen',t:'choice',head:S=>own(S)?'День 5 · Гроші вже зникли':'День 5 · Марко просить поради',text:S=>S.f.hit?'Вечір того ж дня. Шахраї вже забрали '+PG(S.lost)+'. Дані основної картки досі в них, а картка працює. '+(S.card>0?'На ній ще '+PG(S.card)+'.':'Зараз на ній порожньо, але все, що туди надійде, теж буде під ударом.'):S.f.vhit?'Вечір того ж дня. З віртуальної картки зникло '+PG(S.lost)+'. Її дані досі в шахраїв, а картка працює: поповниш її — гроші зникнуть знову.':'Увечері пише однокласник Марко: «У мене щойно списали 1 200 грн із картки. Я ввів її дані на якомусь сайті. Що робити?! Батькам казати страшно».',q:S=>own(S)?'Що робити зараз?':'Що ти порадиш Маркові?',o:[
   {l:S=>own(S)?'Негайно заблокувати картку в застосунку, подзвонити в банк, розповісти мамі й разом подати заяву до поліції':'Негайно заблокувати картку, подзвонити в банк, розповісти батькам і разом із ними подати заяву до поліції',p:2,eff:S=>{if(own(S))S.f.blocked=1;else S.f.marko=2;sec(S,5);},fb:S=>own(S)?'Картку заблоковано, банк випустив нову — з іншим номером. Украдені дані тепер нічого не варті. Заяву про шахрайську операцію прийнято. Чи повернуть гроші, покаже перевірка: у цій історії відповіді ще немає.':'Марко заблокував картку за хвилину, і списання припинилися. Мама допомогла йому написати заяви. А ти тепер знаєш порядок дій і для власної картки.'},
   {l:S=>own(S)?'Дочекатися ранку й тоді спокійно в усьому розібратися':'Порадити не панікувати й розібратися завтра',p:1,eff:S=>{if(S.f.hit){take(S,day(S));S.f.blocked=1;}else if(S.f.vhit)S.f.blocked=1;else S.f.marko=1;S.f.slow=1;},fb:S=>S.f.hit?(S.card>0?'Уночі з картки списали ще '+PG(day(S))+'. Уранці картку заблоковано й випущено нову, але ця ніч коштувала грошей.':'Уночі списувати було нічого: картка порожня. Уранці її заблоковано й випущено нову. Якби на ній щось лишалося, ніч коштувала б грошей.'):S.f.vhit?'На віртуальній картці вже порожньо, тож за ніч нічого не зникло. Уранці її заблоковано. Якби там лишалися гроші, ніч коштувала б дорого.':'Уночі в Марка списали ще 900 грн: картка працювала, а шахраї не спали. У таких справах рахунок іде на хвилини.'},
   {l:S=>own(S)?'Знайти в інтернеті «фахівця з повернення коштів», який бере 300 грн наперед':'Порадити «фахівця з повернення коштів» з інтернету: бере лише 300 грн наперед',p:0,eff:S=>{if(own(S)){S.lost+=pay(S,300);if(S.f.hit)S.f.open=1;S.f.second=1;}else S.f.marko=-1;sec(S,-5);},fb:S=>own(S)?'«Фахівець» отримав 300 грн і зник.'+jn(S,300)+' Тих, кого вже обдурили, охоче обдурюють удруге — обіцянкою повернути втрачене. А картку так і не заблоковано.':'Марко переказав «фахівцеві» 300 грн — і той зник. Тих, кого вже обдурили, охоче обдурюють удруге — обіцянкою повернути втрачене.'},
   {l:S=>own(S)?'Нікому не казати — соромно; надалі просто пильнувати':'Порадити нікому не казати: батьки тільки сваритимуть',p:0,eff:S=>{if(S.f.hit){take(S,day(S));S.f.open=1;}if(own(S))S.f.silent=1;else S.f.marko=-2;sec(S,-5);},fb:S=>S.f.hit?(S.card>0?'Картка з украденими даними лишилася робочою: наступного дня з неї списали ще '+PG(day(S))+'. Мовчання через сором — найкращий подарунок шахраям.':'Картка порожня, тож більше нічого не зникло. Але вона й далі працює, а її дані — у шахраїв. Мовчання через сором їм тільки на руку.'):S.f.vhit?'Більше нічого не зникло — лише тому, що віртуальна картка порожня. Вона й далі працює, а її дані — у шахраїв. Мовчання через сором їм тільки на руку.':'Марко промовчав. Картка працювала далі, і за три дні з неї забрали все. Мовчання через сором — найкращий подарунок шахраям.'}]},
  {id:'call',t:'choice',head:'День 7 · Дзвінок',text:S=>'Дзвонить незнайомий номер. Упевнений голос: «Служба безпеки банку. '+(S.lost>0?'Ми бачимо підозрілі операції з вашими рахунками.':'З вашої картки просто зараз намагаються списати гроші.')+' Щоб це зупинити, продиктуйте номер картки й код, який зараз надійде в SMS. У вас дві хвилини». На фоні чути гамір кол-центру.',q:'Як ти вчиниш?',o:[
   {l:'Покласти слухавку й набрати номер банку, надрукований на звороті картки',p:2,eff:S=>{S.f.callok=1;},fb:'У справжньому банку підтвердили: тобі ніхто не телефонував. Працівник банку ніколи не питає код із SMS, PIN чи CVV — ці дані йому не потрібні.'},
   {l:'Продиктувати код із SMS: ідеться ж про мої гроші',p:0,eff:S=>{take(S,day(S));S.f.code=1;sec(S,-10);},fb:S=>S.card>0?'Код із SMS — це твій підпис. Ним підтверджено чужу операцію: з картки списали '+PG(day(S))+(S.lim>0&&S.card>S.lim?' — більше не дозволив добовий ліміт':S.lim>0?' — усе, що на ній було':' — усе, бо ліміту немає')+'. «Служба безпеки» одразу поклала слухавку.':'Код із SMS — це твій підпис. Цього разу підтверджувати ним було нічого: основна картка порожня. Але «служба безпеки» тепер знає, що код ти називаєш.'},
   {l:'Код не називати, але продиктувати номер картки, термін дії та CVV «для звірки»',p:0,eff:S=>{take(S,300);S.f.cvv=1;S.f.open=0;sec(S,-5);},fb:S=>S.card>0?'За годину хтось оплатив твоєю карткою дві покупки в інтернеті: мінус '+PG(Math.min(S.card,300))+'. Картку довелося заблокувати й випустити нову. CVV — це ключ, а не «дані для звірки».':'На картці порожньо, тож нічого не зникло. Але її довелося заблокувати й випустити нову: CVV — це ключ, а не «дані для звірки».'},
   {l:'Не класти слухавку й розпитати «працівника», щоб перевірити, чи він справжній',p:1,eff:S=>{sec(S,-3);},fb:'Цього разу нічого зайвого не сказано. Але шахраї навчені говорити переконливо: що довша розмова, то більше шансів, що вони доб’ються свого.'}]},
  {id:'pyr',t:'choice',head:'День 8 · «Інвестклуб»',text:S=>'Однокласник Назар кличе тебе в «інвестклуб»: «Вносиш 1 000 грн, приводиш двох друзів — і за місяць отримуєш 3 000. Я вже привів, мені ось-ось виплатять! Старшокласники так на телефони заробили». Чим саме клуб заробляє гроші, Назар пояснити не може. На основній картці в тебе '+PG(S.card)+', на накопичувальному рахунку — '+PG(S.jar)+'.',q:'Що відповісти Назарові?',o:[
   {l:'Відмовитися й пояснити: виплати йдуть лише з внесків новачків, тож останні втратять усе',p:2,eff:S=>{S.f.warn=1;},fb:'Твої гроші цілі — і, можливо, чужі теж: кількох однокласників твоє пояснення зупинило.'},
   {l:'Відмовитися без пояснень: не хочу — і все',p:1,eff:S=>{S.f.nopyr=1;},fb:'Твої гроші цілі. А Назар і далі шукає двох друзів — і хтось із них погодиться.'},
   {l:'Внести 1 000 грн: потроїти гроші за місяць — це ж велосипед уже цієї осені',p:0,eff:S=>{S.pyr=pay(S,1000);},fb:S=>'Гроші пішли «організаторові» — людині, якої ніхто з вас не бачив.'+jn(S,1000)+' Тепер твоя виплата залежить від того, чи знайдуться нові охочі.'},
   {l:'Внести 200 грн «на пробу» й привести двох друзів із паралельного класу',p:0,eff:S=>{S.pyr=pay(S,200);S.f.recruit=1;sec(S,-5);},fb:S=>'Сума мала, але тепер і ти — частина схеми: через тебе ризикують іще двоє.'+jn(S,200)}]},
  {id:'pyrc',t:'calc',head:'День 8 · Арифметика піраміди',text:'Назар намалював схему: він — на першому рівні, двоє його друзів — на другому, четверо їхніх — на третьому, і так далі: кожен приводить двох. У вашій школі 500 учнів.',q:'Скільки нових учасників потрібно на дев’ятому рівні?',ans:S=>256,unit:'осіб',hint:'На кожному наступному рівні людей удвічі більше: 1, 2, 4, 8…',sol:S=>'Рівні: 1, 2, 4, 8, 16, 32, 64, 128, 256. На дев’ятому рівні потрібно 256 новачків, а разом у схемі було б уже 511 людей — більше, ніж учнів у школі. Новачки закінчуються, і всі, хто на останніх рівнях, втрачають внески. Піраміда нічого не заробляє — вона лише перекладає гроші знизу вгору.'},
  {id:'bus',t:'event',head:'День 9 · Загублений чохол',text:S=>{const weak=S.f.pinpaper||S.f.pinyear,x=weak?day(S):S.f.notif?0:Math.min(S.card,300),more=S.f.open?(S.lim>0?Math.min(S.card-x,S.lim):S.card-x):0;
   return 'У маршрутці загубився чохол для проїзного, а в ньому — основна картка. '+
   (!S.card?'На картці не було ні гривні, тож красти нічого. '+(weak?'А могло бути інакше: '+(S.f.pinpaper?'папірець із PIN лежав у тому самому чохлі.':'поруч лежав учнівський квиток із датою народження, а PIN — це твій рік народження.'):'')
   :weak?(S.f.pinpaper?'Папірець із PIN лежав у тому самому чохлі.':'У чохлі лежав і учнівський квиток із датою народження, а PIN — це твій рік народження.')+' У банкоматі хтось зняв '+PG(x)+(S.lim>0&&S.card>S.lim?' — більше не дозволив добовий ліміт.':' — усе, що було на картці.')+(S.f.notif?' Сповіщення прийшло одразу, але готівка вже була в чужих руках.':'')
   :S.f.notif?'Телефон одразу показав сповіщення: хтось пробує розплатитися твоєю карткою в кіоску. За хвилину картку заблоковано в застосунку — нічого не зникло.'
   :'PIN ніхто не дізнався, тож готівку не зняли. Але хтось кілька разів розплатився карткою в кіоску — дрібні покупки цього разу пройшли без PIN. Мінус '+PG(x)+'. '+(S.f.notifbig?'Суми були менші за 1 000 грн, тож сповіщень не надійшло: про покупки стало відомо лише ввечері.':'Сповіщень немає, тож про покупки стало відомо лише ввечері, із застосунку.'))+
   (more>0?' І це ще не все: украдені дані цієї картки досі були в шахраїв — до блокування з неї списали ще '+PG(more)+'.':'')+(S.f.notif&&!weak&&S.card?' Мама допомогла замовити нову.':' Мама допомогла заблокувати картку й замовити нову.');},
   eff:S=>{const weak=S.f.pinpaper||S.f.pinyear;take(S,weak?day(S):S.f.notif?0:300);if(S.f.open){take(S,S.lim>0?S.lim:S.card);S.f.open=0;}}},
  {id:'disc',t:'calc',head:'День 10 · Магазин у соцмережі',text:'У стрічці — реклама: бездротові навушники, які всюди коштують 1 800 грн, тут продають за 540 грн. «Залишилося 3 штуки! Акція до вечора!» Сторінку створено тиждень тому, відгуки є лише під самим дописом. Оплата — тільки повна передоплата.',q:'Скільки відсотків становить знижка?',ans:S=>70,unit:'% знижки',hint:'Знайди, на скільки гривень знижено ціну, і поділи на початкову ціну.',sol:S=>'1 800 − 540 = 1 260 грн. 1 260 : 1 800 = 0,7 = 70 %. Новий товар більш ніж утричі дешевше, ніж у всіх інших, — це не щедрість. Надто вигідна ціна, поспіх і повна передоплата — три ознаки підробленого магазину.'},
  {id:'shopc',t:'choice',head:'День 10 · Купувати чи ні',text:S=>'Навушники за 540 грн. На основній картці — '+PG(S.card)+(S.virt>0?', на віртуальній — '+PG(S.virt):'')+', на накопичувальному рахунку — '+PG(S.jar)+'. «Менеджер» у чаті квапить: «Бронь тримаю 10 хвилин».',q:'Що зробиш?',o:[
   {l:'Перевірити магазин: пошукати відгуки поза його сторінкою й попросити оплату при отриманні; відмовлять — не купувати',p:2,eff:S=>{S.f.shopok=1;},fb:'На прохання про оплату при отриманні «менеджер» одразу заблокував тебе. А в пошуку знайшлися десятки відгуків: «гроші взяли, товар не надіслали».'},
   {l:'Оплатити з віртуальної картки: якщо щось піде не так, втрачу лише ці 540 грн',when:S=>S.virt>=540,p:1,eff:S=>{S.virt-=540;sync(S);S.lost+=540;S.f.vshop=1;},fb:'Товар не прийшов, 540 грн втрачено. Віртуальна картка обмежила втрату ціною покупки: дані основної ніде не «засвітилися». Але три ознаки підробки були перед очима.'},
   {l:S=>S.card>=540?'Оплатити основною карткою через форму на сайті магазину, поки діє акція':'Переказати на основну картку '+PG(540-S.card)+' з накопичувального рахунку й оплатити через форму на сайті, поки діє акція',p:0,eff:S=>{const r=shop(S);S.jar-=r.top;S.card+=r.top;sync(S);take(S,r.x);S.f.hit2=1;S.f.open=0;sec(S,-5);},fb:S=>{const r=shop(S);return 'Товар не прийшов: 540 грн втрачено. '+(r.x>540?'А форма оплати зберегла дані картки, і з неї списали ще '+PG(r.x-540)+'.':'Форма оплати зберегла й дані картки — більше з неї нічого не взяли лише тому, що '+(S.card+r.top<=540?'вона спорожніла.':'спрацювали ліміт і сповіщення.'))+' Картку довелося заблокувати й випустити нову.';}},
   {l:'Спитати в чаті класу, чи хтось купував у цьому магазині, а «бронь» хай згорає',p:1,eff:S=>{S.f.asked=1;},fb:'Поспіх на тебе не подіяв — це головне. Але чат може мовчати до вечора, а перевірити магазин можна й без нього — за п’ять хвилин.'}]},
  {id:'friend',t:'choice',head:'День 11 · Повідомлення від друга',text:'У месенджері пише твій друг Денис: «Привіт! Виручи, позич 800 грн до завтра, дуже треба. Скинь на цю картку, це картка брата, потім усе поясню». Денис ніколи раніше не просив грошей і зазвичай пише з помилками та купою смайликів, а тут — жодного.',q:'Що зробиш?',o:[
   {l:'Подзвонити Денисові звичайним дзвінком і спитати, чи це він',p:2,eff:S=>{S.f.called=1;},fb:'Денис здивувався: його акаунт зламали, і таке саме повідомлення отримали всі його контакти. Один дзвінок зберіг твої гроші, а Денис устиг попередити інших.'},
   {l:'Написати у відповідь: «Це точно ти? Як звати мого кота?»',p:1,eff:S=>{S.f.asked2=1;},fb:'«Денис» перестав відповідати. Гроші цілі, але справжній Денис досі не знає, що від його імені просять у борг.'},
   {l:'Переказати 800 грн: друзів у біді не кидають',p:0,eff:S=>{S.lost+=pay(S,800);S.f.sent=1;},fb:S=>'Гроші пішли на картку незнайомця.'+jn(S,800)+' Справжній Денис дізнався про «свій» борг лише наступного дня: його акаунт зламали.'},
   {l:'Нічого не відповідати й нікому не казати',p:1,eff:S=>{S.f.quiet=1;},fb:'Твої гроші цілі. Та поки всі мовчать, шахрай пише від імені Дениса далі — і хтось таки перекаже.'}]},
  {id:'hack',t:'event',head:'День 12 · Чужий вхід',text:S=>S.f.tfa?'Уночі на телефон прийшло сповіщення: «Спроба входу у ваш акаунт із нового пристрою. Введіть код підтвердження». Хтось '+(S.f.tfa2?'вгадав твій старий пароль':'дізнався твій пароль')+', але без коду далі не пройшов. Уранці ти міняєш пароль'+(S.f.tfa2?' — тепер уже всюди й на різні':'')+' — і на цьому все скінчилося.':S.f.onepass?'Уночі пошта надіслала попередження: «Невдала спроба входу з нового пристрою». Хтось пробував твій старий пароль — із кличкою кота. Новий він не вгадав. Цього разу пощастило: двоетапної перевірки в тебе немає, тож одного вгаданого пароля було б досить.':'Уранці дзвонить бабуся: «Сонечко, я переказала 500 грн, як було в повідомленні. Що в тебе сталося?» Жодних повідомлень від тебе не було. Уночі хтось увійшов у твій акаунт і розіслав усім контактам: «Позич до завтра». Бабуся повірила. Це не твої гроші, але втратила вона їх через твій пароль.',eff:S=>{if(!S.f.tfa&&!S.f.onepass){S.gran=500;sec(S,-20);S.f.hacked=1;}}},
  {id:'rights',t:'choice',head:'День 13 · Незрозуміле списання',text:'У застосунку з’явився рядок: «Плата за пакет послуг — 150 грн», списання заплановано на завтра. Жодного пакета ти не підключаєш. А в тарифах, які мама отримала разом із договором, написано: обслуговування цієї картки безплатне.',q:'Що зробиш?',o:[
   {l:'Разом із мамою написати звернення в чат банку з посиланням на тарифи й зберегти листування; відмовлять — поскаржитися до Національного банку',p:2,eff:S=>{S.f.claim=1;},fb:'Банк визнав помилку й скасував списання. Споживач фінансових послуг має право знати всі умови й оскаржувати порушення. Письмове звернення працює краще за емоції: воно лишає слід.'},
   {l:'Подзвонити на гарячу лінію й усно висловити все, що думаєш',p:1,eff:S=>{S.f.oral=1;},fb:'Оператор пообіцяв «передати інформацію», але сліду звернення не лишилося. 150 грн наступного дня списали. Повернули їх лише через тиждень — після другого дзвінка й маминого листа.'},
   {l:'Змиритися: 150 грн — не та сума, щоб сперечатися з банком',p:0,eff:S=>{S.lost+=pay(S,150);S.f.gaveup=1;},fb:S=>'150 грн списали'+(S.card<150?' — з накопичувального рахунку, бо на картці грошей бракувало':'')+'. І списуватимуть щомісяця, доки хтось не заперечить: банк не знає, що ти проти.'},
   {l:'Вимкнути в застосунку все зайве, зокрема сповіщення: мабуть, це плата за них',p:0,eff:S=>{S.lost+=pay(S,150);S.f.notif=0;S.f.notifbig=0;S.f.off=1;sec(S,-10);},fb:S=>'Плату однаково списали'+(S.card<150?' — з накопичувального рахунку, бо на картці грошей бракувало':'')+': зі сповіщеннями вона не пов’язана. А в тебе більше немає сигналу про операції з карткою.'}]},
  {id:'pyrend',t:'event',head:'День 14 · Новини',text:S=>'Чат «інвестклубу» видалено, «організатор» не відповідає. '+(S.pyr>0?'Твої '+PG(S.pyr)+' зникли разом із ним.':'Назар утратив свою тисячу й боїться сказати батькам.')+(S.f.recruit?' Двоє друзів, які прийшли за тобою, теж утратили внески — і тепер вимагають гроші з тебе.':'')+(S.f.warn?' Троє однокласників дякують тобі: після твого пояснення вони не понесли туди гроші.':'')+(S.f.marko===2?' А Марко розповідає: банк іще перевіряє його заяву, зате після блокування з картки не зникло ні гривні.':S.f.marko===1?' А Марко досі шкодує про ту ніч: 900 грн, списані до ранку, були зайвою втратою.':S.f.marko===-1?' А Марко тепер без 1 500 грн: 1 200 забрали шахраї, ще 300 — «фахівець».':S.f.marko===-2?' А Марко нарешті зізнався батькам — коли на картці вже нічого не лишилося.':''),eff:S=>{S.lost+=S.pyr;S.pyr0=S.pyr;S.pyr=0;}},
  {id:'kept',t:'calc',head:'День 14 · Що вціліло',text:S=>'Два тижні позаду. Було 6 000 грн. Зараз на основній картці — '+PG(S.card)+', на віртуальній — '+PG(S.virt)+', на накопичувальному рахунку — '+PG(S.jar)+'.',q:'Скільки відсотків від початкових 6 000 грн збереглося? Округли до цілого числа.',ans:S=>Math.round(left(S)/60),unit:'% від 6 000 грн',tol:0.5,hint:'Склади три залишки, поділи суму на 6 000 і помнож на 100.',sol:S=>{const t=left(S),p=t/60;return PN(S.card)+' + '+PN(S.virt)+' + '+PN(S.jar)+' = '+PG(t)+'. '+PN(t)+' : 6 000 × 100 % '+(p===Math.round(p)?'= ':'≈ ')+Math.round(p)+' %.'+(t<6000?' Решта — '+PG(6000-t)+' — втрачено.':' Не втрачено нічого.');}},
  {id:'goal',t:'calc',head:'День 14 · Велосипед',text:S=>'У тебе '+PG(left(S))+'. Велосипед коштує 9 000 грн. Щотижня ти можеш відкладати 500 грн.',q:'За скільки тижнів ти назбираєш на велосипед? Якщо виходить неціле число, округли вгору.',ans:S=>Math.ceil((9000-left(S))/500),unit:'тижнів',hint:'Знайди, скільки бракує до 9 000 грн, і поділи на 500. Неповний тиждень теж потрібен.',sol:S=>{const t=left(S),n=9000-t,k=Math.ceil(n/500);return 'Бракує: 9 000 − '+PN(t)+' = '+PG(n)+'. '+PN(n)+' : 500 = '+PN(n/500)+(n%500?', тож потрібно '+W(k)+'.':'. Отже, '+W(k)+'.')+(t<6000?' Без втрат вистачило б 6 тижнів: '+PG(6000-t)+', яких не стало, — це '+W(k-6)+' зайвого чекання.':' Втрат немає — і ціль не віддалилася.');}}],
 finish:S=>{const t=left(S),others=S.f.hacked||S.f.recruit,lvl=S.lost<=600&&S.sec>=50&&(S.lim>0||S.f.notif)&&!others?2:S.lost<=2000&&S.sec>=35?1:0;
  return{level:lvl,title:['Шахраї виявилися спритнішими','Гроші вціліли не всі','Гроші під надійним захистом'][lvl],
   text:'За два тижні з 6 000 грн збережено '+PG(t)+', втрачено '+PG(S.lost)+'. Рівень захисту — '+S.sec+' зі 100.'+(S.f.hacked?' Ще 500 грн через твій зламаний акаунт втратила бабуся.':'')+(S.f.recruit?' Двоє друзів утратили внески в «інвестклубі», куди прийшли за тобою.':'')+(lvl===2?(S.lost>0?' Втрата не перевищила десятої частини грошей: налаштування обмежили шкоду.':' Жодна зі спроб не вдалася.'):lvl===1?(S.lost>600?' Втрачено більше ніж десяту частину грошей.':others?' Твої гроші майже цілі, але через тебе гроші втратили інші.':S.lim>0||S.f.notif?' Грошей утрачено небагато, але рівень захисту нижчий за 50 зі 100.':' Грошей утрачено небагато, але картка без ліміту й сповіщень про кожну операцію: наступна помилка може коштувати всього, що на ній є.'):S.lost>2000?' Утрачено понад третину всіх грошей.':' Рівень захисту нижчий за 35 зі 100: вцілілі гроші — радше везіння.'),
   tips:[S.lim>0&&S.f.notif?'Ліміт і сповіщення про кожну операцію спрацювали як ремінь безпеки: навіть помилка не могла коштувати всіх грошей на картці.':S.lim>0?'Добовий ліміт стримував втрати. Але без сповіщень про кожну операцію пропажу видно запізно — увімкни їх.':S.f.notif?'Сповіщення показують списання одразу. Але без добового ліміту одна операція може забрати з картки все — постав ліміт.':'Без добового ліміту й сповіщень про кожну операцію одна помилка коштує всього, що є на картці. Налаштуй їх у перший же день.',
    S.f.tfa?'Двоетапна перевірка зупинила зламників на порозі твого акаунта.'+(S.f.tfa2?' Але один слабкий пароль на все — це двері, які колись відчинять. Став різні.':''):S.f.onepass?'Новий пароль цього разу врятував акаунт, але один пароль на все — слабке місце. Додай двоетапну перевірку.':'Через слабкий захист акаунта шахраї писали від твого імені — і постраждала бабуся. Увімкни двоетапну перевірку й зміни пароль.',
    S.lost===0&&!others?'Шахраям не дісталося ні гривні: коди лишилися при тобі, прохання перевірено дзвінком, щедрим обіцянкам не повірено.':own(S)||S.f.code||S.f.cvv?'CVV, PIN і код із SMS не кажи нікому й нікуди не вводь, щоб «отримати» гроші. Саме так гроші зникають найшвидше.':S.f.vshop||S.f.hit2?'Надто вигідна ціна, поспіх і повна передоплата — ознаки підробленого магазину. Перевіряй продавця до оплати, а не після.':S.f.sent||S.f.recruit||S.pyr0?'Прохання про гроші перевіряй дзвінком, а обіцянку швидкого прибутку — питанням «звідки ці гроші?».':'Дрібні втрати теж складаються в тижні чекання: бережи PIN, читай тарифи й заперечуй письмово.']};},
 terms:[['Фішинг','виманювання даних картки чи паролів через підроблені сайти, листи або повідомлення'],['CVV-код','три цифри на звороті картки, якими підтверджують оплату в інтернеті; їх не повідомляють нікому'],['Фінансова піраміда','схема, де учасникам платять із внесків нових учасників, а не із заробленого'],['Двоетапна перевірка','вхід до акаунта, для якого крім пароля потрібен ще одноразовий код'],['Добовий ліміт','найбільша сума, яку можна витратити чи зняти з картки за добу']]};
})());

PFG_TOPICS.push((()=>{
 /* допоміжні функції */
 const cl=x=>Math.max(0,Math.min(100,x));
 const rp=(S,d)=>{S.rep=cl(S.rep+d);};
 const sd=(S,d)=>{S.study=cl(S.study+d);};
 const use=(S,h)=>{const d=Math.max(0,h-S.hrs);S.hrs=Math.max(0,S.hrs-h);sd(S,-2*d);return d;};   /* годин бракує — їх забирають у сну й уроків */
 const jobPay=S=>S.busy===4?320:S.busy===8?600:0;
 const T=S=>S.f.press?6:8;                      /* годин на замовлення з 12 шоперів */
 const gain=S=>12*(S.price-80);
 const nb=S=>(S.f.night?3:1)+(S.f.peak?1:0)+(S.f.proto?0:1);   /* шоперів із браком у першій партії */
 const B=n=>PL(n,'шопер','шопери','шоперів');
 const H=n=>n+' год';
 const kw=S=>S.f.press?2:1, onH=S=>T(S)-2+1+(S.f.idle?3:0), kwh=S=>kw(S)*onH(S);
 const n5=S=>S.f.big?15:6;
 const bz=S=>S.biz>=0?'права принесла '+PG(S.biz)+' понад матеріали':'права поки що в мінусі на '+PG(-S.biz);
 const payer=S=>S.f.press?'школа':'родина';
 return {id:'9-1',sec:'9a',title:'Економічний спосіб мислення',minutes:30,
 intro:'Ти навчаєшся в 9 класі й помічаєш: класи та шкільні команди хочуть шопери й худі з власним принтом, але міська друкарня бере замовлення лише від 30 штук і робить їх три тижні. П’ять тижнів ти перевіряєш, чи можна на цьому побудувати власну справу. У тебе 1 200 грн заощаджень і 20 вільних годин на тиждень. Від того, на що підуть години і як ти говориш із людьми, залежить, які можливості з’являться далі.',
 init:()=>({cash:1200,hrs:20,rep:50,study:60,busy:0,rsv:0,price:150,bad:1,biz:0,job:0,f:{}}),
 meters:[{k:'cash',label:'Гроші',unit:'грн'},{k:'hrs',label:'Вільні години цього тижня',unit:'год'},{k:'rep',label:'Репутація',unit:'зі 100'},{k:'study',label:'Навчання',unit:'зі 100'}],
 steps:[
  {id:'notice',t:'choice',head:'Тиждень 1 · Проблема',text:'Понеділок. 9-Б хотів худі до Дня школи, але в міській друкарні сказали: мінімум 30 штук і три тижні. У класі 22 учні, свято за два тижні. Усі бурчать і розходяться. Ти непогано малюєш макети й думаєш: а якщо друкувати малі партії швидко?',q:'Що робити з цим спостереженням?',o:[
   {l:'Розпитати десятьох учнів і капітанів команд: що їм заважає й скільки вони згодні платити (3 години)',p:2,eff:S=>{S.hrs-=3;rp(S,3);S.f.ask=1;},fb:'Три години розмов дали факти: класам потрібно 10–25 речей за тиждень, а шопери замовляли б частіше, ніж худі. Тебе запам’ятали: спершу питає, потім обіцяє.'},
   {l:'Записати ідею в нотатки й повернутися до неї, коли буде час',p:1,eff:S=>{S.f.guess=1;},fb:'Ідея не загубилася, але про клієнтів ти нічого не знаєш. Що їм потрібно, доведеться вгадувати.'},
   {l:'Одразу написати в шкільний чат: «Друкую худі й шопери для всіх класів, пишіть!»',p:0,eff:S=>{rp(S,4);S.f.loud=1;},fb:'Сорок уподобань за вечір — приємно. Але обіцяно те, чого ще немає: ні преса, ні цін, ні строків.'}]},
  {id:'opp',t:'calc',head:'Тиждень 1 · Ціна години',text:'На перевірку ідеї ти відводиш 6 годин на тиждень. Ці години можна витратити й інакше: вигулювати сусідчиного собаку за 80 грн за годину або допомагати п’ятикласникові з математикою за 90 грн за годину. На дві справи часу не вистачить.',q:'Яка альтернативна вартість 6 годин, відданих ідеї? (Скільки гривень принесла б найкраща з можливостей, від яких ти відмовляєшся.)',ans:S=>540,unit:'грн',hint:'Альтернативна вартість — це вигода від НАЙКРАЩОГО з відкинутих варіантів, а не сума всіх.',sol:S=>'Найкраща з відкинутих можливостей — математика за 90 грн за годину. 6 × 90 = 540 грн. Стільки «коштують» шість годин перевірки ідеї: вона має дати щось цінніше за 540 грн — гроші або досвід.'},
  {id:'can',t:'choice',head:'Тиждень 1 · А це взагалі для мене?',text:S=>'Удома мама знизує плечима: «Підприємець — це той, у кого є гроші та зв’язки. А ти ще в школі». Учителька пані Ірина каже інше: підприємець на власний ризик організовує справу, щоб отримати прибуток. А підприємливою людина може бути й без фірми — якщо помічає проблему й береться її розв’язати.'+(S.f.ask?' Проблему ти вже бачиш, і людей розпитано.':''),q:'Як перевірити, чи це для тебе?',o:[
   {l:'Виписати, що я вмію (макети, домовлятися) і чого не вмію (рахувати витрати, друкувати), та знайти, хто навчить (2 години)',p:2,eff:S=>{use(S,2);S.f.self=1;},fb:'Тепер зрозуміло, чого саме бракує, і це не гроші: треба навчитися друкувати й рахувати. Обидві навички здобуваються ділом.'},
   {l:'Пройти в інтернеті тест «Чи підприємець ти?» і повірити результату',p:1,eff:S=>{S.f.quiz=1;},fb:'Тест показав «73 % підприємця». Приємно, але ні друкувати, ні рахувати від цього не навчишся.'},
   {l:'Погодитися з мамою: спершу треба 15 000 грн на власний прес. Цілий вечір шукати, де їх узяти (2 години)',p:0,eff:S=>{use(S,2);S.f.wait=1;},fb:'15 000 грн — це понад рік твоїх заощаджень. А чи потрібен власний прес узагалі, ще невідомо: ідею можна перевірити за кілька сотень гривень.'}]},
  {id:'job',t:'choice',head:'Тиждень 1 · Підробіток',text:'Сусідка чекає на відповідь: собаку треба вигулювати 4 години на тиждень, три тижні поспіль, за 320 грн на тиждень. Знайомий пропонує ще й розклеювати оголошення — теж 4 години на тиждень, 280 грн. На пробний друк потрібно близько 200 грн, вони в тебе є. А вільних годин лише 20 на тиждень: у них мають уміститися уроки, ідея та відпочинок.',q:'Що відповісти?',o:[
   {l:'Подякувати й відмовитися, порадивши сусідці сестру твого друга Данила: зараз мені потрібні години, а не гроші',p:2,eff:S=>{rp(S,2);S.hrs=20;},fb:'Грошей на пробу вистачає, а часу — ні. Новий тиждень почнеться з 20 вільних годин. Сусідка вдячна за пораду.'},
   {l:'Погодитися на собаку: 960 грн за три тижні не завадять',p:1,eff:S=>{S.busy=4;S.hrs=16;},fb:'Гроші реальні. Але з кожного з трьох наступних тижнів зникне 4 години: лишиться 16.'},
   {l:'Узяти обидва підробітки: 600 грн на тиждень — це вже серйозно',p:0,eff:S=>{S.busy=8;S.hrs=12;},fb:'1 800 грн за три тижні. Ціна — 8 годин щотижня: на все інше лишається 12, а ідеї дістануться крихти.'}]},
  {id:'letter',t:'choice',head:'Тиждень 2 · Прохання до пана Ореста',text:S=>'Новий тиждень: у тебе '+H(S.hrs)+' вільного часу'+(S.busy?' — решту забирає підробіток':'')+'. У шкільній майстерні, виявляється, є термопрес; ним завідує вчитель технологій пан Орест. Шкільним пресом шопер друкується за 20 хвилин, домашнім міні-пресом Данилової сестри — за 30.'+(S.f.wait?' Виходить, шукати 15 000 грн на власний прес було не обов’язково.':'')+' Пана Ореста ти майже не знаєш, але маєш його робочу пошту й телефон.',q:'Як попросити дозволу користуватися пресом?',o:[
   {l:'Написати вдень листа: привітатися, назватися, пояснити, що й коли хочеш друкувати, запропонувати допомогу в майстерні, подякувати (1 година)',p:2,eff:S=>{use(S,1);rp(S,3);S.f.press=1;S.f.polite=1;},fb:'Пан Орест відповів того ж дня: «Приємно мати справу з людиною, яка поважає чужий час. Приходьте після шостого уроку». Прес у твоєму розпорядженні.'},
   {l:'Підійти на перерві й спитати: «А можна мені якось прес узяти?»',p:1,eff:S=>{S.f.press=1;},fb:'Пан Орест поспішав на урок і кинув: «Ну, спробуй, тільки обережно». Дозвіл є, але умов не названо.'},
   {l:'Написати йому в месенджер о 22:40: «Здрастє, це з 9-го. Дайте прес на тиждень, дуже треба»',p:0,eff:S=>{rp(S,-3);S.f.press=0;},fb:'Повідомлення без імені, без пояснень і майже вночі. Пан Орест відповів уранці одним словом: «Ні». Доведеться друкувати повільнішим домашнім міні-пресом.'}]},
  {id:'rsvc',t:'calc',head:'Тиждень 2 · Що вміститься в тиждень',text:S=>'У четвер контрольна з алгебри. Вільних годин цього тижня — '+S.hrs+'. На домашні завдання й підготовку потрібно щонайменше 6 годин. На макет і пробний шопер — 4 години (і 160 грн на матеріали).',q:'Скільки годин лишиться на відпочинок і несподіванки, якщо зробити і те, і те?',ans:S=>S.hrs-10,unit:'год',hint:'Від вільних годин відніми години на уроки й на пробний шопер.',sol:S=>S.hrs+' − 6 − 4 = '+H(S.hrs-10)+'.'+(S.hrs-10<3?' Це небагато: підробіток уже забрав '+H(S.busy)+'.':'')},
  {id:'week',t:'choice',head:'Тиждень 2 · План тижня',text:S=>'Після уроків і пробного шопера лишається '+H(S.hrs-10)+'. Минулого тижня несподівані справи забрали в тебе три години — і цей тиждень навряд чи буде спокійнішим.',q:'Як розподілити години?',o:[
   {l:S=>'Уроки — 6 год, пробний шопер — 4 год, решта ('+H(S.hrs-10)+') — відпочинок і резерв, нічим не зайнятий наперед',p:S=>S.hrs-10>=3?2:1,eff:S=>{const r=S.hrs-10;sd(S,4);S.f.proto=1;S.cash-=160;S.biz-=160;S.rsv=r;S.hrs=r;},fb:S=>S.hrs-10>=3?'Уроки захищено, пробний шопер буде, і лишився запас. Так і виглядає план: спершу обов’язкове, потім важливе, і трохи повітря.':'Уроки й шопер отримали своє, але резерву лише '+H(S.hrs-10)+'. Перша ж несподіванка забере години в сну або в домашніх завдань.'},
   {l:S=>'Уроки — 6 год, резерв — 3 год, на справу — решта ('+H(S.hrs-9)+'); пробний шопер перенести',when:S=>S.hrs-10<3,p:2,eff:S=>{sd(S,4);S.rsv=3;S.hrs=3;},fb:'Більше з цих годин не вичавиш: уроки й резерв збережено, але пробного шопера цього тижня не буде. Це ціна підробітку.'},
   {l:S=>'Уроки — 6 год, а всі інші '+H(S.hrs-6)+' — на справу: шопер, макети про запас, сторінка в соцмережі',when:S=>S.hrs-10>=3,p:1,eff:S=>{sd(S,4);S.f.proto=1;S.cash-=160;S.biz-=160;S.rsv=0;S.hrs=0;},fb:'Справа отримала максимум, а резерву немає зовсім. Будь-яка несподіванка забере години в сну або в домашніх завдань.'},
   {l:S=>'Уроки — 10 год, решта ('+H(S.hrs-10)+') — відпочинок; пробний шопер зачекає',p:1,eff:S=>{const r=S.hrs-10;sd(S,6);S.rsv=r;S.hrs=r;},fb:'Контрольна під надійним захистом. Але ідея цього тижня з місця не зрушить, і показати клієнтам буде нічого.'},
   {l:'Нічого не розписувати: братися за те, на що буде настрій',p:0,eff:S=>{sd(S,-8);S.rsv=0;S.hrs=0;},fb:'Години, яким не дали завдання, розходяться самі: стрічка, серіал, «ще п’ять хвилин». До четверга немає ні підготовки, ні шопера.'}]},
  {id:'urgent',t:'event',head:'Тиждень 2 · Середа, несподіванка',text:S=>'Соломія, капітанка волейбольної команди, '+(S.f.ask?'запам’ятала твої розпитування':'почула про твій задум від Данила')+' й просить сьогодні ж показати зразок: завтра команда вирішує, де замовляти шопери. А до контрольної з алгебри додали ще одну тему. Разом це 3 години, яких у плані не було. '+(S.rsv>=3?'У резерві в тебе '+H(S.rsv)+' — вистачило, і лягти спати вдалося вчасно.':(S.rsv>0?'У резерві лише '+H(S.rsv)+'.':'Резерву немає.')+' Решту довелося забрати в сну й домашніх завдань — на контрольній це далося взнаки.')+(S.f.proto?' Соломія довго крутить у руках твій пробний шопер.':' Зразка немає, тож Соломія бачить лише ескіз у телефоні.')+(S.f.loud?' А в шкільному чаті після твого оголошення вже одинадцять запитань «коли й почому?». Відповісти нічого — і люди це помічають.':''),eff:S=>{const d=Math.max(0,3-S.rsv);S.hrs=Math.max(0,S.rsv-3);sd(S,-3*d);if(d>0)S.f.thin=1;if(S.f.loud)rp(S,-6);}},
  {id:'w3',t:'event',head:'Тиждень 3 · Перше замовлення',text:S=>'Понеділок. Пише Соломія: «Нам потрібно 12 шоперів із логотипом команди до турніру в п’ятницю. Скільки це коштує і коли буде готово?» Це твоє перше справжнє замовлення.'+(S.busy?' За минулий тиждень підробітку ти отримуєш '+PG(jobPay(S))+'; цього тижня він знову забере '+H(S.busy)+'.':'')+' У четвер контрольна з фізики.',eff:S=>{S.hrs=20-S.busy;S.cash+=jobPay(S);S.job+=jobPay(S);}},
  {id:'quote',t:'choice',head:'Тиждень 3 · Ціна і строк',text:S=>S.f.proto?'Завдяки пробному шоперу ти знаєш свої цифри: заготовка коштує 55 грн, термоплівка — 25 грн, а на один шопер іде '+(S.f.press?20:30)+' хвилин.':'Пробного шопера в тебе досі немає. Скільки коштують матеріали й скільки часу йде на один шопер, ти уявляєш лише приблизно.',q:'Що відповісти Соломії?',o:[
   {l:'«150 грн за шопер, віддам у четвер після уроків» — я знаю свої витрати й час',when:S=>!!S.f.proto,p:2,eff:S=>{S.price=150;},fb:'Ціна покриває матеріали й твій час, а строк названо із запасом в один день. Соломія погодилась одразу.'},
   {l:'«Сьогодні ввечері зроблю пробний шопер, а завтра вранці назву точну ціну і строк» (2 години, 160 грн)',when:S=>!S.f.proto,p:2,eff:S=>{use(S,2);S.cash-=160;S.biz-=160;S.f.proto=1;S.price=150;},fb:'Соломія почекала один вечір. Зате за словами «150 грн і четвер» уже стоять твої витрати й час. Такій обіцянці можна вірити.'},
   {l:'«По 100 грн, і буде готово вже в середу!» — аби тільки не пішла до інших',p:0,eff:S=>{S.price=100;S.f.rush=1;},fb:'Соломія зраділа. А в тебе тепер найнижча ціна й найкоротший строк — і жодного розрахунку за ними.'},
   {l:'«150 грн. А коли… ну, до п’ятниці якось устигну»',p:1,eff:S=>{S.price=150;S.f.vague=1;},fb:'Ціна розумна, але «якось устигну» — це не строк. Соломія погодилась, проте щодня перепитуватиме, чи все гаразд.'}]},
  {id:'margin',t:'calc',head:'Тиждень 3 · Вигоди й витрати',text:S=>'Домовлено: 12 шоперів по '+S.price+' грн. На кожен потрібна заготовка за 55 грн і термоплівка за 25 грн.',q:'Скільки гривень принесе це замовлення після витрат на матеріали?',ans:S=>gain(S),unit:'грн',hint:'Спершу знайди, скільки лишається з одного шопера: ціна мінус заготовка й плівка. Потім помнож на 12.',sol:S=>'Матеріали на один шопер: 55 + 25 = 80 грн. З одного шопера лишається '+S.price+' − 80 = '+(S.price-80)+' грн. За 12 шоперів: 12 × '+(S.price-80)+' = '+PG(gain(S))+'.'},
  {id:'hour',t:'calc',head:'Тиждень 3 · Скільки коштує твоя година',text:S=>'Тепер порахуй час. '+(S.f.press?'Шкільним пресом':'Домашнім міні-пресом')+' один шопер друкується '+(S.f.press?20:30)+' хвилин. Ще 2 години підуть на макет, закупівлю матеріалів і доставку. Замовлення принесе '+PG(gain(S))+'.',q:'Скільки гривень припадає на одну годину твоєї роботи?',ans:S=>gain(S)/T(S),unit:'грн за годину',hint:'Знайди час на друк 12 шоперів у годинах, додай 2 години й поділи заробіток на всі години.',sol:S=>{const t=T(S),e=gain(S)/t;return 'Друк: 12 × '+(S.f.press?20:30)+' хв = '+(S.f.press?240:360)+' хв = '+H(t-2)+'. Разом із макетом і доставкою: '+H(t)+'. '+PN(gain(S))+' : '+t+' = '+PN(e)+' грн за годину. '+(e>=90?'Це більше, ніж 90 грн за годину математики — найкращої з відкинутих можливостей. Замовлення вигідне.':'А година математики з п’ятикласником — це 90 грн. За такої ціни шоперів твій час коштує дешевше, ніж найкраща альтернатива.');}},
  {id:'energy',t:'choice',head:'Тиждень 3 · Прес і розетка',text:S=>'Перед друком треба домовитися про енергію. '+(S.f.press?'Шкільний прес':'Домашній міні-прес')+' споживає багато електрики й пів години розігрівається. '+(S.f.press?'Пан Орест попереджає: за кожну кіловат-годину платить школа, а з 17-ї до 21-ї мережа перевантажена, тож потужні прилади в цей час краще не вмикати.':'Мама попереджає: за світло платить родина, а з 17-ї до 21-ї, коли вдома працюють плита й пральна машина, зайвий прилад вибиває автомат.'),q:'Яке правило роботи з пресом ти собі встановиш?',o:[
   {l:'Заздалегідь підготувати заготовки й плівку, вмикати прес один раз на денну партію, а після роботи вимикати з розетки',p:2,eff:S=>{rp(S,2);S.f.batch=1;},fb:S=>'Один розігрів на партію і жодної хвилини простою. '+(S.f.press?'Пан Орест помітив, що після тебе прес завжди вимкнений, — і сказав про це колегам.':'Мама бачить, що лічильник майже не відчуває твого друку, і більше не хвилюється за рахунок.')},
   {l:'Друкувати по кілька шоперів за підхід, а між підходами прес не вимикати — щоб не чекати розігріву',p:0,eff:S=>{rp(S,-4);S.f.idle=1;},fb:S=>'Увімкнений прес між підходами гріє повітря. '+(S.f.press?'Пан Орест уже раз знайшов його гарячим у порожній майстерні й не певен, чи давати ключ надалі.':'Мама вже раз знайшла його гарячим у порожній кімнаті — розмова була неприємна.')},
   {l:'Вмикати прес лише ввечері після шостої: удень уроки, а ввечері ніхто не заважає',p:1,eff:S=>{S.f.peak=1;},fb:S=>'Це саме ті години, коли мережа перевантажена найбільше. '+(S.f.press?'У майстерні двічі блимнуло світло.':'Удома двічі вибило автомат.')+' Плівка на одному шопері прихопилася нерівно — це випливе, коли замовлення вже буде в Соломії.'}]},
  {id:'kwh',t:'calc',head:'Тиждень 3 · Скільки коштує розетка',text:S=>'За умовою задачі потужність '+(S.f.press?'шкільного преса — 2 кВт':'домашнього міні-преса — 1 кВт')+', тариф — 4,32 грн за кіловат-годину. Друк 12 шоперів триває '+H(T(S)-2)+'. Ще 1 година піде на розігрів (два дні по пів години).'+(S.f.idle?' І ще 3 години прес простоїть увімкненим між підходами.':''),q:'Скільки гривень коштує електроенергія на замовлення?',ans:S=>Math.round(kwh(S)*432)/100,unit:'грн',tol:0.01,hint:'Спершу знайди, скільки годин прес увімкнений. Години × потужність = кіловат-години. Потім помнож на тариф.',sol:S=>{const h=onH(S),e=kwh(S),c=Math.round(e*432)/100;return 'Прес увімкнений: '+(T(S)-2)+' + 1'+(S.f.idle?' + 3':'')+' = '+H(h)+'. Енергія: '+h+' × '+kw(S)+' = '+e+' кВт·год. Вартість: '+e+' × 4,32 = '+PG(c)+'. Платить за це '+payer(S)+', а не ти.'+(S.f.idle?' Із них '+PG(Math.round(3*kw(S)*432)/100)+' — за простій: гроші, заплачені ні за що.':' Енергоетикет — це берегти чужі кіловати так само, як власні гроші.');}},
  {id:'sched',t:'choice',head:'Тиждень 3 · Розклад',text:S=>'На замовлення потрібно '+H(T(S))+', цього тижня в тебе '+S.hrs+' вільних. '+(S.f.rush?'Обіцяний строк — середа.':'Шопери треба віддати в четвер, турнір у п’ятницю.')+' У четвер контрольна з фізики. Матеріали на 12 шоперів коштують 960 грн.',q:'Як розкласти роботу?',o:[
   {l:S=>S.f.rush?'Понеділок — макет і закупівля, вівторок і середа — друк одразу після уроків; домашні завдання — як вийде':'Понеділок — макет і закупівля, вівторок і середа — друк рівними частинами, четвер — фізика й запас на випадок браку',p:2,eff:S=>{use(S,T(S));if(S.f.rush)sd(S,-5);S.cash-=960;S.f.ok=1;},fb:S=>(S.f.rush?'До середи все готово, але два вечори без домашніх завдань — це плата за строк, названий навмання.':'Велику справу розбито на частини, і перед строком лишився запас. Шопери готові в середу ввечері, четвер вільний для фізики.')+(S.hrs<T(S)?' Вільних годин забракло: '+H(T(S)-S.hrs)+' довелося забрати в сну й уроків.':'')},
   {l:'Спершу зробити всі уроки на тиждень наперед, а шопери друкувати, коли лишиться час',p:1,eff:S=>{S.hrs=Math.max(0,S.hrs-T(S));sd(S,2);S.cash-=960;S.f.slow=1;},fb:'Уроки в порядку, але друк з’їхав на самий кінець тижня. Запасу перед строком не лишилося зовсім.'},
   {l:'Зробити все за один раз у ніч перед строком: так не доведеться щодня перемикатися',p:0,eff:S=>{sd(S,-8);S.cash-=960;S.f.night=1;},fb:'О другій ночі руки вже не слухаються: на трьох шоперах логотип ліг криво. А вранці — контрольна, на якій злипаються очі.'}]},
  {id:'deliver',t:'event',head:'Тиждень 3 · Замовлення віддано',text:S=>{const n=nb(S);return (S.f.ok?(S.f.rush?'У середу, як і обіцяно, ти приносиш Соломії 12 шоперів.':'У четвер після уроків ти приносиш Соломії 12 шоперів — на день раніше від турніру.'):S.f.slow?(S.f.rush?'Обіцяно було на середу, а шопери готові лише в п’ятницю вранці. Соломія двічі писала «ну де?».':'Шопери готові лише в п’ятницю вранці, за годину до турніру. Команда встигла, але Соломія нервувала.'):'Після безсонної ночі ти приносиш Соломії 12 шоперів — точно в строк.')+(S.f.vague?' Через твоє «якось устигну» вона всі ці дні перепитувала, чи все гаразд.':'')+' Вона платить '+PG(12*S.price)+'. Увечері з’ясовується, що '+(n===1?'один шопер — із плямою від плівки. У першій партії таке буває навіть у досвідчених майстрів.':'з браком '+B(n)+'. '+(S.f.night?'Три — із кривим логотипом після нічної роботи.':'Один — із плямою від плівки: у першій партії таке буває.')+(S.f.peak?' Ще один — той, що друкувався, коли стрибала напруга.':'')+(S.f.proto?'':' Ще один — бо без пробного шопера вчитися довелося просто на замовленні.'))+' О 23:10 від Соломії приходить сердите повідомлення: «'+(n===1?'Один шопер із плямою':'Бракованих шоперів — '+n)+'! '+(S.f.slow?'На турнірі це помітили всі. Що мені казати дівчатам?!':'У п’ятницю турнір, що мені казати дівчатам?!')+'»';},eff:S=>{S.bad=nb(S);S.cash+=12*S.price;S.biz+=gain(S);rp(S,(S.f.ok?6:S.f.slow?(S.f.rush?-6:2):-2)-(S.f.vague?2:0));}},
  {id:'etiq',t:'choice',head:'Тиждень 3 · Сердите повідомлення',text:S=>'На годиннику 23:10. Соломія чекає на відповідь. Ти не чуєш ніг від утоми, і трохи прикро: '+(S.f.rush?'це ж вона хотіла якнайшвидше.':'решта шоперів вийшла добре.')+' Передрукувати '+B(S.bad)+' — це '+PG(80*S.bad)+' на матеріали'+(S.f.ok&&!S.f.rush?'; запас часу в розкладі на це є.':'.'),q:'Як відповісти?',o:[
   {l:S=>'Коротко: «Вибач, це моя помилка. Передрукую власним коштом і принесу '+(S.f.slow?'в понеділок':'завтра')+' до першого уроку» — і зробити це',p:2,eff:S=>{S.cash-=80*S.bad;S.biz-=80*S.bad;rp(S,8);S.f.fix=1;},fb:'Помилку визнано, названо рішення і строк — і слова дотримано. Соломія розповіла про це всій команді. Клієнт, чию проблему розв’язали, часто стає найвідданішим.'},
   {l:'Одразу записати довге голосове: часу було мало, плівка така, і взагалі за ці гроші краще ніхто не зробить',p:0,eff:S=>{rp(S,-10);S.f.rude=1;},fb:'Голосове на три хвилини Соломія переслала подругам із підписом «оце сервіс». Виправдання замість рішення коштують репутації дорожче, ніж сама помилка.'},
   {l:S=>'Мовчки переказати їй '+PG(S.price*S.bad)+' за бракований товар і написати «ок»',p:1,eff:S=>{S.cash-=S.price*S.bad;S.biz-=S.price*S.bad;rp(S,-2);},fb:'Гроші повернуто, тож формально все чесно. Але браку ніхто не замінив, а сухе «ок» прозвучало як образа.'}]},
  {id:'w4',t:'event',head:'Тиждень 4 · Що про тебе кажуть',text:S=>(S.rep>=62?'Чутки в школі розходяться швидко — і цього разу на твою користь. До тебе підходять двоє: староста 9-А хоче 15 шоперів до Дня школи, тренер баскетбольної команди — 10 шоперів для гравців.':'Після турніру нових замовлень немає. Соломіїна команда ходить із твоїми шоперами, проте радити тебе іншим не поспішає. Єдиний, хто написав, — Данило: просить три шопери для себе й братів.')+(S.busy?' За минулий тиждень підробітку отримано '+PG(jobPay(S))+'. Цей тиждень — останній: ще мінус '+H(S.busy)+'.':''),eff:S=>{S.hrs=20-S.busy;S.cash+=jobPay(S);S.job+=jobPay(S);S.f.hot=S.rep>=62?1:0;}},
  {id:'big',t:'choice',head:'Тиждень 4 · Нові можливості',text:S=>S.f.hot?'Обидва замовлення потрібні до Дня школи — тобто за два тижні, і на другий із них припадають семестрові контрольні. Цього тижня в тебе '+S.hrs+' вільних годин.':'Данило — твій друг, тож про гроші він і не згадав. Три шопери — це 240 грн на матеріали й дві години роботи.',q:S=>S.f.hot?'Що відповісти старості й тренерові?':'Що відповісти Данилові?',o:[
   {l:'Узяти 15 шоперів для 9-А з передоплатою половини суми, а тренерові чесно назвати дату на тиждень пізніше',when:S=>!!S.f.hot,p:2,eff:S=>{S.cash+=1050;S.biz+=1050;rp(S,5);S.hrs=Math.max(0,S.hrs-4);S.f.big=1;},fb:'Передоплата покрила матеріали, строк пораховано за твоїми годинами. Тренер згоден почекати: «Краще пізніше, ніж абияк». Замовлення 9-А дає 15 × 70 = 1 050 грн понад матеріали; цього тижня на нього пішло 4 години.'},
   {l:'Узяти обидва замовлення на один строк: відмовиш — підуть до інших',when:S=>!!S.f.hot,p:0,eff:S=>{S.cash+=1430;S.biz+=1430;sd(S,-10);rp(S,-3);S.hrs=0;S.f.over=1;},fb:'25 шоперів за два тижні з контрольними. Усе встигнуто, але друкувати довелося ночами. Чотири шопери пішли в брак — мінус 320 грн із 1 750. Лишилося 1 430 грн і дві контрольні, написані гірше, ніж могли б бути.'},
   {l:'Відмовити обом: «Такі обсяги мені поки що не під силу»',when:S=>!!S.f.hot,p:1,eff:S=>{rp(S,-1);},fb:'Чесно й безпечно. Але можливість, зароблену трьома тижнями роботи, отримає хтось інший.'},
   {l:'Зробити за собівартістю, 240 грн, і попросити чесний відгук із фото в шкільному чаті',when:S=>!S.f.hot,p:2,eff:S=>{rp(S,6);use(S,2);S.f.review=1;},fb:'У чаті з’явилося Данилове фото з підписом: «Готово за два дні, як і обіцяно». Відгук живої людини важить більше за будь-яке твоє оголошення.'},
   {l:'Зробити безплатно: це ж друг',when:S=>!S.f.hot,p:1,eff:S=>{S.cash-=240;S.biz-=240;rp(S,2);use(S,2);},fb:'Данило задоволений. А тобі це коштувало 240 грн і вечір часу. Справі це не допомогло.'},
   {l:'Відмовити: дрібні замовлення не варті часу, краще почекати на великі',when:S=>!S.f.hot,p:0,eff:S=>{rp(S,-3);},fb:'Великі замовлення не приходять до того, про кого мовчать. А єдиний, хто хотів у тебе купити, почув «ні».'}]},
  {id:'w5',t:'event',head:'Тиждень 5 · Контрольні',text:S=>'Тиждень семестрових контрольних. '+(S.busy?'Підробіток закінчився: останні '+PG(jobPay(S))+' отримано, і всі 20 годин знову твої. ':'')+(S.f.big?'Замовлення 9-А — 15 шоперів — треба віддати до п’ятниці.':S.f.over?'Після двох замовлень про тебе знають: за вихідні надійшло ще 6 дрібних замовлень на шопери.':S.rep>=52?'За вихідні набралося 6 дрібних замовлень на шопери.':'Замовлень немає. Данило пропонує надрукувати 6 шоперів із гербом школи й продати їх у п’ятницю на шкільному ярмарку.')+' Із кожного шопера після матеріалів лишається 70 грн. І ще одна пропозиція від Данила: «Давай я друкуватиму, а ти роби макети й говори з людьми. Мені — 30 грн із кожного шопера».',eff:S=>{S.hrs=20;S.cash+=jobPay(S);S.job+=jobPay(S);}},
  {id:'team',t:'choice',head:'Тиждень 5 · Удвох чи наодинці',text:S=>'На уроки й підготовку до контрольних цього тижня треба 12 годин із 20. Друк '+B(n5(S))+' — це '+H(Math.ceil(n5(S)/(S.f.press?3:2)))+', ще 2 години — макети й розмови з людьми.',q:'Як пройти цей тиждень?',o:[
   {l:'Погодитися й записати в нотатках на двох: хто що робить, до якого дня і скільки отримує',p:2,eff:S=>{const d=30*n5(S),g=S.f.big?-d:70*n5(S)-d;S.cash+=g;S.biz+=g;S.f.partner=1;rp(S,2);use(S,14);},fb:S=>'Данило отримує 30 × '+n5(S)+' = '+PG(30*n5(S))+(S.f.big?'':', тобі лишається '+PG(40*n5(S)))+'. Натомість до тебе повертаються вечори перед контрольними. Залучати людей — така сама риса підприємливості, як і помічати проблеми.'},
   {l:S=>S.f.big?'Попросити старосту 9-А перенести строк на тиждень і чесно пояснити чому':S.rep>=52||S.f.over?'Написати клієнтам: «Цього тижня в мене контрольні. Замовлення приймаю з понеділка» — і назвати точну дату':'Відмовитися від ярмарку: цього тижня лише контрольні',p:1,eff:S=>{sd(S,2);if(S.f.big)rp(S,-2);use(S,12);S.f.pause=1;},fb:S=>S.f.big?'Староста погодилась, хоч і без радості: День школи клас зустріне без шоперів. Контрольні написано спокійно, але допомога була поруч.':S.rep>=52||S.f.over?'Чесно названа дата нікого не образила. Але тиждень справа стояла, хоча допомога була поруч.':'Контрольні написано спокійно. Але ярмарок минув без тебе, хоча Данило пропонував допомогу.'},
   {l:'Відмовитися й друкувати все без помічника, ночами: так надійніше, і гроші не треба ділити',p:0,eff:S=>{const g=S.f.big?0:70*n5(S);S.cash+=g;S.biz+=g;sd(S,-8);S.hrs=0;S.f.solo=1;},fb:S=>(S.f.big?'Замовлення віддано вчасно, і ділитися не довелося.':'70 × '+n5(S)+' = '+PG(70*n5(S))+' — усі твої.')+' А от дві контрольні написано на сонну голову. Хто все робить без допомоги, платить власним часом і здоров’ям.'}]},
  {id:'cap',t:'calc',head:'Тиждень 5 · Скільки я подужаю',text:S=>'Час порахувати свої межі на звичайний тиждень. Із 20 вільних годин 8 потрібно на уроки. '+(S.f.partner?'Данило готовий друкувати 6 годин на тиждень. ':'')+'Із годин, що лишаються на справу, 2 йдуть на макети й клієнтів, решта — на друк. '+(S.f.press?'Шкільним пресом виходить 3 шопери за годину.':'Домашнім міні-пресом виходить 2 шопери за годину.'),q:'Скільки шоперів на тиждень можна друкувати за таких умов?',ans:S=>(10+(S.f.partner?6:0))*(S.f.press?3:2),unit:'шт.',hint:'Спершу знайди години на справу, відніми 2 години на макети й клієнтів, а решту помнож на кількість шоперів за годину.',sol:S=>{const all=12+(S.f.partner?6:0),r=S.f.press?3:2;return 'Твої години на справу: 20 − 8 = 12 год.'+(S.f.partner?' Із Даниловими: 12 + 6 = 18 год.':'')+' На друк: '+all+' − 2 = '+H(all-2)+'. '+(all-2)+' × '+r+' = '+((all-2)*r)+' шт. на тиждень. Більше обіцяти клієнтам не можна — хіба що змінити умови: залучити помічника, знайти швидший прес або звільнити години.';}},
  {id:'next',t:'choice',head:'Тиждень 5 · Що далі',text:S=>'П’ять тижнів позаду. С'+bz(S)+(S.job?', підробіток — '+PG(S.job):'')+'. Репутація — '+S.rep+' зі 100, навчання — '+S.study+' зі 100. '+(S.study<50?'Класна керівниця вже питала в мами, що сталося з твоїми оцінками.':'Оцінки тримаються.')+(S.rep>=62?' Данило каже: «Слухай, це ж уже майже майстерня. Назвемо її „Відбиток“?»':' Данило питає: «То що, продовжуємо — чи ну його?»'),q:'Що ти вирішиш?',o:[
   {l:'Сісти з батьками й показати підсумок: скільки справа дає за годину, що з оцінками; домовитися про межу годин на тиждень і продовжити',p:2,eff:S=>{sd(S,3);rp(S,1);S.f.plan=1;},fb:'Батьки бачать цифри, а не мрії, і межу годин називаєш ти. Мама вперше каже: «Схоже, ти знаєш, що робиш».'},
   {l:'Продовжувати так само, як є: воно ж якось працює',p:1,eff:S=>{S.f.drift=1;},fb:'Справа живе, але без підсумків і меж. Наступний тиждень контрольних так само застане тебе зненацька.'},
   {l:'Кинути гурток і спати на годину менше: тоді вистачить часу на більше замовлень',p:0,eff:S=>{sd(S,-6);S.f.burn=1;},fb:'Годин на справу стало більше лише на папері. Утомлена людина працює повільніше й частіше помиляється — і на уроках, і біля преса.'}]}],
 finish:S=>{const lvl=S.rep>=62&&S.study>=52&&S.biz>=540?2:S.rep>=52&&S.study>=42?1:0;return{level:lvl,title:['Справа поки не стала на ноги','Справа жива, але далася дорого','«Відбиток» готовий до старту'][lvl],text:'За п’ять тижнів с'+bz(S)+(S.job?', підробіток — ще '+PG(S.job):'')+'; на руках '+PG(S.cash)+'. Репутація — '+S.rep+' зі 100, навчання — '+S.study+' зі 100. '+[S.rep<52?'Клієнти не радять тебе іншим — засновувати майстерню зарано.':'Навчання просіло так, що справу доведеться зупинити.',S.rep>=62&&S.study>=52?'Тебе радять, і оцінки тримаються, але справа дала менше ніж 540 грн — стільки коштує один тиждень твоїх годин за найкращою альтернативою.':'Замовлення є, але репутація чи оцінки постраждали. Перш ніж рости, варто залатати слабке місце.','Тебе радять, оцінки тримаються, свої цифри ти знаєш. Підприємливість уже працює на тебе.'][lvl]+(S.job>0&&S.job>S.biz?' Зверни увагу: підробіток дав більше грошей, ніж справа. Це не вирок ідеї, але привід порахувати, скільки коштує твоя година.':''),tips:[
   S.busy?'Підробіток дав гроші, яких на пробу й так вистачало, і забрав години, яких бракувало. Перш ніж погоджуватися, питай себе: чого мені зараз не вистачає насправді?':'Відмова від підробітку була розрахунком, а не лінощами: години виявилися потрібнішими за гроші.',
   S.f.rude||S.f.press===0?'Люди запам’ятовують не помилку, а те, як із ними говорили. Наступного разу пиши коротко, вчасно і з рішенням замість виправдань.':S.f.fix?'Чесне «це моя помилка, передрукую власним коштом» дало тобі більше клієнтів, ніж реклама.':'Діловий етикет — це не церемонії, а повага до чужого часу: представитися, пояснити, назвати строк і дотримати його.',
   S.f.night||S.f.over||S.f.burn||S.f.solo?'Робота ночами здається економією часу, а насправді коштує браку й оцінок. Розбивай велике на частини, лишай запас перед строком і не відмовляйся від допомоги.':S.f.rush?'Строк і ціну варто називати після розрахунку, а не до нього: один пробний виріб відповідає на обидва питання.':S.f.thin||S.f.slow?'У тижні не було запасу — і перша ж несподіванка забрала години в сну та уроків. Плануй від обов’язкового й лишай резерв.':S.f.idle||S.f.peak?'Із часом у тебе лад. Тепер так само сплануй енергію: прес працює не в години перевантаження й не гріє порожню кімнату.':'План тижня йшов від обов’язкового до важливого й мав резерв — тому несподіванки його не ламали.']};},
 terms:[['Підприємець','людина, яка на власний ризик організовує справу, щоб отримати прибуток'],['Підприємливість','уміння помічати проблеми й можливості та братися за їх розв’язання, залучаючи час, гроші й людей'],['Альтернативна вартість','вигода від найкращої з можливостей, від яких довелося відмовитися'],['Тайм-менеджмент','планування часу: спершу обов’язкове, потім важливе, і резерв на несподіване'],['Енергоетикет','правила ощадного й уважного користування енергією на роботі та вдома']]};
})());

PFG_TOPICS.push({id:'9-2',sec:'9a',title:'Шукаємо бізнес-ідею. Створюємо бізнес-команду',minutes:30,
 intro:'Ти засновуєш «Відбиток» — майстерню, що друкує принти на худі для класів і шкільних команд. До Дня школи, коли всі хочуть однаковий одяг, лишилося 30 днів. На старт у тебе є 4 000 грн — це і є показник «Стартовий бюджет». Гроші клієнтів (завдатки й передоплати) лежать окремо: на них купуються заготовки худі, і в бюджет вони не входять. За цей місяць ти досліджуєш ринок, обираєш нішу й збираєш команду. Від того, як глибоко ти вивчиш попит і кого покличеш у партнери, залежать цифри, з якими ти рахуватимеш, і проблеми, які доведеться розв’язувати.',
 init:()=>({cash:4000,days:30,team:50,orders:0,acc:0,pct:80,est:120,price:650,vc:440,dlv:2,mat:0,r0:12,niche:'small',f:{}}),
 meters:[{k:'cash',label:'Стартовий бюджет',unit:'грн'},{k:'days',label:'Днів до Дня школи',unit:'дн.'},{k:'team',label:'Злагодженість команди',unit:'балів'},{k:'orders',label:'Замовлено худі',unit:'шт.'}],
 steps:[
  {id:'start',t:'event',head:'День 1 · Ринок',text:'Що вже є в місті. Друкарня «Формат»: 560 грн за худі з принтом, але щонайменше 30 штук і три тижні очікування. Інтернет-магазин: будь-який принт від однієї штуки, 900 грн, доставка 10 днів. Одинадцятикласник Марко возить готові худі з ринку — без друку й лише трьох розмірів. До Дня школи готуються п’ять класів, у яких разом 150 учнів. Заготовку худі ти можеш купити за 300 грн, друк і пакування обходяться ще в 140 грн (із них 20 грн — плівка й фарби).'},
  {id:'research',t:'choice',head:'День 1 · Дослідження',text:'Перш ніж витрачати бюджет, варто зрозуміти, скільки людей справді куплять худі з принтом і що для них важливо. Але дослідження теж коштує днів і грошей.',q:'Як ти вивчатимеш попит?',o:[
   {l:'Опитати 60 учнів із шести різних класів і поговорити з трьома класними керівниками (4 дні, 200 грн на друк анкет)',p:2,eff:S=>{S.acc=2;S.days-=4;S.cash-=200;},fb:'Чотири дні й 200 грн дали відповіді від різних людей, а не лише від знайомих. Класні керівники ще й пояснили: класам потрібно 15–25 штук, швидко, зі своїм малюнком, і щоб можна було приміряти розмір.'},
   {l:'Запустити опитування у власних сторіз (1 день, безплатно)',p:1,eff:S=>{S.acc=1;S.days-=1;},fb:'Швидко й дешево, але відповіли здебільшого друзі. Вони схильні тебе підтримати — і це ще не означає, що заплатять.'},
   {l:'Не витрачати час: спитати десятьох однокласників на перерві, і так видно, що худі хочуть усі',p:0,eff:S=>{S.acc=0;},fb:'Десятеро людей з одного класу, які сидять поруч із тобою, — це не ринок. А на цю цифру спиратимуться всі подальші розрахунки.'}]},
  {id:'sample',t:'calc',head:S=>'День '+(31-S.days)+' · Результат опитування',text:S=>S.acc===2?'Із 60 опитаних у шести класах 24 відповіли, що куплять худі з принтом свого класу за 650 грн.':S.acc===1?'На опитування у твоїх сторіз відповіли 30 людей, майже всі — друзі. «Куплю за 650 грн» натиснули 15.':'Ти питаєш десятьох однокласників на перерві. Восьмеро кажуть: «Так, класно, беру».',q:'Який відсоток опитаних каже, що купить худі?',ans:S=>S.acc===2?40:S.acc===1?50:80,unit:'відсотків',hint:'Поділи кількість тих, хто сказав «так», на кількість усіх опитаних і помнож на 100.',sol:S=>(S.acc===2?'24 : 60 × 100 = 40 %. Опитані — з різних класів, тож цифра близька до правди.':S.acc===1?'15 : 30 × 100 = 50 %. Але відповідали друзі, а не випадкові учні: така вибірка завищує результат.':'8 : 10 × 100 = 80 %. Але десять сусідів по класу — замала й надто «своя» вибірка, щоб судити про всю школу.'),eff:S=>{S.pct=S.acc===2?40:S.acc===1?50:80;}},
  {id:'market',t:'calc',head:S=>'День '+(31-S.days)+' · Оцінка попиту',text:S=>'У п’яти класах, що готуються до Дня школи, 150 учнів. Припустімо, що частка охочих серед них така сама, як в опитуванні: '+S.pct+' %.',q:'Скільки худі можна очікувати за цією оцінкою?',ans:S=>150*S.pct/100,unit:'шт.',hint:'Знайди відсоток від 150: помнож 150 на відсоток і поділи на 100.',sol:S=>'150 × '+S.pct+' : 100 = '+(150*S.pct/100)+' худі. Це лише оцінка: вона настільки точна, наскільки точним було опитування.',eff:S=>{S.est=150*S.pct/100;S.est0=S.est;}},
  {id:'pre',t:'choice',head:S=>'День '+(31-S.days)+' · Слова і гроші',text:S=>'Твоя оцінка — '+S.est+' худі. Але сказати «куплю» в опитуванні й справді заплатити — не одне й те саме.',q:'Як ти перевіриш оцінку?',o:[
   {l:'Відкрити попередній запис на худі класу за 650 грн: хто вносить завдаток 100 грн, той у списку (3 дні)',p:2,eff:S=>{S.est=60;S.days-=3;S.f.pre=1;},fb:S=>(S.acc===2?'Завдаток внесли 60 учнів — стільки, скільки й показало опитування. Тепер оцінку підтверджено грошима.':'Завдаток внесли лише 60 учнів, а не '+S.est0+'. Сказати «куплю» і дістати гаманець — різні речі. Добре, що це з’ясувалося до закупівлі: далі плануй на 60.')+' Завдатки лежать окремо від бюджету: це гроші клієнтів.'},
   {l:'Довіритися опитуванню й переходити до справи',p:S=>S.acc===2?1:0,eff:S=>{},fb:S=>S.acc===2?'Опитування було ретельним, тож ризик невеликий. Та доки ніхто не заплатив, це все ще обіцянки.':'Оцінка в '+S.est+' худі тримається на словах знайомих. На неї ти далі плануватимеш гроші.'},
   {l:'Спитати в шкільному чаті: «Хто точно братиме худі? Ставте вподобайку» (1 день)',p:1,eff:S=>{S.days-=1;},fb:'Вподобайок 96. Це приємно, але вподобайка нічого не коштує — оцінка лишилася тією самою.'},
   {l:'Написати в чаті, що замовлень уже понад сотню: нехай решта теж захоче',p:0,eff:S=>{S.team-=5;S.f.fake=1;},fb:'Кілька людей справді зацікавились. А потім хтось спитав: «А хто ці сто?» — і відповісти було нічого. Це бачили й ті, кого ти збираєшся кликати в команду: довіри до твоїх слів поменшало.'}]},
  {id:'niche',t:'choice',head:S=>'День '+(31-S.days)+' · Ніша',text:S=>'Час вирішити, для кого саме працює «Відбиток» і чим він відрізняється від «Формату», інтернет-магазину та Марка.'+(S.acc===2?' З опитування ти знаєш: класам потрібно 15–25 штук за тиждень, зі своїм малюнком і з приміркою розмірів.':' Що саме важливо класам, ти достеменно не знаєш.'),q:'Яку нішу ти обереш?',o:[
   {l:'Малі партії 10–25 штук для класів і команд: власний макет класу, примірка розмірів у школі, готово за 7 днів, 650 грн',p:2,eff:S=>{S.niche='small';S.price=650;},fb:'Це місце на ринку вільне: «Формат» не бере малих партій, магазин не дає приміряти, Марко не друкує.'},
   {l:'Дешевше, ніж у «Форматі»: 520 грн за худі, а щоб вкластися в ціну — три готові макети на вибір замість власного',p:0,eff:S=>{S.niche='price';S.price=520;},fb:'Єдина твоя відмінність — ціна, а з кожного худі лишається 80 грн. У друкарні обладнання й запас грошей більші: якщо вона знизить ціну, відповісти буде нічим.'},
   {l:'Поштучні худі з будь-яким принтом для кожного охочого, 700 грн',p:1,eff:S=>{S.niche='single';S.price=700;},fb:'Це дешевше, ніж в інтернет-магазині, але кожне замовлення — окремий макет і окрема розмова. Замовлень буде менше, а мороки з кожним — більше.'}]},
  {id:'cmp',t:'calc',head:S=>'День '+(31-S.days)+' · Очима клієнта',text:S=>'Подивися на вибір очима 9-В, якому потрібно 20 худі. У «Форматі» худі коштує 560 грн, але менше ніж 30 штук там не друкують — доведеться оплатити всі 30. У тебе худі коштує '+S.price+' грн, і замовити можна рівно 20.',q:'На скільки гривень дешевше обійдеться класу замовлення у «Відбитку»?',ans:S=>16800-20*S.price,unit:'грн',hint:'Порахуй обидві суми: 30 штук за ціною «Формату» і 20 штук за твоєю ціною. Потім знайди різницю.',sol:S=>'«Формат»: 30 × 560 = 16 800 грн. «Відбиток»: 20 × '+S.price+' = '+PG(20*S.price)+'. Різниця: 16 800 − '+PN(20*S.price)+' = '+PG(16800-20*S.price)+'. '+(S.niche==='price'?'Клас заощаджує багато, але тобі з кожного худі лишається лише 520 − 440 = 80 грн.':'Хоча за штуку в тебе дорожче, клас платить менше, бо не купує зайвого.')},
  {id:'desc',t:'choice',head:S=>'День '+(31-S.days)+' · Опис ідеї',text:'Пані Ірина, вчителька економіки, пропонує подати ідею на шкільний конкурс стартапів: за перше місце дають 1 000 грн. Потрібен опис на кілька речень. Підготовка й виступ забирають день.',q:'Який опис ти подаси?',o:[
   {l:S=>'«'+(S.niche==='small'?'Класам і командам, яким потрібно 10–25 худі зі своїм принтом, ми робимо їх за 7 днів із приміркою в школі. Друкарні беруть лише від 30 штук.':S.niche==='price'?'Класам, які хочуть худі з принтом, ми друкуємо їх на 40 грн дешевше, ніж міська друкарня, — з готових макетів.':'Кожному, хто хоче худі з власним принтом в одному примірнику, ми робимо його дешевше й швидше, ніж інтернет-магазин.')+' Заробляємо на різниці між ціною '+S.price+' грн і витратами 440 грн на худі»',p:2,eff:S=>{S.cash+=1000;S.days-=1;S.f.pitch=1;},fb:'З кількох речень зрозуміло, для кого це, яку проблему розв’язує, чим відрізняється від конкурентів і на чому заробляє. Журі дало перше місце: 1 000 грн додано до бюджету.'},
   {l:'«Ми друкуватимемо найкрутіші худі в місті. У нас найкраща якість, найнижчі ціни та індивідуальний підхід»',p:0,eff:S=>{S.days-=1;},fb:'Журі спитало: «Для кого? Чим ви кращі за друкарню? Звідки прибуток?» Гучні слова без клієнта й цифр нічого не описують. Призу немає.'},
   {l:'«Ми купимо термопрес 38 × 38 см, плотер і плівку п’яти кольорів та нанесемо зображення методом термоперенесення»',p:1,eff:S=>{S.cash+=300;S.days-=1;},fb:'Як ти друкуватимеш — зрозуміло. Кому це потрібно і чому куплять саме в тебе — ні. Заохочувальний приз: 300 грн додано до бюджету.'}]},
  {id:'team1',t:'choice',head:S=>'День '+(31-S.days)+' · Команда',text:'Ти добре малюєш макети й друкуєш — це продукт. Але справі потрібні ще продажі та облік грошей. Узяти можеш двох. Данило — твій найкращий друг, теж малює. Назар — веселий, теж малює, давно хоче «щось замутити». Соломія — капітанка волейбольної команди, знає старост усіх класів. Тимур — акуратний, любить таблиці, веде касу класу. На розмови піде день.',q:'Кого ти покличеш?',o:[
   {l:'Соломію — на продажі, Тимура — на фінанси',p:2,eff:S=>{S.f.sales=1;S.f.fin=1;S.f.full=1;S.days-=1;},fb:'Тепер у команді є всі три ролі: продукт, продажі, фінанси. Друзями ви ще не стали, але кожен уміє те, чого не вміють інші.'},
   {l:'Данила й Соломію: друг поруч, і продавати є кому',p:1,eff:S=>{S.f.sales=1;S.team+=3;S.days-=1;},fb:'Продажі закрито, працювати весело. Але рахувати гроші не буде кому: і ти, і Данило — про малюнки.'},
   {l:'Данила й Тимура: друг поруч, і гроші під наглядом',p:1,eff:S=>{S.f.fin=1;S.team+=3;S.days-=1;},fb:'Гроші будуть пораховані, але ходити по класах і домовлятися зі старостами не любить ніхто з вас трьох.'},
   {l:'Данила й Назара: з друзями найлегше, а решти навчимося',p:0,eff:S=>{S.team+=6;S.days-=1;},fb:'Разом вам легко й весело. Але в команді троє художників і жодного продавця чи фінансиста: дві ділянки з трьох лишилися без господаря.'}]},
  {id:'agree',t:'choice',head:S=>'День '+(31-S.days)+' · Домовленості',text:'Команда зібралася вперше. Усі в захваті, і ніхто ще не спитав головного: хто за що відповідає і як ділити зароблене.',q:'Як ви домовитеся?',o:[
   {l:'Записати на одному аркуші: хто за що відповідає, як ділимо прибуток, що робимо, якщо хтось виходить, — і всім підписати',p:2,eff:S=>{S.team+=10;S.f.deal=1;},fb:'Пів години незручної розмови зараз замість сварки потім. Кожен знає свою ділянку і свою частку.'},
   {l:'«Ми ж свої люди, домовимося по ходу»',p:0,eff:S=>{S.f.nodeal=1;},fb:'Сьогодні всі задоволені. Питання «а чому я роблю більше, а отримую стільки ж?» з’явиться разом із першими грошима.'},
   {l:'Оголосити: рішення ухвалюю я, решта — помічники за невелику плату з майбутнього заробітку',p:1,eff:S=>{S.team-=6;S.f.boss=1;},fb:'Порядок є, але партнерів у тебе немає — є найняті помічники. Думати про справу, як про власну, вони не будуть.'}]},
  {id:'budget',t:'plan',head:S=>'День '+(31-S.days)+' · Бюджет старту',text:S=>'У стартовому бюджеті '+PG(S.cash)+'. '+(S.f.pre?'Завдаток внесли '+S.est+' учнів.':'За твоєю оцінкою, замовлять '+S.est+' худі.')+' Плівку й фарби треба закупити наперед: 20 грн на одне худі. Комплект із трьох худі-зразків різних розмірів для примірки коштує 1 300 грн. Афіші й оголошення — щонайменше 300 грн. Заготовки ви купуватимете пізніше, за передоплати клієнтів. Закупівлі заберуть день.'+(S.f.pre?'':' Пам’ятай: цю оцінку ще ніхто не підтвердив грошима.'),q:'Як ти розподілиш бюджет?',
   fields:[{k:'mat',label:'Плівка й фарби'},{k:'samp',label:'Зразки для примірки'},{k:'adv',label:'Афіші й оголошення'},{k:'res',label:'Резерв'}],
   total:S=>S.cash,
   best:S=>({mat:1200,samp:1300,adv:300,res:S.cash-2800}),
   check:(S,v)=>v.samp>0&&v.samp<1300?'Комплект зразків коштує 1 300 грн: або відведи на нього щонайменше стільки, або 0.':null,
   score:(S,v)=>v.mat>=1200&&v.samp>=1300&&v.adv>=300&&v.res>=500?{p:2,fb:'Плівки вистачить на 60 худі, класи зможуть приміряти розміри, про вас дізнаються, і лишився резерв на несподіване.'+(v.mat>1200&&!S.f.pre?' Але плівку закуплено під оцінку, якої ніхто не підтвердив грошима, — побачиш, чи вся вона знадобиться.':'')}:v.mat>=1200&&v.samp>=1300?{p:1,fb:'Плівка й зразки є, але '+(v.adv<300?'на оголошення грошей замало: про вас мало хто дізнається.':'резерву майже не лишилося: перша ж несподіванка застане вас без грошей.')}:v.mat>20*S.est+400?{p:0,fb:'На плівку й фарби пішло '+PG(v.mat)+', хоча навіть на '+S.est+' худі з твоєї оцінки досить '+PG(20*S.est)+'. Зайва плівка лежатиме без діла, а на зразки для примірки грошей не лишилося.'}:v.mat>=1200?{p:1,fb:'Плівку закуплено, але зразків для примірки не буде. Клієнти вгадуватимуть розмір наосліп, і частина просто не замовить.'}:{p:0,fb:'На плівку й фарби відведено менше ніж 1 200 грн. '+(S.est===60?'Цього не вистачить на 60 худі з твого ж плану: 60 × 20 = 1 200 грн.':'Цього не вистачить навіть на 60 худі, а твоя оцінка — '+S.est+'.')+' Бюджет має спиратися на власні цифри.'},
   eff:(S,v)=>{S.mat=v.mat;S.f.samp=v.samp>=1300?1:0;S.f.adv=v.adv>=300?1:0;S.cash=v.res;S.days-=1;let r=({small:[36,60],single:[24,36],price:[12,24]})[S.niche][S.f.sales?1:0];r=Math.max(12,r-(S.f.samp?0:12)-(S.f.adv?0:12));let gap=Math.max(0,20*r-S.mat);if(gap>S.cash&&r>12){r-=12;S.f.lost=1;gap=Math.max(0,20*r-S.mat);}S.r0=r;if(gap>0)S.f.short=Math.min(S.cash,gap);}},
  {id:'month',t:'event',head:S=>'День '+(31-S.days)+' · Тиждень продажів',text:S=>{const r=S.r0,need=20*r;return'Минає тиждень продажів. Замовлено '+r+' худі'+(r===S.est?' — рівно стільки, скільки '+(S.f.pre?'було в списку із завдатками. ':'у твоїй оцінці. '):', а '+(S.f.pre?'завдаток вносили '+S.est+' учнів. Завдаток — ще не замовлення: коли стали відомі остаточні умови, частина записаних забрала гроші. ':'твоя оцінка була '+S.est+'. '))+(S.niche==='price'?'Класи хотіли худі зі своїм малюнком, тож готові макети привабили небагатьох, навіть за 520 грн. ':S.niche==='single'?'Поштучне худі за 700 грн дорожче, ніж худі класу за 650, і кожне потребує окремого макета — охочих виявилося менше. ':'Класи охоче беруть малі партії зі своїм принтом. ')+(S.f.sales?'Соломія обійшла всіх старост. ':'Ходити по класах не було кому, тож про вас знають не всі. ')+(S.f.samp?'Зразки для примірки зняли головний страх — помилитися з розміром.':'Без зразків частина учнів побоялася помилитися з розміром і не замовила.')+(S.f.adv?'':' Без афіш і оголошень дехто дізнався про «Відбиток» запізно.')+(S.f.lost?' Плівки й фарб забракло, а резерву на них не вистачило: від 12 замовлень довелося відмовитися.':'')+(S.f.short?' Плівки не вистачило: довелося терміново докупити її з резерву на '+PG(S.f.short)+'.':S.mat>=need+600?' Плівки й фарб закуплено на '+PG(S.mat)+', а знадобилося на '+PG(need)+': '+PG(S.mat-need)+' лежать мертвим вантажем.':'')+(S.f.nodeal?' А з першими замовленнями в команді почалася суперечка про те, хто скільки робить і скільки отримає.':'');},eff:S=>{S.orders=S.r0;S.days-=7;if(S.f.short)S.cash=Math.max(0,S.cash-S.f.short);if(S.f.nodeal)S.team-=6;}},
  {id:'fact',t:'calc',head:S=>'День '+(31-S.days)+' · Прогноз і факт',text:S=>(S.f.pre?'У списку із завдатками було '+S.est+' учнів.':'Твоя оцінка попиту була '+S.est+' худі.')+' Насправді замовили '+S.orders+'.',q:'Скільки відсотків від прогнозу становить факт?',ans:S=>Math.round(S.orders/S.est*100),tol:1,unit:'відсотків',hint:'Поділи фактичну кількість на прогнозовану й помнож на 100.',sol:S=>{const p=Math.round(S.orders/S.est*100);return S.orders+' : '+S.est+' × 100 '+(S.orders*100%S.est===0?'= ':'≈ ')+p+' %. '+(p===100?'Прогноз збігся з фактом: '+(S.f.pre?'перевірка грошима':'ретельне опитування')+' й рішення про нішу та команду спрацювали.':p>=80?'Прогноз майже збігся з фактом.':p>=50?'Прогноз помітно розійшовся з фактом. '+(S.f.pre?'Список був чесним — різницю дали рішення про нішу, команду, зразки й рекламу.':'Частину різниці дали рішення про нішу й команду, частину — неточна оцінка.'):'Факт щонайменше вдвічі нижчий за прогноз. '+(S.f.pre||S.acc===2?'Оцінка була чесною — розрив дали рішення про нішу, команду, зразки й рекламу.':'Оцінку зібрано зі слів знайомих, тож вона була завищена. Решту розриву дали рішення про нішу, команду, зразки й рекламу.'));}},
  {id:'react',t:'choice',head:S=>'День '+(31-S.days)+' · Конкуренти відповідають',text:S=>S.niche==='price'?'«Формат» помітив тебе за три дні: тепер у друкарні 500 грн за худі і два тижні замість трьох. Твоя єдина перевага — ціна — зникла.':S.niche==='single'?'Інтернет-магазин запустив знижку для школярів: худі з принтом тепер 675 грн — дешевше, ніж у тебе. А ти тим часом малюєш окремий макет для кожного замовлення.':'Марко оголосив у чаті: «Теж роблю худі для класів, по 600!» Щоправда, без друку й лише трьох розмірів. «Формат» на тебе не зважає: малі партії йому не цікаві.',q:'Як ти відповіси?',o:[
   {l:'Ціну не чіпати. Показати те, чого конкурент не дає: свій макет, примірку, 7 днів — і попросити старост, які вже замовили, розповісти, чому обрали вас',when:S=>S.niche!=='price',p:2,eff:S=>{S.orders+=12;S.team+=3;},fb:'Розповіді тих, хто вже замовив, зробили більше, ніж будь-яка знижка: додалося ще 12 замовлень. Конкурувати можна не лише ціною.'},
   {l:'Перестати змагатися ціною з друкарнею: перейти на малі партії з власним макетом класу за 7 днів і ціною 650 грн',when:S=>S.niche==='price',p:2,eff:S=>{S.niche='small';S.price=650;S.orders+=24;S.team+=3;S.f.pivot=1;},fb:'Тепер ти там, куди друкарня не піде: малі партії їй не вигідні. За кілька днів додалося 24 замовлення на худі зі своїм макетом, і з кожного худі лишається вже не 80 грн, а значно більше.'},
   {l:'Знизити ціну на 30 грн',p:0,eff:S=>{S.price-=30;S.f.cut=1;},fb:'Замовлень не додалося: конкурент може знижувати ціну довше, ніж ти. А з кожного худі тепер лишається на 30 грн менше.'},
   {l:'Додати до кожного худі подарунок — набір наліпок за 20 грн',p:1,eff:S=>{S.vc+=20;S.f.gift=1;},fb:'Наліпки сподобалися, але нових клієнтів не привели: витрати на кожне худі зросли на 20 грн, а відмінності від конкурента так і не з’явилося.'},
   {l:'Написати в шкільному чаті, що в конкурента після першого прання облазить принт',p:0,eff:S=>{S.team-=8;S.f.smear=1;},fb:'Доказів у тебе немає, і це швидко помітили. Команді соромно, а клієнти тепер перепитують, чи можна вірити й твоїм словам.'}]},
  {id:'news',t:'event',head:S=>'День '+(31-S.days)+' · Переїзд',text:'Дві новини в один день. Перша: склад, де ти збираєшся купувати заготовки по 300 грн, переїжджає в іншу область — доставка тепер триватиме 8 днів замість 2. Друга: до вашого міста переїхала зі сходу країни швейна майстерня «Нитка» пані Олени. Вона перевезла шість машин і чотирьох швачок, але втратила майже всіх клієнтів, не знає місцевих постачальників і вже платить за нове приміщення. «Нитка» шиє худі-заготовки будь-яких розмірів за 2 дні, по 330 грн.'},
  {id:'reloc',t:'choice',head:S=>'День '+(31-S.days)+' · Звідки брати заготовки',text:S=>'У тебе '+PL(S.orders,'замовлення','замовлення','замовлень')+', до Дня школи '+PL(S.days,'день','дні','днів')+'. Друкуєш ти 12 худі на день, і почати можна лише тоді, коли приїдуть заготовки. Замовляти їх треба вже сьогодні.',q:'Що ти вирішиш?',o:[
   {l:'Домовитися з «Ниткою»: заготовки по 330 грн за 2 дні, а «Відбиток» стає її першим постійним клієнтом у місті',p:2,eff:S=>{S.vc+=30;S.dlv=2;S.team+=3;S.f.nitka=1;},fb:'Кожне худі обходиться тобі на 30 грн дорожче, зате постачальник тепер за десять хвилин пішки й дає запас днів. Для пані Олени переїзд — це втрачені клієнти, але й новий ринок; для тебе — партнер, якого вчора не було.'},
   {l:'Лишитися зі старим складом і чекати 8 днів: 30 грн на кожному худі — теж гроші',p:S=>8+S.orders/12<=S.days?1:0,eff:S=>{S.dlv=8;S.f.old=1;},fb:'Витрати не зросли. Але 8 днів доставки — це дні, яких уже не повернеш. Чи вистачить решти на друк — покаже розрахунок.'},
   {l:'Купити готові худі в Марка на ринку: по 280 грн і вже завтра, хоч і лише трьох розмірів',p:0,eff:S=>{S.vc-=20;S.dlv=1;S.f.bl=S.orders>12?1:0;if(S.f.bl)S.orders-=12;S.team-=3;S.f.bazar=1;},fb:S=>'Найшвидше й найдешевше. Але трьох розмірів вистачило не всім: '+((S.f.bazar?S.f.bl:S.orders>12)?'12 клієнтів, яким не знайшлося свого розміру, відмовилися від замовлення.':'кільком клієнтам дістанеться завелике худі, і вони цього не забудуть.')}]},
  {id:'margin',t:'calc',head:S=>'День '+(31-S.days)+' · Чи сходиться справа',text:S=>'Перерахуй заробіток на замовленні з 20 худі за новими цифрами. Ціна худі — '+S.price+' грн. Заготовка — '+(S.f.nitka?330:S.f.bazar?280:300)+' грн, друк і пакування — 140 грн'+(S.f.gift?', наліпки в подарунок — 20 грн':'')+'.',q:'Скільки гривень лишиться з такого замовлення після цих витрат?',ans:S=>20*(S.price-S.vc),unit:'грн',hint:'Знайди всі витрати на одне худі, відніми їх від ціни й помнож на 20.',sol:S=>{const m=S.price-S.vc;return'Витрати на одне худі: '+(S.f.nitka?330:S.f.bazar?280:300)+' + 140'+(S.f.gift?' + 20':'')+' = '+S.vc+' грн. З одного худі: '+S.price+' − '+S.vc+' = '+m+' грн. З двадцяти: 20 × '+m+' = '+PG(20*m)+'. '+(m>=150?'Справа сходиться: є з чого платити команді й відкладати на власний прес.':m>=100?'Заробіток є, але запас невеликий: кожна знижка чи зайва витрата помітно його зменшує.':'Заробіток тонкий: один зіпсований принт чи ще одна знижка — і замовлення піде в нуль.');}},
  {id:'team2',t:'choice',head:S=>'День '+(31-S.days)+' · Що зламалося в команді',text:S=>(!S.f.fin?'Частину передоплат класи внесли готівкою — комусь у руки, комусь на картку. Записів ніхто не вів. Сьогодні з’ясувалося: бракує 600 грн, і ніхто не знає чому. Це гроші клієнтів, тож нестачу треба покрити: '+(S.cash>=600?'600 грн зі стартового бюджету.':S.cash>0?PG(S.cash)+' зі стартового бюджету, решту — з власних кишенькових.':'бюджет порожній, тож усі 600 грн — із власних кишенькових.'):!S.f.sales?'Гроші пораховано до копійки, але замовлень мало: по класах ніхто не ходить, усі чекають, що клієнти прийдуть самі.':'Соломія принесла ще одне замовлення — і пообіцяла класу готовність за три дні, не спитавши того, хто друкує. А біля преса ти без помічників і вже ледве встигаєш.')+(S.f.nodeal?' Суперечка про частки теж не вщухає: домовленостей на папері у вас немає.':S.f.boss?' Помічники знизують плечима: «Вирішуєш тут ти — от і вирішуй».':''),q:'Що ти зробиш?',o:[
   {l:'Запросити Тимура вести облік: таблиця передоплат, витрат і залишку — за частку в прибутку',when:S=>!S.f.fin,p:2,eff:S=>{S.cash=Math.max(0,S.cash-600);S.f.fin=1;S.team+=8;},fb:'Нестачу покрито, і більше гроші не губляться: кожну передоплату Тимур записує того ж дня.'},
   {l:'Запросити Соломію на продажі: вона знає старост усіх класів — за частку в прибутку',when:S=>!!S.f.fin&&!S.f.sales,p:2,eff:S=>{S.f.sales=1;S.orders+=12;S.team+=8;},fb:'Соломія обійшла старост і того ж дня принесла ще 12 замовлень. Ролі, якої бракує, не замінить старанність решти.'},
   {l:'Домовитися про правило: строк клієнтові називають лише після згоди того, хто друкує; а Данила покликати помічником до преса',when:S=>!!S.f.fin&&!!S.f.sales,p:2,eff:S=>{S.team+=8;S.f.rule=1;},fb:'Продажі й продукт тепер узгоджують обіцянки до того, як їх почує клієнт. А біля преса з’явилися другі руки.'},
   {l:'Взяти все на себе: малювати, друкувати, продавати й рахувати самотужки — так надійніше',p:0,eff:S=>{if(!S.f.fin)S.cash=Math.max(0,S.cash-600);S.team-=10;S.days=Math.max(0,S.days-2);S.f.solo=1;},fb:'Два дні пішли на чужу ділянку замість друку. Команда відчула, що їй не довіряють, а проблема лишилася: однієї людини на три ролі не вистачає.'},
   {l:'Зібрати всіх і суворо сказати, що так далі не можна',p:1,eff:S=>{if(!S.f.fin)S.cash=Math.max(0,S.cash-600);S.team-=3;},fb:'Усі покивали. Але хто саме і що робитиме інакше, так і не прозвучало — отже, повториться.'}]},
  {id:'deadline',t:'calc',head:S=>'День '+(31-S.days)+' · Чи встигнемо',text:S=>'Останній розрахунок. Замовлено '+S.orders+' худі. Заготовки їдуть '+PL(S.dlv,'день','дні','днів')+', після цього друк — 12 худі на день. До Дня школи '+PW(S.days,'лишився','лишилося','лишилося')+' '+PL(S.days,'день','дні','днів')+'.',q:'Скільки днів потрібно, щоб виконати всі замовлення?',ans:S=>S.dlv+S.orders/12,unit:'дн.',hint:'Поділи кількість худі на 12 — це дні друку. Додай дні доставки заготовок.',sol:S=>{const n=S.dlv+S.orders/12;return'Друк: '+S.orders+' : 12 = '+(S.orders/12)+' дн. Разом із доставкою: '+S.dlv+' + '+(S.orders/12)+' = '+n+' дн. '+(n<=S.days?'До свята '+PL(S.days,'день','дні','днів')+' — ви встигаєте'+(n===S.days?', але впритул: запасу немає.':'.'):'А до свята лише '+PL(S.days,'день','дні','днів')+': частина класів отримає худі вже після Дня школи.');},eff:S=>{const n=S.dlv+S.orders/12;if(n>S.days)S.f.late=1;S.days=Math.max(0,S.days-n);}}],
 finish:S=>{const lvl=S.orders>=48&&S.team>=58&&!S.f.late?2:S.orders>=24&&S.team>=42?1:0;return{level:lvl,title:['Старт «Відбитка» не вдався','«Відбиток» працює, але кульгає','«Відбиток» упевнено стартував'][lvl],text:'За місяць: замовлено '+S.orders+' худі, у стартовому бюджеті лишилося '+PG(S.cash)+', злагодженість команди — '+PL(S.team,'бал','бали','балів')+'. '+(S.f.late?'Частину замовлень ви віддали вже після Дня школи.':'Усі замовлення готові до Дня школи.')+(lvl===2?'':S.orders<24?' Замовлень замало, щоб справа годувала команду.':S.team<42?' Замовлення є, але команда майже розсварилася — працювати далі разом буде важко.':S.orders<48?' З п’яти класів вдалося охопити не всі: частина попиту лишилася конкурентам.':S.f.late?' Запізнення коштувало довіри клієнтів.':' Команді бракує злагодженості, щоб упевнено рости.'),tips:[
   S.f.pre?'Попередній запис із завдатком перевірив оцінку грошима: далі твій план спирався на 60 людей, які справді заплатили, а не на слова.':S.acc===2?'Ретельне опитування дало чесну цифру. Наступного разу перевір її ще й грошима — завдатком.':'Оцінку попиту зібрано зі слів знайомих, і вона виявилася завищеною. Питай різних людей і перевіряй слова завдатком.',
   S.f.full?'У команді від початку були всі три ролі — продукт, продажі, фінанси, — тому жодна ділянка не лишилася без господаря.':S.f.sales&&S.f.fin?'Роль, якої бракувало, довелося закривати посеред місяця — уже після втрат. Спершу випиши ролі, потім шукай людей.':'У команді так і лишилася ділянка без господаря. Збирай людей під ролі — продукт, продажі, фінанси, — а не лише тих, із ким приємно.',
   S.f.late?'Частина замовлень запізнилася. Коли умови змінюються, рахуй дні так само уважно, як гроші, — до рішення, а не після.':S.f.bazar?'Найдешевший постачальник підвів клієнтів, яким не знайшлося розміру. Дешевше — не завжди вигідніше.':S.f.cut||S.niche==='price'?'Змагання ціною з більшим конкурентом ти не виграєш. Нішу тримає те, чого конкуренти не дають.':S.f.nitka?'Переїзд чужого бізнесу став твоєю можливістю: новий постачальник поруч дав запас днів.':'Нішу тримає не ціна, а те, чого конкуренти не дають. Бережи це, коли змінюються обставини.']};},
 terms:[['Дослідження ринку','збирання відомостей про покупців, їхні потреби та про конкурентів перед запуском справи'],['Ніша','частина ринку з особливою потребою, яку конкуренти задовольняють погано або зовсім не задовольняють'],['Вибірка','частина людей, яких опитують, щоб судити про всіх; має бути різноманітною'],['Бізнес-команда','партнери з різними ролями: продукт, продажі, фінанси'],['Релокований бізнес','підприємство, яке переїхало в безпечніший регіон і заново шукає клієнтів та постачальників']]});

PFG_TOPICS.push({id:'9-3',sec:'9a',title:'Де взяти гроші для реалізації бізнес-проєкту?',minutes:30,
 intro:'«Відбиток» — твоя майстерня друку на худі для класів і шкільних команд. Ідея є, перші клієнти теж. Бракує грошей на власний прес. За вісім тижнів ти збираєш стартовий капітал із різних джерел. Кожне має свою ціну, свій строк очікування і свої зобов’язання: борг повертають із відсотками, за грант звітують, жертводавцям надсилають винагороди. Від того, з чого ти складеш суму, залежить, скільки доведеться повертати і коли справа окупиться. Усі ставки й умови програм у цій історії — «за умовою задачі»: справжні щоразу перевіряй в офіційних джерелах.',
 init:()=>({got:9000,need:22000,debt:0,trust:50,over:0,first:0,own:9000,fam:0,gr:0,cr:0,tot:9000,gap:13000,dm:0,dl:0,lg:0,lk:0,lp:0,dx:0,f:{}}),
 meters:[{k:'got',label:'Зібрано',unit:'грн'},{k:'need',label:'Потрібно на старт',unit:'грн'},{k:'debt',label:'Борг до повернення',unit:'грн'},{k:'trust',label:'Довіра до тебе',unit:'балів'}],
 steps:[
  {id:'start',t:'event',head:'Тиждень 1 · Кошторис',text:'Кошторис старту готовий: термопрес — 14 000 грн, стартовий запас матеріалів — 6 000 грн, реклама — 2 000 грн. Твої заощадження — 9 000 грн: два літа підробітків і подарунки на дні народження. Власні кошти — найдешевші гроші: за них не платять відсотків і ні перед ким не звітують. Але їх не вистачає. Через вісім тижнів починається сезон замовлень до Дня школи — до того часу прес має працювати.'},
  {id:'gap',t:'calc',head:'Тиждень 1 · Скільки бракує',text:'Потрібно: прес — 14 000 грн, матеріали — 6 000 грн, реклама — 2 000 грн. Власних коштів — 9 000 грн.',q:'Скільки гривень треба знайти?',ans:S=>13000,unit:'грн',hint:'Склади три статті кошторису й відніми власні кошти.',sol:S=>'14 000 + 6 000 + 2 000 = 22 000 грн. 22 000 − 9 000 = 13 000 грн. Цю суму ти збиратимеш із різних джерел.'},
  {id:'first',t:'choice',head:'Тиждень 1 · Замовлення без преса',text:'Староста 9-В пише: класу потрібно 20 худі з принтом по 650 грн — уже за два тижні. Преса в тебе ще немає. Зате в копі-центрі біля школи є термопрес, який здають погодинно: 160 грн за годину. На 20 худі вистачить 5 годин. Заготовка й матеріали на одне худі коштують 440 грн.',q:'Що ти відповіси 9-В?',o:[
   {l:'Узяти замовлення з передоплатою 50 %: на ці гроші купити матеріали, а прес орендувати в копі-центрі',p:2,eff:S=>{S.first=3400;S.trust+=5;S.f.first='a';},fb:'Клас вніс 6 500 грн наперед — це більша частина витрат на матеріали. Свого преса немає, власних грошей вкладено мінімум, а перше замовлення вже в роботі. Почати справу можна й без великого капіталу.'},
   {l:'Узяти замовлення без передоплати: брати гроші наперед якось незручно. Матеріали купити зі своїх',p:1,eff:S=>{S.first=800;S.f.first='b';},fb:'У матеріали пішло 8 800 грн власних коштів: два тижні в тебе лишалося 200 грн. А в день видачі четверо учнів передумали — завдатку ж ніхто не вносив.'},
   {l:'Відмовити: спершу куплю прес, тоді й братиму замовлення',p:0,eff:S=>{S.first=0;S.trust-=3;S.f.first='c';},fb:'9-В пішов до друкарні. Втрачено не лише заробіток, а й перших клієнтів, які розповіли б про тебе іншим.'}]},
  {id:'firstc',t:'calc',head:'Тиждень 2 · Перший заробіток',text:S=>S.f.first==='a'?'Замовлення виконано: 20 худі по 650 грн. Матеріали — 440 грн на одне худі. Оренда преса — 5 годин по 160 грн.':S.f.first==='b'?'Замовлення виконано, але забрали й оплатили лише 16 худі з 20 — по 650 грн. Матеріали куплено на всі 20 худі, по 440 грн. Оренда преса — 5 годин по 160 грн.':'Порахуй, чого коштувала відмова. Замовлення: 20 худі по 650 грн. Матеріали — 440 грн на одне худі. Оренда преса в копі-центрі — 5 годин по 160 грн.',q:S=>S.f.first==='c'?'Скільки гривень принесло б це замовлення після всіх витрат?':'Скільки гривень принесло замовлення після всіх витрат?',ans:S=>S.f.first==='b'?800:3400,unit:'грн',hint:'Від виручки відніми вартість матеріалів на 20 худі та оренду преса.',sol:S=>S.f.first==='b'?'Виручка: 16 × 650 = 10 400 грн. Матеріали: 20 × 440 = 8 800 грн. Оренда: 5 × 160 = 800 грн. 10 400 − 8 800 − 800 = 800 грн. Із передоплатою було б 3 400 грн: чотири неоплачені худі з’їли майже весь заробіток.':'Виручка: 20 × 650 = 13 000 грн. Матеріали: 20 × 440 = 8 800 грн. Оренда: 5 × 160 = 800 грн. 13 000 − 8 800 − 800 = 3 400 грн'+(S.f.first==='a'?' — і вони йдуть у стартовий капітал.':'. Стільки могло б додатися до стартового капіталу.')},
  {id:'w3',t:'event',head:'Тиждень 3 · Перший підсумок',text:S=>(S.first>0?'Заробіток із першого замовлення — '+PG(S.first)+' — додається до власних коштів: тепер зібрано '+PG(9000+S.first)+'.':'Зібрано так само 9 000 грн: першого замовлення не було.')+' Про твій задум уже знають удома. Мама може позичити 4 000 грн. А Данило, твій друг, пропонує вкласти 3 000 грн — але не в борг, а за частку: чверть прибутку «Відбитка» щомісяця.',eff:S=>{S.own=9000+S.first;S.got=S.own;}},
  {id:'family',t:'choice',head:'Тиждень 3 · Гроші близьких',text:S=>'До 22 000 грн бракує '+PG(22000-S.got)+'. Мамині 4 000 грн — позика без відсотків, але це її відкладені гроші. Данилові 3 000 грн повертати не треба, зате 25 % прибутку він отримуватиме, доки існує справа.',q:'Чиї гроші ти візьмеш?',o:[
   {l:'Мамині 4 000 грн — із розпискою та графіком: по 1 000 грн щомісяця, починаючи з другого місяця роботи',p:2,eff:S=>{S.got+=4000;S.fam=4000;S.debt+=4000;S.dm=4000;S.trust+=3;S.f.mom=1;},fb:'Безвідсоткова позика з чітким графіком — дешеві гроші. А розписка — не знак недовіри: вона береже стосунки, бо обидві сторони знають, чого чекати.'},
   {l:'Данилові 3 000 грн за чверть прибутку',p:1,eff:S=>{S.got+=3000;S.fam=3000;S.f.share=1;},fb:'Боргу немає, і Данило тепер уболіває за справу як за свою. Але чверть прибутку — назавжди: скільки це в гривнях, ти ще порахуєш.'},
   {l:'Мамині 4 000 грн просто так: «Віддам, як розкручуся», свої ж люди',p:0,eff:S=>{S.got+=4000;S.fam=4000;S.debt+=4000;S.dm=4000;S.trust-=8;S.f.vague=1;},fb:'Гроші ті самі, але мама не знає, коли їх побачить, а спитати їй ніяково. Борг без строку — це борг, про який мовчать за вечерею.'}]},
  {id:'grant',t:'choice',head:'Тиждень 4 · Грант',text:'Пані Ірина, вчителька економіки, пересилає оголошення: міський конкурс молодіжних ініціатив дає гранти до 4 000 грн. Грант не повертають. Умови: опис проєкту, кошторис, власний внесок, а після витрачання — звіт із чеками. Рішення оголосять через три тижні.',q:'Що ти зробиш?',o:[
   {l:'Витратити три вечори на заявку: описати, кому потрібен «Відбиток», показати власний внесок і скласти кошторис',p:2,eff:S=>{S.f.grant=1;},fb:'Заявка — це робота. Але три вечори можуть принести гроші, яких не доведеться повертати. Лишилося скласти кошторис.'},
   {l:'Не подавати: чекати три тижні, а дадуть чи ні — невідомо',p:1,eff:S=>{S.f.nogrant=1;},fb:'Три вечори збережено, але й шансу на гроші без повернення немає. Усе, чого бракує, доведеться позичати.'},
   {l:'Подати за один вечір: скопіювати кошторис із чужої заявки на кав’ярню й замінити назву',p:0,eff:S=>{S.trust-=8;S.f.copy=1;},fb:'Комісія читає десятки заявок і чужий кошторис упізнала одразу. Відмова — і неприємний лист на адресу школи.'}]},
  {id:'gbudget',t:'plan',when:S=>!!S.f.grant,head:'Тиждень 4 · Кошторис гранту',text:'Ти просиш 4 000 грн. У правилах конкурсу написано: грант дають на обладнання й матеріали; на рекламу можна спрямувати не більш як 20 % гранту; статті «інше» та «непередбачені витрати» комісія не фінансує.',q:'Як ти розпишеш 4 000 грн у кошторисі?',
   fields:[{k:'press',label:'Обладнання: частина вартості преса'},{k:'mat',label:'Матеріали'},{k:'adv',label:'Реклама'},{k:'oth',label:'Інше, непередбачені витрати'}],
   total:S=>4000,
   best:S=>({press:3000,mat:1000,adv:0,oth:0}),
   score:(S,v)=>v.oth===0&&v.adv<=800?{p:2,fb:'Кожна гривня прив’язана до дозволеної статті. Такий кошторис комісії нема за що скоротити.'}:v.oth===0?{p:1,fb:'На рекламу закладено '+PG(v.adv)+' — більше, ніж 20 % гранту (800 грн). Перевищення комісія викреслить.'}:v.oth<=1000?{p:1,fb:'Статтю «інше» комісія не фінансує: якщо грант і дадуть, то без цих '+PG(v.oth)+'.'}:{p:0,fb:'Велика частина грошей — без призначення. Для комісії це означає, що заявник не знає, на що їх витратить: цю частину викреслять.'},
   eff:(S,v)=>{S.gr=Math.max(0,Math.floor((4000-v.oth-Math.max(0,v.adv-800))/100)*100);S.f.cut=S.gr<4000?1:0;}},
  {id:'crowd',t:'choice',head:'Тиждень 4 · Краудфандинг',text:'Данило показує краудфандингову платформу: люди скидаються на проєкти, які їм подобаються. Правила за умовою задачі: якщо за три тижні мету не зібрано, усі внески повертаються жертводавцям; із зібраного платформа бере 10 %; кожному, хто підтримав, автор надсилає обіцяну винагороду.',q:'Чи запускатимеш ти збір?',o:[
   {l:'Мета 4 000 грн, винагорода за внесок — шопер із принтом «Відбитка» (собівартість 80 грн)',p:2,eff:S=>{S.cr=2400;S.trust+=5;S.f.crowd=1;},fb:'Скромну мету реально зібрати зі знайомих, батьків і випускників. А кожен шопер-винагорода — ще й реклама, яку носитимуть містом.'},
   {l:'Мета 15 000 грн — щоб вистачило напевно; винагорода — худі',p:0,eff:S=>{S.trust-=5;S.f.crfail=1;},fb:'Зібрати 15 000 грн у людей, які про тебе ще не чули, — задача не на три тижні. А якщо мети не досягнуто, автор не отримує нічого.'},
   {l:'Не запускати: знімати відео й розсилати шопери — забагато клопоту',p:1,eff:S=>{S.f.nocrowd=1;},fb:'Клопоту справді чимало. Але це гроші без відсотків, а заодно — перші люди, які знають про «Відбиток».'}]},
  {id:'crowdc',t:'calc',head:'Тиждень 4 · Скільки дасть збір',text:S=>(S.f.crowd?'Порахуй, скільки ти отримаєш, якщо збір досягне мети.':'Порахуй, скільки дав би скромний збір.')+' Мета — 4 000 грн. Її складають 15 внесків, і кожному жертводавцеві треба надіслати шопер собівартістю 80 грн. Платформа бере 10 % зібраної суми.',q:'Скільки гривень лишиться на справу?',ans:S=>2400,unit:'грн',hint:'Від 4 000 грн відніми комісію платформи (10 %) і вартість 15 шоперів.',sol:S=>'Комісія: 4 000 × 10 : 100 = 400 грн. Винагороди: 15 × 80 = 1 200 грн. 4 000 − 400 − 1 200 = 2 400 грн. Краудфандинг — не подарунок: його ціна — комісія, винагороди і твій час.'},
  {id:'prep',t:'choice',head:'Тиждень 5 · Про запас',text:S=>(S.f.grant||S.f.crowd?'Результати '+(S.f.grant&&S.f.crowd?'гранту й збору':S.f.grant?'гранту':'збору')+' стануть відомі на сьомому тижні. ':'До купівлі преса лишилося три тижні. ')+'Якщо грошей не вистачить, решту доведеться позичати. Кредит неповнолітнім не дають, тож позичальницею буде мама — вона підприємниця. За умовою задачі: банк — 24 % річних; потрібні паспорт, довідка про доходи й добра кредитна історія, розгляд — до двох тижнів. Програма пільгових кредитів для малого бізнесу — 7 % річних; документи ті самі плюс опис проєкту. Кредитна спілка — лише для своїх членів, 30 % річних, зате рішення за три дні.',q:'Як ти підготуєшся?',o:[
   {l:'Уже зараз разом із мамою зібрати документи й подати заявку на пільговий кредит — про всяк випадок',p:2,eff:S=>{S.f.docs=1;},fb:'Якщо грошей вистачить, від кредиту можна відмовитися. Якщо ні — найдешевша позика буде готова саме тоді, коли знадобиться.'},
   {l:'Вступити разом із мамою до кредитної спілки: там рішення за три дні',p:1,eff:S=>{S.f.union=1;},fb:'Запасний варіант є, і він швидкий. Але 30 % річних — учетверо більше, ніж за пільговою програмою.'},
   {l:'Нічого не готувати: якщо забракне, є «гроші за 15 хвилин» без жодних довідок',p:0,eff:S=>{S.f.noprep=1;},fb:'Там, де не питають довідок, питають відсотки. На сьомому тижні вибирати доведеться між дорогим і дуже дорогим.'}]},
  {id:'fast',t:'calc',head:'Тиждень 6 · «Усього 1 % на день»',text:S=>'На зупинці висить оголошення фінансової компанії: «Гроші за 15 хвилин! Без довідок і поручителів. Усього 1 % на день». Перевір, що означає це «усього». Зараз у тебе '+PG(S.got)+', до 22 000 грн бракує '+PG(22000-S.got)+'. Припустімо, усю цю суму взято там на 90 днів і повертається вона разом із відсотками в кінці строку.',q:'Скільки гривень довелося б повернути?',ans:S=>(22000-S.got)*19/10,unit:'грн',hint:'1 % від суми позики — це плата за один день. Помнож її на 90 днів і додай саму позику.',sol:S=>{const g=22000-S.got;return'За день: '+PN(g)+' × 1 : 100 = '+PG(g/100)+'. За 90 днів: '+PN(g/100)+' × 90 = '+PG(g*9/10)+'. Повернути: '+PN(g)+' + '+PN(g*9/10)+' = '+PG(g*19/10)+'. «Усього 1 % на день» — це 90 % за три місяці, майже подвійна сума. Для порівняння: 24 % річних за той самий строк — приблизно 6 %.';}},
  {id:'press',t:'choice',head:'Тиждень 6 · Який прес',text:S=>'Час обирати прес. Напевно є '+PG(S.got)+(S.f.grant||S.f.crowd?'; чи додадуться '+(S.f.grant&&S.f.crowd?'грант і збір':S.f.grant?'гроші гранту':'гроші збору')+', ще невідомо':'')+'. Звичайний новий прес коштує 14 000 грн. Енергоощадний — 16 000 грн, але в цій історії діє програма енергоощадності: за умовою задачі вона повертає 20 % ціни такого обладнання — після купівлі, за чеком і заявкою. Лізинг: звичайний прес за внесок 2 800 грн і 12 щомісячних платежів по 1 050 грн; до останнього платежу прес належить лізинговій компанії. Вживаний прес з оголошення — 8 000 грн: продавець в іншому місті, перевірити в роботі не можна, гарантії немає.',q:'Який варіант ти обереш?',o:[
   {l:'Енергоощадний за 16 000 грн і подати заявку на повернення 20 %',p:2,eff:S=>{S.need=24000;S.f.eco=1;S.tot=S.got+S.gr+S.cr;S.gap=Math.max(0,S.need-S.tot);},fb:'Зараз потрібно на 2 000 грн більше, зате 20 % від 16 000 — це 3 200 грн, які повернуться: прес обійдеться в 12 800 грн і щомісяця заощаджуватиме близько 100 грн на електроенергії.'},
   {l:'Звичайний новий за 14 000 грн',p:1,eff:S=>{S.need=22000;S.tot=S.got+S.gr+S.cr;S.gap=Math.max(0,S.need-S.tot);},fb:'Надійний вибір за початковим кошторисом. Але енергоощадний прес після повернення 20 % коштував би 12 800 грн — на 1 200 грн менше.'},
   {l:'Звичайний у лізинг: 2 800 грн зараз і 12 платежів по 1 050 грн',p:1,eff:S=>{S.need=10800;S.debt+=12600;S.dl=12600;S.over+=1400;S.f.lease=1;S.tot=S.got+S.gr+S.cr;S.gap=Math.max(0,S.need-S.tot);},fb:'Зараз потрібно лише 10 800 грн замість 22 000, і старт не залежить від гранту чи збору. Ціна спокою: 2 800 + 12 × 1 050 = 15 400 грн за прес замість 14 000, і рік він буде не твій.'},
   {l:'Вживаний за 8 000 грн: економія 6 000 грн одразу',p:0,eff:S=>{S.need=16000;S.f.used=1;S.tot=S.got+S.gr+S.cr;S.gap=Math.max(0,S.need-S.tot);},fb:'Зібрати треба на 6 000 грн менше. Але прес куплено наосліп: без перевірки й гарантії будь-яка поломка — твій клопіт і твої гроші.'}]},
  {id:'w7',t:'event',head:'Тиждень 7 · Результати',text:S=>(S.f.grant?(S.gr>=4000?'Комісія конкурсу дала грант повністю — 4 000 грн. ':S.gr>0?'Комісія конкурсу дала грант, але урізаний: '+PG(S.gr)+' із 4 000 — статті, що не відповідали правилам, викреслено. ':'Комісія відхилила заявку на грант: кошторис не відповідав правилам конкурсу. '):S.f.copy?'Заявку на грант відхилено через чужий кошторис. ':'Заявки на грант не було. ')+(S.f.crowd?'Збір закрито успішно: після комісії та винагород лишається 2 400 грн.':S.f.crfail?'Збір зупинився на 5 200 грн із 15 000: мети не досягнуто, усі внески повернулися людям, а три тижні пішли намарно.':'Збору не було.')+' Прес треба купувати вже наступного тижня — час підбити суму.'},
  {id:'sum7',t:'calc',head:'Тиждень 7 · Скільки зібрано',text:S=>'Склади все, що є. Власні кошти'+(S.first>0?' разом із першим заробітком':'')+' — '+PG(S.own)+'. '+(S.f.share?'Внесок Данила':'Мамина позика')+' — '+PG(S.fam)+'. Грант — '+PG(S.gr)+'. Краудфандинг — '+PG(S.cr)+'. На старт із обраним пресом потрібно '+PG(S.need)+'.',q:'Скільки гривень зібрано разом?',ans:S=>S.tot,unit:'грн',hint:'Додай усі джерела. Нулі теж рахуються — це джерела, які нічого не дали.',sol:S=>PN(S.own)+' + '+PN(S.fam)+' + '+PN(S.gr)+' + '+PN(S.cr)+' = '+PG(S.tot)+'. Потрібно '+PG(S.need)+': '+(S.gap>0?'бракує '+PG(S.gap)+'.':S.tot>S.need?'це на '+PG(S.tot-S.need)+' більше, ніж треба.':'рівно стільки, скільки треба.'),eff:S=>{S.got=S.tot;}},
  {id:'loan',t:'choice',when:S=>S.gap>0,head:'Тиждень 7 · Де позичити решту',text:S=>'Бракує '+PG(S.gap)+'. '+(S.f.docs?'Пільговий кредит мамі схвалили: 7 % річних на 12 місяців. Банк теж дасть гроші — під 24 % річних, зате вже завтра.':S.f.union?'Кредитна спілка видасть гроші за три дні: 30 % річних на 12 місяців. Для банку документи ще треба зібрати — це два тижні.':'Готових документів немає ні для банку, ні для пільгової програми; зібрати їх для банку — два тижні.')+' Фінансова компанія дає позику під 1 % на день на 90 днів. Ломбард дає під заставу ноутбука й планшета щонайбільше 5 000 грн: 10 % на місяць, викупити треба через 3 місяці. За умовою задачі відсотки всюди рахуємо просто — від усієї суми позики за весь строк.',q:'Де взяти решту?',o:[
   {l:'Пільговий кредит: 7 % річних на 12 місяців',when:S=>!!S.f.docs,p:2,eff:S=>{S.lg=S.gap;S.lk=7;S.debt+=S.gap*107/100;S.over+=S.gap*7/100;S.got+=S.gap;S.f.loan='soft';},fb:'Найдешевша позика з усіх можливих — і вона готова вчасно, бо документи зібрано заздалегідь.'},
   {l:'Банківський кредит: 24 % річних на 12 місяців, зате гроші вже завтра',when:S=>!!S.f.docs,p:1,eff:S=>{S.lg=S.gap;S.lk=24;S.debt+=S.gap*124/100;S.over+=S.gap*24/100;S.got+=S.gap;S.f.loan='bank';},fb:'Гроші прийшли на кілька днів раніше, але поспіху не було: прес купувати лише наступного тижня. А переплата — більш ніж утричі вища, ніж за пільговою програмою.'},
   {l:'Позика кредитної спілки: 30 % річних на 12 місяців',when:S=>!S.f.docs&&!!S.f.union,p:2,eff:S=>{S.lg=S.gap;S.lk=30;S.debt+=S.gap*130/100;S.over+=S.gap*30/100;S.got+=S.gap;S.f.loan='union';},fb:'З того, що тобі зараз доступно, це найрозумніше: старт буде вчасно. Але пільгова програма коштувала б учетверо менше — якби документи були готові.'},
   {l:'Попросити маму терміново зібрати документи для банку: 24 % річних, але старт зсунеться на два тижні',when:S=>!S.f.docs,p:S=>S.f.union?1:2,eff:S=>{S.lg=S.gap;S.lk=24;S.debt+=S.gap*124/100;S.over+=S.gap*24/100;S.got+=S.gap;S.trust-=5;S.f.loan='bank';S.f.delay=1;},fb:S=>S.f.union?'Відсотків трохи менше, ніж у спілці, але два тижні сезону втрачено: частина класів замовить худі деінде.':'Два тижні сезону втрачено, і частина класів замовить худі деінде. Та це дешевше, ніж швидкі гроші: запізнілий старт можна надолужити, а борг під 90 % — ні.'},
   {l:'Фінансова компанія: 1 % на день на 90 днів, без довідок',p:0,eff:S=>{S.lg=S.gap;S.lk=90;S.debt+=S.gap*190/100;S.over+=S.gap*90/100;S.got+=S.gap;S.f.loan='fast';},fb:'Гроші за 15 хвилин — і майже подвійна сума до повернення через три місяці. Саме тоді, коли справа ще тільки вчиться заробляти.'},
   {l:'Ломбард: закласти ноутбук і планшет, 10 % на місяць на 3 місяці',when:S=>S.gap<=5000,p:S=>!S.f.docs&&!S.f.union?1:0,eff:S=>{S.lp=S.gap;S.debt+=S.gap*130/100;S.over+=S.gap*30/100;S.got+=S.gap;S.trust-=2;S.f.loan='pawn';},fb:'За три місяці набіжить 30 %, і весь цей час ти без ноутбука, на якому малюються макети. Не викупиш вчасно — техніку продадуть.'},
   {l:S=>'Ломбард і фінансова компанія разом: 5 000 грн під заставу техніки, решту — '+PG(S.gap-5000)+' — під 1 % на день',when:S=>S.gap>5000,p:0,eff:S=>{S.lp=5000;S.lg=S.gap-5000;S.lk=90;S.debt+=6500+S.lg*190/100;S.over+=1500+S.lg*90/100;S.got+=S.gap;S.trust-=2;S.f.loan='fast';S.f.pawn2=1;},fb:'Два дорогі борги замість одного: техніка в заставі, а швидка позика майже подвоюється за три місяці. І обидва треба закрити водночас.'}]},
  {id:'nol',t:'choice',when:S=>S.gap<=0,head:'Тиждень 7 · Грошей вистачає',text:S=>'Зібраного вистачає без нових позик'+(S.tot>S.need?', і ще '+PG(S.tot-S.need)+' лишається':'')+'. '+(S.f.docs?'Мамі схвалили пільговий кредит, але він тепер не потрібен. ':'')+(S.f.lease&&S.tot>S.need?'Договір лізингу вже підписано, тож надлишок його платежів не скасовує. ':'')+'А на мамин телефон приходить SMS від фінансової компанії: «Вам попередньо схвалено 5 000 грн на 90 днів!»',q:'Що ти зробиш?',o:[
   {l:S=>'Нічого не позичати'+(S.dm&&S.tot-S.need>=4000?', мамі одразу повернути її 4 000 грн'+(S.tot-S.need>4000?', а решту тримати як резерв':''):S.tot>S.need?', а надлишок тримати як резерв на несподіване':', а резерв почати збирати з першого ж прибутку')+(S.f.docs?'; від кредиту відмовитися':''),p:2,eff:S=>{S.f.reserve=1;if(S.dm&&S.tot-S.need>=4000){S.debt-=4000;S.got-=4000;S.dm=0;S.f.mom=0;S.f.vague=0;S.f.back=1;S.trust+=3;}},fb:S=>'Найдешевший кредит — той, якого не брали. '+(S.f.back||(S.dm&&S.tot-S.need>=4000)?'А зайвий борг краще закрити одразу: мама отримала свої гроші раніше, ніж чекала.':'А резерв рятує, коли щось іде не за планом.')},
   {l:S=>S.tot>S.need?'Витратити все, що понад план ('+PG(S.tot-S.need)+'), на великий банер, фірмові наліпки й матеріали «на виріст»':'Нічого не позичати, а про резерв подумати колись потім',p:1,eff:S=>{S.got=S.need;S.f.spent=1;},fb:S=>S.tot>S.need?'Усе вкладено в справу, але запасу на несподіване тепер немає зовсім'+(S.dm?', а мамин борг лишився':'')+'.':'Боргів не додалося. Але без резерву перша ж несподіванка змусить позичати поспіхом.'},
   {l:'Умовити маму взяти ці 5 000 грн під 1 % на день: зайвих грошей на старті не буває',p:0,eff:S=>{S.dx=9500;S.debt+=9500;S.over+=4500;S.got+=5000;S.f.extra=1;},fb:'Грошей, які не були потрібні, стало на 5 000 більше, а боргу — на 9 500. Позичати «про запас» під 90 % за три місяці — найдорожчий спосіб почуватися спокійно.'}]},
  {id:'repay',t:'calc',head:'Тиждень 7 · Скільки повертати',text:S=>{const pr=S.f.eco?2200:2100;return S.debt>0?'Збери докупи всі борги. '+(S.dm?'Мамі — 4 000 грн без відсотків. ':'')+(S.dl?'Лізинговій компанії — 12 платежів по 1 050 грн. ':'')+(S.lp?'Ломбарду — '+PG(S.lp)+' і ще 30 % від цієї суми за три місяці. ':'')+(S.lg?(S.lk===90?'Фінансовій компанії':'За кредитом')+' — '+PG(S.lg)+' і ще '+S.lk+' % від цієї суми за весь строк. ':'')+(S.dx?'Швидка позика 5 000 грн на 90 днів під 1 % на день. ':''):S.f.share?'Боргів у тебе немає, але Данило отримуватиме 25 % прибутку. За планом «Відбиток» дає '+PG(pr)+' прибутку щомісяця.':'Боргів у тебе не лишилося: мамині 4 000 грн уже повернуто. Порівняй: якби ті самі 4 000 грн довелося взяти у фінансовій компанії на 90 днів під 1 % на день.';},q:S=>S.debt>0?'Скільки гривень усього доведеться повернути?':S.f.share?'Скільки гривень отримає Данило за рік?':'Скільки гривень довелося б повернути фінансовій компанії?',ans:S=>S.debt>0?S.debt:S.f.share?(S.f.eco?6600:6300):7600,unit:'грн',hint:S=>S.debt>0?'Порахуй кожен борг окремо — разом із відсотками, якщо вони є, — і склади.':S.f.share?'Знайди 25 % від місячного прибутку й помнож на 12.':'1 % від 4 000 грн — плата за день. Помнож на 90 і додай саму позику.',sol:S=>{const pr=S.f.eco?2200:2100;if(!(S.debt>0)&&!S.f.share)return'За день: 4 000 × 1 : 100 = 40 грн. За 90 днів: 40 × 90 = 3 600 грн. Повернути: 4 000 + 3 600 = 7 600 грн. Мамина позика не коштувала тобі нічого — крім дотриманого слова.';if(!(S.debt>0))return'25 % від '+PN(pr)+' грн — це '+PG(pr/4)+' на місяць. За рік: '+PN(pr/4)+' × 12 = '+PG(pr*3)+'. Данило вклав 3 000 грн і вже за перший рік отримає більш ніж удвічі більше. Частка в прибутку — теж ціна грошей, просто вона не називається відсотками.';const a=[];if(S.dm)a.push('мамі — 4 000 грн');if(S.dl)a.push('лізинг: 12 × 1 050 = 12 600 грн');if(S.lp)a.push('ломбард: '+PN(S.lp)+' + '+PN(S.lp)+' × 30 : 100 = '+PG(S.lp*130/100));if(S.lg)a.push((S.lk===90?'фінансова компанія':'кредит')+': '+PN(S.lg)+' + '+PN(S.lg)+' × '+S.lk+' : 100 = '+PG(S.lg*(100+S.lk)/100));if(S.dx)a.push('швидка позика: 5 000 + 50 × 90 = 9 500 грн');return'Рахуємо кожен борг: '+a.join('; ')+'. Разом до повернення: '+PG(S.debt)+'. Із них '+(S.over>0?PG(S.over)+' — плата за користування чужими грошима.':'0 грн — плата за користування чужими грошима: усі позики були без відсотків.');}},
  {id:'w8',t:'event',head:'Тиждень 8 · Старт',text:S=>(S.f.delay?'Кредит надійшов із запізненням на два тижні, і лише тепер прес стоїть у майстерні. Два класи за цей час замовили худі у друкарні. ':'Прес стоїть у майстерні, матеріали закуплено, афіші висять. ')+(S.f.used?'Вживаний прес пропрацював чотири дні й перестав грітися. Гарантії немає: ремонт коштував 3 000 грн, а замовлення тиждень стояли. ':S.f.eco?'Заявку на повернення 20 % за енергоощадний прес подано разом із чеком: за умовою задачі 3 200 грн надійдуть за місяць. ':S.f.lease?'На пресі наліпка лізингової компанії: рік він належить їй, а не тобі. ':'')+'«Відбиток» відкрито. Тепер у тебе є не лише гроші, а й зобов’язання перед усіма, хто їх дав.',eff:S=>{if(S.f.used&&!S.f.broke){S.f.broke=1;S.rep=3000;S.trust=Math.max(0,S.trust-6);}}},
  {id:'oblig',t:'choice',head:'Тиждень 8 · Зобов’язання',text:S=>{const a=[];if(S.gr>0)a.push('звіт із чеками за грант — до кінця місяця');if(S.f.crowd)a.push('15 шоперів-винагород жертводавцям — до обіцяної дати');if(S.f.mom)a.push('мамі — по 1 000 грн щомісяця за графіком');if(S.f.vague)a.push('мамині 4 000 грн, про строк яких ви так і не домовилися');if(S.f.share)a.push('Данилові — чверть прибутку й чесні цифри щомісяця');if(S.dl)a.push('лізинговий платіж 1 050 грн щомісяця');if(S.lp)a.push('викуп техніки з ломбарду через три місяці');if(S.lg)a.push(S.lk===90?'борг фінансовій компанії — через 90 днів':'повернення кредиту');if(S.dx)a.push('швидка позика — 9 500 грн через 90 днів');a.push('клієнтам — замовлення в обіцяний строк');return'Ось твої зобов’язання: '+a.join('; ')+'. Водночас пішли перші платні замовлення. Данило радить: «Спершу заробимо, а решта почекає».';},q:'Як ти вчиниш?',o:[
   {l:'Скласти календар зобов’язань із датами й сумами, відкладати на платежі з кожного замовлення, а обіцяне людям робити першим',p:2,eff:S=>{S.trust+=10;S.f.cal=1;},fb:'Усі, хто дав тобі гроші, отримали своє вчасно. Наступного разу вони дадуть знову — і порадять тебе іншим.'},
   {l:'Виконувати лише те, де за прострочення є штраф, а решту відкласти до спокійніших часів',p:1,eff:S=>{S.trust=Math.max(0,S.trust-5);S.f.part=1;},fb:'Штрафів немає. Але обіцянка без штрафу — теж обіцянка: ті, хто повірив тобі на слово, чекають найдовше.'},
   {l:'Послухати Данила: спершу платні замовлення, усе інше — коли розгребемося',p:0,eff:S=>{S.trust=Math.max(0,S.trust-15);S.f.late=1;},fb:S=>{const a=[];if(S.gr>0)a.push('звіт за грант подано запізно');if(S.f.crowd)a.push('жертводавці не дочекалися шоперів');if(S.dm)a.push('мама досі чекає на свої гроші');if(S.f.share)a.push('Данило не бачить ні цифр, ні своєї частки');if(S.dl||S.lg||S.lp||S.dx)a.push('платіж за боргом пропущено');return'Замовлення зроблено, а обіцянки — ні'+(a.length?': '+a.join(', '):'')+'. Кожна порушена обіцянка — це зачинені двері наступного разу.';}}]},
  {id:'payback',t:'calc',head:'Тиждень 8 · Коли справа окупиться',text:S=>{const p=(2100+(S.f.eco?100:0))*(S.f.share?0.75:1);return'«Відбиток» продає 40 худі на місяць і заробляє 210 грн на кожному. Постійні витрати — '+PG(S.f.eco?6200:6300)+' на місяць'+(S.f.eco?' (енергоощадний прес зменшив рахунок за світло на 100 грн)':'')+'. '+(S.f.share?'Прибуток — '+PG(p/0.75)+' на місяць, чверть отримує Данило, тож тобі лишається '+PG(p)+'. ':'Отже, прибуток — '+PG(p)+' на місяць. ')+'Із нього треба повернути: власні 9 000 грн'+(S.debt>0?', борги — '+PG(S.debt):'')+(S.f.broke?', витрати на ремонт — 3 000 грн':'')+'.'+(S.f.eco?' Повернення 3 200 грн за енергоощадний прес зменшує цю суму.':'');},q:'За скільки місяців справа окупиться? Неповний місяць рахуй як цілий.',ans:S=>Math.ceil((9000+S.debt+(S.f.broke?3000:0)-(S.f.eco?3200:0))/((2100+(S.f.eco?100:0))*(S.f.share?0.75:1))),unit:'міс.',hint:'Спершу знайди суму, яку треба повернути. Потім поділи її на прибуток за місяць і округли вгору.',sol:S=>{const A=9000+S.debt+(S.f.broke?3000:0)-(S.f.eco?3200:0),p=(2100+(S.f.eco?100:0))*(S.f.share?0.75:1),m=Math.ceil(A/p);return'Повернути: 9 000'+(S.debt>0?' + '+PN(S.debt):'')+(S.f.broke?' + 3 000':'')+(S.f.eco?' − 3 200':'')+' = '+PG(A)+'. '+PN(A)+' : '+PN(p)+(A%p===0?' = '+m+'. ':' — це більше ніж '+(m-1)+', але менше ніж '+m+'; неповний місяць рахуємо як цілий. ')+'Отже, '+PL(m,'місяць','місяці','місяців')+'. '+(m<=7?'Справа швидко поверне все вкладене: дешеві гроші окуповуються швидко.':m<=12?'До року роботи лише на повернення грошей: кожна зайва гривня відсотків відсуває цей день.':'Понад рік справа працюватиме лише на повернення грошей: що більше боргів і відсотків, то довший цей шлях.');}}],
 finish:S=>{const ov=S.over+(S.rep||0),lvl=ov<=1500&&S.trust>=60&&!S.f.share&&!S.f.delay?2:ov<=4500&&S.trust>=40?1:0;return{level:lvl,title:['Старт відбувся, але надто дорогою ціною','«Відбиток» стартував із важким рюкзаком','«Відбиток» стартував на дешевих грошах'][lvl],text:'Зібрано '+PG(S.got)+' за потреби '+PG(S.need)+'. Борг до повернення — '+PG(S.debt)+'. '+(S.rep&&S.over>0?'Переплата за чужі гроші та ремонт преса':S.rep?'Втрати на ремонті преса':'Переплата за чужі гроші')+' — '+PG(ov)+'. Довіра тих, хто дав гроші, — '+PL(S.trust,'бал','бали','балів')+'.'+(lvl===2?'':ov>4500&&S.trust<40?' Гроші обійшлися задорого, і довіру теж розгублено.':ov>4500?' Гроші обійшлися задорого: переплата з’їсть не один місяць прибутку.':S.trust<40?' Гроші були недорогі, але люди, які їх дали, вже не певні, що тобі варто довіряти.':ov>1500&&S.over<=1500?' Самі гроші були недорогі, але ремонт преса без гарантії з’їв заощаджене.':ov>1500?' Гроші обійшлися дорожче, ніж могли б.':S.trust<60?' Грошей зібрано недорого, але довіру тих, хто їх дав, ще треба зміцнити.':S.f.share?' Боргів небагато, але чверть прибутку щомісяця йтиме Данилові — це теж ціна грошей, і вона не має строку.':' Гроші недорогі, але через неготові документи старт запізнився на два тижні сезону.'),tips:[
   S.f.first==='a'?'Передоплата й орендований прес дали перший заробіток ще до купівлі обладнання: почати можна й без великих грошей.':'Перше замовлення могло принести 3 400 грн без жодного боргу. Наступного разу бери передоплату й орендуй те, чого ще не маєш.',
   S.f.loan==='fast'||S.f.extra?'Швидка позика під 1 % на день майже подвоїла борг. Дешеві гроші потребують підготовки заздалегідь — документів і часу.':S.f.loan==='pawn'?'Ломбард забрав і гроші, і робочий ноутбук. Готуй документи для дешевшого кредиту до того, як гроші знадобляться.':S.gr>0||S.f.crowd?'Грант і краудфандинг дають гроші, яких не треба повертати, — ціною заявки, звіту й винагород.':'Без гранту й краудфандингу майже все, чого бракувало, довелося позичати. Наступного разу спробуй джерела, які не треба повертати.',
   S.f.late||S.f.vague?'Гроші близьких і грантодавців — це теж зобов’язання. Записуй строки й виконуй їх першими: довіра — джерело, яке відкриється ще не раз.':S.f.used?'Дешевий прес без гарантії коштував ремонту й тижня простою. Порівнюй не ціну купівлі, а повну вартість.':S.f.eco?'Програма з цієї історії зробила кращий прес дешевшим за звичайний. Справжні програми підтримки та їхні умови шукай на офіційних сайтах держави й громади.':'Перед великою купівлею перевір на офіційних сайтах держави й громади, чи немає програм підтримки: їхні умови змінюються.']};},
 terms:[['Стартовий капітал','гроші, потрібні, щоб розпочати справу: на обладнання, матеріали, рекламу'],['Грант','гроші на проєкт, які не повертають, але за які звітують'],['Краудфандинг','збирання невеликих внесків від багатьох людей на спеціальній платформі'],['Лізинг','довгострокова оренда обладнання з правом викупу: платиш частинами, а користуєшся одразу'],['Переплата за кредитом','сума, яку позичальник віддає понад позичене: відсотки й комісії']]});

PFG_TOPICS.push((()=>{
 const mar=S=>S.P-S.vc;
 const bep=(F,m)=>Math.ceil(F/m);
 const HD=n=>PN(n)+' худі';
 const repf=S=>S.rep>=50?1:S.rep>=30?0.9:0.8; // репутація → грудневий попит
 const dem=(S,k)=>k===1?S.d:k===2?S.d*1.25:Math.round(S.d*1.5*repf(S));
 /* місяць k: D — попит, pl — графік, miss — не встигли, rush — докуплено терміново (+60 грн), ret — повернення */
 const mo=(S,k)=>{const D=dem(S,k),pl=S['v'+k],miss=k===3&&S.f.grump?Math.min(5,D):0,q=D-miss,rush=Math.max(0,q-pl),ret=S.f.cheap&&k>1?Math.round(q/5):0;return{D,pl,miss,q,rush,ret,pr:q*mar(S)-60*rush-(k===3?fDec(S):6300)-ret*S.P};};
 const fDec=S=>S.F+((S.f.audit||S.f.press)?(S.f.mon===2?0:S.f.mon===1?270:540):0);
 const money=(S,x)=>{if(x>0&&S.debt>0){const r=Math.min(S.debt,x);S.debt-=r;x-=r;}S.cash+=x;if(S.cash<0){S.debt-=S.cash;S.cash=0;}};
 const rep=(S,x)=>{S.rep=Math.max(0,Math.min(100,S.rep+x));};
 const drep=r=>{const bad=r.rush+r.miss;return bad===0?5:bad>r.D*0.2?-15:-5;};
 const note=(S,x)=>x<0&&S.cash+x<0?' У касі забракло '+PG(-(S.cash+x))+' — їх довелося позичити в батьків Марка.':x>0&&S.debt>0?(x>=S.debt?' З цих грошей повернуто весь борг батькам Марка — '+PG(S.debt)+'.':' Увесь цей прибуток пішов на борг батькам Марка; ще лишилося '+PG(S.debt-x)+'.'):'';
 const pl=x=>x>=0?'прибуток '+PG(x):'збиток '+PG(-x);
 const fit=r=>r.rush>0?' У графіку було лише '+r.pl+': заготовки ще на '+HD(r.rush)+' довелося докупити терміново. Доплата: 60 × '+r.rush+' = '+PG(60*r.rush)+', і ці замовлення запізнилися на тиждень.':r.pl>r.q?' У графіку було '+r.pl+': зайві заготовки ('+(r.pl-r.q)+' шт.) постачальник забрав назад.':' Стільки ж було й у графіку.';
 const chat=r=>drep(r)>0?' Усі отримали худі вчасно: репутація зросла на 5 балів.':' Про зірвані строки написали в шкільних чатах: репутація впала на '+(-drep(r))+' балів.';
 const fc=S=>[S.d,S.d*1.25,S.d*1.5];
 const pscore=(S,v)=>{const D=fc(S),miss=D.reduce((s,x,i)=>s+Math.max(0,x-v['v'+(i+1)]),0);return{miss,D,p:miss<=2?2:miss<=S.d*0.4?1:0};};
 const gap=S=>Math.max(0,S.d*1.25-S.v2)+Math.max(0,S.d*1.5-S.v3);
 const net=S=>S.prof-(S.f.paid?4500:0); // прибуток після виплат
 const deal=S=>net(S)>=6000&&S.f.bp===2&&S.f.sum===2&&S.debt===0&&S.rep>=60?2:net(S)>0&&S.f.sum!==0&&S.f.bp>=1?1:0;
 return {id:'9-4',sec:'9a',title:'Управління фінансами в бізнесі. Формуємо бізнес-план',minutes:30,
 intro:'Ти, Соля й Марко — команда «Відбитка», учнівської майстерні, що друкує принти на худі для класів і шкільних команд. За три місяці ти встановиш ціну, складеш графік виробництва, порахуєш маржу, точку беззбитковості й прибуток, а в грудні покажеш бізнес-план партнерці. Від ціни й графіка залежать продажі, репутація й каса, а від них — її відповідь.',
 init:()=>({P:650,d:40,vc:440,F:6300,cash:5000,debt:0,sold:0,rep:60,v1:0,v2:0,v3:0,q1:0,q2:0,q3:0,r1:0,rush:0,pr1:0,pr2:0,pr3:0,prof:0,rev:0,f:{}}),
 meters:[{k:'cash',label:'Каса',unit:'грн'},{k:'sold',label:'Продано худі',unit:'шт.'},{k:'F',label:'Постійні витрати на місяць',unit:'грн'},{k:'rep',label:'Репутація серед замовників (0–100)',unit:'балів'}],
 steps:[
  {id:'vc',t:'calc',head:'Вересень · Собівартість',text:'До старту сезону місяць. Спершу треба знати, у що обходиться одне худі. Марко виписав із чеків: заготовка худі — 340 грн, термоплівка й фарба — 55 грн, пакування з биркою — 25 грн, доставка замовникові — 20 грн. Немає замовлень — немає й цих витрат.',q:'Скільки гривень змінних витрат припадає на одне худі?',ans:S=>440,unit:'грн',hint:'Склади всі чотири суми.',sol:S=>'340 + 55 + 25 + 20 = 440 грн. Це змінні витрати: вони зростають разом із кількістю худі.'},
  {id:'fix',t:'calc',head:'Вересень · Постійні витрати',text:'Інші витрати доводиться платити щомісяця, хоч би скільки худі ви надрукували: оренда кутка в шкільній майстерні — 2 500 грн, електроенергія — 2 000 грн, обслуговування термопреса — 700 грн, реклама в соцмережах — 700 грн, інтернет і зв’язок — 400 грн.',q:'Скільки гривень становлять постійні витрати майстерні за місяць?',ans:S=>6300,unit:'грн',hint:'Склади п’ять щомісячних сум. Заготовки сюди не входять.',sol:S=>'2 500 + 2 000 + 700 + 700 + 400 = 6 300 грн. Їх доведеться заплатити, навіть якщо не буде жодного замовлення.'},
  {id:'price',t:'choice',head:'Вересень · Ціна',text:'Соля опитала старшокласників трьох шкіл: скільки худі вони замовили б у звичайний місяць за різної ціни. За 520 грн — 60 худі, за 590 грн — 48, за 650 грн — 40, за 740 грн — 24. Марко: «Ставмо 520 — заберемо всіх!» Соля: «Спершу порахуй, скільки лишається з худі після 440 грн витрат і чи покриє це 6 300 грн постійних».',q:'Яку ціну худі ти встановиш на квартал?',o:[
   {l:'650 грн',p:2,eff:S=>{S.P=650;S.d=40;},fb:'З худі лишається 210 грн. 40 худі дають 8 400 грн — на 2 100 грн більше за постійні витрати. Це найбільший запас із чотирьох варіантів.'},
   {l:'590 грн',p:1,eff:S=>{S.P=590;S.d=48;},fb:'48 худі по 150 грн маржі дають 7 200 грн — лише на 900 грн більше за постійні витрати. Роботи більше, ніж за ціни 650 грн, а лишається менше.'},
   {l:'740 грн',p:1,eff:S=>{S.P=740;S.d=24;},fb:'Маржа 300 грн — найвища, але покупців лише 24: це 7 200 грн проти 6 300 грн постійних витрат. Запас — усього 900 грн на місяць.'},
   {l:'520 грн',p:0,eff:S=>{S.P=520;S.d=60;},fb:'Покупців найбільше, але з худі лишається тільки 80 грн: 60 × 80 = 4 800 грн проти 6 300 грн постійних витрат. У звичайний місяць це збиток 1 500 грн, хоч роботи й повно.'}]},
  {id:'vol',t:'plan',head:'Вересень · Графік виробництва',text:S=>'За ціни '+S.P+' грн у звичайний місяць куплять близько '+S.d+' худі. Але попит нерівний. Жовтень — звичайний місяць. У листопаді замовлень на чверть більше (турніри, поїздки класів), у грудні — у півтора раза більше, ніж у жовтні (подарунки до свят). Постачальник заготовок просить графік на квартал: скільки худі ви друкуватимете щомісяця. Якщо замовлень буде більше, ніж у графіку, заготовки доведеться докуповувати терміново: кожна на 60 грн дорожча, а замовлення запізниться на тиждень. Зайві заготовки постачальник забере назад.',q:S=>'На квартал виходить '+HD(S.d*3.75)+'. Скільки з них ти заплануєш на кожен місяць?',
   fields:[{k:'v1',label:'Жовтень, худі'},{k:'v2',label:'Листопад, худі'},{k:'v3',label:'Грудень, худі'}],
   total:S=>S.d*3.75,
   best:S=>({v1:S.d,v2:S.d*1.25,v3:S.d*1.5}),
   check:(S,v)=>['v1','v2','v3'].some(k=>v[k]<0||v[k]!==Math.round(v[k]))?'Тут потрібна кількість худі, а не гроші. У кожному полі має бути ціле число — наприклад, 45.':null,
   eff:(S,v)=>{S.v1=v.v1;S.v2=v.v2;S.v3=v.v3;S.f.plan=pscore(S,v).p;},
   score:(S,v)=>{const r=pscore(S,v),D=r.D[0]+', '+r.D[1]+' і '+r.D[2]+' худі';return r.p===2?{p:2,fb:'Графік повторює прогноз попиту: '+D+'. Ні термінових закупівель, ні зайвих заготовок.'}:r.p===1?{p:1,fb:'Графік близький до прогнозу ('+D+'), але не повторює сезонність точно: за квартал забракне заготовок приблизно на '+HD(r.miss)+'. Їх доведеться докуповувати терміново й дорожче.'}:{p:0,fb:'Графік майже не враховує сезонність. Прогноз — '+D+', а заготовок забракне приблизно на '+HD(r.miss)+'. Кожна термінова закупівля — мінус 60 грн маржі й замовник, що чекає зайвий тиждень.'};}},
  {id:'oct',t:'event',head:'Жовтень · Перший місяць',text:S=>{const r=mo(S,1);return 'Жовтень позаду. За ціни '+S.P+' грн замовили '+HD(r.D)+'.'+fit(r)+chat(r);},eff:S=>{const r=mo(S,1);S.q1=r.q;S.r1=r.rush;S.rush+=r.rush;S.sold+=r.q;rep(S,drep(r));}},
  {id:'rev',t:'calc',head:'Жовтень · Дохід',text:S=>'За жовтень продано '+HD(S.q1)+' по '+S.P+' грн.',q:'Скільки гривень доходу отримала майстерня за жовтень?',ans:S=>S.P*S.q1,unit:'грн',hint:'Помнож ціну одного худі на кількість проданих.',sol:S=>S.P+' × '+S.q1+' = '+PG(S.P*S.q1)+'. Це дохід (виручка) — усі гроші від покупців. Заробітком він стане, коли відняти витрати.',eff:S=>{money(S,S.P*S.q1);}},
  {id:'pay',t:'choice',head:'Жовтень · Гроші в касі',text:S=>'У касі тепер '+PG(S.cash)+'. Марко сяє: «Поділімо — ми ж місяць працювали без копійки!» Але за заготовки, оренду й електроенергію за жовтень ще не заплачено.',q:'Що ти відповіси Маркові?',o:[
   {l:'Спершу віднімемо від доходу всі витрати. Ділити можна лише прибуток — зробимо це наприкінці кварталу',p:2,eff:S=>{S.f.rule=1;},fb:'Дохід — ще не заробіток: із нього ще платити за заготовки, оренду, світло. Команда знає правило й час винагороди.'},
   {l:'Виплатимо кожному по 1 500 грн уже зараз, решти має вистачити',p:0,eff:S=>{S.f.paid=1;money(S,-4500);},fb:'З каси пішло 4 500 грн, хоча ніхто ще не знає, чи був у жовтні прибуток. Можливо, роздано гроші, потрібні на оренду й заготовки.'},
   {l:'Нічого й нікому не платитимемо: усе, що надійшло, лишається в майстерні',p:1,eff:S=>{S.f.grump=1;},fb:'Каса ціла. Але Марко й Соля не почули, коли й за яким правилом отримають щось за роботу. Без винагороди довго ніхто не працюватиме.'}]},
  {id:'pr1',t:'calc',head:'Жовтень · Прибуток',text:S=>{const pr=S.q1*(S.P-440)-60*S.r1-6300;return 'Дохід жовтня — '+PG(S.P*S.q1)+'. Тепер витрати: змінні — 440 грн на кожне з '+HD(S.q1)+(S.r1?'; термінова доплата — 60 грн за кожну з '+S.r1+' докуплених заготовок':'')+'; постійні — 6 300 грн.'+(pr<0?'':'');},q:S=>S.q1*(S.P-440)-60*S.r1-6300>=0?'Який прибуток отримала майстерня за жовтень?':'Жовтень закінчився збитком. На скільки гривень витрати більші за дохід? Запиши саму суму збитку, без знака «мінус».',ans:S=>Math.abs(S.q1*(S.P-440)-60*S.r1-6300),unit:S=>S.q1*(S.P-440)-60*S.r1-6300>=0?'грн':'грн збитку',hint:S=>'Знайди змінні витрати: 440 грн × кількість худі. Додай '+(S.r1?'термінову доплату й ':'')+'постійні витрати. Потім порівняй усі витрати з доходом.',sol:S=>{const R=S.P*S.q1,V=440*S.q1,E=60*S.r1,T=V+E+6300,pr=R-T;return 'Змінні витрати: 440 × '+S.q1+' = '+PG(V)+'.'+(E?' Термінова доплата: 60 × '+S.r1+' = '+PG(E)+'.':'')+' Усі витрати: '+PN(V)+(E?' + '+PN(E):'')+' + 6 300 = '+PG(T)+'. '+(pr>=0?PN(R)+' − '+PN(T)+' = '+PG(pr)+'. ':PN(T)+' − '+PN(R)+' = '+PG(-pr)+'. ')+(pr>0?'Це прибуток — те, що майстерня справді заробила.':pr<0?'Витрати більші за дохід: це збиток, і покривати його доведеться з каси.':'Рівно нуль: майстерня покрила всі витрати, але нічого не заробила.')+(S.f.paid?(pr<4500?' А команді вже виплачено 4 500 грн — більше, ніж заробила майстерня.':' Виплати команді — 4 500 грн — менші за цей прибуток, але з’ясувати це треба було до виплати.'):'')+note(S,-T);},eff:S=>{const T=440*S.q1+60*S.r1+6300;S.pr1=S.P*S.q1-T;money(S,-T);}},
  {id:'be',t:'calc',head:'Жовтень · Точка беззбитковості',text:S=>'Соля: «А скільки худі на місяць треба продавати, щоб нічого не втрачати?» Маржею з кожного худі (ціна мінус 440 грн) майстерня покриває постійні витрати — 6 300 грн на місяць. Твоя ціна — '+S.P+' грн.'+(S.r1?' Термінові доплати не враховуй: за точного графіка їх не буде.':''),q:'Яку найменшу кількість худі треба продати за місяць, щоб не бути в збитку? Якщо виходить неціле число — округли вгору.',ans:S=>bep(6300,S.P-440),unit:'худі',hint:'Знайди маржу: ціна мінус 440 грн. Поділи на неї постійні витрати. Неціле число округли вгору.',sol:S=>{const m=S.P-440,b=bep(6300,m);return 'Маржа: '+S.P+' − 440 = '+m+' грн. 6 300 : '+m+' = '+PN(6300/m)+(6300%m?', округлюємо вгору — '+b:'')+' худі. Це точка беззбитковості. У жовтні продано '+S.q1+': '+(S.q1>b?'на '+(S.q1-b)+' більше'+(S.pr1<=0?', але прибуток з’їли термінові доплати.':S.r1?' — звідси прибуток, хоч частину його й з’їли термінові доплати.':', і кожне з них дало '+m+' грн прибутку.'):S.q1<b?'на '+(b-S.q1)+' менше — звідси й збиток.':'рівно стільки'+(S.r1?', а термінові доплати загнали місяць у мінус.':', тому результат місяця — нуль.'));}},
  {id:'replan',t:'choice',when:S=>gap(S)>2,head:'Листопад · План і факт',text:S=>'Соля кладе поруч дві колонки. Прогноз: листопад — '+HD(S.d*1.25)+', грудень — '+HD(S.d*1.5)+'. Твій графік: листопад — '+S.v2+', грудень — '+S.v3+'. Постачальник каже: до 5 листопада графік ще можна змінити.',q:'Що ти зробиш із графіком?',o:[
   {l:S=>'Переписати обидва місяці за прогнозом: '+S.d*1.25+' і '+S.d*1.5+' худі',p:2,eff:S=>{S.v2=S.d*1.25;S.v3=S.d*1.5;S.f.replan=2;},fb:'План звірено з фактом і виправлено: листопад і грудень тепер відповідають прогнозу.'},
   {l:'Додати по 10 худі до кожного місяця — про всяк випадок',p:1,eff:S=>{S.v2+=10;S.v3+=10;S.f.replan=1;},fb:S=>{const g=Math.max(0,S.d*1.25-S.v2-10)+Math.max(0,S.d*1.5-S.v3-10);return 'Тепер у графіку '+(S.v2+10)+' і '+(S.v3+10)+' худі. Але «по 10 про всяк випадок» — не розрахунок: '+(g>0?'до прогнозу однаково бракує '+HD(g)+'.':'цього разу заготовок вистачить, проте частина з них буде зайвою.');}},
   {l:'Нічого не міняти: графік погоджено, турбувати постачальника незручно',p:0,eff:S=>{S.f.replan=0;},fb:'План, який не звіряють із фактом, перестає допомагати: розрив із попитом нікуди не зник, а з ним і термінові доплати.'}]},
  {id:'sup',t:'choice',head:'Листопад · Постачальник',text:S=>'Постачальник попереджає: заготовка дорожчає на 30 грн — із 340 до 370 грн. Марко знайшов в інтернеті тонші заготовки по 320 грн. Твоя маржа зараз — '+(S.P-440)+' грн із худі.'+(S.f.plan>=1||S.f.replan===2?' Твій графік закупівель у постачальника є, і він реалістичний.':' Постачальник зауважує, що твій графік мало схожий на реальні замовлення.'),q:'Що ти зробиш із подорожчанням?',o:[
   {l:'Нагадати про графік до кінця кварталу й домовитися про стару ціну за гарантований обсяг',when:S=>S.f.plan>=1||S.f.replan===2,p:2,eff:S=>{S.f.neg=1;},fb:'Постачальникові вигідний клієнт, який купує за графіком. Ціна лишилася 340 грн, змінні витрати — 440 грн на худі.'},
   {l:'Порівняти ціни трьох постачальників і перейти до того, хто дає таку саму заготовку за 340 грн',when:S=>!(S.f.plan>=1||S.f.replan===2),p:2,eff:S=>{S.f.neg=1;},fb:'Знижки за обсяг із неточним графіком не випросиш. Але інший постачальник привозить таку саму заготовку за 340 грн. Змінні витрати лишилися 440 грн.'},
   {l:'Погодитися: 30 грн — не катастрофа',p:1,eff:S=>{S.vc=470;},fb:S=>'Змінні витрати зросли до 470 грн, маржа з худі зменшилася з '+(S.P-440)+' до '+(S.P-470)+' грн. Це мінус 30 грн із кожного худі до кінця кварталу.'},
   {l:'Перейти на тонші заготовки по 320 грн — маржа навіть зросте',p:0,eff:S=>{S.vc=420;S.f.cheap=1;},fb:S=>'Змінні витрати впали до 420 грн, маржа зросла з '+(S.P-440)+' до '+(S.P-420)+' грн. Але тканина тонша, і принт на ній тримається гірше.'}]},
  {id:'nov',t:'event',head:'Листопад · Підсумок місяця',text:S=>{const r=mo(S,2);return 'Листопад. Замовили '+HD(r.D)+'.'+fit(r)+chat(r)+(S.vc===470?' Заготовки вже по 370 грн, тож кожне худі обходиться в 470 грн.':'')+(S.f.cheap?' Тонші заготовки здешевили худі до 420 грн. Але після першого прання принт потріскався: кожне п’яте худі — '+r.ret+' шт. — повернули, і за них довелося віддати '+PG(r.ret*S.P)+'. Про тріщини знають усі школи: репутація впала ще на 25 балів.':'')+' Після всіх витрат місяць дав '+pl(r.pr)+'.'+note(S,r.pr);},eff:S=>{const r=mo(S,2);S.q2=r.q-r.ret;S.rush+=r.rush;S.sold+=S.q2;S.pr2=r.pr;money(S,r.pr);rep(S,drep(r)+(S.f.cheap?-25:0));}},
  {id:'idle',t:'calc',head:'Листопад · Куди йде енергія',text:'Електроенергія — 2 000 грн на місяць. Учитель фізики пан Тарас позичив вам розетку-лічильник, і вона тиждень записувала споживання. З’ясувалося: термопрес вмикають зранку, а друкують після уроків. Близько 5 годин щодня він лише тримає температуру й споживає при цьому в середньому 1 кВт. Майстерня працює 25 днів на місяць. Тариф за умовою задачі — 4,32 грн за кВт·год.',q:'Скільки гривень на місяць коштує нагрів преса, на якому ніхто не друкує?',ans:S=>540,unit:'грн',hint:'Знайди зайві кіловат-години: потужність × години на день × кількість днів. Потім помнож на тариф.',sol:S=>'1 кВт × 5 год × 25 днів = 125 кВт·год. 125 × 4,32 = 540 грн. Понад чверть рахунку за електроенергію йде на прес, на якому ніхто не друкує.'},
  {id:'audit',t:'choice',head:'Листопад · Енергоаудит',text:'Пан Тарас пропонує енергоаудит усієї майстерні: виміряти кожен прилад, знайти, де енергія йде в нікуди, і скласти план заходів. На це підуть дві суботи. Марко: «Навіщо? Купімо новий економний прес у розстрочку — і все».',q:'Що ти вирішиш?',o:[
   {l:'Провести повний енергоаудит і почати з безкоштовного: прес вмикати за 15 хвилин до друку',p:2,eff:S=>{S.f.audit=1;S.F-=840;},fb:'Новий режим преса — мінус 540 грн на місяць. Аудит знайшов ще й обігрівач, що працював ночами: розетка з таймером заощаджує 300 грн. Постійні витрати — 5 460 грн.'},
   {l:'Змінити лише режим преса; решта приладів навряд чи щось дасть',p:1,eff:S=>{S.f.press=1;S.F-=540;},fb:'540 грн на місяць повернуто, постійні витрати — 5 760 грн. Але решту приладів ніхто не міряв: можливо, там губиться ще кілька сотень.'},
   {l:'Купити новий економний прес у розстрочку: платіж 1 500 грн на місяць',p:0,eff:S=>{S.f.newpress=1;S.F+=900;},fb:'Рахунок за світло впав на 600 грн, але платіж 1 500 грн більший за економію: постійні витрати зросли до 7 200 грн. А звичка вмикати прес зранку нікуди не зникла.'}]},
  {id:'mon',t:'choice',head:'Листопад · Моніторинг',text:S=>(S.f.audit||S.f.press?'Нові правила роботи з пресом висять на стіні. ':'У майстерні стоїть новий прес, але вмикають його так само зранку. ')+'Пан Тарас: «Одне вимірювання — це знімок одного тижня. Звички повертаються непомітно. Потрібен моніторинг — постійне спостереження».',q:'Як ви стежитимете за споживанням енергії?',o:[
   {l:'Щоп’ятниці записувати показник лічильника й ділити спожите на кількість надрукованих худі',p:2,eff:S=>{S.f.mon=2;if(S.f.newpress){S.F-=240;S.f.late=1;}},fb:S=>S.f.audit||S.f.press?'Тепер щотижня видно, скільки кіловат-годин іде на одне худі. Щойно показник поповзе вгору — це буде помітно одразу.':'Перший же тиждень записів показав: новий прес теж гріється даремно. Режим змінили, і постійні витрати впали на 240 грн.'},
   {l:'Повісити біля преса наліпку «Вимикай!» — цього досить',p:1,eff:S=>{S.f.mon=1;},fb:'Наліпка нагадує, але нічого не вимірює. Чи дотримуються правил, покаже лише рахунок.'},
   {l:'Не стежити: рахунок і так приходить щомісяця',p:0,eff:S=>{S.f.mon=0;},fb:'Рахунок показує суму за місяць, коли змінити вже нічого не можна, і не каже, який прилад її накрутив.'}]},
  {id:'dec',t:'event',head:'Грудень · Гарячий сезон',text:S=>{const r=mo(S,3),F=fDec(S),k=repf(S),saved=S.f.audit||S.f.press;return 'Грудень — найгарячіший місяць. Прогноз обіцяв '+HD(S.d*1.5)+'. '+(k===1?'Репутація — '+PL(S.rep,'бал','бали','балів')+': на «Відбиток» не нарікають, і прогноз справдився.':'Але репутація — лише '+PL(S.rep,'бал','бали','балів')+': '+(S.f.cheap?'про потрісканий принт':'про зірвані строки')+' пам’ятають, і частина класів пішла до інших. Замовили '+HD(r.D)+'.')+(r.miss?' Марко третій місяць працює без винагороди, і кілька субот його не було. '+PL(r.miss,'замовлення','замовлення','замовлень')+' до свят надрукувати не встигли — від них довелося відмовитися. Надруковано '+HD(r.q)+'.':'')+fit(r)+(r.ret?' Кожне п’яте худі — '+r.ret+' шт. — знову повернули через принт: мінус '+PG(r.ret*S.P)+'.':'')+chat(r)+(F>S.F?(S.f.mon===1?' До наліпки біля преса звикли за два тижні: половина економії на світлі зникла.':' Без спостереження прес знову вмикали зранку: рахунок за світло повернувся до старого.'):saved||S.f.late?' Рахунок за світло тримається на новому рівні — журнал це підтверджує.':'')+' Постійні витрати грудня — '+PG(F)+'. Місяць дав '+pl(r.pr)+'.'+note(S,r.pr);},eff:S=>{const r=mo(S,3),F=fDec(S);S.q3=r.q-r.ret;S.rush+=r.rush;S.sold+=S.q3;S.pr3=r.pr;S.F=F;money(S,r.pr);S.prof=S.pr1+S.pr2+S.pr3;S.rev=S.P*S.sold;rep(S,drep(r));}},
  {id:'be2',t:'calc',head:'Грудень · Нова точка беззбитковості',text:S=>'Зараз ціна худі — '+S.P+' грн, змінні витрати на одне худі — '+S.vc+' грн, постійні витрати на місяць — '+PG(S.F)+'. У вересні було 440 грн і 6 300 грн.',q:'Скільки худі на місяць тепер треба продавати, щоб не бути в збитку? Якщо виходить неціле число — округли вгору.',ans:S=>bep(S.F,mar(S)),unit:'худі',hint:'Нова маржа: ціна мінус теперішні змінні витрати. Поділи на неї теперішні постійні витрати й округли вгору.',sol:S=>{const m=mar(S),b=bep(S.F,m),b0=bep(6300,S.P-440);return 'Маржа: '+S.P+' − '+S.vc+' = '+m+' грн. '+PN(S.F)+' : '+m+' = '+PN(S.F/m)+(S.F%m?', округлюємо вгору — '+b:'')+' худі. У жовтні точка беззбитковості була '+b0+' худі. '+(b<b0?'Вона знизилася: майстерня починає заробляти раніше, і спад продажів для неї менш небезпечний.':b>b0?'Вона зросла: щоб вийти в нуль, тепер треба продавати більше.':'Вона не змінилася.')+(S.f.cheap?' Але цей розрахунок не бачить повернень.':'');}},
  {id:'bp',t:'choice',head:'Грудень · Бізнес-план',text:'Пані Ірина, власниця магазину спортивної форми «Жовтий м’яч», шукає, хто друкуватиме форму для шкільної ліги міста. Вона може вкласти 30 000 грн у другий термопрес для «Відбитка» — якщо її переконає бізнес-план. До зустрічі тиждень.',q:'З чого складатиметься твій бізнес-план?',o:[
   {l:'Резюме; опис продукту й клієнтів; план продажів по місяцях; фінансовий план — доходи, витрати, точка беззбитковості; ризики',p:2,eff:S=>{S.f.bp=2;},fb:'Повна структура: видно, що ви продаєте, кому, скільки заробляєте і що може піти не так.'},
   {l:'Лише таблиця доходів і витрат за три місяці — цифри говорять самі за себе',p:1,eff:S=>{S.f.bp=1;},fb:'Цифри — серце плану, але вони не пояснюють, хто ваші клієнти і куди підуть 30 000 грн.'},
   {l:'Яскрава презентація: фото худі, відгуки, історія команди. Цифри — усно, якщо спитає',p:0,eff:S=>{S.f.bp=0;},fb:'Фото покажуть, що ви вмієте друкувати. Але партнерка вкладає гроші й вирішуватиме за цифрами, яких у плані немає.'}]},
  {id:'sum',t:'choice',head:'Грудень · Резюме',text:S=>'Резюме — перша сторінка бізнес-плану. Пані Ірина прочитає її за хвилину. Підсумки кварталу: продано '+HD(S.sold)+', дохід — '+PG(S.rev)+', '+pl(S.prof)+'.',q:'Що ти напишеш у резюме?',o:[
   {l:S=>'Що ми робимо й для кого; факт кварталу — '+HD(S.sold)+' і '+pl(S.prof)+'; скільки грошей просимо, на що і коли вони повернуться',p:2,eff:S=>{S.f.sum=2;},fb:S=>S.prof>0?'Пів сторінки — і партнерка знає головне: справа працює, цифри справжні, а її гроші мають мету.':'Збиток у резюме виглядає слабко, але партнерка однаково побачила б його в таблиці. Чесні цифри — шанс на довіру.'},
   {l:'Докладну історію: як виникла ідея, хто що вміє, які принти ви вже друкували',p:1,eff:S=>{S.f.sum=1;},fb:'Історія тепла, але на першій сторінці немає ні цифр, ні відповіді, чого ти хочеш від партнерки.'},
   {l:S=>'Прогноз із запасом: «уже з січня — '+HD(S.sold*2)+' за квартал». Партнери люблять амбітні цифри',p:0,eff:S=>{S.f.sum=0;},fb:S=>'За три місяці продано '+HD(S.sold)+'. Обіцянка подвоїти продажі нічим не підкріплена, і порівняти її з фактом — справа хвилини.'}]},
  {id:'rent',t:'calc',head:S=>S.prof>=0?'Грудень · Рентабельність':'Грудень · Скільки бракує до нуля',text:S=>'За квартал дохід майстерні — '+PG(S.rev)+', а результат після всіх витрат — '+pl(S.prof)+'.'+(S.prof>=0?' Пані Ірина спитає: «Скільки прибутку приносить вам кожна сотня гривень доходу?»':' Рентабельності тут немає: є збиток. Пані Ірина спитає інакше: «Скільки ще худі вам треба було продати, щоб вийти в нуль?» Маржа з одного худі зараз — '+mar(S)+' грн.'),q:S=>S.prof>=0?'Яка рентабельність продажу у відсотках? Округли до цілого числа.':'Скільки ще худі треба було продати за квартал, щоб покрити збиток? Якщо виходить неціле число — округли вгору.',ans:S=>S.prof>=0?Math.round(S.prof/Math.max(1,S.rev)*100):Math.ceil(-S.prof/mar(S)),tol:0.5,unit:S=>S.prof>=0?'% доходу':'худі',hint:S=>S.prof>=0?'Поділи прибуток на дохід і помнож на 100.':'Кожне додаткове худі приносить маржу. Поділи збиток на маржу з одного худі й округли вгору.',sol:S=>{if(S.prof<0){const m=mar(S),n=Math.ceil(-S.prof/m);return PN(-S.prof)+' : '+m+' = '+PN(-S.prof/m)+((-S.prof)%m?', округлюємо вгору — '+n:'')+' худі. Стільки продажів бракувало до нуля. Інший шлях — підняти маржу або знизити постійні витрати.';}const x=Math.round(S.prof/Math.max(1,S.rev)*100);return PN(S.prof)+' : '+PN(S.rev)+' × 100 ≈ '+x+' %. '+(x>0?'Із кожних 100 грн доходу майстерні лишається близько '+x+' грн прибутку.':'Із кожних 100 грн доходу майстерні лишається менше ніж 50 копійок: прибутку майже немає.')+' Що вища рентабельність, то легше пережити подорожчання й спад продажів.';}},
  {id:'pitch',t:'event',head:'Грудень · Зустріч із партнеркою',text:S=>{const d=deal(S),b=bep(S.F,mar(S));return 'Зустріч у магазині «Жовтий м’яч». Пані Ірина '+(S.f.bp===2?'гортає бізнес-план і зупиняється на фінансовій таблиці.':S.f.bp===1?'дивиться на таблицю: «Цифри бачу. А хто ваші клієнти? І що буде, якщо продажі впадуть?»':'переглядає фото: «Гарно. А де цифри?» Доводиться називати їх із пам’яті.')+' Факт кварталу: '+HD(S.sold)+', дохід '+PG(S.rev)+', '+pl(S.prof)+'. Точка беззбитковості — '+b+' худі на місяць, у грудні продано '+S.q3+'.'+(S.f.paid?(S.prof>0?' «Із цього прибутку 4 500 грн ви роздали ще в жовтні, не знаючи результату. У справі лишилося '+PG(net(S))+'», — зауважує вона.':' «А 4 500 грн виплат у жовтні — з якого прибутку?» — питає вона.'):'')+(S.f.sum===0?' Вона порівнює прогноз із резюме з фактом: «Продано '+S.sold+', а обіцяєте '+(S.sold*2)+'. Звідки ця цифра?» Відповіді в тебе немає.':'')+(d===2?' «Я розпитала тренерів — про вас кажуть добре. Ви знаєте свої цифри й заробляєте. Я вкладаю 30 000 грн у другий прес, а ви друкуєте форму для ліги».':d===1?' «Вкладати поки рано'+(net(S)<6000?': у справі лишається замало прибутку, щоб повернути вкладене':S.debt>0?': спершу розрахуйтеся з боргом':S.rep<60?': я розпитала тренерів, і про вас кажуть різне':S.f.bp<2?': у плані бракує важливих частин':': із резюме я так і не зрозуміла, чого ви хочете')+'. Але дам пробне замовлення — 20 футболок для однієї команди. Упораєтеся — поговоримо навесні».':net(S)<=0?' «Поки що майстерня не заробляє. Розберіться з ціною й витратами — тоді приходьте».':S.f.sum===0?' «Я не вкладаю гроші в цифри, яким не можу вірити».':' «Без плану з цифрами я не можу ухвалити рішення».');},eff:S=>{S.f.deal=deal(S);}}],
 finish:S=>{const lvl=S.f.deal===2||(S.f.deal===1&&net(S)>=6000&&S.debt===0&&S.rep>=50)?2:net(S)>0?1:0;return{level:lvl,title:[S.prof>0?'Прибуток роздано раніше, ніж зароблено':'Квартал без прибутку','Майстерня в плюсі, але не все вдалося','«Відбиток» заробляє, і партнерка це бачить'][lvl],text:'За три місяці: продано '+HD(S.sold)+' за ціни '+S.P+' грн, дохід — '+PG(S.rev)+', '+pl(S.prof)+(S.f.paid?' (із нього 4 500 грн роздано в жовтні)':'')+'. У касі '+PG(S.cash)+(S.debt>0?', борг перед батьками Марка — '+PG(S.debt):'')+'. Постійні витрати — '+PG(S.F)+' на місяць, точка беззбитковості — '+bep(S.F,mar(S))+' худі. Репутація — '+PL(S.rep,'бал','бали','балів')+'.'+(S.f.deal===2?' Пані Ірина вкладає 30 000 грн у другий прес.':S.f.deal===1?' Пані Ірина дала пробне замовлення.':' Пані Ірина відмовила.'),tips:[
  S.P===650?'Ціна 650 грн дала найкраще поєднання маржі й кількості покупців: твій вибір спирався на порівняння варіантів.':(S.P===520?'За ціни 520 грн маржа 80 грн не покривала постійних витрат: багато покупців — ще не прибуток.':'За ціни '+S.P+' грн майстерня заробляла менше, ніж могла б за 650 грн.')+' Наступного разу для кожної ціни порахуй: маржа × кількість худі − постійні витрати.',
  S.f.cheap?'Дешевші заготовки обернулися поверненнями й утратою репутації: економія на якості зменшує не лише витрати, а й дохід.':S.rush>0?'За квартал терміново докуплено заготовок: '+S.rush+'. Це '+PG(60*S.rush)+' доплати й замовники, які чекали зайвий тиждень. Графік має повторювати сезонність попиту'+(S.f.replan===2?' — добре, що після жовтня план виправлено за фактом.':S.f.replan>=0?', а після першого ж місяця план варто звіряти з фактом.':'.'):'Графік виробництва збігся з попитом: жодної термінової закупівлі за квартал.',
  S.f.paid?'Виплати в жовтні зроблено з доходу, а не з прибутку. Спершу порахуй прибуток, потім діли.':S.f.bp===2&&S.f.sum===2?(S.F<6300?(S.f.mon===2?'Вимірювання й щотижневий моніторинг знизили постійні витрати до '+PG(S.F)+' — а з ними й точку беззбитковості.':'Постійні витрати знизилися до '+PG(S.F)+', але без моніторингу частина економії розтанула. Вимірюй споживання щотижня.'):'Постійні витрати не зменшилися ('+PG(S.F)+' на місяць). Наступного разу почни з вимірювань: енергоаудит показує, де гроші йдуть у нікуди.'):'Бізнес-план переконує, коли в ньому є всі частини, а резюме відповідає: що ви робите, які фактичні цифри і на що потрібні гроші.']};},
 terms:[['Собівартість','витрати на виготовлення й продаж одиниці товару'],['Змінні й постійні витрати','змінні зростають разом з обсягом (заготовки, пакування); постійні платять щомісяця незалежно від обсягу (оренда, зв’язок)'],['Маржа','різниця між ціною товару та змінними витратами на нього'],['Точка беззбитковості','обсяг продажу, за якого дохід дорівнює всім витратам'],['Рентабельність','відношення прибутку до доходу у відсотках']]};
})());

PFG_TOPICS.push((()=>{
 /* місячний внесок: спершу частина поліса (оплата частинами), потім борг, решта — у фонд */
 const split=S=>{let x=S.r,ins=0,d=0,sh=0;if(S.inst>0){ins=Math.min(600,x);sh=600-ins;x-=ins;}if(S.debt>0){d=Math.min(S.debt,x);x-=d;}return{ins,sh,d,x};};
 const add=S=>{const k=split(S);if(S.inst>0)S.inst--;S.debt+=k.sh-k.d;S.res+=k.x;};
 const cn=S=>{const k=split(S);return (S.inst>0?(k.sh>0?'На поліс цього місяця треба 600 грн: із внеску взято '+PG(k.ins)+', решту позичено в батьків. ':'Із місячного внеску 600 грн пішло на поліс. '):'')+(k.d>0?'Із внеску '+PG(k.d)+' повернуто батькам'+(k.x>0?', решта — '+PG(k.x)+' — пішла до резервного фонду.':'; до резервного фонду не надійшло нічого.'):k.x>0?'До резервного фонду надійшов внесок — '+PG(k.x)+'.':'До резервного фонду цього місяця не надійшло нічого.');};
 const hit=(S,x)=>{S.loss+=x;if(S.res>=x)S.res-=x;else{S.debt+=x-S.res;S.res=0;}};
 const paid=(S,x)=>{if(!x)return '';const k=split(S),res=S.res+k.x;return res>=x?' Втрати покрито з резервного фонду.':' Резервного фонду ('+PG(res)+') не вистачило: '+PG(x-res)+' довелося позичити в батьків.';};
 const d3=S=>S.f.pow===2?900:S.f.pow===1?2400:S.f.pow===-1?3600:4500;
 const d5=S=>S.f.qc===2?0:S.f.qc===1?2200:6600;
 const fr=S=>S.f.ins===2?2000:8000;
 const prem=S=>S.f.ins===2?1800:900;
 const comp=S=>(12000-fr(S))*(S.f.claim===2?1:S.f.claim===1?0.7:0);
 const oth=S=>(70-big(S))/2;
 const big=S=>S.dev>=1000?14:28;
 const mth=S=>Math.round(S.res/6300*10)/10;
 const prot=S=>6000-S.bud+(S.f.part?1800:0);
 return {id:'9-5',sec:'9a',title:'Ризики підприємницької діяльності',minutes:30,
 intro:'«Відбиток» — майстерня, де ти, Соля й Марко друкуєте принти на худі для класів і шкільних команд, — працює вже рік і продає близько 70 худі на місяць. Попереду пів року. Спершу ти оціниш ризики, почнеш збирати резервний фонд і розподілиш бюджет на захист. Потім частина ризиків справдиться, а частина — ні. Скільки це коштуватиме, залежить від твоєї підготовки.',
 init:()=>({res:0,bud:6000,loss:0,debt:0,r:0,team:0,dev:0,inst:0,d1:0,f:{}}),
 meters:[{k:'res',label:'Резервний фонд',unit:'грн'},{k:'bud',label:'Бюджет на захист',unit:'грн'},{k:'loss',label:'Втрати від ризиків',unit:'грн'},{k:'debt',label:'Борг',unit:'грн'}],
 steps:[
  {id:'map',t:'choice',head:'Місяць 1 · Що може піти не так',text:'Соля приносить список: постачальник зірве поставку заготовок; вимикатимуть електроенергію; вийде з ладу термопрес; партія вийде з браком; піде найбільший клієнт; хтось із команди покине справу. Марко кривиться: «Не накаркай! Рік працюємо — і нічого». Ризик — це подія, яка може статися, а може й ні. Але якщо станеться, забере гроші, час або клієнтів.',q:'Що ти зробиш зі списком Солі?',o:[
   {l:'Скласти карту ризиків: для кожного оцінити ймовірність і наслідки в гривнях',p:2,eff:S=>{S.f.map=1;},fb:'Тепер у кожного ризику є дві цифри: наскільки він імовірний і скільки коштуватиме.'},
   {l:'Повісити список на стіну — хай усі пам’ятають',p:1,eff:S=>{},fb:'Список нагадує, що ризики існують. Але не каже, який найнебезпечніший і на що витрачати обмежений бюджет.'},
   {l:'Відкласти: проблеми вирішуватимемо, коли з’являться',p:0,eff:S=>{},fb:'Коли ризик уже справдився, лишається тільки платити. Далі доведеться вирішувати без цифр.'}]},
  {id:'ev1',t:'calc',head:'Місяць 1 · Оцінка ризику',text:S=>(S.f.map?'Починаєш карту ризиків. ':'Соля все ж наполягла порахувати хоча б два ризики. ')+'Щоб порівнювати ризики, кожен оцінюють одним числом: імовірність множать на наслідки. Постачальник заготовок у вас один. За оцінкою знайомих майстерень, імовірність, що за пів року він зірве поставку, — 50 %. Тоді «Відбиток» втратить близько 6 000 грн.',q:'Яка оцінка цього ризику в гривнях?',ans:S=>3000,unit:'грн',hint:'Запиши ймовірність десятковим дробом (50 % = 0,5) і помнож на суму можливих втрат.',sol:S=>'0,5 × 6 000 = 3 000 грн. Це не сума, яку майстерня обов’язково втратить: подія або станеться (і забере 6 000 грн), або ні. Оцінка потрібна, щоб порівнювати ризики між собою.'},
  {id:'ev2',t:'calc',head:'Місяць 1 · Рідший, але дорогий',text:'Тепер термопрес. Узимку після відключень напруга в мережі стрибає. Імовірність, що за пів року стрибок або поломка виведе прес із ладу, — 20 %. Ремонт коштуватиме 12 000 грн, і заплатити доведеться одразу: без преса майстерня стоїть.',q:'Яка оцінка цього ризику в гривнях?',ans:S=>2400,unit:'грн',hint:'20 % — це 0,2. Помнож імовірність на вартість ремонту.',sol:S=>'0,2 × 12 000 = 2 400 грн. Оцінка менша, ніж у постачальника (3 000 грн), але сам удар удвічі більший. Часті й недорогі ризики покривають запобіганням і власним резервом, рідкісні й руйнівні — страхують.'},
  {id:'fund',t:'plan',head:'Місяць 1 · Резервний фонд',text:'Перший спосіб захисту — самострахування: власний резервний фонд на чорний день. Майстерня заробляє близько 8 400 грн прибутку на місяць. Соля пропонує правило: за три місяці зібрати резерв на місяць постійних витрат — 6 300 грн. Марко нагадує: команда працює не безкоштовно, а без пошуку нових клієнтів ви залежите від одного ліцею.',q:'Як ти щомісяця ділитимеш 8 400 грн прибутку?',
   fields:[{k:'res',label:'Резервний фонд'},{k:'team',label:'Виплати команді'},{k:'dev',label:'Пошук нових клієнтів'}],
   total:S=>8400,
   best:S=>({res:2100,team:4200,dev:2100}),
   eff:(S,v)=>{S.r=v.res;S.res=v.res;S.team=v.team;S.dev=v.dev;},
   score:(S,v)=>v.res>=2100&&v.team>=2000&&v.dev>=1000?{p:2,fb:'Із внеском '+PG(v.res)+' резерв на місяць постійних витрат збереться щонайбільше за три місяці. Команда має винагороду, а на пошук клієнтів іде '+PG(v.dev)+'.'}:v.res>=2100?{p:1,fb:'Резерв збирається за правилом Солі, але '+(v.team<2000?'команді дістається лише '+PG(v.team)+' на трьох — надовго такої мотивації не вистачить.':'на пошук клієнтів лишається лише '+PG(v.dev)+', і залежність від одного ліцею не зникне.')}:v.res>=1000?{p:1,fb:'Щоб зібрати 6 300 грн за три місяці, треба відкладати по 2 100 грн. Із внеском '+PG(v.res)+' резерв ростиме надто повільно.'}:{p:0,fb:'Майже весь прибуток розходиться одразу, а резерв росте лише на '+PG(v.res)+' на місяць. Перша ж несподіванка стане боргом.'}},
  {id:'sup',t:'choice',head:'Місяць 1 · Постачальник',text:S=>'Другий спосіб — запобігання й запасні варіанти. На них є окремий бюджет: 6 000 грн на всі ризики разом. Почнімо з постачальника заготовок.'+(S.f.map?' За картою ризиків: імовірність зриву поставки — 50 %, наслідки — 6 000 грн.':' Марко: «Та він жодного разу не підвів!»'),q:'Як захиститися від зриву поставки?',o:[
   {l:'Знайти другого постачальника, зробити в нього пробне замовлення й підписати договір — 2 000 грн',p:2,eff:S=>{S.f.sup=2;S.bud-=2000;},fb:'Тепер є перевірений запасний варіант: якщо основний постачальник підведе, заготовки приїдуть за два дні.'},
   {l:'Доплатити постачальникові 3 000 грн за «пріоритет»: обіцяє відвантажувати вам першим',p:1,eff:S=>{S.f.sup=1;S.bud-=3000;},fb:'За короткої затримки вас обслужать першими. Але це половина бюджету захисту, а постачальник, як і раніше, один.'},
   {l:'Узяти з постачальника слово, що попередить про затримку заздалегідь',p:0,eff:S=>{S.f.sup=0;},fb:'Обіцянка нічого не коштує — ні тобі, ні йому. Якщо поставка зірветься, попередження заготовок не замінить.'}]},
  {id:'pow',t:'choice',head:'Місяць 1 · Електроенергія',text:S=>'Наступний ризик — відключення електроенергії. Термопрес на 2 кВт без струму не працює, а взимку світло вимикають за графіком.'+(S.f.map?' За картою ризиків: імовірність — 90 %, наслідки — близько 4 500 грн зірваних замовлень.':' Наскільки це серйозно, ніхто не рахував.')+' У бюджеті на захист — '+PG(S.bud)+'.',q:'Як підготуватися до відключень?',o:[
   {l:'Перебудувати графік: друкувати в години зі світлом, макети готувати на ноутбуках; купити два павербанки — 1 200 грн',p:2,eff:S=>{S.f.pow=2;S.bud-=1200;},fb:'Друк переїхав на години зі світлом, а без нього Соля готує макети. Дешево — і точно в причину втрат.'},
   {l:'Купити зарядну станцію за 4 000 грн',when:S=>S.bud>=4000,p:0,eff:S=>{S.f.pow=-1;S.bud-=4000;},fb:'Станція живить ноутбуки й лампи, але термопрес на 2 кВт розряджає її за пів години. Друк під час відключень однаково стоїть: дорого — і повз причину втрат.'},
   {l:'Домовитися із сусідньою майстернею: друкувати в неї, коли у вас немає світла',p:1,eff:S=>{S.f.pow=1;},fb:'Безкоштовно, але сусіди пускають лише тоді, коли їхній прес вільний.'},
   {l:'Нічого не робити: графіки відключень уже не такі суворі',p:0,eff:S=>{S.f.pow=0;},fb:'Грошей не витрачено. Але найімовірніший із ваших ризиків лишився без жодного захисту.'}]},
  {id:'m2',t:'event',head:'Місяць 2 · Поставка',text:S=>cn(S)+' Заготовки приїхали вчасно: ризик з імовірністю 50 % цього разу не справдився.'+(S.f.sup===2?' Запасний постачальник не знадобився. Чи змарновано 2 000 грн? Ні: ними оплачено впевненість, що зрив поставки не зупинить майстерню. А ризик нікуди не зник.':S.f.sup===1?' Доплата за «пріоритет» нічого не змінила: 3 000 грн пішли, а залежність від одного постачальника лишилася.':' Тобі пощастило. Але добрий результат — ще не добре рішення: наступного разу монета може впасти інакше.'),eff:S=>{add(S);}},
  {id:'tar',t:'calc',head:'Місяць 2 · Ціна поліса',text:'Соля нагадує про найдорожчий ризик — термопрес. Третій спосіб захисту — страхування: ти платиш компанії невелику суму, а вона бере на себе великий збиток. Обладнання майстерні (прес, принтер, ноутбук) коштує 30 000 грн. Страховий тариф за умовою задачі — 6 % страхової суми на рік.',q:'Скільки гривень коштуватиме поліс на рік?',ans:S=>1800,unit:'грн',hint:'Знайди 6 % від 30 000 грн.',sol:S=>'30 000 × 0,06 = 1 800 грн. Це страховий платіж: він не повертається, навіть якщо нічого не станеться.'},
  {id:'ins',t:'choice',head:'Місяць 2 · Страхова компанія',text:S=>(S.bud>=1800?'У тебе три пропозиції страхових компаній.':'Із трьох страхових компаній довіру викликає лише «Тисовий щит»: вона є в реєстрі на сайті Національного банку, покриває поломку й перепади напруги, франшиза — 2 000 грн. Але поліс коштує 1 800 грн, а в бюджеті на захист стільки вже немає.')+(S.f.map?' За картою ризиків: прес — 20 %, але це 12 000 грн за один день.':'')+' У бюджеті на захист — '+PG(S.bud)+'.',q:'Що ти обереш?',o:[
   {l:'«Тисовий щит»: 1 800 грн на рік. Є в реєстрі на сайті Національного банку; покриває поломку, перепади напруги, пожежу й крадіжку; франшиза 2 000 грн; у відгуках — виплати за два тижні',when:S=>S.bud>=1800,p:2,eff:S=>{S.f.ins=2;S.bud-=1800;},fb:'Перевірено головне: чи має компанія право страхувати, що покриває поліс, яка франшиза і як компанія платить.'},
   {l:'«Тисовий щит» з оплатою частинами: три місяці по 600 грн із внесків до резервного фонду',when:S=>S.bud<1800,p:2,eff:S=>{S.f.ins=2;S.f.part=1;S.inst=3;},fb:'Найдорожчий ризик без захисту не лишився. Три місяці резерв ростиме на 600 грн повільніше — це ціна поліса.'},
   {l:'«Вербовий міст»: 900 грн на рік. Є в реєстрі; покриває те саме; франшиза 8 000 грн',when:S=>S.bud>=1800,p:1,eff:S=>{S.f.ins=1;S.bud-=900;},fb:'Удвічі дешевше, але франшиза 8 000 грн означає: більшу частину майже будь-якого збитку майстерня однаково покриє сама.'},
   {l:'«Миттєвий поліс»: 600 грн на рік. «Без франшизи, покриваємо все, виплата за добу». Сайт на одну сторінку, у реєстрі такої компанії немає',when:S=>S.bud>=1800,p:0,eff:S=>{S.f.ins=-1;S.bud-=600;},fb:'Найщедріші обіцянки дає той, хто не збирається їх виконувати. Компанії немає в реєстрі — отже, права страхувати вона не має.'},
   {l:'Самострахування: щомісяця додавати до резервного фонду ще 300 грн із виплат команді — саме на ремонт',when:S=>S.bud<1800,p:1,eff:S=>{S.f.ins=0;S.f.self=1;S.r+=300;S.team=Math.max(0,S.team-300);},fb:'Резерв ростиме швидше, але 12 000 грн так не зібрати й за три роки. Від рідкісного й руйнівного удару власний фонд захищає погано.'},
   {l:'Не страхувати: прес майже новий, що з ним станеться',p:0,eff:S=>{S.f.ins=0;},fb:'Гроші лишилися в бюджеті. А ризик на 12 000 грн — повністю на майстерні.'}]},
  {id:'m3',t:'event',head:'Місяць 3 · Відключення',text:S=>'Зима. Світло вимикають щодня на кілька годин: найімовірніший ризик справдився. '+(S.f.pow===2?'Ви друкуєте в години зі світлом, а в темряві Соля готує макети. Зірвалося лише кілька термінових замовлень.':S.f.pow===1?'Сусіди пускають до свого преса не щоразу: частину замовлень урятовано, частина пішла до інших.':S.f.pow===-1?'Зарядна станція тримає ноутбуки й лампи, але прес стоїть щоразу, коли немає світла. Замовлення йдуть до інших.':'Прес стоїть по пів дня, замовлення накопичуються, клієнти йдуть туди, де встигають.')+' Втрати за місяць — '+PG(d3(S))+'. '+cn(S),eff:S=>{add(S);S.d1=d3(S);}},
  {id:'left',t:'calc',head:'Місяць 3 · Резерв і втрати',text:S=>'У резервному фонді зараз '+PG(S.res)+(S.debt>0?', борг — '+PG(S.debt):'')+'. Втрати через відключення — '+PG(S.d1)+': це повернуті передоплати, і віддати їх треба негайно.',q:S=>S.res>=S.d1?'Скільки гривень залишиться в резервному фонді?':'Скільки гривень не вистачає в резервному фонді, щоб покрити втрати?',ans:S=>Math.abs(S.res-S.d1),unit:S=>S.res>=S.d1?'грн':'грн бракує',hint:'Порівняй резерв із сумою втрат і знайди різницю.',sol:S=>S.res>=S.d1?PN(S.res)+' − '+PN(S.d1)+' = '+PG(S.res-S.d1)+'. Резерв прийняв удар на себе: позичати не довелося.':PN(S.d1)+' − '+PN(S.res)+' = '+PG(S.d1-S.res)+'. Цю суму довелося позичити в батьків. Тепер наступні внески підуть не в резерв, а на повернення боргу.',eff:S=>{hit(S,S.d1);}},
  {id:'qc',t:'choice',head:'Місяць 3 · Брак',text:S=>'Ще один ризик зі списку — брак. Нова партія термоплівки може виявитися гіршою: принт ляже плямами, і ціле замовлення піде в смітник.'+(S.f.map?' За картою ризиків: імовірність отримати таку плівку — 30 %, наслідки — до 6 600 грн (15 зіпсованих худі).':' Досі такого не траплялося.')+' У бюджеті на захист — '+PG(S.bud)+'.',q:'Що ви робитимете з кожною новою партією плівки?',o:[
   {l:'Робити тестовий відбиток і перевіряти його пранням; 600 грн на тестові матеріали',when:S=>S.bud>=600,p:2,eff:S=>{S.f.qc=2;S.bud-=600;},fb:'Один пробний відбиток перед партією — і дефект плівки зупиниться на ньому, а не на цілому замовленні.'},
   {l:'Робити тестовий відбиток на обрізках і старих футболках — безкоштовно, але на день довше',when:S=>S.bud<600,p:2,eff:S=>{S.f.qc=2;},fb:'Перевірка не обов’язково коштує грошей. Дефект плівки зупиниться на обрізку, а не на цілому замовленні.'},
   {l:'Оглядати перші п’ять худі з кожного замовлення вже після друку',p:1,eff:S=>{S.f.qc=1;},fb:'Брак буде помічено, але не одразу: перші худі вже будуть зіпсовані.'},
   {l:'Не перевіряти: плівку завжди беремо в одного продавця',p:0,eff:S=>{S.f.qc=0;},fb:'Той самий продавець не означає ту саму партію. Якщо плівка виявиться іншою, про це скаже вже клієнт.'}]},
  {id:'m4',t:'event',head:'Місяць 4 · Термопрес',text:S=>cn(S)+' А після чергового відключення світло повернулося зі стрибком напруги. Термопрес задимів і вимкнувся. Ремонт — 12 000 грн. Імовірність була лише 20 %, а зрив поставки з його 50 % так і не стався: імовірність — це не розклад.'+(S.f.ins===2?' У тебе є поліс «Тисового щита»: перепади напруги він покриває.':S.f.ins===1?' У тебе є поліс «Вербового мосту»: перепади напруги він покриває, але франшиза — 8 000 грн.':S.f.ins===-1?' Ти телефонуєш у «Миттєвий поліс». Номер не обслуговується, сайт зник. 600 грн пропали разом із ним.':S.f.self?' Поліса немає — є лише резервний фонд із додатковими внесками на ремонт.':' Поліса немає. Увесь ремонт — клопіт майстерні.'),eff:S=>{add(S);}},
  {id:'claim',t:'choice',when:S=>S.f.ins>=1,head:'Місяць 4 · Страховий випадок',text:'Настав страховий випадок. У твоєму договорі записано: повідомити страховика протягом трьох робочих днів, а пошкоджене майно зберегти до огляду. Марко: «Замовлення горять! Майстер може прийти вже сьогодні. Полагодимо, а страховій розкажемо потім».',q:'Що ти зробиш?',o:[
   {l:'Сфотографувати прес, того ж дня повідомити страхову, нічого не ремонтувати до огляду й зібрати документи: поліс, чек на прес, висновок майстра',p:2,eff:S=>{S.f.claim=2;},fb:'Умови договору виконано: страховик оглядає прес і має всі документи. Підстав відмовляти немає.'},
   {l:'Повідомити страхову, коли з’явиться вільна хвилина, — днів за десять',p:1,eff:S=>{S.f.claim=1;},fb:'Строк повідомлення пропущено. За умовами цього договору страховик у такому разі зменшує виплату на 30 %.'},
   {l:'Спершу відремонтувати — замовлення важливіші; страховій повідомити після',p:0,eff:S=>{S.f.claim=0;},fb:'Після ремонту страховик не може перевірити, що й чому зламалося. За умовами цього договору це підстава відмовити у виплаті.'}]},
  {id:'comp',t:'calc',when:S=>S.f.ins>=1,head:'Місяць 4 · Відшкодування',text:S=>S.f.claim===0?'Страхова відмовила: прес відремонтовано до огляду. Ремонт — 12 000 грн — повністю на майстерні. У резервному фонді — '+PG(S.res)+'.':'Ремонт коштує 12 000 грн. Франшиза за твоїм договором — '+PG(fr(S))+': цю частину збитку власник покриває сам.'+(S.f.claim===1?' Через запізніле повідомлення суму до виплати зменшено на 30 %.':''),q:S=>S.f.claim===0?(S.res>=12000?'Скільки гривень залишиться в резервному фонді після ремонту?':'Скільки гривень не вистачає в резервному фонді на ремонт?'):'Скільки гривень відшкодує страхова компанія?',ans:S=>S.f.claim===0?Math.abs(S.res-12000):comp(S),unit:S=>S.f.claim===0&&S.res<12000?'грн бракує':'грн',hint:S=>S.f.claim===0?'Порівняй резервний фонд із вартістю ремонту й знайди різницю.':'Від вартості ремонту відніми франшизу.'+(S.f.claim===1?' Потім знайди 70 % від того, що вийшло.':''),sol:S=>{const b=12000-fr(S),c=comp(S),own=12000-c;return (S.f.claim===0?(S.res>=12000?PN(S.res)+' − 12 000 = '+PG(S.res-12000)+'.':'12 000 − '+PN(S.res)+' = '+PG(12000-S.res)+'. Цю суму довелося позичити в батьків.')+' Поліс був, але умови договору порушено — і '+PG(prem(S))+' страхового платежу нічого не дали.':'12 000 − '+PN(fr(S))+' = '+PG(b)+'.'+(S.f.claim===1?' Після зменшення на 30 %: '+PN(b)+' × 0,7 = '+PG(c)+'. Запізнення коштувало '+PG(b-c)+'.':'')+' Частка майстерні — '+PG(own)+'.'+(S.f.ins===2?(S.f.claim===2?' Поліс за 1 800 грн зберіг їй 10 000 грн.':''):' Що нижчий платіж, то зазвичай більша франшиза.')+(S.res<own?' У резерві бракує '+PG(own-S.res)+' — їх довелося позичити в батьків.':''));},eff:S=>{hit(S,12000-comp(S));}},
  {id:'short',t:'calc',when:S=>!(S.f.ins>=1),head:'Місяць 4 · Чим платити',text:S=>'Відшкодування не буде: ремонт — 12 000 грн — повністю на майстерні. У резервному фонді — '+PG(S.res)+'.',q:S=>S.res>=12000?'Скільки гривень залишиться в резервному фонді після ремонту?':'Скільки гривень не вистачає в резервному фонді на ремонт?',ans:S=>Math.abs(S.res-12000),unit:S=>S.res>=12000?'грн':'грн бракує',hint:'Порівняй резервний фонд із вартістю ремонту й знайди різницю.',sol:S=>S.res>=12000?PN(S.res)+' − 12 000 = '+PG(S.res-12000)+'. Резерву вистачає, але після ремонту він помітно схудне.':'12 000 − '+PN(S.res)+' = '+PG(12000-S.res)+'. Надійний поліс за 1 800 грн покрив би 10 000 грн цього збитку.'},
  {id:'fix',t:'choice',when:S=>!(S.f.ins>=1),head:'Місяць 4 · Ремонт',text:S=>'Без преса майстерня не заробляє. '+(S.res>=12000?'Резервного фонду на ремонт вистачає.':'Резервного фонду на ремонт не вистачає: бракує '+PG(12000-S.res)+'.')+' Марко показує рекламу: «Гроші за 15 хвилин, усього 1 % на день».',q:'Як ти оплатиш ремонт?',o:[
   {l:'Оплатити з резервного фонду',when:S=>S.res>=12000,p:2,eff:S=>{hit(S,12000);},fb:'Саме для такого дня резерв і збирали. Прес працює, боргу немає.'},
   {l:'Віддати весь резерв, а решту позичити в батьків без відсотків і повертати з щомісячних внесків',when:S=>S.res<12000,p:2,eff:S=>{hit(S,12000);},fb:'Борг без відсотків, і зрозуміло, з чого його повертати. Найдешевший вихід із дорогої ситуації.'},
   {l:S=>'Місяць друкувати на старому маленькому пресі'+(S.res>=12000?': шкода одразу спустошувати резерв':', а з ремонтом зачекати'),p:1,eff:S=>{S.loss+=2500;hit(S,12000);},fb:S=>'Старий прес удвічі повільніший: за місяць майстерня недоотримала 2 500 грн. А ремонт однаково довелося оплатити — з резерву'+(S.res>=12000?'.':', а решту позичити в батьків.')},
   {l:'Узяти швидку позику: 12 000 грн під 1 % на день на 30 днів',p:0,eff:S=>{S.f.loan=1;hit(S,15600);},fb:S=>'За умовою — 1 % на день. За 30 днів це 30 %: 12 000 × 0,3 = 3 600 грн зверху. Через місяць довелося віддати 15 600 грн — з резерву'+(S.res>=15600?'.':', а решту позичити в батьків.')}]},
  {id:'m5',t:'event',head:S=>S.f.qc===2?'Місяць 5 · Брак, якому запобігли':'Місяць 5 · Брак',text:S=>cn(S)+' Нова партія термоплівки виявилася з дефектом: принт лягає плямами. '+(S.f.qc===2?'Це показав тестовий відбиток. Плівку повернули продавцеві, втрат немає. Ризик не зник сам: його зупинила перевірка.':S.f.qc===1?'Це стало видно на перших п’яти худі замовлення. П’ять худі — 2 200 грн — пішли в брак.':'Ніхто нічого не перевіряв, і замовлення для 10-Б надрукували повністю. 15 зіпсованих худі — 6 600 грн.')+paid(S,d5(S))+(S.team<2000?' І ще одне: Маркові з прибутку дістається зовсім мало. Тепер він має підробіток і приходить через раз: затримки коштували ще 2 000 грн.':''),eff:S=>{add(S);hit(S,d5(S));if(S.team<2000)S.loss+=2000;}},
  {id:'client',t:'choice',head:'Місяць 6 · Найбільший клієнт',text:S=>'Ліцей № 3 — ваш найбільший клієнт. '+(S.dev>=1000?'На пошук клієнтів щомісяця йшли гроші, тож замовляють уже чотири школи, і ліцей дає лише п’яту частину замовлень — 14 худі з 70.':'Нових клієнтів майже ніхто не шукав, тож ліцей дає 40 % замовлень — 28 худі з 70.')+' Завуч пише: «Інша майстерня пропонує нам худі по 550 грн. Дасте таку саму ціну — лишимося з вами». Твоя ціна — 650 грн, маржа з худі — 210 грн.',q:'Що ти відповіси завучеві?',o:[
   {l:'Запропонувати 620 грн — за умови договору на рік і фіксованого обсягу',p:2,eff:S=>{S.loss+=big(S)*30;S.f.cl=2;},fb:S=>'Ліцей каже «так»: знижка 30 грн коштує майстерні '+PG(big(S)*30)+' на місяць, зате замовлення гарантовані на рік уперед.'},
   {l:'Відмовити: ціна для всіх однакова',p:S=>S.dev>=1000?1:0,eff:S=>{S.loss+=big(S)*210;S.f.cl=1;},fb:S=>S.dev>=1000?'Ліцей пішов. Це мінус 14 худі й 2 940 грн маржі на місяць — боляче, але майстерня встоїть.':'Ліцей пішов, а з ним 28 худі й 5 880 грн маржі на місяць — понад дві третини прибутку.'},
   {l:'Погодитися на 550 грн: втрачати такого клієнта не можна',p:0,eff:S=>{S.loss+=(big(S)+oth(S))*100;S.f.cl=0;},fb:S=>'Мінус 100 грн із кожного худі для ліцею — '+PG(big(S)*100)+' на місяць. За тиждень про знижку дізналися інші школи й зажадали такої самої: ще '+oth(S)+' худі, тобто '+PG(oth(S)*100)+'. Разом — '+PG((big(S)+oth(S))*100)+' на місяць.'}]},
  {id:'m6',t:'event',head:'Місяць 6 · Що справдилося, а що ні',text:S=>'Пів року позаду. '+cn(S)+' Соля дістає свій список і ставить позначки. Справдилися: відключення світла, поломка преса'+(S.f.qc<2?', брак':'')+', тиск найбільшого клієнта'+(S.team<2000?', а Марко майже покинув справу':'')+'. Не справдилися: зрив поставки, пожежа, крадіжка'+(S.f.qc===2?'. Браку запобігла перевірка':'')+(S.team>=2000?'. Команда на місці':'')+'. Соля: «Подія з 20 % сталася, а з 50 % — ні. Тому готуються не до того, що станеться напевно, а до того, чого не можна собі дозволити».',eff:S=>{add(S);}},
  {id:'months',t:'calc',head:'Місяць 6 · Запас міцності',text:S=>'У резервному фонді — '+PG(S.res)+(S.debt>0?', борг — '+PG(S.debt):'')+'. Постійні витрати майстерні — 6 300 грн на місяць.',q:'На скільки місяців постійних витрат вистачить резервного фонду? Округли до десятих.',ans:S=>mth(S),tol:0.05,unit:'міс.',hint:'Поділи резервний фонд на постійні витрати за місяць.',sol:S=>PN(S.res)+' : 6 300 ≈ '+PN(mth(S))+' міс. '+(mth(S)>=1?'Мету Солі — резерв на місяць постійних витрат — досягнуто.':'До мети Солі — резерву на місяць постійних витрат — фонд не дотягнув.')+(S.debt>0?' А борг '+PG(S.debt)+' означає, що найближчі внески підуть не в резерв.':'')},
  {id:'share',t:'calc',head:'Місяць 6 · Ціна ризиків',text:S=>'За пів року майстерня мала заробити 50 400 грн прибутку — шість місяців по 8 400 грн. Події, що справдилися, забрали '+PG(S.loss)+'. На захист (запасні варіанти, перевірки, поліс) витрачено '+PG(prot(S))+'.',q:'Скільки відсотків піврічного прибутку забрали втрати й захист разом? Округли до цілого числа.',ans:S=>Math.round((S.loss+prot(S))/50400*100),tol:0.5,unit:'% прибутку',hint:'Додай втрати й витрати на захист. Поділи суму на 50 400 грн і помнож на 100.',sol:S=>{const t=S.loss+prot(S),x=Math.round(t/50400*100);return PN(S.loss)+' + '+PN(prot(S))+' = '+PG(t)+'. '+PN(t)+' : 50 400 × 100 ≈ '+x+' %. '+(t<12000?'Не весь захист знадобився. Але разом із втратами це менше, ніж забрала б сама лише поломка преса без поліса — 12 000 грн.':x<=45?'Найдорожче обійшлися ризики, що лишилися без захисту або з захистом, який не бив у причину.':'Ті самі події коштували б у кілька разів менше з підготовкою: перевірка плівки, надійний поліс, план на відключення.');}}],
 finish:S=>{const lvl=S.debt===0&&S.loss<=15000&&S.res>=3000?2:S.debt<=6000&&S.loss<=25000?1:0;return{level:lvl,title:['Ризики виявилися сильнішими','Майстерня встояла, але дорогою ціною','«Відбиток» готовий до несподіванок'][lvl],text:'За пів року: втрати від ризиків — '+PG(S.loss)+', на захист витрачено '+PG(prot(S))+' — разом '+PG(S.loss+prot(S))+' із 50 400 грн можливого прибутку. Резервний фонд — '+PG(S.res)+', борг — '+PG(S.debt)+'.',tips:[
  S.f.sup===2?'Запасний постачальник не знадобився — і це не помилка. Захист оцінюють за тим, чи витримала б майстерня удар, а не чи він стався.':S.f.sup===0?'Зрив поставки не стався, і без захисту обійшлося. Це везіння, а не розрахунок: ризик 50 % × 6 000 грн лишається й на наступні пів року.':(S.f.map?'Карта ризиків дала цифри для кожного рішення.':'Спершу оцінюй кожен ризик: імовірність × наслідки.')+' 3 000 грн за «пріоритет» — дорожче, ніж другий постачальник, а залежність від одного лишилася.',
  S.f.ins>=1?(S.f.claim<2?'Поліс був, але умови договору порушено: повідомляй страховика одразу й нічого не ремонтуй до огляду.':S.f.ins===2?'Перевірена страхова компанія й дії за договором перетворили збиток 12 000 грн на 2 000 грн.':'Дешевий поліс із франшизою 8 000 грн покрив лише третину ремонту. Порівнюй не тільки ціну поліса, а й франшизу.'):S.f.ins===-1?'Страховика обирають не за ціною й обіцянками: перевір, чи є компанія в реєстрі, що покриває поліс і яка франшиза.':'Рідкісний, але руйнівний ризик — прес за 12 000 грн — варто було застрахувати надійним полісом.',
  S.f.loan?'Швидка позика під 1 % на день зробила ремонт на 3 600 грн дорожчим. Дешевші гроші — власний резерв або позика без відсотків у близьких.':S.debt>0?'Борг '+PG(S.debt)+' з’явився там, де не вистачило резерву або дешевшого захисту.':S.res>=6300?'Резервний фонд досі покриває місяць постійних витрат — самострахування спрацювало.':'Боргу немає, але резерв менший за місяць постійних витрат: '+(S.r>=2100?'його з’їли втрати, від яких був дешевший захист.':'відкладай у фонд щонайменше 2 100 грн щомісяця.')]};},
 terms:[['Ризик','можлива подія, яка завдасть бізнесу втрат, якщо справдиться'],['Оцінка ризику','імовірність події, помножена на суму можливих втрат'],['Самострахування','власний резервний фонд для покриття несподіваних втрат'],['Страхування','передання ризику страховій компанії за плату (страховий платіж)'],['Франшиза','частина збитку, яку за договором страхування власник покриває сам']]};
})());

PFG_TOPICS.push((()=>{
 /* допоміжні функції теми */
 const KS=['vid','pub','tch','fly','news'];
 const NM={vid:'відео',pub:'шкільний паблік',tch:'зразки для класних керівників',fly:'листівки',news:'газета'};
 const CAC={vid:150,pub:200,tch:125,fly:500,news:2000};       // скільки гривень реклами в каналі приводить одне замовлення
 const CAPA={vid:12,pub:8,tch:12,fly:99,news:99},CAPB={vid:6,pub:4,tch:6,fly:99,news:99};   // межа аудиторії каналу
 const raw=(v,cap)=>{const o={};KS.forEach(k=>{o[k]=Math.min(cap[k],Math.floor((v[k]||0)/CAC[k]));});return o;};
 const sum=o=>KS.reduce((s,k)=>s+o[k],0);
 const mm=S=>S.f.msg===0?1.3:S.f.msg===1?0.7:S.f.msg===-1?0.7:1;
 const resA=S=>{const r=raw(S.a,CAPA),o={};KS.forEach(k=>{o[k]=Math.round(r[k]*mm(S));});return o;};
 const tm=S=>S.trust>=70?1.2:S.trust>=40?1:0.6;
 const resB=S=>{const r=raw(S.b,CAPB),o={};KS.forEach(k=>{o[k]=Math.round(r[k]*tm(S)*(S.f.msg===1?0.7:1));});return o;};
 const org=S=>S.trust>=70?6:S.trust>=50?3:0;
 const blg=S=>S.f.blog===2||S.f.blog===0?5:0;
 const tr=(S,x)=>{S.trust=Math.max(0,Math.min(100,S.trust+x));};
 const top=S=>KS.reduce((b,k)=>S.oA[k]>S.oA[b]?k:b,'vid');
 const table=S=>KS.filter(k=>S.a[k]>0).map(k=>NM[k]+' — '+PG(S.a[k])+', замовлень: '+S.oA[k]).join('; ');
 const costs=S=>KS.filter(k=>S.a[k]>0).map(k=>NM[k]+' — '+(S.oA[k]>0?PG(Math.round(S.a[k]/S.oA[k]))+' за замовлення':'жодного замовлення')).join('; ');
 const full=S=>KS.filter(k=>S.a[k]>CAPA[k]*CAC[k]&&CAPA[k]<99);
 const zam=n=>n+(n%100>=11&&n%100<=14?' замовлень':n%10===1?' замовлення':n%10>=2&&n%10<=4?' замовлення':' замовлень');   // називний/знахідний
 const zamG=n=>n+(n%10===1&&n%100!==11?' замовлення':' замовлень');                                                  // родовий (із N …)
 const reach=S=>[S.a.vid>0?'відео зібрало '+PN(S.a.vid*6)+' переглядів':'',S.a.pub>0?'допис у пабліку побачили '+PN(S.a.pub*3)+' людей':'',S.a.tch>0?'зразки потримали в руках '+Math.floor(S.a.tch/125)+' '+PW(Math.floor(S.a.tch/125),'класний керівник','класні керівники','класних керівників'):'',S.a.fly>0?'листівки розлетілися за день':'',S.a.news>0?'газета вийшла накладом 12 000 примірників':''].filter(x=>x).join(', ');
 const eq=(a,b)=>a%b===0?' = ':' ≈ ';
 const prof=S=>S.ord*210-6000;
 const pscore=(v,cap,hi,lo)=>{const n=sum(raw(v,cap));return n>=hi?2:n>=lo?1:0;};
 return {id:'9-6',sec:'9a',title:'Реклама та комунікації — рушії бізнесу',minutes:30,
 intro:'У «Відбитка» — майстерні, де ти, Соля й Марко друкуєте принти на худі для класів і шкільних команд, — є 6 000 грн на чотиритижневу рекламну кампанію. Ти обереш канали й текст реклами, порахуєш, у скільки обходиться кожне замовлення, відповіси на скаргу й публічний коментар, а на останній тиждень перерозподілиш бюджет за власними результатами. Від каналів залежать замовлення, від чесності — довіра, а від довіри — те, що буде наприкінці.',
 init:()=>({bud:6000,ord:0,trust:50,o2:0,cancel:0,cancelSoc:0,socn:0,a:{vid:0,pub:0,tch:0,fly:0,news:0},b:{vid:0,pub:0,tch:0,fly:0,news:0},oA:{vid:0,pub:0,tch:0,fly:0,news:0},f:{}}),
 meters:[{k:'bud',label:'Рекламний бюджет',unit:'грн'},{k:'ord',label:'Замовлення',unit:'шт.'},{k:'trust',label:'Довіра клієнтів',unit:'зі 100'}],
 steps:[
  {id:'aud',t:'choice',head:'До старту · Кому рекламуємо',text:'Мета кампанії — замовлення на худі з принтом. Носять їх підлітки 13–17 років, а замовлення на цілий клас зазвичай оформлює класний керівник. Марко вже все вирішив: «Що більше людей побачить рекламу, то краще. Беремо все найголосніше!»',q:'З чого ти почнеш?',o:[
   {l:'Опитати 20 учнів і 5 класних керівників: звідки вони дізнаються про такі речі',p:2,eff:S=>{S.f.aud=1;},fb:'Тепер ти знатимеш не «де голосніше», а де справді бувають твої покупці. Результати опитування побачиш, коли ділитимеш бюджет.'},
   {l:'Орієнтуватися на себе й друзів: ми ж самі підлітки',p:1,eff:S=>{},fb:'Частково це спрацює: твої покупці — такі самі підлітки, як ти. Але класні керівники шукають інформацію зовсім не там, де ти, — а про них так нічого й не відомо.'},
   {l:'Рекламуватися на все місто: хтось та й замовить',p:0,eff:S=>{},fb:'Реклама «для всіх» коштує стільки само, а більшість тих, хто її побачить, ніколи не купить худі з принтом для класу. Бюджет доведеться ділити навмання.'}]},
  {id:'mix',t:'plan',head:'До старту · Канали реклами',text:S=>'Реклама — це оплачене повідомлення про товар, а канал — шлях, яким воно доходить до людини. На перші два тижні ти виділяєш 4 000 грн, ще 2 000 грн лишаєш на фінал. Канали на вибір: короткі відео в соцмережі з показом підліткам твого міста; допис у міському шкільному пабліку; зразки худі з пропозицією для класних керівників (їх розвезе Соля); листівки біля шкіл; оголошення в міській газеті.'+(S.f.aud?' Опитування показало: із 20 учнів 15 дізнаються про новинки з коротких відео, 11 — зі шкільного пабліка, 2 звертають увагу на листівки, газету не читає ніхто. Із 5 класних керівників 4 хочуть побачити зразок і отримати пропозицію особисто, один читає газету.':' Де саме бувають твої покупці, ти точно не знаєш — доведеться покладатися на відчуття.'),q:'Скільки гривень ти спрямуєш у кожен канал?',
   fields:[{k:'vid',label:'Короткі відео в соцмережі'},{k:'pub',label:'Допис у шкільному пабліку'},{k:'tch',label:'Зразки й пропозиція класним керівникам'},{k:'fly',label:'Листівки біля шкіл'},{k:'news',label:'Оголошення в міській газеті'}],
   total:S=>4000,
   best:S=>({vid:1500,pub:1000,tch:1500,fly:0,news:0}),
   eff:(S,v)=>{KS.forEach(k=>{S.a[k]=v[k]||0;});S.bud-=4000;S.f.mix=pscore(v,CAPA,22,12);},
   score:(S,v)=>{const p=pscore(v,CAPA,22,12),w=(v.fly||0)+(v.news||0);return p===2?{p:2,fb:'Гроші розійшлися між кількома каналами, і жоден не забрав усе. Чи справді там бувають твої покупці — покажуть замовлення за два тижні.'}:p===1?{p:1,fb:'У цього плану є слабке місце, але зараз його не видно. Його покажуть замовлення за два тижні — якщо буде як порахувати, звідки вони прийшли.'}:{p:0,fb:'Гроші пішли в роботу. Чи бувають твої покупці там, куди ти їх спрямовуєш, — на це запитання відповість не план, а замовлення за два тижні.'};}},
  {id:'msg',t:'choice',head:'До старту · Рекламне повідомлення',text:'Канали обрано — тепер текст. Факти такі: худі коштує 650 грн, замовлення ви виконуєте за 7 днів, принт витримує щонайменше 30 прань (перевіряли самі). У місті є конкурент — майстерня «Фарба».',q:'Який текст піде в рекламу?',o:[
   {l:'«Худі з принтом вашого класу — 650 грн, готово за 7 днів. Принт перевірено 30 праннями. Замовляйте за посиланням»',p:2,eff:S=>{S.f.msg=2;tr(S,5);},fb:'Конкретно, правдиво і з закликом до дії. Усе обіцяне ти можеш виконати — саме за це потім радять друзям.'},
   {l:'«Майстерня „Відбиток“. Друк на тканині. Працюємо другий рік»',p:1,eff:S=>{S.f.msg=1;},fb:'Усе правда, але незрозуміло, що саме ти пропонуєш, скільки це коштує і що робити далі. Таку рекламу гортають не помітивши.'},
   {l:'«Найкращі худі в місті! Готово за 2 дні! Принт не зітреться ніколи!»',p:0,eff:S=>{S.f.msg=0;},fb:'Звучить гучно, і замовлень спершу буде більше. Але «2 дні» й «ніколи» — неправда. Реклама має бути правдивою, а кожну обіцянку клієнт перевірить на собі.'},
   {l:'«Не несіть гроші у „Фарбу“: там принт злазить після першого прання. У нас — якість»',p:0,eff:S=>{S.f.msg=-1;},fb:'Реклама не має принижувати конкурентів чи вводити людей в оману. Доказів у тебе немає, а «Фарба» таку рекламу неодмінно помітить.'}]},
  {id:'track',t:'choice',head:'До старту · Як рахувати результат',text:'Марко: «Запустимо — і побачимо, чи пішли замовлення». Соля: «А як ми дізнаємося, яка саме реклама їх привела?»',q:'Як ти вимірюватимеш результат?',o:[
   {l:'Дати кожному каналу свій промокод і додати у форму замовлення запитання «Звідки ви про нас дізналися?»',p:2,eff:S=>{S.f.track=1;},fb:'Тепер кожне замовлення «підписане» каналом. За два тижні ти знатимеш, яка реклама приводить клієнтів, а яка лише витрачає гроші.'},
   {l:'Порівняти кількість замовлень до кампанії й після неї',p:1,eff:S=>{S.f.track=0;},fb:'Ти побачиш, чи спрацювала реклама загалом. Але не дізнаєшся, який канал привів клієнтів, а який просто з’їв гроші.'},
   {l:'Стежити за переглядами й вподобайками: де їх більше, той канал і кращий',p:0,eff:S=>{S.f.track=0;S.f.likes=1;},fb:'Перегляди й вподобайки показують увагу, а не замовлення. Оголошення можуть побачити тисячі людей — і жоден нічого не купить.'}]},
  {id:'w2',t:'event',head:'Тиждень 2 · Перші результати',text:S=>{const o=resA(Object.assign({},S)),n=sum(o),T=Object.assign({},S,{oA:o}),fu=full(S);return 'Минуло два тижні, 4 000 грн витрачено. Реклама привела '+zam(n)+'.'+(S.f.msg===0?' Гучні обіцянки спрацювали: замовлень приблизно на третину більше, ніж дав би чесний текст.':S.f.msg===1?' Текст без ціни й пропозиції мало кого зачепив: майже третина тих, хто міг би замовити, просто прогорнула рекламу.':S.f.msg===-1?' Власниця «Фарби» поскаржилася на неправдиве порівняння всюди, де побачила цю рекламу. Частину оголошень довелося зняти, а на сторінці майстерні питають, де докази.':'')+(S.f.track?' Промокоди показали, звідки прийшли клієнти: '+table(T)+'.'+(fu.length?' У каналі «'+NM[fu[0]]+'» останні гривні вже нікого не привели: усі, кого він міг охопити за два тижні, рекламу побачили.':''):S.f.likes?' Цифри охоплення вражають: '+reach(S)+'. Але скільки з цих людей щось замовили — невідомо.':' Який канал привів клієнтів, а який ні — невідомо: замовлення ніхто не позначав.');},eff:S=>{S.oA=resA(S);S.o2=sum(S.oA);S.ord+=S.o2;if(S.f.msg===-1)tr(S,-15);}},
  {id:'cac',t:'calc',head:'Тиждень 2 · Ціна одного замовлення',text:S=>'За два тижні на рекламу пішло 4 000 грн. '+(S.o2>0?'Вона привела '+zam(S.o2)+'.':'Вона не привела жодного замовлення.'),q:S=>S.o2>0?'Скільки гривень реклами в середньому коштувало одне замовлення? Округли до цілого числа.':'Скільки гривень рекламного бюджету витрачено без жодного замовлення?',ans:S=>S.o2>0?Math.round(4000/S.o2):4000,tol:1,unit:'грн',hint:'Поділи витрати на рекламу на кількість замовлень, які вона привела.',sol:S=>{if(!S.o2)return 'Усі 4 000 грн. Реклама, яку не бачать твої покупці, не коштує дешевше — вона просто нічого не дає.';const x=Math.round(4000/S.o2);return '4 000 : '+S.o2+eq(4000,S.o2)+PG(x)+'. Це вартість залучення одного замовлення. Маржа з худі — 210 грн: '+(x<210?'після реклами з кожного замовлення лишається близько '+(210-x)+' грн.':x===210?'реклама забирає її повністю.':'реклама коштує дорожче, ніж приносить замовлення, — на '+(x-210)+' грн.');}},
  {id:'chan',t:'calc',when:S=>S.f.track===1&&S.o2>0,head:'Тиждень 2 · Канали поодинці',text:S=>{const k=top(S);return 'Середня ціна приховує різницю між каналами. Найбільше замовлень дав канал «'+NM[k]+'»: витрачено '+PG(S.a[k])+', замовлень — '+S.oA[k]+'.';},q:'Скільки гривень реклами коштувало одне замовлення з цього каналу? Округли до цілого числа.',ans:S=>{const k=top(S);return Math.round(S.a[k]/S.oA[k]);},tol:1,unit:'грн',hint:'Поділи витрати саме на цей канал на кількість замовлень із нього.',sol:S=>{const k=top(S);return PN(S.a[k])+' : '+S.oA[k]+eq(S.a[k],S.oA[k])+PG(Math.round(S.a[k]/S.oA[k]))+'. Усі канали поруч: '+costs(S)+'. Канал окупається, якщо замовлення з нього дешевше за маржу — 210 грн.';}},
  {id:'back',t:'calc',head:'Тиждень 2 · Чи окупилася реклама',text:S=>'Кожне замовлення — це 210 грн маржі: 650 грн ціни мінус 440 грн змінних витрат. За два тижні — '+zam(S.o2)+' і 4 000 грн на рекламу.',q:'Скільки гривень маржі принесла кожна гривня, вкладена в рекламу? Округли до десятих.',ans:S=>Math.round(S.o2*210/4000*10)/10,tol:0.05,unit:'грн',hint:'Спершу знайди всю маржу: 210 грн × кількість замовлень. Потім поділи її на 4 000 грн.',sol:S=>{const m=S.o2*210,x=Math.round(m/400)/10;return S.o2+' × 210 = '+PG(m)+' маржі. '+PN(m)+' : 4 000 ≈ '+PN(x)+'. '+(m>4000?'Маржа більша за витрати: за ці два тижні реклама окупилася, кожна вкладена гривня повернулася з надлишком.':'Маржа менша за витрати: за ці два тижні реклама не окупилася — з кожної вкладеної гривні повернулося близько '+PN(x)+' грн.');}},
  {id:'soc',t:'choice',head:'Тиждень 3 · Сторінка майстерні',text:'За два тижні на сторінку «Відбитка» в соцмережі підписалося 140 людей. Марко знайшов сервіс: «5 000 підписників за 300 грн! З такою цифрою нам довірятимуть одразу».',q:'Як ти розвиватимеш сторінку?',o:[
   {l:'Показувати справжнє: як друкують худі, фото класів у готових худі (з їхнього дозволу), і відповідати на кожен коментар',p:2,eff:S=>{S.f.soc=2;tr(S,10);},fb:'Людям цікаво бачити, хто і як робить їхні речі. А фото задоволеного класу переконує краще за будь-яку рекламу — його поширюють самі клієнти.'},
   {l:'Публікувати лише рекламні дописи з ціною й посиланням',p:1,eff:S=>{S.f.soc=1;},fb:'Сторінка-вітрина нікого не дратує, але й не дає приводу повертатися на неї чи показувати її друзям.'},
   {l:'Купити 5 000 підписників за 300 грн із рекламного бюджету',p:0,eff:S=>{S.f.soc=0;S.bud-=300;tr(S,-10);},fb:'Цифра виросла, але це порожні акаунти: вони не коментують і нічого не купують. Соцмережа бачить, що дописи нікого не цікавлять, і може показувати їх рідше. А уважні відвідувачі накрутку помічають.'}]},
  {id:'cmp',t:'choice',head:'Тиждень 3 · Скарга',text:S=>S.f.msg===0?'В особисті повідомлення пише Оля з 9-В: «У рекламі було „готово за 2 дні“. Минуло шість. Ви нас обманули?»':'В особисті повідомлення пише Оля з 9-В: «Обіцяли за 7 днів, сьогодні дев’ятий. Нам худі потрібні на суботу!» Затримка справжня: постачальник спізнився із заготовками.',q:'Що ти відповіси Олі?',o:[
   {l:'Вибачитися, пояснити причину, назвати точний день і запропонувати безкоштовну доставку до школи',p:2,eff:S=>{S.f.cmp=2;tr(S,8);},fb:S=>S.f.msg===0?'Оля отримала те, чого чекає кожен клієнт зі скаргою: її почули, перед нею вибачилися, їй назвали точний день. Але «готово за 2 дні» в рекламі прочитала не лише вона.':'Оля отримала те, чого чекає кожен клієнт зі скаргою: її почули, їй пояснили, їй назвали строк. Худі привезли до школи в п’ятницю — до суботи клас устиг.'},
   {l:'Надіслати шаблон: «Ваше замовлення в роботі, очікуйте»',p:1,eff:S=>{S.f.cmp=1;tr(S,-3);},fb:'Відповідь формально є, але на запитання Олі в ній немає нічого: ні причини, ні строку. Коли буде замовлення, вона так і не знає.'},
   {l:'Не відповідати, доки худі не будуть готові: сказати поки нічого',p:0,eff:S=>{S.f.cmp=0;tr(S,-10);},fb:'Мовчання клієнт читає як «їм байдуже». Скарга, на яку не відповіли в особистих, зазвичай з’являється там, де її побачать усі.'}]},
  {id:'neg',t:'event',head:'Тиждень 3 · Коментар на сторінці',text:S=>S.f.msg===0?'Під рекламним дописом на сторінці майстерні з’являється коментар: «Обман. Обіцяли 2 дні й „вічний“ принт. Чекали тиждень, а після прання букви потьмяніли». За вечір його вподобало 40 людей. Клієнти, які повірили у «2 дні», забирають передоплату: скасовано '+Math.round(S.o2*0.4)+' із '+zamG(S.o2)+'.':S.f.cmp<2?'Оля не дочекалася нормальної відповіді й написала під рекламним дописом на сторінці майстерні: «Замовили худі на свято — досі чекаємо. На повідомлення відповідають відписками або мовчать». Коментар уподобало 25 людей.':'Під рекламним дописом на сторінці майстерні з’являється коментар незнайомого користувача: «650 грн за худі? В інтернеті такі по 400. Наживаються на школярах». Кілька людей його вподобали.',eff:S=>{if(S.f.msg===0){S.cancel=Math.round(S.o2*0.4);S.cancelSoc=Math.min(S.cancel,S.oA.vid+S.oA.pub);S.ord-=S.cancel;tr(S,-15);}else if(S.f.cmp<2)tr(S,-5);}},
  {id:'pub',t:'choice',head:'Тиждень 3 · Публічна відповідь',text:'Цей коментар бачить кожен, хто заходить на сторінку, — тобто твої майбутні клієнти. Марко хоче його негайно видалити.',q:'Що ти зробиш?',o:[
   {l:S=>S.f.msg===0||S.f.cmp<2?'Відповісти публічно й спокійно: визнати помилку, вибачитися, написати, що саме вже виправлено, і запросити в особисті повідомлення':'Відповісти публічно й спокійно: пояснити, з чого складається ціна (якісна заготовка, принт на замовлення, 30 прань), і запросити подивитися зразки',p:2,eff:S=>{S.f.pub=2;tr(S,10);},fb:'Відповідаєш ти одній людині, а читають усі. Спокійна відповідь по суті показує сотням глядачів, як «Відбиток» поводиться, коли його критикують.'},
   {l:'Промовчати: за кілька днів усі забудуть',p:1,eff:S=>{S.f.pub=1;tr(S,-5);},fb:'Коментар без відповіді читають як «їм нема чого сказати». І він лишається першим, що бачать нові відвідувачі.'},
   {l:'Видалити коментар і заблокувати автора',p:0,eff:S=>{S.f.pub=0;tr(S,-15);},fb:'Знімок екрана з видаленим коментарем за вечір розійшовся шкільними чатами. Тепер обговорюють не худі, а те, що «Відбиток» затикає рота незгодним.'},
   {l:'Відповісти різко: «Не подобається — не замовляйте»',p:0,eff:S=>{S.f.pub=0;tr(S,-15);},fb:'Автор коментаря, може, й не замовить. Але разом із ним відповідь прочитали всі, хто ще вагався.'}]},
  {id:'blog',t:'choice',head:'Тиждень 3 · Блогер',text:'Одинадцятикласник Денис, у якого 8 000 підписників зі шкіл міста, готовий розповісти про «Відбиток» в обмін на худі зі своїм принтом.',q:'Про що ти з ним домовишся?',o:[
   {l:'Денис показує своє худі, чесно каже, що це реклама, і ділиться власними враженнями',p:2,eff:S=>{S.f.blog=2;tr(S,5);},fb:'Позначка «реклама» довіри не зменшує: підписники бачать справжнє худі на людині, яку знають, і розуміють умови.'},
   {l:'Відмовитися: реклама в блогерів — завжди нечесна',p:1,eff:S=>{S.f.blog=1;},fb:'Нечесною рекламу робить неправда, а не блогер. Відкрито позначена рекомендація людини, якій довіряють твої покупці, — один із найсильніших каналів у соцмережах.'},
   {l:'Денис розповідає, ніби худі — його власна покупка й жодної реклами тут немає: так більше повірять',p:0,eff:S=>{S.f.blog=0;tr(S,-12);},fb:'Реклама має бути впізнаваною: глядач має розуміти, що йому щось рекламують. У коментарях швидко з’ясували, що худі було подарунком, — і довіру втратили і Денис, і «Відбиток».'},
   {l:'Денис обіцяє підписникам «знижку 50 % лише сьогодні» — знижки не буде, але головне, щоб написали',p:0,eff:S=>{S.f.blog=-1;tr(S,-15);},fb:'Люди написали — і дізналися, що знижки немає. Така реклама вводить в оману: вона приводить не клієнтів, а ображених.'}]},
  {id:'re',t:'plan',head:'Тиждень 4 · Останні гроші',text:S=>'На фінальний тиждень лишилося '+PG(S.bud)+'. Канали ті самі. '+(S.f.track?'Твої дані за перші два тижні'+(S.cancel?' (пораховано до скасувань)':'')+': '+costs(S)+'. Канал окупається, якщо замовлення з нього коштує менше за маржу — 210 грн. ':'Даних по каналах у тебе немає: відомо лише, що 4 000 грн привели '+zam(S.o2)+'. ')+'Соля нагадує: за один тиждень канал охопить удвічі менше людей, ніж за два, тож вливати всі гроші в один — марно.',q:'Як ти розподілиш бюджет останнього тижня?',
   fields:[{k:'vid',label:'Короткі відео в соцмережі'},{k:'pub',label:'Допис у шкільному пабліку'},{k:'tch',label:'Зразки й пропозиція класним керівникам'},{k:'fly',label:'Листівки біля шкіл'},{k:'news',label:'Оголошення в міській газеті'}],
   total:S=>S.bud,
   best:S=>({vid:900,pub:S.bud-1650,tch:750,fly:0,news:0}),
   eff:(S,v)=>{KS.forEach(k=>{S.b[k]=v[k]||0;});S.f.re=pscore(v,CAPB,10,5);S.bud=0;},
   score:(S,v)=>{const p=pscore(v,CAPB,10,5),w=(v.fly||0)+(v.news||0);return p===2?{p:2,fb:'Гроші пішли в канали, де замовлення коштує дешевше за маржу, і розподілені так, щоб жоден не «захлинувся».'}:p===1?{p:1,fb:w>=600?PG(w)+' пішло на листівки й газету. '+(S.f.track&&(S.a.fly>0||S.a.news>0)?'За твоїми ж даними замовлення звідти найдорожчі або їх немає зовсім.':'Ці канали бачить багато людей, але мало хто з них замовляє худі для класу.'):'Канали обрано дієві, але в один із них пішло забагато: за тиждень він не встигне охопити стільки нових людей.'}:{p:0,fb:'Останні гроші пішли туди, де замовлення коштує в рази дорожче за маржу.'+(S.f.track?' Результати перших двох тижнів це показували.':' Без даних по каналах це було рішення наосліп.')};}},
  {id:'w4',t:'event',head:'Тиждень 4 · Фініш кампанії',text:S=>{const o=resB(S),n=sum(o),g=org(S),b=blg(S);return 'Останній тиждень. Платна реклама привела ще '+zam(n)+'.'+(S.trust>=70?' Довіра спрацювала як підсилювач: на рекламу майстерні, яку радять друзі, відгукуються охочіше.':S.trust<40?' Після історій у коментарях багато хто, побачивши рекламу «Відбитка», просто гортав далі.':'')+(g>0?' Ще '+zam(g)+' прийшли без жодної реклами: клієнти виклали фото у своїх худі й радили вас однокласникам.':' Замовлень «за порадою друзів» цього тижня не було.')+(S.f.blog===2?' Відео Дениса з позначкою «реклама» привело 5 замовлень.':S.f.blog===0?' Відео Дениса привело 5 замовлень, хоча в коментарях його досі питають, чому він не сказав, що це реклама.':'')+(S.f.blog===-1?' Під дописами Дениса й досі питають, де ж обіцяна «знижка 50 %».':'')+(S.f.soc===0?' А дописи на сторінці з 5 000 «підписників» збирають по три вподобайки — і це впадає в око.':'');},eff:S=>{const o=resB(S),g=org(S),b=blg(S),sa=S.oA.vid+S.oA.pub;S.ord+=sum(o)+g+b;S.socn=Math.max(0,Math.min(S.ord,sa-(S.cancelSoc||0)+o.vid+o.pub+g+b));}},
  {id:'roi',t:'calc',head:'Підсумок · Результат кампанії',text:S=>'Кампанію завершено. За чотири тижні вона привела '+zam(S.ord)+(S.cancel?' (скасовані вже не враховано)':'')+'. Кожне — це 210 грн маржі. На рекламу витрачено весь бюджет — 6 000 грн.',q:S=>prof(S)>=0?'Скільки гривень заробила майстерня на кампанії: маржа мінус витрати на рекламу?':'Скільки гривень втратила майстерня на кампанії? Запиши число без мінуса.',ans:S=>Math.abs(prof(S)),unit:'грн',hint:'Знайди маржу з усіх замовлень (210 грн × кількість) і порівняй її з 6 000 грн витрат на рекламу.',sol:S=>{const m=S.ord*210,p=prof(S);return S.ord+' × 210 = '+PG(m)+' маржі. '+PN(m)+' − 6 000 = '+PN(p)+' грн. '+(p>0?'Кампанія окупилася й принесла прибуток. А клієнти, які прийшли зараз, можуть замовити ще раз — уже без реклами.':p===0?'Кампанія вийшла рівно в нуль.':'Кампанія не окупилася: витрати на рекламу більші за маржу, яку вона принесла.');}},
  {id:'socp',t:'calc',head:'Підсумок · Сила соцмереж',text:S=>(S.f.track?'':'Після кампанії Соля все ж розпитала кожного замовника, звідки він дізнався про майстерню. ')+'Із '+zamG(S.ord)+' через соцмережі прийшло '+S.socn+': відео, шкільний паблік, блогер і фото, якими клієнти ділилися на своїх сторінках.',q:'Яку частку замовлень дали соцмережі? Запиши у відсотках, округли до цілого числа.',ans:S=>Math.round(S.socn/Math.max(1,S.ord)*100),tol:0.5,unit:'% замовлень',hint:'Поділи кількість замовлень із соцмереж на загальну кількість замовлень і помнож на 100.',sol:S=>{const x=Math.round(S.socn/Math.max(1,S.ord)*100);return S.socn+' : '+Math.max(1,S.ord)+' × 100'+eq(S.socn*100,Math.max(1,S.ord))+x+' %. '+(x>=50?(x===50?'Рівно половина':'Більшість')+' твоїх покупців приходить із соцмереж. Тому все, що там відбувається, — відгук, коментар, фото клієнта — працює на майстерню або проти неї.':'Соцмережі дали менше половини замовлень: більшість клієнтів прийшла іншим шляхом. Але й ці замовлення залежать від того, що про майстерню пишуть і показують у мережі.');}}],
 finish:S=>{const p=prof(S),lvl=p>=0&&S.trust>=55?2:p>=-2000&&S.trust>=25?1:0;return{level:lvl,title:['Кампанія не спрацювала','Кампанія спрацювала наполовину','Про «Відбиток» знають, і йому довіряють'][lvl],text:'За чотири тижні: '+zam(S.ord)+', витрачено 6 000 грн, '+(p>=0?'кампанія принесла '+PG(p)+' понад витрати':'кампанія дала збиток '+PG(-p))+'. Одне замовлення обійшлося в середньому в '+PG(Math.round(6000/Math.max(1,S.ord)))+' реклами за маржі 210 грн. Довіра клієнтів — '+PL(S.trust,'бал','бали','балів')+' зі 100.',tips:[
  S.f.mix===2&&S.f.re===2?'Гроші йшли в канали, де бувають твої покупці, і жоден не було перевантажено — так кожна гривня реклами приводить найбільше замовлень.':S.f.track?'Дані по каналах у тебе були, але бюджет розподілено не найкраще: частина грошей пішла в дорогі або переповнені канали. Щойно бачиш цифри — перекладай гроші туди, де замовлення дешевше.':'Без промокодів було невідомо, який канал приводить клієнтів. Спробуй пройти ще раз і з першого дня позначати, звідки прийшло кожне замовлення.',
  S.f.msg===2?'Правдивий і конкретний текст реклами не створив жодної обіцянки, яку довелося б виправдовувати.':S.f.msg===0?'Перебільшення в рекламі дало швидкі замовлення, а потім — скасування й публічний коментар. Обіцяй лише те, що точно виконаєш.':S.f.msg===-1?'Реклама, що принижує конкурента, нечесна й б’є по довірі до тебе. Розповідай про себе, а не про інших.':'Правдивої реклами мало — вона ще має казати, що ти пропонуєш, скільки це коштує і що робити далі.',
  S.f.pub===2&&S.f.cmp===2?'На скаргу й на публічний коментар дано швидку відповідь по суті — і невдоволення не перетворилося на втрачену репутацію.':'Скарги не зникають від мовчання чи видалення: відповідай швидко, спокійно й по суті — цю відповідь читають усі майбутні клієнти.']};},
 terms:[['Реклама','оплачене повідомлення про товар чи послугу, яке має спонукати людину до покупки'],['Канал поширення реклами','шлях, яким реклама доходить до людини: соцмережі, друковані матеріали, особиста зустріч, блогер'],['Недобросовісна реклама','реклама, що вводить споживачів в оману або може зашкодити людям чи іншим підприємцям: неправдиві обіцянки, вигадані знижки, приниження конкурентів'],['Вартість залучення клієнта','витрати на рекламу, поділені на кількість клієнтів (замовлень), яких вона привела'],['Окупність реклами','порівняння маржі від залучених замовлень із витратами на рекламу']]};
})());

PFG_TOPICS.push((()=>{
 /* допоміжні функції теми */
 const tr=(S,x)=>{S.trust=Math.max(0,Math.min(100,S.trust+x));};
 const TR=S=>PL(S.trust,'бал','бали','балів');
 const kwh=S=>S.f.batch?375:S.f.eve?625:500;                       // споживання за місяць залежить від режиму преса
 const pen=S=>(S.f.fake?16:0)+(S.f.vague?8:0);                      // розплата за показні обіцянки
 const n3of=S=>{const t=Math.max(0,S.trust-pen(S));return (t>=70?60:t>=50?50:40)-(S.f.help?0:5);};
 const pct=S=>S.f.ch||10;
 const rawDon=S=>S.p3*pct(S)/100;
 const mode=S=>S.f.ch?'ch':S.f.quiet?'q':'v';                        // як учень долучився до збору
 const half=S=>Math.round(S.don/20)*10;
 return {id:'9-7',sec:'9b',title:'Соціальна відповідальність бізнесу',minutes:30,
 intro:'Ти керуєш «Відбитком» — учнівською майстернею, що друкує на худі й шоперах для класів і шкільних команд. Попереду квартал: вересень, жовтень, листопад. Ти вирішуєш, що робити з відходами й енергією, кому й як допомагати, що розповідати про себе. Справжні вчинки додають довіри громади, показні — забирають її. А від довіри залежать замовлення й гроші.',
 init:()=>({cash:12000,trust:50,waste:20,vc:440,fixed:6300,n3:50,p2:0,p3:0,don:0,f:{}}),
 meters:[{k:'cash',label:'Гроші',unit:'грн'},{k:'trust',label:'Довіра громади',unit:'зі 100'},{k:'waste',label:'Відходи на вивезення',unit:'кг'}],
 steps:[
  {id:'p1',t:'calc',head:'Вересень · Перший підсумок',text:'«Відбиток» — це ти, Марко біля термопреса й Соломія з макетами. За вересень ви продали 40 худі по 650 грн. Змінні витрати — 440 грн на одне худі, постійні — 6 300 грн на місяць. У касі на початок кварталу було 12 000 грн.',q:'Який прибуток майстерня отримала за вересень?',ans:S=>2100,unit:'грн',hint:'Спершу знайди, скільки лишається з одного худі: 650 − 440. Помнож на 40 і відніми постійні витрати.',sol:S=>'З одного худі: 650 − 440 = 210 грн. 210 × 40 = 8 400 грн. 8 400 − 6 300 = 2 100 грн прибутку. Саме з прибутку майстерня вирішує, чим ділитися.',eff:S=>{S.cash+=2100;}},
  {id:'scraps',t:'choice',head:'Вересень · Залишки',text:'У кутку майстерні назбиралося 15 кг обрізків тканини та 6 худі з дрібним браком друку. Марко пропонує скласти все в мішки: наприкінці кварталу їх забере фірма, що вивозить відходи. Соломія каже, що волонтерки з хабу «Сітка» на сусідній вулиці плетуть маскувальні сітки й шукають тканину.',q:'Що зробити із залишками?',o:[
   {l:'Обрізки відвезти волонтеркам на сітки, а худі з браком продати зі знижкою, чесно показавши дефект',p:2,eff:S=>{S.cash+=1200;tr(S,3);S.f.reuse=1;},fb:'Відходів не додалося, каса отримала 1 200 грн за шість худі, а волонтерки — матеріал. Те, що для майстерні сміття, для когось — ресурс.'},
   {l:'Скласти все в коморі — розберемося, коли буде час',p:1,eff:S=>{S.waste+=8;S.f.store=1;},fb:'Нічого не викинуто, але й нікому не допомогло. Частину обрізків з’їла вогкість — це ще 8 кг відходів на вивезення.'},
   {l:'Скласти все в мішки на вивезення — швидко й без клопоту',p:0,eff:S=>{S.waste+=15;},fb:'Майстерня чиста за десять хвилин. Але до вивезення додалося 15 кг тканини, за які доведеться платити, а шість худі могли дати гроші.'}]},
  {id:'paint',t:'choice',head:'Вересень · Фарби',text:'Закінчується фарба. Постачальник пропонує дві нові. Водна фарба з сертифікатом безпеки: без різкого запаху, залишки можна здати, але худі подорожчає у виробництві на 10 грн. Фарба з розчинником: на 10 грн дешевша на кожному худі, але порожні банки — небезпечні відходи, і в кімнаті потрібна витяжка.',q:'Яку фарбу замовити?',o:[
   {l:'Водну з сертифікатом — і чесно написати про це на сторінці',p:2,eff:S=>{S.vc=450;S.waste=Math.max(0,S.waste-5);tr(S,3);S.f.eco=1;},fb:'Змінні витрати зросли до 450 грн на худі. Зате відходів на вивезення стало на 5 кг менше, а в майстерні чистіше повітря. Екологічна відповідальність має ціну — і ти її бачиш.'},
   {l:'Залишити звичну фарбу, нічого не міняти',p:1,eff:S=>{},fb:'Витрати ті самі, шкоди не додалося, але й кроку вперед немає.'},
   {l:'Дешеву з розчинником: 10 грн з кожного худі — це гроші',p:0,eff:S=>{S.vc=430;S.waste+=10;S.f.cheap=1;},fb:'Змінні витрати впали до 430 грн. Але додалося 10 кг банок, які не можна кидати у звичайний контейнер, і в майстерні тепер пахне хімією.'},
   {l:'Дешеву з розчинником, а на сторінці написати «100 % еко-друк» — так зараз модно',p:0,eff:S=>{S.vc=430;S.waste+=10;tr(S,4);S.f.cheap=1;S.f.green=1;},fb:'Підписникам подобається, вподобайок багато. Та слова не збігаються з ділом — це називають грінвошингом, і правда рано чи пізно випливає.'}]},
  {id:'press',t:'choice',head:'Вересень · Термопрес',text:'Термопрес і сушарка споживають 500 кВт·год електроенергії на місяць. За умовою задачі тариф — 4,32 грн за кВт·год, тож рахунок — 2 160 грн. Він уже входить у постійні витрати (6 300 грн). Марко помітив: прес гріється цілий день, навіть коли замовлень немає. Якщо друкувати партіями двічі на тиждень, вийде на 125 кВт·год менше, але клієнт іноді чекатиме день-два довше. Маркові зручніше, коли прес завжди гарячий.',q:'Як працюватиме прес із жовтня?',o:[
   {l:'Друкувати партіями двічі на тиждень і попереджати клієнтів про строк',p:2,eff:S=>{S.fixed=5760;tr(S,1);S.f.batch=1;},fb:'Споживання впаде до 375 кВт·год, а рахунок — на 540 грн (125 × 4,32). Постійні витрати тепер 5 760 грн на місяць. Клієнти спокійно чекають, коли знають дату наперед.'},
   {l:'Залишити як є: рахунок і так закладено у витрати',p:1,eff:S=>{},fb:'Нічого не змінилося: 540 грн щомісяця й далі гріють порожню майстерню.'},
   {l:'Тримати прес увімкненим ще й увечері — щоб брати термінові замовлення',p:0,eff:S=>{S.fixed=6840;S.f.eve=1;},fb:'Споживання зросло до 625 кВт·год, а рахунок — на 540 грн. Постійні витрати тепер 6 840 грн на місяць. Термінових замовлень за місяць прийшло лише два — вони цього не покрили.'}]},
  {id:'p2',t:'calc',head:'Жовтень · Прибуток',text:S=>'У жовтні «Відбиток» продав 50 худі по 650 грн. Змінні витрати на одне худі — '+PG(S.vc)+(S.vc===450?' (водна фарба)':S.vc===430?' (дешевша фарба)':'')+', постійні — '+PG(S.fixed)+(S.fixed!==6300?' (змінився рахунок за світло)':'')+'.',q:'Який прибуток за жовтень?',ans:S=>50*(650-S.vc)-S.fixed,unit:'грн',hint:S=>'З одного худі лишається 650 − '+S.vc+'. Помнож на 50 і відніми постійні витрати.',sol:S=>'(650 − '+S.vc+') × 50 = '+PG(50*(650-S.vc))+'. Мінус постійні '+PN(S.fixed)+': прибуток '+PG(50*(650-S.vc)-S.fixed)+'.'+(S.vc===450?' Безпечніша фарба коштувала 500 грн прибутку за місяць.':S.vc===430?' Дешева фарба додала 500 грн прибутку — побачимо, чого вона коштуватиме далі.':'')+(S.f.batch?' Друк партіями додав 540 грн.':S.f.eve?' Вечірня робота преса забрала 540 грн.':''),eff:S=>{S.p2=50*(650-S.vc)-S.fixed;S.cash+=S.p2;}},
  {id:'energy',t:'calc',head:'Жовтень · Рахунок за світло',text:S=>'Прийшов рахунок за електроенергію за жовтень. '+(S.f.batch?'Друк партіями спрацював: спожито 375 кВт·год замість звичних 500.':S.f.eve?'Прес грівся ще й вечорами: спожито 625 кВт·год замість звичних 500.':'Термопрес і сушарка спожили, як завжди, 500 кВт·год.')+' Тариф за умовою задачі — 4,32 грн за кВт·год. Соломія роздивляється квитанцію: у ціні енергії є податки, і сплачує їх кожен споживач просто в рахунку. За умовою задачі податки становлять шосту частину суми рахунку.',q:'Скільки гривень податків у рахунку «Відбитка» за жовтень?',ans:S=>kwh(S)*4.32/6,unit:'грн',hint:'Спершу знайди суму рахунку: кіловат-години × тариф. Потім поділи її на 6.',sol:S=>{const k=kwh(S),b=k*4.32;return k+' × 4,32 = '+PG(b)+' — сума рахунку. '+PN(b)+' : 6 = '+PG(b/6)+' — податки. '+(k===375?'За 500 кВт·год податків було б 360 грн.':k===625?'За звичних 500 кВт·год податків було б 360 грн, а за друку партіями — 270 грн.':'За друку партіями (375 кВт·год) податків було б 270 грн.')+' Податки на споживання енергії залежать від того, скільки її витрачено: менше кіловат-годин — менший і рахунок, і податки в ньому.';}},
  {id:'sponsor',t:'choice',head:'Жовтень · Команда «Крила»',text:S=>'Тренер шкільної волейбольної команди «Крила» просить допомогти з формою до обласних змагань: потрібно 12 футболок із номерами. «Можемо розмістити ваш логотип на формі й подякувати на змаганнях», — додає він. У касі зараз '+PG(S.cash)+'.',q:'Як учинить «Відбиток»?',o:[
   {l:'Стати спонсором: безкоштовно надрукувати номери й назву на 12 футболках, а команда розмістить логотип «Відбитка» на формі',p:2,eff:S=>{S.cash-=1200;tr(S,5);S.f.spons=1;},fb:'Матеріали коштували 1 200 грн. Команда має форму, а логотип майстерні побачать на змаганнях. Це спонсорство — чесний обмін, про який знають обидві сторони.'},
   {l:'Зробити благодійний внесок: передати команді 3 000 грн на форму й нічого не просити навзамін',p:1,eff:S=>{S.cash-=3000;tr(S,5);S.f.gift=1;},fb:'Це благодійність: допомога без жодних умов. Команда вдячна. Але 3 000 грн — більше, ніж увесь прибуток за вересень, а надрукувати форму власноруч коштувало б 1 200 грн.'},
   {l:'Чемно відмовити: майстерня ще надто мала для такого',p:1,eff:S=>{},fb:'Гроші цілі, стосунки не зіпсовано. Але команда поїде у старих футболках, а про «Відбиток» на змаганнях не почує ніхто.'},
   {l:'Сфотографуватися з командою, оголосити «Відбиток» «генеральним спонсором», а форму пообіцяти «трохи згодом»',p:0,eff:S=>{tr(S,3);S.f.fake=1;},fb:'Допис зібрав багато вподобайок і не коштував ні гривні. Проте змагання вже за три тижні, а обіцянку не виконано.'}]},
  {id:'news',t:'event',head:'Кінець жовтня · Що кажуть про «Відбиток»',text:S=>(S.f.green?'Мама одного з учнів, хімік за фахом, побачила на фото з майстерні банки з розчинником і написала в коментарях: «То де ж 100 % еко?» Допис розійшовся шкільними чатами.':S.f.eco?'Клас 9-Б обрав «Відбиток» серед трьох майстерень: батьки прочитали про водну фарбу із сертифікатом і вирішили, що дітям так безпечніше.':'Про фарби «Відбитка» ніхто нічого не каже: ні доброго, ні поганого.')+(S.f.reuse?' Хаб «Сітка» подякував майстерні за тканину на своїй сторінці.':'')+(S.f.spons?' «Крила» вийшли на змагання у формі з логотипом «Відбитка» — і вже двоє тренерів спитали про ціни.':S.f.gift?' «Крила» купили форму й подякували майстерні на шкільній лінійці.':''),eff:S=>{if(S.f.nw)return;S.f.nw=1;if(S.f.green)tr(S,-18);if(S.f.reuse)tr(S,2);}},
  {id:'art',t:'choice',head:'Листопад · Шкільний театр',text:'Шкільна театральна студія готує виставу до зимових свят. Грошей на афіші й 15 футболок для хору немає. Керівниця пані Леся просить про допомогу й одразу попереджає: «Реклами на афішах і на сцені не буде — це дитяча вистава».',q:'Що ти відповіси пані Лесі?',o:[
   {l:'Надрукувати афіші й футболки без жодних умов — як меценат',p:2,eff:S=>{S.cash-=900;tr(S,4);S.f.art=2;},fb:'Матеріали коштували 900 грн. Це меценатство: безкорислива підтримка мистецтва, без реклами навзамін. На прем’єрі пані Леся подякувала майстерні зі сцени — так вирішила вона сама.'},
   {l:'Запропонувати спонсорство: надрукуємо безкоштовно, якщо логотип «Відбитка» буде на афішах і футболках',p:1,eff:S=>{S.f.art=1;},fb:'Спонсорство — чесний обмін, але тут реклами не пропонували. Пані Леся подякувала й відмовилася: афіші діти намалювали від руки. Гроші цілі, а допомоги не вийшло.'},
   {l:'Надрукувати безкоштовно, а потім оголосити на сторінці «Ми — меценати мистецтва!» й попросити студію згадувати «Відбиток» у кожному дописі',p:0,eff:S=>{S.cash-=900;tr(S,-5);S.f.artshow=1;},fb:'Матеріали коштували 900 грн. Але меценат не вимагає реклами: коли за допомогу просять згадок у кожному дописі, це вже спонсорство без домовленості. Студії ніяково, і батьки це помітили.'}]},
  {id:'charity',t:'choice',head:'Листопад · Збір',text:S=>'Волонтерський фонд міста збирає на зарядну станцію для пункту незламності біля школи. Команда хоче долучитися. Прибуток за жовтень був '+PG(S.p2)+'. Соломія пропонує написати про участь на сторінці.',q:'Як «Відбиток» долучиться до збору?',o:[
   {l:'Оголосити наперед: 10 % прибутку за листопад, але не менше 400 грн, — на збір. І пообіцяти звіт із квитанцією',p:2,eff:S=>{S.f.ch=10;tr(S,3);},fb:'Обіцянка конкретна: кожен може порахувати й перевірити. І така сума майстерні до снаги.'},
   {l:'Оголосити наперед: 30 % прибутку за листопад, але не менше 400 грн, — на збір, зі звітом',p:1,eff:S=>{S.f.ch=30;tr(S,4);},fb:'Щедро, і обіцянку можна перевірити. Але майже третина прибутку — багато для майстерні, якій ще купувати фарбу й тканину на грудень.'},
   {l:'Без розголосу переказати 500 грн уже сьогодні',p:1,eff:S=>{S.cash-=500;S.f.quiet=1;tr(S,2);},fb:'Допомога справжня, і фонд отримав її одразу. Але про неї ніхто не знає, тож приклад «Відбитка» поки нікого не надихнув.'},
   {l:'Написати: «Частина коштів із кожного худі йде на допомогу» — без цифр',p:0,eff:S=>{S.f.vague=1;tr(S,2);},fb:'Звучить гарно. Тільки «частина» — це скільки? І куди саме? Обіцянку, яку не можна перевірити, легко не виконати.'}]},
  {id:'neighbor',t:'choice',head:'Листопад · Сусіди',text:'Уночі місто обстріляли. У пекарні «Крихта» через дорогу вибило всі вікна, залу засипало склом. Власниця пані Наталя розгублена: завтра вона має віддати замовлення на шкільний ярмарок. У «Відбитка» цього тижня теж щільний графік.',q:'Що зробить твоя команда?',o:[
   {l:'Прийти зранку втрьох прибирати скло, пустити пані Наталю пакувати замовлення у твоїй майстерні й замовити в неї обіди на тиждень',p:2,eff:S=>{S.cash-=600;tr(S,8);S.f.help=1;},fb:'Пів дня роботи й 600 грн на обіди. «Крихта» віддала замовлення вчасно. Сусіди, які підставляють плече одне одному, вистоюють разом.'},
   {l:'Передати пані Наталі 1 000 грн із каси на нові вікна',p:1,eff:S=>{S.cash-=1000;tr(S,4);S.f.money=1;},fb:'Гроші знадобляться, і пані Наталя вдячна. Але сьогодні їй найбільше потрібні були руки й місце для роботи.'},
   {l:'Опублікувати допис «Ми з вами, „Крихто“!» з логотипом «Відбитка»',p:0,eff:S=>{tr(S,-6);S.f.showy=1;},fb:'Скло пані Наталя прибирала сама до ночі. А під дописом спитали: «То ви допомогли чи лише логотип поставили?» Чужа біда — не привід для реклами.'},
   {l:'Нічого: у майстерні горить власне замовлення на 20 худі',p:0,eff:S=>{},fb:'Замовлення віддано вчасно. А сусідка залишилася наодинці з бідою.'}]},
  {id:'volunteer',t:'choice',head:'Листопад · Волонтерство',text:S=>'Хаб «Сітка» просить про допомогу: потрібні бирки з маркуванням на сітки, а друкувати на тканині поблизу вміє лише «Відбиток».'+(S.f.reuse?' Волонтерки вже знають майстерню — обрізки тканини з вересня пішли на їхні сітки.':'')+' Марко хоче кинути все й піти туди на два тижні.',q:'Як допомогти хабу?',o:[
   {l:'Домовитися про графік: щосуботи дві години друкуєте бирки на їхній тканині, замовлення клієнтів не зупиняються',p:2,eff:S=>{tr(S,5);S.f.vol=1;},fb:'Ти допомагаєш тим, що вмієш найкраще, і можеш робити це місяцями. Волонтерству потрібна регулярність, а не один порив.'},
   {l:'Зупинити замовлення на два тижні й усією командою працювати в хабі',p:1,eff:S=>{S.cash=Math.max(0,S.cash-2100);tr(S,3);S.f.vol=1;},fb:'Хаб вдячний, але три класи отримали худі із запізненням, і два з них забрали передоплату — мінус 2 100 грн. Якщо майстерня зупиниться, допомагати буде нічим.'},
   {l:'Прийти один раз усією командою, зробити фото для сторінки й повернутися до справ',p:0,eff:S=>{tr(S,-4);S.f.photo=1;},fb:'Бирок за годину надрукували сорок, а потрібно дві тисячі. Фото на сторінці вийшло гарне, та волонтерки більше не дзвонили.'}]},
  {id:'nov',t:'event',head:'Кінець листопада · Наслідки',text:S=>{const n=S.f.nov?S.n3:n3of(S),b=n+(S.f.help?0:5);return (S.f.fake?'«Крила» поїхали на змагання у старих футболках. Тренер написав у шкільному чаті: «Генерального спонсора ми так і не побачили». ':'')+(S.f.vague?'Під дописом про «частину коштів» з’явилося запитання: «Скільки саме і де квитанція?» Відповісти нічим. ':'')+(b===60?'Майстерню радять знайомим, тож замовлень у листопаді побільшало. ':b===40?'Про «Відбиток» у чатах говорять з недовірою — частина класів замовила худі деінде. ':'Замовлення йшли приблизно як у жовтні. ')+'Після обстрілу в районі на два дні зникло світло. '+(S.f.help?'Пані Наталя сама прийшла й протягнула подовжувач від свого генератора: «Ви мене виручили — тепер моя черга». Прес працював, жодне замовлення не зірвалося. ':'Прес стояв, генератора в майстерні немає — 5 замовлень довелося скасувати. ')+'Разом за листопад продано '+n+' худі (у жовтні було 50).';},eff:S=>{if(S.f.nov)return;const n=n3of(S);tr(S,-pen(S));S.n3=n;S.f.nov=1;}},
  {id:'p3',t:'calc',head:'Листопад · Прибуток',text:S=>'У листопаді продано '+S.n3+' худі по 650 грн. Змінні витрати — '+PG(S.vc)+' на худі, постійні — '+PG(S.fixed)+' на місяць.',q:'Який прибуток за листопад?',ans:S=>S.n3*(650-S.vc)-S.fixed,unit:'грн',hint:S=>'(650 − '+S.vc+') × '+S.n3+', потім відніми постійні витрати.',sol:S=>{const p=S.n3*(650-S.vc)-S.fixed;return '(650 − '+S.vc+') × '+S.n3+' = '+PG(S.n3*(650-S.vc))+'. Мінус '+PN(S.fixed)+': прибуток '+PG(p)+'. У жовтні було '+PG(S.p2)+': '+(p>S.p2?'прибуток зріс.':p<S.p2?'прибуток упав.':'прибуток не змінився.')+(S.n3!==50?' Різницю зробила кількість проданих худі: '+S.n3+' проти 50.':'');},eff:S=>{S.p3=S.n3*(650-S.vc)-S.fixed;S.cash+=S.p3;}},
  {id:'donate',t:'calc',head:'Листопад · Скільки на збір',text:S=>(mode(S)==='ch'?'Час виконувати обіцянку: '+S.f.ch+' % прибутку за листопад, але не менше 400 грн, — на зарядну станцію.':mode(S)==='q'?'На збір уже переказано 500 грн — без розголосу. Пані Ірина, наставниця майстерні, радить на майбутнє правило, яке кожен зможе перевірити: 10 % прибутку за місяць, але не менше 400 грн.':'Підписники чекають відповіді, скільки ж це — «частина коштів». Пані Ірина, наставниця майстерні, радить чесне правило: 10 % прибутку за місяць, але не менше 400 грн.')+' Прибуток за листопад — '+PG(S.p3)+'.',q:S=>mode(S)==='q'?'Скільки гривень вийшло б за цим правилом за листопад?':'Скільки гривень має переказати «Відбиток»?',ans:S=>Math.max(400,rawDon(S)),unit:'грн',hint:S=>'Знайди '+pct(S)+' % прибутку: поділи його на 100 й помнож на '+pct(S)+'. Потім порівняй результат із мінімумом — 400 грн.',sol:S=>{const r=rawDon(S),d=Math.max(400,r);return PN(S.p3)+' : 100 × '+pct(S)+' = '+PG(r)+'. '+(r>=400?'Це не менше за 400 грн, тож сума — '+PG(d)+'.':'Це менше за мінімум, тож сума — 400 грн.')+' Відсоток від прибутку — чесна міра: більший прибуток — більша допомога, і кожен може перевірити розрахунок.'+(mode(S)==='q'?(d<=500?' Уже переказані 500 грн цю суму покривають.':' Уже переказані 500 грн менші за неї на '+PG(d-500)+'.'):'');},eff:S=>{S.don=Math.max(400,rawDon(S));}},
  {id:'report',t:'choice',head:'Листопад · Звіт',text:S=>mode(S)==='ch'?'До переказу — '+PG(S.don)+'. Марко зітхає: «Нам іще тканину на грудень купувати. Може, перекажемо половину? Ніхто ж не рахуватиме».':mode(S)==='q'?'За правилом вийшло '+PG(S.don)+', а тихий внесок — 500 грн. Соломія питає, чи розповідати про нього на сторінці.':'Сума за правилом — '+PG(S.don)+'. Тепер треба вирішити, що з нею робити і що відповісти під дописом.',q:'Що ти зробиш?',o:[
   {l:'Переказати всю суму й опублікувати квитанцію та розрахунок',when:S=>mode(S)==='ch',p:2,eff:S=>{S.cash=Math.max(0,S.cash-S.don);tr(S,6);S.f.report=1;},fb:'Обіцянку дано, виконано й показано. Прозора благодійність працює як рекомендація: люди бачать, що твоєму слову можна вірити.'},
   {l:'Переказати всю суму, але нічого не публікувати: добро любить тишу',when:S=>mode(S)==='ch',p:1,eff:S=>{S.cash=Math.max(0,S.cash-S.don);tr(S,1);},fb:'Гроші дійшли до фонду, це головне. Але звіт було обіцяно — а без нього ніхто не знає, чи дотримано слова.'},
   {l:S=>'Переказати половину — '+PG(half(S))+', а в дописі написати «обіцянку виконано»',when:S=>mode(S)==='ch',p:0,eff:S=>{S.cash=Math.max(0,S.cash-half(S));tr(S,-14);S.f.cheat=1;},fb:'У касі лишилося більше. Але фонд публікує всі надходження, і хтось із батьків звірив цифри. Втрачену довіру половиною суми не викупиш.'},
   {l:S=>'Опублікувати квитанцію про 500 грн'+(S.don>500?', доплатити '+PG(S.don-500):'')+' та оголосити: відтепер — 10 % прибутку щомісяця зі звітом',when:S=>mode(S)==='q',p:2,eff:S=>{S.cash=Math.max(0,S.cash-Math.max(0,S.don-500));tr(S,6);S.f.report=1;},fb:'Квитанція з цифрою — це звіт, а не хвастощі. Під дописом двоє підприємців написали, що теж долучаться до збору.'},
   {l:'Нічого не публікувати: допомогу надано, цього досить',when:S=>mode(S)==='q',p:1,eff:S=>{},fb:'Гроші дійшли до фонду, і це головне. Але про внесок ніхто не знає, тож приклад «Відбитка» нікого не надихнув.'},
   {l:'Написати «ми передали значну суму на добру справу» — без цифр і квитанції',when:S=>mode(S)==='q',p:0,eff:S=>{tr(S,-6);S.f.brag=1;},fb:'«Значну суму» ніхто не може перевірити. Справжні 500 грн тепер виглядають як хвастощі без доказів.'},
   {l:'Переказати цю суму, показати квитанцію й оголосити: відтепер — 10 % прибутку щомісяця зі звітом',when:S=>mode(S)==='v',p:2,eff:S=>{S.cash=Math.max(0,S.cash-S.don);tr(S,6);S.f.report=1;},fb:'Розмиті слова стали цифрою, яку можна перевірити. Запитання під дописом зникли.'},
   {l:'Тихо переказати цю суму й більше не повертатися до теми',when:S=>mode(S)==='v',p:1,eff:S=>{S.cash=Math.max(0,S.cash-S.don);tr(S,1);},fb:'Гроші дійшли до фонду, це головне. Але запитання під дописом так і лишилося без відповіді.'},
   {l:'Написати «ми передали значну суму на добру справу» — без цифр, квитанцій і переказу',when:S=>mode(S)==='v',p:0,eff:S=>{tr(S,-10);S.f.cheat=1;},fb:'Гроші лишилися в касі, а «значну суму» ніхто не може перевірити. У коментарях уже жартують про «невидиму благодійність».'}]},
  {id:'wst',t:'calc',head:'Листопад · Вивезення відходів',text:S=>'За квартал у майстерні зібралося '+S.waste+' кг відходів: упаковка, зіпсована плівка'+(S.f.cheap?', банки від фарби з розчинником':'')+(S.f.reuse?'':', обрізки тканини')+'. Кидати їх у шкільний контейнер не можна. Фірма, що вивозить і утилізує такі відходи, бере 12 грн за кілограм.',q:'Скільки гривень коштуватиме вивезення?',ans:S=>S.waste*12,unit:'грн',hint:'Помнож кількість кілограмів на ціну за кілограм.',sol:S=>{const w=[S.f.reuse?'':'обрізки могли піти волонтеркам',S.f.eco?'':'водна фарба лишає менше відходів'].filter(x=>x);return S.waste+' × 12 = '+PG(S.waste*12)+'. За відходи платить той, хто їх створив.'+(w.length?' Найменший можливий рахунок — 180 грн за 15 кг: '+w.join(', а ')+'.':' Це найменший можливий рахунок: залишки пішли в діло, а не на звалище.');},eff:S=>{S.cash=Math.max(0,S.cash-S.waste*12);}},
  {id:'echo',t:'event',head:'Грудень на порозі',text:S=>'Квартал завершено. Довіра громади — '+TR(S)+' зі 100. '+(S.trust>=65?'Директорка ліцею з сусіднього району телефонує сама: «Мені вас порадили троє людей. Беремо 80 худі на випуск». Клієнти приходять за порадою знайомих, а не через рекламу.':S.trust>=50?'Замовлення йдуть рівно: клієнти повертаються, але нових приводять рідко. Про «Відбиток» кажуть «нормальні», а не «свої».':'Два класи, що збиралися замовляти, пішли до іншої майстерні. У чатах про «Відбиток» пишуть: «Гарно говорять, а на ділі…»')+' Пані Ірина пропонує скласти бюджет відповідальності на наступний квартал.'},
  {id:'csr',t:'plan',head:'Грудень · Бюджет відповідальності',text:'На наступний квартал команда відкладає 4 000 грн. Розподіли їх повністю. Довкілля — контейнери для сортування й здавання плівки на переробку: потрібно щонайменше 1 000 грн. Громада — підтримка шкільних команд і зборів: щонайменше 1 000 грн. Команда — респіратори, витяжка, навчання для Марка й Соломії: щонайменше 500 грн. Розповідь — фото й відео про зроблене. Пані Ірина радить: на розповідь — не більше чверті бюджету.',q:'Скільки гривень на кожен напрям?',
   fields:[{k:'eco',label:'Довкілля'},{k:'com',label:'Громада'},{k:'team',label:'Безпека й навчання команди'},{k:'pr',label:'Розповідь про зроблене'}],
   total:S=>4000,best:S=>({eco:1300,com:1500,team:800,pr:400}),
   eff:(S,v)=>{S.cash=Math.max(0,S.cash-4000);S.f.prBig=v.pr>1000?1:0;},
   score:(S,v)=>{const lack=[v.eco<1000?'довкілля':'',v.com<1000?'громаді':'',v.team<500?'безпеці команди':''].filter(x=>x);if(v.pr>2000)return{p:0,fb:'Більше половини бюджету — на розповідь про добрі справи, а на самі справи лишилося мало. Це вже реклама, перевдягнена у відповідальність, і громада це помітить.'};if(!lack.length&&v.pr<=1000)return{p:2,fb:'Гроші пішли на справи, а на розповідь — стільки, скільки треба, щоб про них дізналися. Відповідальність починається зі своєї команди й своїх відходів.'};return{p:lack.length>=2?0:1,fb:(lack.length?'Забракло грошей '+lack.join(' і ')+': тут сума менша за потрібний мінімум.':'На справи вистачило.')+(v.pr>1000?' А на розповідь пішло більше чверті бюджету — розповідь не має переважати справи.':'')+(v.team<500?' Відповідальний бізнес спершу дбає про своїх людей.':'')};}}],
 finish:S=>{const bad=(S.f.green?1:0)+(S.f.fake?1:0)+(S.f.cheat?1:0);const show0=(S.f.showy?1:0)+(S.f.photo?1:0)+(S.f.artshow?1:0);const lvl=S.trust>=65&&S.waste<=28&&bad+show0===0&&S.cash>=11000?2:S.trust>=45&&bad<=1?1:0;
  const show=[S.f.green?'«100 % еко» з розчинником':'',S.f.fake?'спонсорство лише на фото':'',S.f.cheat?'звіт, що не збігся з ділом':'',S.f.showy?'допис із логотипом замість допомоги сусідці':'',S.f.photo?'волонтерство заради фото':'',S.f.artshow?'«меценатство» з вимогою реклами':''].filter(x=>x);
  return{level:lvl,title:['«Відбитку» більше не вірять','«Відбиток» втримався, але без довіри «на виріст»','«Відбиток» — свій для громади'][lvl],text:'За квартал: у касі — '+PG(S.cash)+' (після того як 4 000 грн відкладено на наступний квартал), довіра громади — '+TR(S)+' зі 100, вивезено відходів — '+S.waste+' кг. У листопаді продано '+S.n3+' худі проти 40 у вересні.',tips:[
   show.length?'Показні вчинки повернулися: '+show.join('; ')+'. Кожен такий крок забрав більше довіри, ніж приніс.':'Жодної показухи: обіцянки збігалися з ділом, а цифри можна було перевірити.',
   S.f.help?'Коли зникло світло, пані Наталя поділилася генератором. Сусіди, які підтримують одне одного, стійкіші.':S.f.money?'Гроші на вікна пані Наталі знадобилися. Та найбільше їй потрібні були руки й місце для роботи — іноді допомога ділом важить більше за гроші.':'Коли зникло світло, виручити майстерню було нікому. Подумай, кому з сусідів можеш допомогти ти.',
   S.waste>28?'Відходів забагато — '+S.waste+' кг, і за кожен кілограм довелося платити. Обрізки можна віддавати, фарбу обирати безпечнішу.':S.f.reuse&&!S.f.cheap?'Відходів небагато: залишки знайшли нового власника, а фарба не додала небезпечних банок.':'Відходів — '+S.waste+' кг. Найменше було б 15 кг: обрізки потрібні волонтеркам, а водна фарба лишає менше відходів.']};},
 terms:[['Корпоративна соціальна відповідальність','добровільне зобов’язання бізнесу дбати про працівників, громаду й довкілля, а не лише про прибуток'],['Спонсорство','підтримка в обмін на рекламу: обидві сторони домовляються про це відкрито'],['Благодійність і меценатство','допомога без вимоги чогось навзамін; меценатством називають таку підтримку культури, освіти, науки, мистецтва'],['Волонтерство','добровільна безоплатна робота на користь інших людей або громади'],['Грінвошинг','коли бізнес називає себе екологічним лише на словах, щоб сподобатися покупцям']]};
})());

PFG_TOPICS.push((()=>{
 /* допоміжні функції теми. Усі ставки, штрафи й пеня — «за умовою задачі». */
 const pay=(S,x)=>{const p=Math.min(S.cash,x);S.cash-=p;S.due+=x-p;};                 /* платіж з основного рахунку; чого не вистачило — у несплачене */
 const payTax=(S,x)=>{const r=Math.min(S.res,x);S.res-=r;pay(S,x-r);};                 /* податок: спершу з податкового рахунку */
 const settle=(S,d)=>{S.cash+=d;const r=Math.min(S.cash,S.due);S.cash-=r;S.due-=r;};   /* підсумок кварталу: виручка, потім несплачене */
 const dec1=S=>104000+(S.club===2?24000:0)-(S.rec===0?13000:0);                        /* дохід 1 кв. за записами */
 const T1=S=>dec1(S)*0.05;
 const n2=S=>200+S.adx-(S.f.team?0:20)-(S.rec===1?10:0);
 const T2=S=>n2(S)*32.5;
 const n3=S=>100+(S.club===2?10:0);
 const T3=S=>n3(S)*32.5;
 const lost3=S=>S.rec===0?2100:0;                                                      /* витрати без чеків */
 const n4=S=>160+(S.trust===2?20:S.trust===0?-20:0)-(S.spill===0?20:0);
 const m4=S=>S.hire===2?200:S.hire===0?170:140;
 const inc4=S=>n4(S)*650+m4(S)*300;
 const T4=S=>inc4(S)*0.05;
 const cost4=S=>n4(S)*440+m4(S)*60+18900+(S.hire===2?12200:0);                         /* підтверджені витрати 4 кв. */
 const ptax4=S=>(inc4(S)-cost4(S))*0.18;
 const aug=S=>{const t=T2(S),a=Math.min(S.res,t),b=Math.min(S.cash,t-a),l=t-a-b;return{t,a,b,l,f:Math.round(l*0.12)};}; /* сплата за 2 кв. у серпні */
 const sumA=S=>{const mv=Math.min(S.cash,Math.max(0,T2(S)-S.res));return{mv,out:Math.max(0,S.cash-mv-10000)};};
 const outTxt=p=>p>0?'На основному рахунку лишити 10 000 грн запасу, решту — '+PG(p)+' — виплатити команді':'Усе, що є на основному рахунку, лишити як запас; виплату команді поки відкласти';
 const elig=S=>S.tpen===0&&S.hire!==0;
 const yearInc=S=>104000+(S.club!==1?24000:0)+n2(S)*650+n3(S)*650+inc4(S);
 const locEP=S=>T1(S)+S.hid*0.05+T2(S)+T3(S)+T4(S);
 return {id:'9-8',sec:'9b',title:'Оподаткування бізнесу та відповідальність за зобов’язаннями',minutes:30,
 intro:'Тобі виповнилося 16, і за згодою мами «Відбиток» — ваша з Марком і Соломією майстерня друку на худі — тепер офіційна справа: тебе зареєстровано підприємцем. Худі коштує 650 грн, на заготовку й фарбу йде 440 грн, оренда та інші постійні витрати — 6 300 грн на місяць. Попереду рік із чотирьох кварталів. Ти рахуєш податок на власних цифрах, відкладаєш на нього гроші, платиш у строк або із запізненням — і бачиш, як кожне рішення повертається через квартал-два. Усі ставки податків, штрафи й пеня в цій історії — за умовою задачі, а не з чинних законів.',
 init:()=>({cash:5000,res:0,pen:0,tpen:0,due:0,hid:0,rec:2,club:2,adx:0,late:0,days:0,pre:0,loan:0,trust:1,rule:0,spill:2,hire:2,f:{}}),
 meters:[{k:'cash',label:'Гроші на рахунку',unit:'грн'},{k:'res',label:'Відкладено на податки',unit:'грн'},{k:'pen',label:'Штрафи й пеня',unit:'грн'}],
 steps:[
  {id:'rec',t:'choice',head:'Січень · Книга доходів',text:'Ти працюєш на спрощеній системі: раз на квартал сплачуєш єдиний податок. За умовою задачі це 5 % від усього доходу, записаного у твоїй книзі доходів. Пані Ірина, знайома бухгалтерка мами, попереджає: «Податок рахують із записів. Немає запису — немає й порядку». Гроші надходять по-різному: класи платять переказом на рахунок, а на шкільних ярмарках худі купують за готівку.',q:'Як ти вестимеш записи?',o:[
   {l:'Записувати кожен продаж того самого дня — і переказ, і готівку; чеки на витрати складати в окрему теку',p:2,eff:S=>{S.rec=2;},fb:'П’ять хвилин щовечора. Наприкінці кварталу дохід уже пораховано, і кожну цифру можна підтвердити документом.'},
   {l:'Раз на місяць переписувати надходження з банківської виписки, а готівку — з нотаток у телефоні',p:1,eff:S=>{S.rec=1;},fb:'Записи будуть повні, але збирати їх доведеться зі шматочків. Коли цифри знадобляться терміново, на це піде не один вечір.'},
   {l:'Порахувати все наприкінці кварталу за випискою з банку — там же й так усе видно',p:0,eff:S=>{S.rec=0;},fb:'Найменше клопоту сьогодні. Тільки виписка показує самі перекази: готівка з ярмарків у неї не потрапляє.'}]},
  {id:'club',t:'choice',head:'Лютий · «Без чека дешевше»',text:'Танцювальна студія «Ритм» хоче 40 худі. Її керівник пан Віктор пропонує: «Плачу готівкою, чек мені не потрібен. Ти цей продаж ніде не записуєш і податку з нього не платиш, а мені за це — по 600 грн замість 650. Усім вигідно».',q:'Що ти відповіси?',o:[
   {l:'Знижку за велику партію дати — по 600 грн, але з чеком і записом у книзі доходів',p:2,eff:S=>{S.club=2;},fb:'Пан Віктор знизує плечима й погоджується: йому потрібна знижка, а не таємниця. 24 000 грн записано в книгу доходів, податок із них — 1 200 грн — буде сплачено.'},
   {l:'Відмовитися від замовлення: з таким клієнтом краще не зв’язуватися',p:1,eff:S=>{S.club=1;},fb:'Ризику немає, але й 40 худі не продано. Знижку за велику партію можна було дати цілком офіційно.'},
   {l:'Погодитися: 40 худі по 600 грн готівкою, без чека й без запису',p:0,eff:S=>{S.club=0;S.hid+=24000;},fb:'24 000 грн готівки лежать у шухляді, у книзі доходів їх немає. «Заощаджений» податок — 1 200 грн. Про угоду знаєте ти, пан Віктор і сорок родин, які отримали худі без чека.'}]},
  {id:'q1end',t:'event',head:'Березень · Підсумок кварталу',text:S=>'Перший квартал закрито. Продано 160 худі по 650 грн'+(S.club!==1?' і ще 40 — студії «Ритм» по 600 грн':'')+'. Після заготовок, фарби й оренди на рахунку «Відбитка» '+PG(19700+(S.club!==1?6400:0))+'. '+(S.rec===2?'У книзі доходів — '+(S.club===0?'усі продажі, крім готівки від студії «Ритм»':'кожен продаж, день у день')+': разом '+PG(dec1(S))+'.':S.rec===1?'Щоб звести записи докупи, пішло два вечори з випискою й телефоном. У книзі доходів — '+PG(dec1(S))+'.':'Дохід ти рахуєш за банківською випискою: '+PG(dec1(S))+'. Про 20 худі, проданих за готівку на ярмарку, — це 13 000 грн — виписка мовчить.')+(S.club===0&&S.rec<2?' Готівки від студії в записах '+(S.rec===0?'теж ':'')+'немає.':''),eff:S=>{if(S.rec===0)S.hid+=13000;S.cash=19700+(S.club!==1?6400:0);}},
  {id:'tax1',t:'calc',head:'Квітень · Перша декларація',text:S=>'Час звітувати за перший квартал. Дохід за твоїми записами — '+PG(dec1(S))+'. Єдиний податок, за умовою задачі, — 5 % від доходу. Саме від доходу, тобто від усіх надходжень: витрати на заготовки й оренду його не зменшують.',q:'Скільки гривень єдиного податку треба сплатити за перший квартал?',ans:S=>T1(S),unit:'грн',hint:'Знайди 5 % від доходу: поділи його на 100 і помнож на 5.',sol:S=>PN(dec1(S))+' × 0,05 = '+PG(T1(S))+'. Єдиний податок — місцевий: уся ця сума надійде до бюджету твоєї громади.'},
  {id:'plan1',t:'plan',head:'Квітень · Куди підуть гроші',text:S=>'На рахунку '+PG(S.cash)+'. Податок за перший квартал — '+PG(T1(S))+' — треба сплатити в травні. Розподіли всі гроші. Податковий рахунок — те, що чекатиме дня сплати. Реклама до сезону випускних: кожна 1 000 грн приводить близько 10 замовлень худі, але понад 40 додаткових майстерня не встигне. Виплата команді: Марко й Соломія три місяці працюють без виплат і розраховують разом хоча б на 3 000 грн. Запас — гроші, що лишаються на основному рахунку на несподіванки.',q:'Скільки гривень на кожну статтю?',
   fields:[{k:'res',label:'На податковий рахунок'},{k:'ad',label:'Реклама до сезону'},{k:'team',label:'Виплата команді'},{k:'cush',label:'Запас на основному рахунку'}],
   total:S=>S.cash,
   best:S=>({res:T1(S),ad:4000,team:4000,cush:S.cash-T1(S)-8000}),
   check:(S,v)=>v.res+v.cush<T1(S)?'На двох рахунках разом має лишитися щонайменше '+PG(T1(S))+': стільки податку доведеться сплатити вже в травні. Зменш рекламу чи виплату.':null,
   eff:(S,v)=>{S.res=v.res;S.cash=v.cush;S.adx=Math.min(40,Math.floor(v.ad/1000)*10);S.f.team=v.team>=3000?1:0;},
   score:(S,v)=>{const t=T1(S);return v.res>=t&&v.team>=3000&&v.cush>=3000?{p:2,fb:'Податок відкладено повністю, команда отримала зароблене, і на основному рахунку лишився запас. У травні ти просто перекажеш гроші, які вже чекають.'}:v.res>=t?{p:1,fb:'Податок відкладено повністю — це головне. Але '+(v.team<3000?'команда лишилася без обіцяної виплати':'запасу на несподіванки майже немає')+', і це ще дасться взнаки.'}:v.res>=t/2?{p:1,fb:'На податковому рахунку менше, ніж треба: бракує '+PG(t-v.res)+'. У травні їх доведеться брати із запасу.'}:{p:0,fb:'Податок майже не відкладено: бракує '+PG(t-v.res)+'. Гроші на основному рахунку здаються вільними, але частина з них уже належить бюджету.'};}},
  {id:'pay1',t:'choice',head:'Травень · Строк сплати',text:S=>'До строку сплати єдиного податку за перший квартал — '+PG(T1(S))+' — лишилося два дні. На податковому рахунку '+PG(S.res)+', на основному — '+PG(S.cash)+'. '+(S.res>=T1(S)?'Гроші готові, але тиждень шалений':'На податковому рахунку бракує '+PG(T1(S)-S.res)+' — їх доведеться взяти із запасу. А тиждень шалений')+': ліцей чекає 60 худі до п’ятниці, і всі троє не відходять від преса.',q:'Коли ти сплатиш податок?',o:[
   {l:'Сьогодні ж: десять хвилин в онлайн-банку — і питання закрито',p:2,eff:S=>{payTax(S,T1(S));},fb:S=>S.res>=T1(S)?'Податок пішов із податкового рахунку — основні гроші не зачеплено, боргів перед бюджетом немає.':'Сплачено вчасно. Щоправда, '+PG(T1(S)-S.res)+' довелося взяти з основного рахунку — запас на несподіванки схуд.'},
   {l:'Після того як здамо замовлення ліцею, — це на п’ять днів пізніше строку, зате зі спокійною головою',p:1,eff:S=>{S.late=T1(S);S.days=5;},fb:'Замовлення здано без поспіху. А податок прострочено, і до нього додасться рахунок за запізнення — навіть за п’ять днів.'},
   {l:'Наприкінці місяця, разом з усіма іншими рахунками, — це на 20 днів пізніше, але так зручніше',p:0,eff:S=>{S.late=T1(S);S.days=20;},fb:'Один платіжний день на місяць — зручно. Тільки строк сплати податку минув, і відтоді щодня нараховується пеня.'}]},
  {id:'late1',t:'calc',when:S=>S.late>0,head:S=>(S.days===5?'Травень':'Червень')+' · Ціна запізнення',text:S=>'Ти сплачуєш податок за перший квартал — '+PG(S.late)+' — на '+S.days+' днів пізніше строку. За умовою задачі за прострочення нараховують штраф 10 % від суми, не сплаченої вчасно, і пеню — 0,1 % цієї суми за кожен день.',q:'Скільки гривень штрафу й пені разом треба доплатити? Округли до гривні.',ans:S=>Math.round(S.late*(0.1+S.days*0.001)),tol:1,unit:'грн',hint:S=>'Штраф — 10 % від '+PN(S.late)+'. Пеня — 0,1 % × '+S.days+' = '+PN(S.days*0.1)+' % від тієї самої суми. Додай обидві частини.',sol:S=>'Штраф: '+PN(S.late)+' × 0,1 = '+PG(S.late*0.1)+'. Пеня: '+PN(S.late)+' × 0,001 × '+S.days+' = '+PG(S.late*S.days*0.001)+'. Разом близько '+PG(Math.round(S.late*(0.1+S.days*0.001)))+'. Зверни увагу: штраф не залежить від кількості днів — навіть один день запізнення коштує 10 %.',eff:S=>{const f=Math.round(S.late*(0.1+S.days*0.001));payTax(S,S.late);pay(S,f);S.pen+=f;S.tpen+=f;}},
  {id:'sup',t:'choice',head:'Червень · Рахунок пана Ореста',text:S=>'Постачальник заготовок пан Орест відвантажив партію на сезон випускних із відстрочкою: 6 000 грн треба сплатити до п’ятниці. Окремим рядком у рахунку стоїть ПДВ — загальнодержавний податок, який покупець сплачує в ціні товару. За договором кожен день прострочення — це пеня 0,5 % від суми боргу. Ліцей заплатить за свої худі лише за 10 днів, а на основному рахунку зараз '+PG(S.cash)+'.',q:'Що ти зробиш?',o:[
   {l:'Сплатити 6 000 грн у строк із запасу на основному рахунку',when:S=>S.cash>=6000,p:2,eff:S=>{S.cash-=6000;S.pre=6000;S.trust=2;},fb:'Ось для чого потрібен запас: зобов’язання виконано день у день. Пан Орест каже, що таким покупцям дає відстрочку й на великі партії.'},
   {l:'Зателефонувати панові Оресту до п’ятниці, пояснити ситуацію й письмово домовитися про нову дату — за 10 днів',p:S=>S.cash>=6000?1:2,eff:S=>{S.trust=S.cash>=6000?1:2;},fb:S=>S.cash>=6000?'Пан Орест погодився почекати без пені, але здивувався: гроші ж на рахунку є. Домовленість чесна, проте великих партій із відстрочкою він тепер не обіцяє.':'Грошей справді немає, і ти кажеш про це до строку, а не після. Пан Орест погоджується почекати 10 днів без пені: «Буває. Головне — не зникай».'},
   {l:'Узяти мікропозику онлайн — 6 000 грн на 10 днів, повернути 6 600 грн (умови задачі) — і сплатити в строк',when:S=>S.cash<6000,p:1,eff:S=>{S.loan=600;S.trust=2;},fb:'Рахунок сплачено вчасно, пан Орест задоволений. Але 600 грн за десять днів — висока ціна того, що на рахунку не було запасу, а один дзвінок був безкоштовним.'},
   {l:'Нічого не казати й заплатити, коли прийдуть гроші від ліцею',p:0,eff:S=>{S.trust=0;S.f.supLate=1;},fb:'Десять днів пан Орест не знає, де його гроші й чи будуть вони взагалі. Пеня за договором нараховується щодня, а довіра зникає ще швидше.'}]},
  {id:'supPen',t:'calc',when:S=>!!S.f.supLate,head:'Червень · Пеня за договором',text:'Гроші від ліцею прийшли, і ти платиш панові Оресту 6 000 грн — на 10 днів пізніше, ніж обіцяно. За договором пеня становить 0,5 % від суми боргу за кожен день прострочення.',q:'Скільки гривень пені треба доплатити панові Оресту?',ans:S=>300,unit:'грн',hint:'Спершу знайди пеню за один день: 0,5 % від 6 000. Потім помнож на 10 днів.',sol:S=>'6 000 × 0,005 = 30 грн за день. 30 × 10 = 300 грн. Гірше інше: надалі пан Орест відпускатиме «Відбитку» заготовки лише за повної передоплати.',eff:S=>{pay(S,300);S.pen+=300;}},
  {id:'chk',t:'event',head:'Червень · Лист із податкової',text:S=>'Податкова надсилає запит: підтвердити дохід за перший квартал. '+(S.rec===2?'Ти відкриваєш книгу доходів і теку з чеками — відповідь готова за пів години.':S.rec===1?'Записи є, але зібрати їх в один документ — це два дні з випискою й телефоном. Прес увесь цей час стояв: 10 худі не надруковано.':'Школа, яка проводила ярмарок, відзвітувала про виручку кожного учасника. У твоїй декларації цих 13 000 грн немає.')+(S.club===0?' А одна з мам зі студії «Ритм» хотіла обміняти худі на більший розмір і попросила чек. Чека немає — і вона поскаржилася. Так знайшлися ще 24 000 грн, яких немає в книзі доходів.':'')+(S.hid>0?' Забуто чи приховано — податковій однаково: за умовою задачі з доходу, якого немає в записах, треба доплатити 5 % податку й сплатити штраф — 20 % від цієї суми. Пані Ірина додає: якби йшлося про умисне ухилення у великих розмірах, це була б уже кримінальна відповідальність.':' Розбіжностей немає. Пані Ірина каже: у кого знаходять дохід, якого немає в записах, той доплачує податок і штраф, а за умисне ухилення у великих розмірах передбачено кримінальну відповідальність.')},
  {id:'chkc',t:'calc',when:S=>S.hid>0,head:'Червень · Доплата після перевірки',text:S=>'Перевірка виявила '+PG(S.hid)+' доходу, якого немає в книзі доходів. За умовою задачі треба доплатити 5 % податку з цієї суми й сплатити штраф — 20 % від неї.',q:'Скільки гривень разом — податку й штрафу — треба сплатити?',ans:S=>S.hid*0.25,unit:'грн',hint:S=>'Знайди 5 % від '+PN(S.hid)+' і 20 % від '+PN(S.hid)+', потім додай.',sol:S=>'Податок: '+PN(S.hid)+' × 0,05 = '+PG(S.hid*0.05)+'. Штраф: '+PN(S.hid)+' × 0,2 = '+PG(S.hid*0.2)+'. Разом '+PG(S.hid*0.25)+'. Податок довелося сплатити однаково, а штраф учетверо більший за сам податок.',eff:S=>{pay(S,S.hid*0.25);S.pen+=S.hid*0.2;S.tpen+=S.hid*0.2;}},
  {id:'q2end',t:'event',head:'Червень · Підсумок сезону',text:S=>{const n=n2(S),p=n*210-18900;return 'Другий квартал — сезон випускних. '+(S.adx>0?'Реклама привела '+S.adx+' додаткових замовлень. ':'Реклами не було, тож прийшли тільки постійні клієнти. ')+(S.f.team?'':'Марко й Соломія, які так і не дочекалися виплати за зиму, працювали без запалу: мінус 20 худі. ')+'Продано '+n+' худі на '+PG(n*650)+'. Після заготовок, фарби й оренди квартал приніс '+PG(p)+'.'+(S.pre?' Ліцей розрахувався, тож 6 000 грн, сплачені панові Оресту наперед, повернулися на рахунок.':'')+(S.loan?' Мікропозику повернуто: 600 грн понад позичене.':'')+(S.due>0?' Із виручки насамперед закрито несплачене раніше — '+PG(S.due)+'.':'')+' Єдиний податок за другий квартал — 5 % від '+PN(n*650)+', тобто '+PG(T2(S))+'; сплатити його треба в серпні.';},eff:S=>{settle(S,n2(S)*210-18900+S.pre-S.loan);}},
  {id:'sum',t:'choice',head:'Липень · Гроші після сезону',text:S=>'На основному рахунку '+PG(S.cash)+', на податковому — '+PG(S.res)+'. Попереду тихе літо: замовлень мало, а оренду платити треба щомісяця. У серпні — податок за другий квартал, '+PG(T2(S))+'. Команда чекає на виплату за сезон.',q:'Як ти розпорядишся грошима?',o:[
   {l:S=>{const a=sumA(S);return (a.mv>0?'Перевести на податковий рахунок '+PG(a.mv)+', щоб там був увесь податок за другий квартал, і надалі':'Податок за другий квартал уже є на податковому рахунку; надалі')+' відкладати туди 5 % із кожної оплати. '+outTxt(a.out);},p:2,eff:S=>{const a=sumA(S);S.cash-=a.mv+a.out;S.res+=a.mv;S.rule=1;},fb:'Гроші на податок більше не лежать разом з іншими — на них уже ніхто не розраховує. А запас на основному рахунку прикриє літо.'},
   {l:S=>'Окремо на податок не відкладати — гроші й так лежать на рахунку. '+outTxt(Math.max(0,S.cash-10000)),p:1,eff:S=>{S.cash=Math.min(S.cash,10000);},fb:S=>T2(S)>S.res?'Зараз грошей на рахунку ніби більше. Але в серпні із запасу треба буде віддати '+PG(T2(S)-S.res)+' податку — на несподіванки лишиться зовсім мало.':'Цього разу на податковому рахунку грошей вистачить і так. Але правила немає: наступний податок знову доведеться шукати серед інших грошей.'},
   {l:S=>'Виплатити команді все, що є на основному рахунку, — '+PG(S.cash)+': сезон відпрацьовано, а податок сплатимо з літніх продажів',p:0,eff:S=>{S.cash=0;},fb:'Усі задоволені. Основний рахунок порожній, а влітку «Відбиток» ледве покриває оренду — податку за другий квартал братися нізвідки.'}]},
  {id:'spill',t:'choice',head:'Серпень · Розлита каністра',text:S=>'Марко переставляв полиці й перекинув 10-літрову каністру розчинника, яким змивають фарбу з трафаретів. Калюжа розтікається подвір’ям і повзе до зливового стоку, що веде до ставка в парку. Ніхто цього не хотів — але каністра ваша, і відповідає за неї «Відбиток». На основному рахунку '+PG(S.cash)+'.',q:'Що ти зробиш?',o:[
   {l:'Перекрити стік, засипати калюжу піском, зібрати його в закриті мішки, повідомити власника приміщення й здати мішки фірмі, яка приймає небезпечні відходи',p:2,eff:S=>{S.spill=2;pay(S,1800);},fb:S=>'Вивезення й утилізація, за умовою задачі, коштують 1 800 грн'+(S.cash<1800?' — на рахунку стільки немає, тож частину доведеться доплатити з найближчої виручки':'')+'. Пів дня роботи втрачено, зате розчинник не дійшов до ставка, а власник приміщення знає про все від тебе.'},
   {l:'Засипати калюжу піском, пісок викинути у звичайний контейнер для сміття й нікому не казати',p:1,eff:S=>{S.spill=1;},fb:'Калюжі немає, грошей не витрачено, до ставка нічого не дотекло. Але просочений розчинником пісок лежить тепер у дворовому контейнері, і пахне звідти зовсім не сміттям.'},
   {l:'Швидко змити все шлангом у стік, поки ніхто не бачить',p:0,eff:S=>{S.spill=0;},fb:'За десять хвилин подвір’я чисте. Розчинник нікуди не зник: він поплив трубою до ставка.'}]},
  {id:'q3end',t:'event',head:'Вересень · Підсумок літа',text:S=>{const a=aug(S),n=n3(S);return 'У серпні настав строк сплати податку за другий квартал — '+PG(a.t)+'. '+(a.l===0?(a.b===0?'Гроші чекали на податковому рахунку: сплачено день у день.':a.a===0?'Сплачено вчасно — усю суму взято з основного рахунку.':'Сплачено вчасно: '+PG(a.a)+' з податкового рахунку й '+PG(a.b)+' з основного.'):(a.a+a.b>0?'На обох рахунках знайшлося лише '+PG(a.a+a.b)+'. Решту — ':'Обидва рахунки були порожні. Усю суму — ')+PG(a.l)+' — сплачено на 20 днів пізніше, з вересневих продажів, і до неї, за умовою задачі, додалися штраф 10 % та пеня 0,1 % за день: разом '+PG(a.f)+'.')+' Літо було тихим: продано '+n+' худі на '+PG(n*650)+'.'+(S.club===2?' Серед них 10 — для нової групи студії «Ритм»: пан Віктор повернувся, бо має чеки для звіту перед батьками.':'')+' Після заготовок, фарби й оренди квартал приніс лише '+PG(n*210-18900)+'.';},eff:S=>{const a=aug(S);S.res-=a.a;S.cash-=a.b;settle(S,n3(S)*210-18900);if(a.l>0){pay(S,a.l+a.f);S.pen+=a.f;S.tpen+=a.f;}}},
  {id:'t3',t:'calc',head:'Жовтень · Декларація за літо',text:S=>'За третій квартал у книзі доходів '+PG(n3(S)*650)+' — це '+n3(S)+' худі по 650 грн. Єдиний податок, за умовою задачі, — 5 % від доходу.',q:'Скільки гривень єдиного податку треба сплатити за третій квартал?',ans:S=>T3(S),unit:'грн',hint:'Візьми 5 % від доходу за квартал. Прибуток тут ні до чого.',sol:S=>PN(n3(S)*650)+' × 0,05 = '+PG(T3(S))+'. '+(S.rule?'Саме стільки зібралося на податковому рахунку за твоїм правилом «5 % із кожної оплати» — шукати ці гроші не доведеться.':'Окремо ці гроші ніхто не відкладав — у листопаді їх доведеться знайти на основному рахунку.'),eff:S=>{if(S.rule){const x=Math.min(S.cash,T3(S));S.cash-=x;S.res+=x;}}},
  {id:'base3',t:'calc',head:'Жовтень · А якби податок брали з прибутку?',text:S=>{const n=n3(S);return 'Соломія дивується: «Ми за літо майже нічого не заробили, а податок — '+PG(T3(S))+'?» Пані Ірина пояснює: єдиний податок беруть із доходу. Є й загальна система: там, за умовою задачі, платять 18 % від прибутку — доходу мінус витрати, підтверджені документами (інших платежів у цьому порівнянні не рахуємо). Літні цифри «Відбитка»: дохід — '+PG(n*650)+'; заготовки й фарба — '+n+' × 440 = '+PG(n*440)+'; оренда та інші постійні витрати — 18 900 грн.'+(lost3(S)?' Щоправда, чеки на фарбу на 2 100 грн так і не знайшлися — підтвердити ці витрати нічим, і в розрахунок вони не підуть.':'');},q:'Скільки гривень податку з прибутку довелося б сплатити за третій квартал?',ans:S=>(n3(S)*210-18900+lost3(S))*0.18,unit:'грн',hint:S=>'Спершу знайди прибуток: від доходу відніми '+(lost3(S)?'підтверджені ':'')+'витрати на заготовки й постійні витрати. Потім візьми від прибутку 18 %.',sol:S=>{const n=n3(S),c=n*440+18900-lost3(S),p=n*650-c;return 'Витрати'+(lost3(S)?' з документами':'')+': '+PN(n*440)+(lost3(S)?' − 2 100':'')+' + 18 900 = '+PG(c)+'. Прибуток: '+PN(n*650)+' − '+PN(c)+' = '+PG(p)+'. Податок: '+PN(p)+' × 0,18 = '+PG(p*0.18)+'. Єдиний податок за той самий квартал — '+PG(T3(S))+': коли прибуток малий, податок із доходу виявляється значно більшим.'+(lost3(S)?' Якби чеки на фарбу збереглися, податок із прибутку був би на 378 грн меншим.':'')+' Але з висновком не поспішай — подивимося ще на квартал, коли прибуток великий.';}},
  {id:'hire',t:'choice',head:'Жовтень · Помічник на сезон',text:'Попереду листопад і грудень — найгарячіша пора. До худі додалася нова послуга: друк на речах клієнта за 300 грн, із яких 60 грн ідуть на фарбу й плівку. Утрьох ви всього не встигнете. Данило, студент коледжу, згоден попрацювати два місяці на пів ставки за 5 000 грн на місяць. Пані Ірина попереджає: з офіційної зарплати утримують податки, а роботодавець ще й сплачує понад неї соціальний внесок. Данило знизує плечима: «Можна й без паперів. 4 500 на руки — і все».',q:'Як ти вчиниш?',o:[
   {l:'Оформити Данила офіційно: договір, зарплата 5 000 грн, усі податки й внесок',p:2,eff:S=>{S.hire=2;},fb:'На руки Данило отримає менше, ніж просив у конверті, зате має договір і стаж, а його обов’язки записано на папері. І тобі не доведеться ні від кого ховатися.'},
   {l:'Нікого не наймати: впораємося втрьох, скільки встигнемо',p:1,eff:S=>{S.hire=1;},fb:'Жодних податків і жодного ризику, але й рук не додалося: частину замовлень на друк доведеться відхилити.'},
   {l:'Платити Данилові 4 500 грн готівкою без оформлення',p:0,eff:S=>{S.hire=0;},fb:'Обом здається, що вигідно: Данило має більше на руки, ти платиш менше. Тільки договору немає — отже, немає ні його обов’язків перед майстернею, ні твого захисту, якщо хтось поскаржиться.'}]},
  {id:'wage',t:'calc',head:'Жовтень · Скільки коштує зарплата',text:S=>'Ставки за умовою задачі: із зарплати утримують 18 % податку на доходи фізичних осіб (ПДФО) і 5 % військового збору; понад зарплату роботодавець сплачує 22 % єдиного соціального внеску. Зарплата — 5 000 грн на місяць, сезон триває два місяці. '+(S.hire===2?'Данила оформлено, і тобі треба знати повну ціну цього рішення.':S.hire===0?'Данило працює без оформлення, тож жоден із цих платежів до бюджету не надходить.':'Найму не буде, але варто розуміти, з чого складається офіційна зарплата.'),q:S=>S.hire===2?'Скільки гривень коштуватиме тобі Данило за два місяці — зарплата разом із соціальним внеском?':S.hire===0?'Скільки гривень податку, збору й внеску разом не надійде до бюджету за два місяці?':'Скільки гривень Данило отримував би на руки за місяць офіційної роботи?',ans:S=>S.hire===2?12200:S.hire===0?4500:3850,unit:'грн',hint:S=>S.hire===2?'Знайди 22 % від 5 000, додай до зарплати й помнож на 2 місяці.':S.hire===0?'За місяць: 18 %, 5 % і 22 % від 5 000. Додай і помнож на 2.':'Із 5 000 відніми 18 % і 5 % від цієї суми.',sol:S=>S.hire===2?'Внесок: 5 000 × 0,22 = 1 100 грн. За місяць: 5 000 + 1 100 = 6 100 грн, за два — 12 200 грн. Із зарплати утримають 900 грн ПДФО і 250 грн військового збору, тож на руки Данило отримає 3 850 грн на місяць.':S.hire===0?'ПДФО: 5 000 × 0,18 = 900. Військовий збір: 5 000 × 0,05 = 250. Соціальний внесок: 5 000 × 0,22 = 1 100. За місяць 2 250 грн, за два — 4 500 грн. Якщо про роботу без оформлення дізнаються, цю суму доведеться сплатити разом зі штрафом.':'ПДФО: 5 000 × 0,18 = 900. Військовий збір: 5 000 × 0,05 = 250. На руки: 5 000 − 900 − 250 = 3 850 грн. А майстерні він коштував би 5 000 + 1 100 = 6 100 грн на місяць.'},
  {id:'q4end',t:'event',head:'Грудень · Відлуння року',text:S=>{const fr=Math.min(S.res,T3(S));return 'У листопаді сплачено єдиний податок за третій квартал — '+PG(T3(S))+': '+(fr>=T3(S)?'гроші вже лежали на податковому рахунку.':fr>0?PG(fr)+' з податкового рахунку, решту — з жовтневої виручки.':'усю суму довелося взяти з жовтневої виручки.')+(S.due>0?' Із першої осінньої виручки закрито рахунки, що лишилися несплаченими з літа, — '+PG(S.due)+'.':'')+(S.trust===2?' Пан Орест дав велику партію заготовок із відстрочкою — вистачило на 20 худі більше.':S.trust===0?' Пан Орест відпускав заготовки лише за повної передоплати, тож великі замовлення довелося брати частинами: мінус 20 худі.':'')+(S.hire===2?' Данило відпрацював обидва місяці: разом зроблено 200 принтів на речах клієнтів.':S.hire===1?' Утрьох ви встигли 140 принтів; ще з шістдесят замовлень довелося відхилити.':' Данило в останній тиждень перед святами знайшов кращий підробіток і просто не прийшов — договору ж немає; принтів вийшло 170. Потім йому знадобилася довідка про доходи, якої без оформлення не буває, і його мама поскаржилася. За умовою задачі довелося доплатити податки й внесок із його зарплати — 4 500 грн, штраф 10 % — 450 грн і пеню за 30 днів — 135 грн: разом 5 085 грн.')+(S.spill===2?' Ставок у парку чистий, а власник приміщення продовжив оренду на наступний рік.':S.spill===1?' Двірник відчув запах розчинника з контейнера, і власник приміщення швидко з’ясував, чий це пісок. За умовою задачі вивезення небезпечних відходів і заміна контейнера коштували 3 500 грн — майже вдвічі більше, ніж утилізація одразу.':' На ставку в парку з’явилася масляниста пляма, і комунальна служба простежила стік до вашого подвір’я. Умислу не було, але за шкоду довкіллю підприємство відповідає й без нього: за умовою задачі відшкодування збитків — очищення стоку й берега — 9 000 грн. Про пляму написали в шкільній групі, і два класи відклали замовлення: мінус 20 худі.')+' За квартал продано '+n4(S)+' худі та '+m4(S)+' принтів, дохід — '+PG(inc4(S))+'. Єдиний податок за четвертий квартал — 5 % від доходу, '+PG(T4(S))+'; сплатити його треба в лютому. '+(S.rule?'За твоїм правилом ці гроші вже відкладено.':'Окремо їх ніхто не відкладав.');},eff:S=>{payTax(S,T3(S));settle(S,n4(S)*210+m4(S)*240-18900-(S.hire===2?12200:S.hire===0?9000:0));if(S.hire===0){pay(S,5085);S.pen+=585;S.tpen+=585;}if(S.spill<2)pay(S,S.spill===1?3500:9000);if(S.rule){const x=Math.min(S.cash,T4(S));S.cash-=x;S.res+=x;}}},
  {id:'base4',t:'calc',head:'Грудень · Податок із доходу чи з прибутку',text:S=>'Тепер той самий розрахунок для найприбутковішого кварталу. Дохід — '+PG(inc4(S))+'. Витрати, підтверджені документами: заготовки й фарба для худі — '+n4(S)+' × 440 = '+PG(n4(S)*440)+'; фарба й плівка для принтів — '+m4(S)+' × 60 = '+PG(m4(S)*60)+'; оренда та інші постійні витрати — 18 900 грн'+(S.hire===2?'; Данило (зарплата й внесок) — 12 200 грн.':S.hire===0?'. Зарплату Данила в конверті жоден документ не підтверджує — до витрат її не зарахуєш.':'.')+' Єдиний податок за цей квартал — '+PG(T4(S))+'.',q:'Скільки гривень становив би податок із прибутку — за умовою задачі 18 % — за четвертий квартал?',ans:S=>ptax4(S),unit:'грн',hint:'Додай усі підтверджені витрати, відніми їх від доходу — це прибуток. Потім візьми від нього 18 %.',sol:S=>{const c=cost4(S),p=inc4(S)-c,x=ptax4(S),t=T4(S);return 'Витрати: '+PG(c)+'. Прибуток: '+PN(inc4(S))+' − '+PN(c)+' = '+PG(p)+'. Податок: '+PN(p)+' × 0,18 = '+PG(x)+'. Єдиний податок — '+PG(t)+', тобто на '+PG(Math.abs(x-t))+(x>t?' менше':' більше')+'. Улітку було '+(x>t?'навпаки':'так само')+'. Справа в базі оподаткування: 5 % беруть з усього доходу, 18 % — лише з прибутку. Тож податок із доходу менший, коли прибуток перевищує приблизно 28 % доходу, і більший, коли прибутку мало. «Кращої» системи немає: спрощена дає простіший облік, але має обмеження, зокрема щодо розміру доходу; на загальній кожну витрату треба підтвердити документом. Вибір рахують на власних цифрах.';}},
  {id:'loc',t:'calc',head:'Грудень · Куди пішли твої податки',text:S=>'Громада звітує про бюджет: цього року з нього оплатили освітлення шкільного стадіону. Марко питає: «А наші гроші там є?» Пані Ірина пояснює: податки бувають місцеві й загальнодержавні. Єдиний податок і податок на майно — місцеві, вони повністю йдуть до бюджету громади. ПДВ, податок на прибуток і ПДФО — загальнодержавні; щоправда, частину ПДФО — за умовою задачі 60 % — теж зараховують до бюджету громади. Єдиний податок «Відбитка» за рік: за перший квартал — '+PG(T1(S))+(S.hid>0?', доплата після перевірки — '+PG(S.hid*0.05):'')+', за другий — '+PG(T2(S))+', за третій — '+PG(T3(S))+', за четвертий — '+PG(T4(S))+' (його буде сплачено в лютому). '+(S.hire===2?'ПДФО із зарплати Данила — 900 × 2 = 1 800 грн. Військовий збір і соціальний внесок до бюджету громади не надходять.':S.hire===0?'ПДФО із зарплати Данила, стягнутий після скарги, — 1 800 грн. Військовий збір, соціальний внесок і штрафи тут не рахуємо.':'ПДФО «Відбиток» цього року не сплачував: найманих працівників не було.'),q:'Скільки гривень із цих платежів потрапляє до бюджету твоєї громади?',ans:S=>locEP(S)+(S.hire!==1?1080:0),unit:'грн',hint:S=>S.hire!==1?'Єдиний податок додай повністю — він місцевий. Від ПДФО візьми 60 %.':'Єдиний податок — місцевий: просто додай усі суми.',sol:S=>'Єдиний податок за рік: '+PG(locEP(S))+' — уся сума лишається в громаді.'+(S.hire!==1?' ПДФО: 1 800 × 0,6 = 1 080 грн. Разом '+PG(locEP(S)+1080)+'.':'')+' У освітленні стадіону є й податки «Відбитка». А ПДВ, який ти сплачуєш у ціні заготовок, іде до державного бюджету.'},
  {id:'priv',t:'choice',head:'Грудень · Податкова пільга',text:S=>'Останнє рішення року. У цій історії — умова вигадана для задачі — рада громади запроваджує пільгу для молодіжних підприємств: наступного року єдиний податок для них становитиме 3 % замість 5 %. Умови: подати заяву до кінця грудня, не мати цього року штрафів за податкові порушення й оформити всіх працівників офіційно. Справжні пільги визначають закон і рішення місцевих рад, і діють вони теж лише для тих, хто відповідає умовам і подає документи. '+(elig(S)?'Під умови «Відбиток» підходить.':'Під умови «Відбиток» не підходить: '+(S.tpen>0?'цього року були штрафи й пеня за податками — '+PG(S.tpen):'')+(S.tpen>0&&S.hire===0?', а ще ':'')+(S.hire===0?'Данило працював без оформлення':'')+'.'),q:'Що ти зробиш?',o:[
   {l:'Подати заяву й документи до кінця грудня',when:S=>elig(S),p:2,eff:S=>{S.f.priv=1;},fb:S=>'Заяву прийнято. Якщо дохід наступного року буде таким самим, як цього, — '+PG(yearInc(S))+', — податку буде на 2 % менше: '+PG(yearInc(S)*0.02)+' залишаться в майстерні.'},
   {l:'Цього року не подаватися: умов не виконано. Провести наступний рік без порушень — і тоді подати заяву',when:S=>!elig(S),p:2,eff:S=>{S.f.wait=1;},fb:'Пільга — для тих, хто виконує умови. Рік без порушень — і наступна заява матиме шанс.'},
   {l:'Не подаватися: забагато паперів заради двох відсотків',when:S=>elig(S),p:1,eff:S=>{S.f.skip=1;},fb:S=>'Папери забрали б один вечір. А два відсотки від річного доходу '+PG(yearInc(S))+' — це '+PG(yearInc(S)*0.02)+', які могли б лишитися в майстерні.'},
   {l:'Подати заяву, не згадуючи про порушення: раптом не перевірять',when:S=>!elig(S),p:0,eff:S=>{S.f.lie=1;pay(S,1000);S.pen+=1000;S.tpen+=1000;},fb:'Перевірили. Заяву відхилено, а за недостовірні відомості, за умовою задачі, — штраф 1 000 грн.'},
   {l:'Заяви не подавати, а просто сплатити за четвертий квартал 3 % замість 5 %: пільга ж саме для таких підприємств',p:0,eff:S=>{const f=Math.round(inc4(S)*0.02*0.12);S.f.self=1;pay(S,f);S.pen+=f;S.tpen+=f;},fb:S=>'Пільга не діє сама собою й не діє заднім числом: потрібні заява й рішення. Недоплату '+PG(inc4(S)*0.02)+' помітили одразу; її довелося внести, а до неї, за умовою задачі, додалися штраф 10 % і пеня за 20 днів — '+PG(Math.round(inc4(S)*0.02*0.12))+'.'}]}],
 finish:S=>{const t4=T4(S),ok=S.cash+S.res>=t4+6300,clean=S.spill===2&&S.hire!==0&&S.hid===0;
  const lvl=S.pen<=700&&S.due===0&&ok&&clean?2:S.pen<=7000&&S.due===0&&ok&&!(S.spill===0&&S.pen>3000)?1:0;
  return{level:lvl,title:['Рік коштував «Відбитку» надто дорого','«Відбиток» вистояв, але переплатив','«Відбиток» працює чесно й без боргів'][lvl],
   text:'За рік: на основному рахунку — '+PG(S.cash)+', на податковому — '+PG(S.res)+', на штрафи й пеню пішло '+PG(S.pen)+'.'+(S.due>0?' Несплаченим лишилося '+PG(S.due)+'.':'')+' Податок за четвертий квартал — '+PG(t4)+' — '+(S.res>=t4?'уже чекає на податковому рахунку.':ok?'доведеться взяти з основного рахунку: окремо його не відкладено.':'сплатити буде важко: грошей на обох рахунках для цього й для оренди замало.'),
   tips:[S.pen===0?'Жодної гривні штрафу чи пені за рік: податки й рахунки сплачувалися в строк.':'Штрафи й пеня забрали '+PG(S.pen)+'. Щоразу це було дорожче за вигоду, заради якої строк чи правило порушувалося.',
    S.rule?'Правило «5 % із кожної оплати — на окремий рахунок» зробило податок непомітним: гроші на нього вже ніхто не вважав своїми.':'Окремого правила для податкових грошей у тебе не було, і податок доводилося шукати серед інших. Спробуй відкладати 5 % із кожної оплати на окремий рахунок.',
    clean?'Чек для клієнта, договір для працівника, чесність після аварії — саме тому в «Відбитка» немає прихованих боргів.':(S.hid>0?'Дохід, якого не було в записах, повернувся доплатою й штрафом. ':'')+(S.hire===0?'Зарплата в конверті обійшлася дорожче за офіційну. ':'')+(S.spill<2?'Аварію краще прибрати й визнати одразу: за шкоду довкіллю підприємство відповідає навіть без умислу. ':'')+'Наступного разу веди справу так, щоб ховати було нічого.']};},
 terms:[['Місцеві й загальнодержавні податки','місцеві (єдиний податок, податок на майно) надходять до бюджету громади; загальнодержавні (ПДВ, податок на прибуток, ПДФО) однакові для всієї країни'],['База оподаткування','сума, з якої рахують податок: наприклад, увесь дохід або лише прибуток'],['Податкова пільга','передбачене законом або рішенням місцевої ради зменшення податку для тих, хто відповідає визначеним умовам'],['Пеня','плата за кожен день прострочення платежу, зазвичай відсоток від несплаченої суми'],['Відповідальність за зобов’язаннями','обов’язок підприємця вчасно розраховуватися з бюджетом, постачальниками й працівниками та відшкодовувати завдану шкоду']]};
})());

PFG_TOPICS.push((()=>{
 /* допоміжні функції теми */
 const pay=(S,x)=>{const p=Math.min(S.cash,x);S.cash-=p;S.debt+=x-p;};                /* платіж із каси; чого не вистачило — у борг до кінця місяця */
 const n1=S=>8*(20-S.rout)-2*S.setup;                                   /* худі за перший місяць: години друку мінус налаштування */
 const rate=S=>S.f.pay===2?3:2;                                         /* комісія, % (за умовою); для особистої картки рахуємо «якби 2 %» */
 const fee1=S=>n1(S)*(S.f.pay===1?13:S.f.pay===2?19.5:0);                 /* комісія за місяць 1 */
 const eff6=S=>Math.max(0,S.sec-(S.f.leak?1:0));                        /* дієвий захист у день атаки */
 const lostN=e=>e>=3?0:e===2?4:e===1?10:20;
 const base2=S=>8*(20-S.r5)+(S.f.ai||S.f.data?4:0);                     /* звичайний друк за місяць 2; ШІ діє лише останній тиждень */
 const n2=S=>Math.max(0,base2(S)+S.deal+S.extra);
 const fee2=S=>S.f.pay===1?13*n2(S):S.f.pay===2?Math.round(19.5*n2(S)):0;
 const subs=S=>(S.f.crm===2?200:0)+(S.bk===2?300:0);
 const ex=(S,n,t)=>{S.extra+=n;S.x.push((n>0?'+':'−')+Math.abs(n)+' — '+t);};                  /* зміна обсягу місяця 2 з підписом для підсумку */
 const bank=S=>S.f.pay===0?' Є й ускладнення: бухгалтерія ліцею платить тільки на рахунок підприємця, а в тебе досі особиста картка. Рахунок доводиться відкривати терміново — три години в банку, мінус 6 худі цього тижня.':'';
 const bankEff=S=>{if(S.f.pay===0)ex(S,-6,'черга в банку заради рахунку для ліцею');};
 return {id:'9-9',sec:'9b',title:'Цифрові технології для ведення бізнесу',minutes:30,
 intro:'Ти керуєш «Відбитком» — майстернею друку на худі для класів і шкільних команд. На справу в тебе 20 годин на тиждень, і більша частина йде не на друк, а на переписку, записи й довідки. За два місяці ти переводиш майстерню «в цифру». Кожен інструмент спершу забирає час на налаштування, а потім повертає години щотижня. Від способу оплати й захисту акаунтів залежить, скільки грошей буде втрачено, коли щось піде не так.',
 init:()=>({cash:8000,rout:12,sec:0,setup:0,deal:0,dmg:0,e:0,extra:0,x:[],debt:0,bk:0,r5:12,n2:0,f:{}}),
 meters:[{k:'cash',label:'Гроші в касі',unit:'грн'},{k:'rout',label:'Рутина на тиждень',unit:'год'},{k:'sec',label:'Захист акаунтів',unit:'із 4'}],
 steps:[
  {id:'base',t:'calc',head:'Тиждень 1 · Куди йде час',text:'Ти рахуєш свій тиждень. Із 20 годин на «Відбиток» 12 з’їдає рутина: переписка з клієнтами й звірка оплат — 5 годин, записи замовлень у зошит — 3, підрахунки доходів — 2, довідки й черги — 2. На друк лишається решта. За годину ви з Марком друкуєте 2 худі, а замовлень завжди більше, ніж ви встигаєте виконати.',q:'Скільки худі майстерня друкує за тиждень?',ans:S=>16,unit:'худі',hint:'Спершу знайди, скільки годин лишається на друк: 20 − 12. Потім помнож на 2.',sol:S=>'20 − 12 = 8 годин на друк. 8 × 2 = 16 худі за тиждень. Худі коштує 650 грн, змінні витрати — 440 грн, тож кожна година, забрана в рутини, — це ще 2 худі, тобто 420 грн понад змінні витрати.'},
  {id:'gov',t:'choice',head:'Тиждень 1 · Витяг до п’ятниці',text:'Ліцей оголосив закупівлю 60 худі для випускників. Щоб подати пропозицію, потрібен свіжий витяг із державного реєстру про твою реєстрацію підприємцем, а ще треба додати новий вид діяльності. Строк — п’ятниця.',q:'Як ти отримаєш документи?',o:[
   {l:'Через застосунок «Дія»: подати заяву онлайн і підписати електронним підписом',p:2,eff:S=>{S.setup+=1;S.rout-=2;S.f.gov=1;},fb:'Година на те, щоб розібратися, — і витяг у телефоні. Дві години на тиждень, що йшли на довідки й черги, тепер вільні, а електронний підпис знадобиться ще не раз.'},
   {l:'Піти до центру адмінпослуг у робочий час і все оформити на папері',p:1,eff:S=>{S.setup+=4;},fb:'Документи отримано, але чотири години цього тижня пішли на дорогу й чергу — це 8 ненадрукованих худі. І наступного разу буде так само.'},
   {l:'Заплатити 1 500 грн «помічнику» з оголошення: він усе зробить, треба лише надіслати фото паспорта й код із SMS',p:0,eff:S=>{pay(S,1500);S.f.leak=1;},fb:'Витяг прийшов, і час збережено. Але чужа людина тепер має фото твого паспорта й побувала у твоєму кабінеті — а послуга, за яку заплачено 1 500 грн, у «Дії» безкоштовна.'}]},
  {id:'reg',t:'choice',head:'Тиждень 1 · Новий постачальник',text:S=>'У месенджер пише акаунт «Плівка гуртом −30 %»: термоплівка на третину дешевша, ніж у твого постачальника, але лише за повної передоплати 6 000 грн і лише сьогодні. У касі '+PG(S.cash)+'. Соломія нагадує: дані про фірми є у відкритому державному реєстрі, перевірка за кодом займе п’ятнадцять хвилин.',q:'Що зробиш?',o:[
   {l:'Попросити код фірми й перевірити її в державному реєстрі, перш ніж платити',p:2,eff:S=>{S.f.checked=1;},fb:'Реєстр показує: фірму створено п’ять днів тому, а за її адресою записано ще двісті таких. Платити ти не стаєш — і 6 000 грн лишаються в касі.'},
   {l:'Замовити пробну партію на 1 000 грн — подивитися, чи надішлють',p:1,eff:S=>{pay(S,1000);},fb:'Плівка не приїхала, акаунт зник. Утрачено 1 000 грн — менше, ніж могло бути, але перевірка в реєстрі була безкоштовною.'},
   {l:'Сплатити 6 000 грн одразу — така знижка буває раз на рік',p:0,eff:S=>{pay(S,6000);},fb:'Плівка не приїхала, акаунт зник, гроші теж. Поспіх і «лише сьогодні» — улюблений прийом шахраїв.'}]},
  {id:'acct',t:'choice',head:'Тиждень 2 · Облік замовлень',text:'Замовлення записані в зошиті, оплати — у скриншотах, розміри — в переписці. Учора Марко сорок хвилин шукав, чи оплатив 8-Б.',q:'Як вести замовлення й гроші?',o:[
   {l:'Спільна онлайн-таблиця замовлень і сервіс онлайн-обліку, який сам підтягує оплати з рахунку',p:2,eff:S=>{S.setup+=3;S.rout-=3;S.f.crm=2;},fb:'Три години на перенесення даних цього тижня й 200 грн на місяць за сервіс. Зате щотижня звільняється три години, і кожен із команди бачить те саме.'},
   {l:'Нотатки в телефоні Марка — він і так усе пам’ятає',p:1,eff:S=>{S.setup+=1;S.rout-=1;S.f.crm=1;},fb:'Година на те, щоб переписати зошит, — і стало трохи швидше: мінус година рутини щотижня. Але всі дані в одному телефоні: коли Марка немає, ніхто нічого не знайде.'},
   {l:'Залишити зошит: він працює, а на таблиці немає часу',p:0,eff:S=>{S.f.crm=0;},fb:'Сьогодні не витрачено ні години. Та зошит не шукає, не рахує й не показує, хто не заплатив, — рутина лишилася вся.'}]},
  {id:'pay',t:'choice',head:'Тиждень 2 · Як приймати оплату',text:'Клієнти платять переказом на твою особисту картку й надсилають скриншот. Ліцей і клуби так платити не можуть — їм потрібен рахунок підприємця. Банк пропонує такий рахунок із платіжними посиланнями й QR-кодом: клієнт платить за хвилину, оплата сама з’являється в обліку.',q:'Який спосіб оплати обереш?',o:[
   {l:'Рахунок підприємця, платіжні посилання й QR-код — за умовою задачі комісія 2 % з кожної оплати',p:2,eff:S=>{S.setup+=1;S.rout-=2;S.f.pay=1;},fb:'Година на підключення. Звіряти скриншоти більше не треба — мінус дві години рутини на тиждень, і платити можуть усі, зокрема школи.'},
   {l:'Сторонній платіжний сервіс-посередник: підключати нічого не треба, за умовою задачі комісія 3 %',p:1,eff:S=>{S.rout-=2;S.f.pay=2;},fb:'Запрацювало одразу, звірка зникла. Але з кожної тисячі гривень 30 іде посередникові — у півтора раза більше, ніж на власному рахунку.'},
   {l:'Залишити особисту картку: комісії немає зовсім',p:0,eff:S=>{S.f.pay=0;},fb:'Комісії нуль. Проте скриншоти й далі звіряєш ти, особисті гроші змішані з грошима майстерні, а частина клієнтів так платити не може.'}]},
  {id:'m1',t:'calc',head:'Тиждень 4 · Скільки встигли',text:S=>'Кінець першого місяця. Після твоїх рішень рутина забирає '+S.rout+' год на тиждень із 20'+(S.rout===12?' — стільки ж, як і була':' (для простоти рахуємо так увесь місяць)')+'. '+(S.setup>0?'Але нічого не дається задарма: на довідки, перенесення даних і підключення цього місяця одноразово пішло '+S.setup+' год, і прес увесь цей час стояв.':'На налаштування цього місяця не пішло жодної години.')+' За годину друку — 2 худі.',q:'Скільки худі майстерня надрукувала за чотири тижні?',ans:S=>n1(S),unit:'худі',hint:S=>'Години друку за місяць: (20 − '+S.rout+') × 4.'+(S.setup>0?' Відніми від них '+S.setup+' год налаштування.':'')+' Результат помнож на 2.',sol:S=>'(20 − '+S.rout+') × 4 = '+(4*(20-S.rout))+' год'+(S.setup>0?'; мінус '+S.setup+' год налаштування — '+(4*(20-S.rout)-S.setup)+' год друку':'')+'. '+(4*(20-S.rout)-S.setup)+' × 2 = '+n1(S)+' худі. '+(S.rout<12?'Без жодних змін було б 64. Налаштування забрало години один раз, а звільнені '+PL(12-S.rout,'година','години','годин')+' повертатимуться щотижня.':S.setup>0?'Без походу по довідки було б 64: години пішли, а рутина не зменшилася.':'Рівно стільки ж, як і місяць тому.')},
  {id:'comm',t:'calc',head:'Тиждень 4 · Ціна способу оплати',text:S=>'За місяць надруковано '+n1(S)+' худі по 650 грн. '+(S.f.pay===1?'Усі оплати йдуть через платіжні посилання з комісією 2 % (за умовою задачі).':S.f.pay===2?'Усі оплати йдуть через сервіс-посередник із комісією 3 % (за умовою задачі).':'Комісії ти не платиш. Але перевір, чи справді це вигідно: на рахунку підприємця комісія, за умовою задачі, становила б 2 % виручки.'),q:S=>S.f.pay?'Скільки гривень комісії майстерня заплатила за місяць?':'Скільки гривень комісії довелося б заплатити за цей місяць на рахунку підприємця?',ans:S=>n1(S)*650*rate(S)/100,unit:'грн',hint:S=>'Знайди виручку: '+n1(S)+' × 650. Потім візьми від неї '+rate(S)+' %.',sol:S=>{const r=n1(S)*650;return 'Виручка: '+n1(S)+' × 650 = '+PG(r)+'. '+(S.f.pay===1?'Комісія 2 % — це '+PG(r*0.02)+'. За ці гроші ти маєш миттєву оплату й дві вільні години щотижня.':S.f.pay===2?'Комісія 3 % — це '+PG(r*0.03)+'. На власному рахунку з комісією 2 % було б '+PG(r*0.02)+' — різниця '+PG(r*0.01)+' щомісяця за те, що не знайшлося години на підключення.':'Комісія 2 % — це було б '+PG(r*0.02)+'. А тепер ціна «безкоштовної» картки: дві години звірки скриншотів щотижня — це 8 годин на місяць, 16 ненадрукованих худі, 16 × 210 = 3 360 грн. Комісія обійшлася б дешевше.');}},
  {id:'w4',t:'event',head:'Тиждень 4 · Каса першого місяця',text:S=>{const n=n1(S),sub=S.f.crm===2?200:0,rw=S.f.crm===0?880:S.f.crm===1?440:0;return 'Перший місяць у цифрах. '+n+' худі дали '+n+' × 210 = '+PG(n*210)+' понад змінні витрати. Мінус оренда й інші постійні витрати — 6 300 грн'+(S.f.pay?', комісія за оплати — '+PG(fee1(S)):'')+(sub?', сервіс обліку — 200 грн':'')+'. '+(S.f.crm===0?'Зошит підвів: Марко переплутав рядки, і два худі надрукували не того розміру — переробка коштувала ще 880 грн. ':S.f.crm===1?'Марко на три дні захворів, і ніхто не міг знайти в його телефоні, кому що обіцяли: одне замовлення надрукували двічі — 440 грн на зайву заготовку й фарбу. ':'У спільній таблиці видно все: хто замовив, хто оплатив, що друкувати завтра. ')+'У касі тепер '+PG(Math.max(0,S.cash+n*210-6300-fee1(S)-sub-rw))+'.';},eff:S=>{S.cash=Math.max(0,S.cash+n1(S)*210-6300-fee1(S)-(S.f.crm===2?200:0)-(S.f.crm===0?880:S.f.crm===1?440:0));S.setup=0;}},
  {id:'esign',t:'choice',head:'Тиждень 5 · Договір із ліцеєм',text:S=>'Ліцей обирає «Відбиток»! Договір на 60 худі треба підписати до завтра, а ліцей — у сусідньому місті, півтори години автобусом в один бік. Таку партію ви друкуватимете додатковими суботніми змінами, понад звичайні 20 годин.'+(S.f.gov?' Електронний підпис у «Дії» в тебе вже є.':' Електронного підпису в тебе ще немає.')+bank(S),q:'Як підпишеш договір?',o:[
   {l:'Підписати договір електронним підписом, який уже є, і надіслати за п’ять хвилин',when:S=>!!S.f.gov,p:2,eff:S=>{S.deal=60;bankEff(S);},fb:'Кваліфікований електронний підпис має таку саму силу, як підпис ручкою. Договір у ліцеї ще до обіду, і жодної години друку не втрачено.'},
   {l:'Сьогодні ж отримати електронний підпис у «Дії» й підписати договір онлайн',when:S=>!S.f.gov,p:2,eff:S=>{S.deal=60;S.f.sign=1;ex(S,-2,'година на електронний підпис');bankEff(S);},fb:'Година на те, щоб розібратися із застосунком, — мінус 2 худі цього тижня, — і договір у ліцеї. Підпис лишається з тобою для всіх наступних договорів і звітів.'},
   {l:'Поїхати до ліцею з паперовим договором',p:1,eff:S=>{S.deal=60;ex(S,-10,'поїздка до ліцею');bankEff(S);},fb:'Договір підписано, але дорога туди й назад із чеканням забрала п’ять годин — це 10 ненадрукованих худі.'},
   {l:'Сфотографувати свій підпис, вставити картинку в документ і надіслати',p:0,eff:S=>{S.deal=30;S.f.fakeSign=1;bankEff(S);},fb:'Картинка підпису — не підпис: юристка ліцею документ не прийняла. Поки договір перероблявся, половину замовлення віддали іншій майстерні — лишилося 30 худі.'}]},
  {id:'sec',t:'choice',head:'Тиждень 5 · Паролі',text:'Сторінка «Відбитка» в соцмережі, пошта й кабінет онлайн-банку відкриваються одним простим паролем — vidbytok2024: назва й рік, які вгадає будь-хто. Його знаєте ви втрьох, і він записаний на стікері біля преса.',q:'Що зробиш із захистом?',o:[
   {l:'Окремий довгий пароль для кожного сервісу в менеджері паролів плюс двофакторна автентифікація через застосунок і збережені резервні коди',p:2,eff:S=>{S.sec=3;S.f.app=1;ex(S,-2,'година на паролі й двофакторний вхід');},fb:'Година роботи — мінус 2 худі цього тижня. Тепер самого пароля замало, щоб увійти: потрібен ще код із твого телефона.'},
   {l:'Увімкнути підтвердження входу кодом із SMS, а пароль залишити той самий',p:1,eff:S=>{S.sec=2;S.f.sms=1;},fb:'Другий крок захисту є, і це вже чимало. Але один простий пароль на все лишився, а код із SMS легше перехопити чи виманити, ніж код із застосунку.'},
   {l:'Придумати один складніший пароль і поставити його всюди',p:1,eff:S=>{S.sec=1;},fb:'Вгадати пароль стало важче. Але якщо його виманять на одному сайті — відчиняться всі три двері одразу.'},
   {l:'Нічого не міняти: сезон, не до того, та й кому потрібна шкільна майстерня',p:0,eff:S=>{S.sec=0;},fb:'Часу не витрачено. Шахраям однаково, чия сторінка: вони розсилають листи тисячам і чекають, хто клацне.'}]},
  {id:'bk',t:'choice',head:'Тиждень 5 · Макети',text:'Усі 200 макетів і база клієнтів лежать на ноутбуці Соломії. Ноутбуку п’ять років, і він їздить із нею до школи в рюкзаку.',q:'Як зберігати макети й базу?',o:[
   {l:'Налаштувати автоматичну копію в хмарне сховище — 300 грн на місяць',p:2,eff:S=>{S.bk=2;ex(S,-2,'година на хмарну копію');},fb:'Година на налаштування — мінус 2 худі цього тижня — і 300 грн на місяць. Тепер копія робиться щодня без твоєї участі й лежить не там, де ноутбук.'},
   {l:'Один раз скопіювати все на флешку й покласти в шухляду',p:1,eff:S=>{S.bk=1;},fb:'Сьогоднішні макети в безпеці. Але копія старіє щодня, а оновлювати її вручну забувають усі.'},
   {l:'Нічого: ноутбук працює, навіщо вигадувати проблеми',p:0,eff:S=>{S.bk=0;},fb:'Нуль зусиль. Уся робота Соломії за рік лежить в одному місці, яке можна впустити, залити чаєм або забути в маршрутці.'}]},
  {id:'dig',t:'plan',head:'Тиждень 5 · Цифровий бюджет',text:S=>'У касі '+PG(S.cash)+'. На цифрові інструменти другого місяця ти можеш виділити до 3 000 грн; чого не витратиш — лишиться в касі. Автоматизація: шаблони відповідей і чат-бот, який приймає замовлення, — від 600 грн, повертає ще годину рутини щотижня. Копії даних: зовнішній диск для щотижневої копії макетів — від 500 грн. Навчання команди: заняття про фішинг і шахрайські листи — від 400 грн, додає бал захисту. Сума, менша за вказаний мінімум, нічого не дає.',q:'Розподіли 3 000 грн.',
   fields:[{k:'tools',label:'Автоматизація'},{k:'safe',label:'Копії даних'},{k:'train',label:'Навчання команди'},{k:'keep',label:'Залишити в касі'}],
   total:S=>3000,best:S=>({tools:600,safe:500,train:400,keep:1500}),
   eff:(S,v)=>{pay(S,v.tools+v.safe+v.train);if(v.tools>=600){S.rout-=1;S.f.auto=1;}if(v.safe>=500){S.bk=Math.max(S.bk,1);S.f.disk=1;}if(v.train>=400){S.sec=Math.min(4,S.sec+1);S.f.train=1;}},
   score:(S,v)=>{const c=(v.tools>=600?1:0)+(v.safe>=500?1:0)+(v.train>=400?1:0),w=(v.tools>0&&v.tools<600?v.tools:0)+(v.safe>0&&v.safe<500?v.safe:0)+(v.train>0&&v.train<400?v.train:0);return c===3?{p:2,fb:'Закрито всі три основи — час, дані й уміння команди. Шаблони й чат-бот забирають ще годину рутини на тиждень, а '+PG(v.keep)+' лишаються в касі.'}:c===2?{p:1,fb:'Дві основи з трьох закрито, третя лишилася без грошей'+(w?', а '+PG(w)+' витрачено намарно — менше за мінімум':'')+'. Слабке місце ще дасться взнаки.'}:{p:0,fb:(v.keep>=2000?'Каса майже ціла, але час, дані й команда лишилися без захисту.':'Гроші пішли, а більшість основ так і не закрито.')+(w?' До того ж '+PG(w)+' витрачено намарно — менше за мінімум.':'')+' Заощаджене зараз доведеться віддати пізніше.'};}},
  {id:'hack',t:'event',head:'Тиждень 6 · Лист «від служби підтримки»',text:S=>{const e=eff6(S);return 'Марко отримує лист: «Ваша сторінка порушує правила. Щоб її не видалили, підтвердьте вхід за посиланням протягом години». Він клацає й вводить пароль на підробленій сторінці. '+(S.f.leak?'Шахраї знали навіть твоє ім’я й дату народження — згадай «помічника», якому пішло фото паспорта. ':'')+(e>=3?(S.f.app?'Пароль шахраї отримали, але без коду з твого застосунку зайти не змогли. Тобі прийшло сповіщення про спробу входу — і все. Жодного збитку.':'Та коли «служба підтримки» попросила ще й код із SMS, Марко згадав заняття про фішинг, коду не дав і одразу написав тобі. Без коду зайти шахраї не змогли. Жодного збитку.'):e===2?(S.f.leak?'Зайти з одним паролем не вдалося, тож шахраї написали у службу підтримки соцмережі від твого імені — з фото паспорта — і попросили «відновити доступ». Поки підтримка з’ясовувала, хто справжній власник, сторінка добу була заблокована, нові замовлення не надходили: мінус 4 худі.':S.f.sms?'Шахраї почали вхід і випросили в Марка ще й код із SMS. Сповіщення про новий вхід допомогло швидко відновити доступ, але сторінка добу була заблокована, нові замовлення не надходили: мінус 4 худі.':'За кілька хвилин Марко згадав заняття про фішинг і сказав тобі. Пароль змінено, але шахраї вже встигли зайти й розіслати спам: сторінка добу була заблокована, нові замовлення не надходили: мінус 4 худі.'):e===1?'Сторінку вкрали. Той самий пароль підходив і до пошти, тож відновлювати доступ довелося через службу підтримки — три дні. Нових замовлень увесь цей час не було: мінус 10 худі.':'Сторінку й пошту вкрали за дві хвилини: пароль був один. Шахраї від імені «Відбитка» зібрали з клієнтів 4 000 грн «передоплати» — ці гроші доведеться повернути людям із каси. Сторінка не працювала тиждень, замовлень не було, прес стояв: мінус 20 худі.');},eff:S=>{S.e=eff6(S);S.dmg=lostN(S.e)*210+(S.e===0?4000:0);if(lostN(S.e))ex(S,-lostN(S.e),'сторінка не працювала після атаки');}},
  {id:'react',t:'choice',head:'Тиждень 6 · Після атаки',text:S=>S.dmg>0?'Доступ до сторінки повернуто. Клієнти пишуть у приватні повідомлення: «Це справді ви?»':'Атака не вдалася. Лист досі лежить у Марка в пошті, а сам він трохи наляканий.',q:'Що зробиш далі?',o:[
   {l:'Завершити всі чужі сеанси, змінити паролі на окремі, увімкнути двофакторний вхід і відкрито попередити клієнтів про шахраїв',when:S=>S.dmg>0,p:2,eff:S=>{S.sec=Math.max(S.sec,3);S.f.fixed=1;},fb:'Двері зачинено, а клієнти дізналися про злам від тебе, а не від шахраїв. Чесне попередження довіру повертає, а не забирає.'},
   {l:'Тихо завести нову сторінку й нікому нічого не пояснювати',when:S=>S.dmg>0,p:1,eff:S=>{ex(S,-6,'нова сторінка без підписників');},fb:'Нова сторінка чиста, але підписників на ній нуль, а частина клієнтів так і не зрозуміла, якій сторінці вірити: мінус 6 худі.'},
   {l:'Заплатити 2 000 грн «фахівцю з відновлення», який сам написав у коментарях і обіцяє покарати зловмисників',when:S=>S.dmg>0,p:0,eff:S=>{pay(S,2000);},fb:'«Фахівець» узяв гроші й зник: це другий заробіток тих самих шахраїв. Мінус 2 000 грн, а паролі так і лишилися старі.'},
   {l:'Показати лист усій команді як приклад, змінити пароль, який увів Марко, і поскаржитися на фішинг у службу підтримки',when:S=>S.dmg===0,p:2,eff:S=>{S.f.aware=1;},fb:'Тепер усі троє знають, який вигляд має такий лист: поспіх, погроза й посилання. А викрадений пароль більше нічого не відчиняє.'},
   {l:'Видалити лист і забути: нічого ж не сталося',when:S=>S.dmg===0,p:1,eff:S=>{},fb:'Цього разу захист спрацював. Але пароль Марко таки ввів — і він досі чинний, а команда нічого не навчилася.'},
   {l:'Нічого не міняти й вимкнути сповіщення про входи — вони лише лякають',when:S=>S.dmg===0,p:0,eff:S=>{S.sec=Math.max(0,S.sec-1);},fb:'Тиша в телефоні. Саме сповіщення сьогодні показало тобі атаку — наступну ти не побачиш.'}]},
  {id:'dmg',t:'calc',head:'Тиждень 6 · Рахунок за атаку',text:S=>S.e>=3?'Порахуй, чого вдалося уникнути завдяки захисту. Без нього сторінка простояла б тиждень: 20 худі не продано, а з кожного майстерня має 210 грн понад змінні витрати. І ще 4 000 грн довелося б повернути ошуканим клієнтам.':S.e===0?'Порахуй збиток. Через тиждень без сторінки не продано 20 худі, а з кожного майстерня мала б 210 грн понад змінні витрати. І ще 4 000 грн треба повернути ошуканим клієнтам.':'Порахуй збиток. Поки сторінка не працювала, не продано '+lostN(S.e)+' худі, а з кожного майстерня мала б 210 грн понад змінні витрати.',q:S=>S.e>=3?'Скільки гривень збитку вдалося уникнути?':'Скільки гривень коштувала атака?',ans:S=>S.e>=3?8200:S.dmg,unit:'грн',hint:S=>'Помнож кількість непроданих худі на 210'+(S.e>=3||S.e===0?' і додай 4 000 грн.':'.'),sol:S=>S.e>=3?'20 × 210 + 4 000 = 8 200 грн. Стільки коштувала б година, якої «не було» на налаштування захисту.':S.e===0?'20 × 210 + 4 000 = 8 200 грн. А двофакторний вхід і окремі паролі налаштовуються за годину.':(S.e===2?'4 × 210 = 840 грн.':'10 × 210 = 2 100 грн.')+' Без жодного захисту було б 20 × 210 + 4 000 = 8 200 грн. Що сильніший захист, то менший рахунок.',eff:S=>{if(S.e===0)pay(S,4000);}},
  {id:'crash',t:'event',head:'Тиждень 7 · Ноутбук',text:S=>'У маршрутці на рюкзак Соломії хтось сів. Екран ноутбука тріснув, диск не читається. '+(S.bk===2?'Соломія взяла шкільний комп’ютер, зайшла у хмарне сховище — і за годину всі макети були на місці.':S.bk===1?'Є копія'+(S.f.disk?' на зовнішньому диску, але останній тиждень її ніхто не оновлював':' на флешці, але їй уже два тижні')+'. Шість свіжих макетів довелося малювати наново — шість годин без друку: мінус 12 худі.':'Копії немає. Майстер відновив частину файлів — це коштувало 1 500 грн із каси. Решту Соломія перемальовувала десять годин, і прес увесь цей час стояв: мінус 20 худі.'),eff:S=>{if(S.bk===1)ex(S,-12,'макети, перемальовані після поломки ноутбука');if(S.bk===0){ex(S,-20,'макети, перемальовані після поломки ноутбука');pay(S,1500);}}},
  {id:'brand',t:'choice',head:'Тиждень 7 · «Як у оригіналу»',text:'11-А хоче 30 худі з логотипом всесвітньо відомого бренду кросівок: «Точно як в оригіналі, ніхто не відрізнить. Платимо одразу». Це ще одна суботня зміна й 6 300 грн понад змінні витрати.',q:'Що відповіси класу?',o:[
   {l:'Відмовити в копії й запропонувати власний дизайн: Соломія намалює оригінальний знак класу в спортивному стилі',p:2,eff:S=>{ex(S,24,'худі з власним знаком 11-А');S.f.own=1;},fb:'Шестеро відмовилися, 24 замовили — і отримали худі, якого немає більше ні в кого. Макет належить «Відбитку», і його ніхто не заборонить.'},
   {l:'Відмовити: чужі логотипи ми не друкуємо, шукайте іншу майстерню',p:1,eff:S=>{},fb:'Чужі права не порушено. Але клієнт пішов ні з чим, хоча хотів не логотип, а круте худі — його можна було запропонувати.'},
   {l:'Надрукувати: це ж лише 30 штук для друзів, бренд і не помітить',p:0,eff:S=>{ex(S,30,'худі з чужим логотипом');S.f.copy=1;},fb:'Гроші отримано. Логотип — це торговельна марка, і друкувати його без дозволу власника не можна, скільки б не було штук.'},
   {l:'Трохи змінити логотип — прибрати одну деталь — і надрукувати',p:0,eff:S=>{ex(S,30,'худі з чужим логотипом');S.f.copy=1;},fb:'Гроші отримано. Але знак, який легко сплутати з оригіналом, — таке саме порушення, як і точна копія.'}]},
  {id:'ai',t:'choice',head:'Тиждень 8 · Штучний інтелект',text:'Останній тиждень. Соломія їде на олімпіаду, і Марко пропонує підключити ШІ: генератор картинок — для макетів, чат-бот — щоб відповідати клієнтам.',q:'Як «Відбиток» користуватиметься ШІ?',o:[
   {l:'Для чернеток: ідеї макетів і шаблони відповідей. Усе перевіряє людина, умови комерційного використання прочитано, дані клієнтів у сервіс не потрапляють',p:2,eff:S=>{S.r5=S.rout;S.rout-=2;S.f.ai=1;},fb:'Ще дві години рутини на тиждень зникли — цього тижня це плюс 4 худі. ШІ пропонує, а відповідаєш за результат ти, тому останнє слово за людиною.'},
   {l:'Не користуватися зовсім: надто ризиковано',p:1,eff:S=>{S.r5=S.rout;},fb:'Ризиків справді немає. Але й годин не додалося, а інструмент, яким користуються відповідально, міг би їх дати.'},
   {l:'Попросити генератор: «Намалюй героя відомого мультсеріалу в худі» — і продавати такі принти',p:0,eff:S=>{S.r5=S.rout;ex(S,10,'принти з героєм мультсеріалу');S.f.copy2=1;},fb:'Принт продався 10 разів. Проте герой належить студії, хто б його не намалював — людина чи програма.'},
   {l:'Завантажити в безкоштовний чат-бот усю базу клієнтів із телефонами — нехай сам пише розсилки',p:0,eff:S=>{S.r5=S.rout;S.rout-=2;S.f.data=1;},fb:'Розсилки пишуться самі, дві години на тиждень вільні. Тільки телефони й імена учнів і батьків тепер зберігаються в чужому сервісі, і дозволу на це ніхто не давав.'}]},
  {id:'claim',t:'event',head:'Тиждень 8 · Відлуння',text:S=>(S.f.copy||S.f.copy2?'Представник правовласника натрапив на фото худі на сторінці «Відбитка» — і до соцмережі надійшла скарга. Соцмережа заблокувала сторінку на тиждень, а майстерня, за умовою задачі, сплатила компенсацію — '+(S.f.copy&&S.f.copy2?'по 5 000 грн за логотип і за героя мультсеріалу, разом 10 000 грн':'5 000 грн')+'. Поки сторінка мовчала, замовлень не було: мінус 16 худі. ':'')+(S.f.data?'Батьки отримали дивні рекламні повідомлення й спитали, звідки в чужих людей їхні номери. Один клас скасував замовлення: мінус 9 худі. ':'')+(S.f.own?'Худі з власним знаком 11-А побачили в інших школах — два класи вже просять «щось таке саме, але своє» на наступний місяць. ':'')+(!(S.f.copy||S.f.copy2||S.f.data||S.f.own)?'Тиждень минув спокійно: жодних скарг і жодних нових ідей. ':'')+'Лишилося підбити підсумок двох місяців.',eff:S=>{if(S.f.copy||S.f.copy2){pay(S,(S.f.copy?5000:0)+(S.f.copy2?5000:0));ex(S,-16,'сторінка, заблокована за скаргою');}if(S.f.data)ex(S,-9,'скасоване замовлення класу');}},
  {id:'hours',t:'calc',head:'Тиждень 8 · Повернуті години',text:S=>'Два місяці тому рутина забирала 12 годин із 20 на тиждень. Тепер — '+S.rout+' год.'+(S.rout===12?' Нічого не змінилося.':''),q:S=>S.rout===12?'Скільки годин рутина забирає за місяць (4 тижні)?':'Скільки годин за місяць (4 тижні) повернуто для друку?',ans:S=>S.rout===12?48:(12-S.rout)*4,unit:'год',hint:S=>S.rout===12?'Помнож години рутини за тиждень на 4.':'Знайди різницю за тиждень: 12 − '+S.rout+'. Помнож на 4 тижні.',sol:S=>S.rout===12?'12 × 4 = 48 годин на місяць — це 96 худі, які ніхто не надрукував. Жоден цифровий інструмент так і не запрацював на майстерню.':'(12 − '+S.rout+') × 4 = '+((12-S.rout)*4)+' год на місяць. За годину — 2 худі, тож відтепер це до '+((12-S.rout)*8)+' додаткових худі щомісяця.'},
  {id:'m2',t:'event',head:'Тиждень 8 · Каса другого місяця',text:S=>{const n=n2(S),s=subs(S);return 'Другий місяць у цифрах. Звичайний друк: (20 − '+S.r5+') год × 2 худі × 4 тижні = '+(8*(20-S.r5))+' худі'+(S.f.ai||S.f.data?'; ще 4 худі — з останнього тижня, коли ШІ забрав дві години рутини':'')+'. Замовлення ліцею — '+S.deal+' худі. '+(S.x.length?'Решта подій місяця (у худі): '+S.x.join('; ')+'. ':'')+'Усього продано '+n+' худі: '+n+' × 210 = '+PG(n*210)+' понад змінні витрати. Мінус постійні витрати — 6 300 грн'+(S.f.pay?', комісія за оплати — '+PG(fee2(S)):'')+(s?', підписки на сервіси — '+PG(s):'')+(S.debt>0?', а ще борги цього місяця, на які в касі не вистачило грошей, — '+PG(S.debt):'')+'. У касі було '+PG(S.cash)+', стало '+PG(Math.max(0,S.cash+n*210-6300-fee2(S)-s-S.debt))+'.'+(S.cash+n*210-6300-fee2(S)-s-S.debt<0?' На решту боргу — '+PG(-(S.cash+n*210-6300-fee2(S)-s-S.debt))+' — грошей немає.':'');},eff:S=>{const n=n2(S),r=S.cash+n*210-6300-fee2(S)-subs(S)-S.debt;S.cash=Math.max(0,r);S.debt=Math.max(0,-r);S.n2=n;}}],
 finish:S=>{const clean=!S.f.copy&&!S.f.copy2&&!S.f.data;const lvl=S.cash>=34000&&S.rout<=7&&S.e>=2&&clean?2:S.cash>=22000&&S.debt===0&&(clean||S.e>=2)?1:0;return{level:lvl,title:['Цифра не врятувала: слабкі місця обійшлися надто дорого','«Відбиток» у цифрі, але з дірками','«Відбиток» працює швидко й захищено'][lvl],text:'За два місяці: у касі — '+PG(S.cash)+', рутина — '+S.rout+' год на тиждень замість 12, захист акаунтів — '+S.sec+' із 4 балів. За другий місяць продано '+S.n2+' худі.'+(S.debt>0?' Несплаченим лишився борг — '+PG(S.debt)+'.':''),tips:[S.rout<=6?'Інструменти, які на початку забрали години на налаштування, тепер повертають тобі '+((12-S.rout)*4)+' год щомісяця.':'Рутина досі забирає '+S.rout+' год на тиждень. Година на налаштування «Дії», таблиці чи платіжних посилань окупається за тиждень-два.',S.e>=3?(S.f.app?'Окремі паролі й двофакторний вхід перетворили атаку на звичайне сповіщення.':'Атаку зупинили код із SMS і команда, яка знає, що таке фішинг. Та один пароль на все лишається слабким місцем.'):'Атака коштувала '+PG(S.dmg)+'. Окремі паролі, двофакторний вхід і резервні копії налаштовують до біди, а не після.',clean?'Жодного чужого логотипа й жодних чужих даних у сторонніх сервісах — тому сторінку ніхто не блокував.':'Чужий логотип, чужий герой чи чужі дані дали швидкі гроші, а потім забрали більше. Власний дизайн — це те, чого в тебе ніхто не відбере.']};},
 terms:[['Електронний підпис','дані в електронній формі, що підтверджують особу підписувача; кваліфікований електронний підпис має силу власноручного'],['Двофакторна автентифікація','вхід, для якого потрібні пароль і ще один доказ — наприклад, код із застосунку'],['Резервна копія','копія важливих даних, що зберігається окремо від оригіналу'],['Комісія','плата банку чи платіжному сервісу за проведення платежу, зазвичай відсоток від суми'],['Авторське право','право автора вирішувати, хто й як може використовувати його твір']]};
})());

